INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('555a73e8-a761-5877-a22a-c838f0aa104b', '8a139fb8-ff8d-597b-af78-d4cd967eff55', 'c368a166-0f59-526e-a0bb-2743bc0b4264', 1, 1, 'በእስራኤል ሠራዊት ፊት የሚሄድ መልአከ ገጹም የዘመኖች አከፋፈል የተጻፈበትን ጽላት ያዘ።'),
  ('69308de6-24dc-57bb-ad28-d807d8fc2f8f', '8a139fb8-ff8d-597b-af78-d4cd967eff55', 'c368a166-0f59-526e-a0bb-2743bc0b4264', 2, 2, 'ይኸውም ለሕግና ለምስክርነት በሱባዔ የሚቈጠረው የዘመኑ አከፋፈል ከዓለም ፍጥረትና አዲስ ፍጥረት ከተፈጠረበት ቀን ጀምሮ፥ ሰማያትና ምድር፥ ፍጥረታቸውም ሁሉ የሰማይ ሠራዊት እንደ መሆናቸው እስኪታደሱ ድረስ ያለው የተጻፈበት ነው።'),
  ('404e7816-5d45-5c1c-a08d-7cc6767abc1b', '8a139fb8-ff8d-597b-af78-d4cd967eff55', 'c368a166-0f59-526e-a0bb-2743bc0b4264', 3, 3, 'የምድር ፍጥረት ሁሉ እንደ መሆናቸውም የእግዚአብሔር መቅደስ በኢየሩሳሌምና በደብረ ጽዮን እስኪሠራ ድረስ፥ ብርሃናትም ሁሉ ከእስራኤል ለተመረጡ ሰዎች ሁሉ ለደኅንነት፥ ለሰላምና ለበረከት ሊሆኑ እስኪታደሱ ድረስ፥ ከዚህች ቀን ጀምሮ እስከ ምድር ዘመን ሁሉ እንደዚሁ ይሆን ዘንድ የሚደረገው ሁሉ የተጻፈበት ነው።'),
  ('8f39273f-cbeb-561b-a580-fc769b3f582a', '8a139fb8-ff8d-597b-af78-d4cd967eff55', 'c368a166-0f59-526e-a0bb-2743bc0b4264', 4, 4, 'መልአከ ገጹም በእግዚአብሔር ቃል ሙሴን እንዲህ አለው፥ “እግዚአብሔር አምላክ በስድስተኛው ቀን ፍጥረቱን ሁሉ ፈጥሮ እንደ ጨረሰ፥ የፍጥረትን ነገር ሁሉ ጻፍ፤'),
  ('df54c031-b252-5627-a3cf-a8a69dff7e8f', '8a139fb8-ff8d-597b-af78-d4cd967eff55', 'c368a166-0f59-526e-a0bb-2743bc0b4264', 5, 5, 'በሰባተኛዪቱም ቀን እንዳረፈ፥ ከዕለታቱም ሁሉ እንደ ለያት፥ ለሥራውም ሁሉ ምልክት አድርጎ እንዳኖራት ጻፍ። በመጀመሪያዪቱ ቀን በላይ ያሉ ሰማዮችን ፈጥሮአልና፤ ምድርንና ውኃዎችንም፥ በፊቱ የሚያገለግል ፍጥረትንም ሁሉ ፈጥሮአልና።'),
  ('7c1a211f-0edb-5280-a7b0-60d9c1c7ee14', '8a139fb8-ff8d-597b-af78-d4cd967eff55', 'c368a166-0f59-526e-a0bb-2743bc0b4264', 6, 6, 'መላእክተ ገጽንም፥ የሚያመሰግኑ መላእክትንም፥ በእሳት አካል ላይ የተሾሙ መላእክትንም፥ በነፋስ አካል ላይ የተሾሙ መላእክትን፥ በብርሃንና በጨለማ አካል ላይ የተሾሙ መላእክትንም፥ በበረድና በውርጭ አካል ላይ የተሾሙ መላእክትንም፥'),
  ('492be62e-782e-555c-ae45-bc0c5ae78580', '8a139fb8-ff8d-597b-af78-d4cd967eff55', 'c368a166-0f59-526e-a0bb-2743bc0b4264', 7, 7, 'በውኃ ላይ የተሾሙ መላእክትን፥ በነጐድጓድና በመብረቅ ላይ የተሾሙ መላእክትን፥ በቍርና በውርጭ፥ በክረምትና በመጸው፥ በጸደይና በበጋ፥ በሰማይና በምድር ባሉ ነፋሳት ሁሉ የተሾሙ መላእክትን፥ በወንዙ ሁሉ፥ በጨለማና በብርሃን፥ በንጋትና በምሽት በባሕርይ ዕውቀቱ ባዘጋጃቸው ላይ የተሾሙ መለእክትን ፈጥሮአልና።”'),
  ('cc943b0a-cf2e-5a72-a43d-d7d4a42cadbf', '8a139fb8-ff8d-597b-af78-d4cd967eff55', 'c368a166-0f59-526e-a0bb-2743bc0b4264', 8, 8, 'ያንጊዜም ሥራውን አይተን ስለ ሠራው ሥራ ሁሉ በፊቱ ፈጽመን አመሰገንነው፤ በመጀመሪያዪቱ ቀን ሰባት ታላላቅ ሥራዎችን ሠርቶአልና።'),
  ('f1998d81-98b0-56ef-a8e4-af9c80de92a3', '8a139fb8-ff8d-597b-af78-d4cd967eff55', 'c368a166-0f59-526e-a0bb-2743bc0b4264', 9, 9, 'በሁለተኛዪቱም ቀን በሐኖስና በውቅያኖስ መካከል ጠፈርን አድርጎአልና፤ በዚያችም ቀን ውኃዎች ተከፍለው እኩሌቶቹ ወደ ላይ ወጥተዋልና፤ እኵሌቶቹ ከጠፈር በታች ወዳለው ወደ ምድር መካከል ወርደዋልና፤ በሁለተኛው ቀን ይህን ሥራ ብቻ ሠራ።'),
  ('bcae62ac-76a8-56ff-a0cc-1b5b41038c38', '8a139fb8-ff8d-597b-af78-d4cd967eff55', 'c368a166-0f59-526e-a0bb-2743bc0b4264', 10, 10, 'በሦስተኛዪቱም ቀን፥ “ውኃዎች ከምድር ላይ ወደ አንዱ ቦታ ሄደው ይወሰኑ፥ ምድርም ትገለጥ” ብሎ እንደ ተናገረው አድርጎአልና።'),
  ('7e98841b-9806-54a6-a26f-a6ab0f15e098', '8a139fb8-ff8d-597b-af78-d4cd967eff55', 'c368a166-0f59-526e-a0bb-2743bc0b4264', 11, 11, 'ውኃዎችም እንዳዘዛቸው እንደዚሁ ተዘጋጁ። ከምድር ፊት ወደ አንድ ቦታ ሄደው ከዚህ ከጠፈር በታች በውቅያኖስ ተወሰኑ፤ ምድርም ተገለጠች።'),
  ('e1fc4dd2-22ae-50bb-aed1-aad044c95876', '8a139fb8-ff8d-597b-af78-d4cd967eff55', 'c368a166-0f59-526e-a0bb-2743bc0b4264', 12, 12, 'በዚያችም ቀን በየመወሰኛቸው የባሕር ጥልቆችን ፈጠረላት፤ ፈሳሾችንም ሁሉ፥ የውኃዎችንም መወሰኛዎች፥ በተራራዎች ሥር በምድር ውስጥ ምንጮች ሁሉና በተራራዎች ሥር ያሉ የውኃዎችን መወሰኛዎች ሁሉ፥ በምድር ያሉ የውኃዎችንም ጕድጓድ ሁሉ ፈጠረላት። በየዘሩም የሚዘራውን ዘር፥ የሚበላውንም ዘር ሁሉ፥ የሚያፈሩ እንጨቶችንና ዛፎችንም፥ በገነትም ለተድላ የተፈጠሩ ተክሎችን፥ በሦስተኛዪቱ ቀን እነዚህን አራቱን ታላላቆች ፍጥረቶች ፈጠረ።'),
  ('29c79ba9-f19b-5b9b-acf1-94fb91de3d4e', '8a139fb8-ff8d-597b-af78-d4cd967eff55', 'c368a166-0f59-526e-a0bb-2743bc0b4264', 13, 13, 'በአራተኛዪቱም ቀን ጨረቃንና ፀሓይን፥ ከዋክብትንም ፈጥሮ በዓለሙ ሁሉ ያበሩ ዘንድ በጠፈር አኖራቸው። ሌሊትንና ቀንንም አስገዛቸው፤ በብርሃንና በጨለማ መካከልም ለመለየት ድንበር አደረጋቸው።'),
  ('fa842310-9bd8-5782-a5b6-f63ae773a32d', '8a139fb8-ff8d-597b-af78-d4cd967eff55', 'c368a166-0f59-526e-a0bb-2743bc0b4264', 14, 14, 'እግዚአብሔርም በምድር ላይ ለቀኖችና ለሱባዔዎች፥ ለወሮችና ለበዓሎች፥ ለዓመታትና ለኢዮቤላት፥ በዓመት ለሚመላለሱ ሰዓቶችም ሁሉ ታላቅ ምልክት እንዲሆን፥ በብርሃንና በጨለማ መካከልም ድንበርን እንዲለይ፥ በምድርም ላይ የሚበቅለውና የሚያድገው ሁሉ ይድን ዘንድ፥ ለማዳን ፀሐይን ፈጠረ፤ በአራተኛዪቱ ቀን እነዚህን ሦስቱን ፍጥረቶች ፈጥረ።'),
  ('e09c33ec-7407-5638-a09e-a8919cba0dbf', '8a139fb8-ff8d-597b-af78-d4cd967eff55', 'c368a166-0f59-526e-a0bb-2743bc0b4264', 15, 15, 'በአምስተኛዪቱም ቀን በጥልቅ ውኃዎች መካከል ያሉትን ታላላቅ ዓሣ አንበሪዎች ፈጠረ። ይህ ሁሉ መጀመሪያ በእጁ ተፈጥሮአልና፤ ሥጋዊ ደማዊ ሁሉ፥ በውኃዎችም ውስጥ የሚመላለስ ፍጥረት ሁሉ፥ ዓሣዎችና የሚበሩ ወፎች ሁሉ፥ ወገኖቻቸውም ሁሉ ተፈጥረዋልና፤'),
  ('8ec33a98-0a0b-5b47-a3d1-09d573ef9ae5', '8a139fb8-ff8d-597b-af78-d4cd967eff55', 'c368a166-0f59-526e-a0bb-2743bc0b4264', 16, 16, 'ፀሓይም ሕይወት ሊሆናቸው በእነርሱ ላይ ወጥቶአልና፥ በዚህ ዓለም በሚኖር ፍጥረትና በምድር በሚበቅለው ሁሉ ላይ፥ በሚያፈራውም እንጨት ሁሉ ላይ፥ በሥጋዊ ደማዊ ሁሉ ላይ ወጥቶአልና፤ በአምስተኛዪቱ ቀን እነዚህን ሦስቱን ፍጥረታት ሁሉ ፈጠረ።'),
  ('6a7546af-b144-5cb6-a56e-4ab149dd3258', '8a139fb8-ff8d-597b-af78-d4cd967eff55', 'c368a166-0f59-526e-a0bb-2743bc0b4264', 17, 17, 'በስድስተኛዪቱም ቀን እንስሳትንና አራዊትን ሁሉ በምድር ላይ የሚመላለሰውንም ፍጥረት ሁሉ ፈጠረ።'),
  ('cfd696ce-1ea4-5f93-aa83-00a2da825fe9', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 1, 1, 'ከዚህም ሁሉ በኋላ ሰውን ፈጠረ፤ ወንድና ሴት አድርጎ ፈጠራቸው፤ በምድር ላይና በባሕር ውስጥ ባለውም ሁሉ ላይ አሠለጠነው። በሚበርሩ አዕዋፍ ላይና በአራዊት ላይ፥ በእንስሳት ላይና በምድር ላይ በሚንቀሳቀሰው ላይ፥ በምድርም ሁሉ ላይ፥ በዚህም ሁሉ ላይ አሠለጠነው፤ በስድስተኛዪቱ ቀን እነዚህን አራት ዓይነት ፍጥረታት ፈጠረ።'),
  ('21e04da3-13e1-5358-a7bb-220ca56d57ec', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 2, 2, 'ሁሉም ሃያ ሁለት ዓይነት ፍጥረት ሆነ፤ በስድስተኛዪቱም ቀን በሰማይና በምድር፥ በባሕሩና በጥልቁ ውስጥ፥ በብርሃንና በጨለማ መካከል፥ በሁሉም ላይ ያለውን ፍጥረት ሁሉ ፈጥሮ ፈጸመ።'),
  ('645cb8c4-96cc-5fb3-afb7-675c1507e037', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 3, 3, 'ስድስት ቀን ሥራ ሠርተን በሰባተኛዪቱ ቀን ከሥራ ሁሉ እናርፍ ዘንድ ታላቅ ምልክት ሰባተኛዪቱን ቀን ሰጠን።'),
  ('685a105f-2ce7-590a-a378-ff47de4d6191', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 4, 4, 'መላእክተ ገጽ ሁሉና የምስጋና መላእክት ሁሉ እነዚህ ሁለቱ ታላላቅ ወገኖች ናቸው። ከእርሱም ጋር በሰማይና በምድር ይህን እናከብር ዘንድ አዘዘን።'),
  ('f3939c2b-730f-5eb3-a6b4-d623c8a4df29', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 5, 5, 'እንዲህም አለን፥ “እነሆ፥ እኔ ከአሕዛብ መካከል ሕዝብን እለያለሁ፤ እነርሱም ሰንበትን ያከብራሉ። ለእኔም ሕዝብ አድርጌ እለያቸዋለሁ፤ የሰንበትንም ቀን እንደ ቀደስኋት እባርካቸዋለሁ። ለእኔም እለያቸዋለሁ።'),
  ('da4ec950-0511-5222-ab13-3b62ae1e3862', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 6, 6, 'እንዲህም እባርካቸዋለሁ። ሕዝቤም ይሆናሉ፤ እኔም አምላክ እሆናቸዋለሁ፤ በሁሉም ካየሁት የያዕቆብን ዘር መረጥሁ፥ ለእኔም የበኵር ልጅ አድርጌ ጻፍሁት፤ ለዘለዓለምም ቀደስሁት።'),
  ('85e68909-631c-5de4-a25e-544c1908caf8', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 7, 7, '“ከሥራ ሁሉ ያርፉባት ዘንድ የሰንበታትን ቀን አመለክታቸዋለሁ። እንደዚሁም በዓል ያከብሩባት ዘንድ ምልክት አደረግሁባት።'),
  ('b9cf6d69-90cc-510b-a158-6b8c5236f35d', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 8, 8, 'እነርሱም በሰባተኛዪቱ ቀን ለመብላትና ለመጠጣት፥ ሁሉን የፈጠረ እግዚአብሔርንም ለማመስገን ከእኛ ጋር ነበሩ። ከእኛ ጋርም በአንድነት ያርፉ ዘንድ ከአሕዛብ ሁሉ ተለይቶ የሚታይ ሕዝብን ባረከ፥ ቀደሰም።'),
  ('18698abf-be97-545f-a138-b663a18a20c2', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 9, 9, 'በዘመኑ ሁሉ በፊቱ የሚቀበለው በጎ መዓዛ ያርግ ዘንድ በፊቱ መሥዋዕትን ሠዋ፥ ከአዳም ጀምሮ እስከ ያዕቆብ ድረስ ያሉ አበው ሃያ ሁለት ናቸው። እስከ ሰባተኛዪቱም ቀን ድረስ ሃያ ሁለት ዓይነት ፍጥረት ተፈጠረ። ይህም የተባረከና የተቀደሰ ሰንበቱ ነው። እርሱም ቡሩክና ቅዱስ ነው።'),
  ('ece8af0c-0158-5856-a30e-e81cf6308855', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 10, 10, 'ይህም ከዚህ ጋር ለምስጋናና ለበረከት ሆነ። ቀድሞ ሰባተኛው ቀን እንደ ተቀደሰና እንደ ተባረከ በዘመኑ ሁሉ ለምስክሩና ለሕጉ የተባረኩና የተቀደሱ ይሆኑ ዘንድ ይህ ለእርሱ ተሰጠው።'),
  ('db86deee-5c9f-55c3-a147-878d8a59bad3', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 11, 11, '“በመጀመሪያዪቱ ሱባዔ ሰማይንና ምድርን፥ በስድስት ቀን የተፈጠረውንም ፍጥረት ሁሉ ፈጠረ። እግዚአብሔርም ለፍጥረቱ ሁሉ የተቀደሰች የበዓል ቀንን ሰጠ። ስለዚህም ሥራን ሁሉ የሚሠራባት ሁሉ ይሞት ዘንድ፥ የሚሽራትም ሞትን ይሞት ዘንድ አዘዘ።'),
  ('a4284e99-647c-5959-aaa5-bb3990346710', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 12, 12, 'አንተም የእስራኤልን ልጆች እዘዛቸው፥ እነርሱም እንዲያከብሯት፥ ሥራንም ሁሉ እንዳይሠሩባት፥ እንዳይሽሩአትም፥ ያችን ዕለት ይጠብቁ፤ ከዕለታት ሁሉ እርስዋ የተቀደሰች ናትና።'),
  ('3e688693-780c-5620-a64c-99033bf4085c', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 13, 13, 'የሚያረክሳትም ሁሉ ሞትን ይሙት፤ ሥራንም የሚሠራባት ሁሉ ለዘለዓለሙ ሞትን ይሙት። የእስራኤልም ልጆች ከምድር እንዳይጠፉ በትውልዳቸው ይህችን ቀን ይጠብቁ። የተባረከችና የተቀደሰች ናትና።'),
  ('f6387a9c-1fd6-50f6-aa1f-2dea92c15ddc', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 14, 14, 'የሚጠብቃት ሰው ሁሉ፥ ከሥራውም ሁሉ የሚያርፍባት ሰው በዘመኑ ሁሉ እንደ እኛ የተቀደሰና የተባረከ ይሆናል።'),
  ('2492aa19-a458-5109-a5b5-eee108bf544a', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 15, 15, '“ለእስራኤል ልጆች፦ የዚህችን ቀን ፍርድ አስረድተህ ንገር፤ ያክብሯትም፤ የማይገባ ሥራን ለመሥራትም የተዘጋጁ እንዳይሆኑ በልቡናቸው ስሕተት አይተዉአት፤ የሚታየውን ፈቃዳቸውንም በእርስዋ ለማድረግ የሚበላውንና የሚጠጣውን ሁሉ ያዘጋጁባት ዘንድ፥'),
  ('8753c854-eb34-581e-a037-b22d162fc08b', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 16, 16, 'ውኃንም ለመቅዳት፥ በአደባባያቸውም ሸክሙን ሁሉ ለማግባትና ለማውጣት፥ እነርሱ በስድስት ቀን በቤታቸው ያላዘጋጁትን ሥራ አይሥሩ።'),
  ('7055958f-7c47-5e72-aea9-18e2a9d8ceb2', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 17, 17, 'በኢዮቤልዩ ከሚቈጠር ቀን ሁሉ ተለይታ የከበረች ናትና በዚህች ቀን ከቤት ወደ ቤት አያውጡባት፥ አያግቡባትም። በምድር ዕረፍት ያደርጉባት ዘንድ ለሥጋዊ ሁሉ ሳይታወቅ እኛ በሰማያት ዕረፍትን አደረግንባት።”'),
  ('a0a5d73c-332c-56c6-a255-6203289a52e1', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 18, 18, 'የሁሉ ፈጣሪም ባረካት፤ ከእስራኤልም ብቻ በቀር በእርስዋ ዕረፍት ለማድረግ አሕዛብን ሁሉ አልመረጠም፤ ነገር ግን በልቶና ጠጥቶ በምድር ዕረፍትን ሊያደርግባት ለእርሱ ብቻ ሰጠው።'),
  ('b177ee54-b5df-524e-a7a1-6e4b1584d414', 'a4642125-5210-5537-a3a2-47e394d146c1', '83f91160-6c53-56c5-a677-b977b320bb8c', 19, 19, 'ከቀኑ ሁሉ ተለይታ ለበረከትና ለቅድስና ለማመስገኛም ልትሆን ይህችን ቀን የፈጠረ የሁሉ ፈጣሪ ባረካት፤ ይህ ሕግ፥ ይህም ምስክር ለእስራኤል ልጆችና ለትውልዳቸውም ለዘለዓለም ሥርዐት ሆኖ ተሰጠ።'),
  ('d7936624-796d-5190-a97e-b40fba41c551', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 1, 1, 'በሁለተኛዉ ሱባዔ በስድስቱ ቀናት በእግዚአብሔር ቃል አራዊትን ሁሉ፥ እንስሳትን ሁሉ፥ አዕዋፍን ሁሉና በምድር የሚንቀሳቀሰውን ፍጥረት ሁሉ፥ በውኃውም ውስጥ የሚንቀሳቀሰውን ፍጥረት ሁሉ በየወገናቸውና በየመልካቸው ወደ አዳም አመጣን።'),
  ('0cf8c02f-d7c0-5197-a362-cc1518c35cc2', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 2, 2, 'በመጀመሪያዪቱ ቀን አራዊትን፥ በሁለተኛዪቱ ቀን እንስሳትን፥ በሦስተኛዪቱ ቀን አዕዋፍን፥ በአራተኛዪቱ ቀን በምድር ላይ የሚንቀሳቀሰውን ሁሉ፥ በአምስተኛዪቱም ቀን በውኃ ውስጥ የሚንቀሳቀሰውን ሁሉ። አዳምም ሁሉን በየስማቸው ጠራቸው፤ ስማቸውም አዳም እንደ ጠራቸው እንዲሁ ሆነ።'),
  ('41e2f3e6-fa76-5b9e-afe2-5dbce829bea7', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 3, 3, 'በእነዚህም በአምስቱ ቀኖች አዳም እነዚህን ሁሉ፥ በምድር ያለውንም ፍጥረት ሁሉ ሴትና ወንድ ሆነው ያይ ነበር። እርሱ ግን ብቻውን ነበረ። እንደ እርሱ ያለ ረዳትንም ለራሱ አላገኘም ነበር።'),
  ('86b64d66-3ed5-5076-a83f-a4c4b733768c', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 4, 4, 'እግዚአብሔርም ለእኛ እንዲህ አለን፥ “አዳም ብቻውን ይኖር ዘንድ መልካም አይደለም፤ ነገር ግን እንደ እርሱ ያለ ረዳትን እንፍጠርለት።” አምላካችን እግዚአብሔርም በእርሱ ላይ እንቅልፍን አመጣበት፤ እርሱም ተኛ።'),
  ('7f7e2437-efa7-5258-ab6b-9add4d9becaf', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 5, 5, 'ከአጥንቶቹም መካከል አንድ አጥንት ወስዶ ሴትን ፈጠራት። ይህችም ጎን ከአጥንቶች መካከል የሴት መገኛ ናት፤ ስለ እርስዋም ፋንታ ሥጋን ሞላ። ሴትም አድርጎ ፈጠራት። አዳምንም ከእንቅልፉ አነቃው።'),
  ('a0217f05-2fbf-5398-a5dd-04c1e7be279b', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 6, 6, 'አዳምም በስድስተኛዪቱ ቀን ከእንቅልፉ ነቅቶ በተነሣ ጊዜ ወደ እርሱ አመጣት፥ ዐወቃትም። እርሱም፥ “ከእኔ ከባልዋ ተገኝታለችና ይህች አጥንት ከአጥንቴ፥ ሥጋም ከሥጋዬ ናት፤ እርስዋም ሚስት ትሁነኝ” አላት። ስለዚህ ባልና ሚስት አንድ አካል ይሆናሉ።'),
  ('433e58e8-decf-5efb-ac9e-6a7c7b3bd1c3', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 7, 7, 'ስለዚህም ሰው አባቱንና እናቱን ይተዋል፤ ከሚስቱም ጋር አንድ ይሆናል፥ አንድ አካልም ይሆናሉ።'),
  ('1fb744fe-ff80-53b4-a3ef-0bb195da0f77', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 8, 8, 'በመጀመሪያዪቱ ሱባዔ አዳም ተፈጠረ፤ ሚስቱም የተገኘችበት ጎኑ ተፈጠረ፤ በሁለተኛዪቱም ሱባዔ እርስዋን አሳየው፤ ስለዚህም በሕርስ ጊዜ ለወንድ ልጅ አንድ ሱባዔ፥ ለሴት ልጅ ሁለት ሱባዔ የመጠበቅ ትእዛዝ ተሰጠ።'),
  ('f493e8b5-cdd2-51db-ac17-34ce8633a086', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 9, 9, 'በተፈጠረባትም ምድር ለአዳም አርባ ቀን ከተፈጸመለት በኋላ ያበጃትና ይጠብቃት ዘንድ ወደ ኤዶም ገነት አስገባነው። ሚስቱንም በሰማንያኛው ቀን አስገባናት።'),
  ('3f4b7953-5ef6-53de-abbd-622dd3e9df44', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 10, 10, 'ከዚህም በኋላ ወደ ኤዶም ገነት ገባች፤ ስለዚህ ለምትወልድ ሴት በጽላተ ሰማይ ሥርዐት ተጻፈ። ወንድ ልጅ ብትወልድ እንደ መጀመሪያው ሰባት ቀን በአራስነቷ ሰባት ቀን ትቈያለች፥ ሠላሳ ሦስት ቀንም በመንጻቷ ደም ትቈያለች።'),
  ('bd4c370d-c96f-5535-a89d-3a5f324920be', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 11, 11, 'የተቀደሰውን ሁሉ አትንካ፤ ለወንድ ልጅ የታዘዘውን ይህን ቀን እስክትፈጽም ድረስ ወደ ቤተ መቅደስ አትግባ። ሴት ልጅ ብትወልድ እንደ መጀመሪያዎቹ ሁለት ሱባዔያት በአራስነቷ ሁለት ሱባዔያት ትቈያለች። ስድሳ ስድስት ቀንም በመንጻቷ ደም ትቈያለች። ሁሉም ሰማንያ ቀኖች ይሆናሉ።'),
  ('52f21caa-0350-5d94-ae9e-5dab86caf973', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 12, 12, 'እነዚህንም ሰማንያ ቀኖች ከፈጸመች በኋላ ገነት ከምድር ሁሉ የተቀደሰች ናትና፥ በውስጥዋም የበቀለው እንጨት ሁሉ የተቀደሰ ነውና ወደ ኤዶም ገነት አገባናት።'),
  ('99011772-5111-54f4-ac37-c035df38c564', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 13, 13, 'ስለዚህም ወንድ ልጅና ሴት ልጅ ለምትወልድ ሴት የእነዚህ ቀኖች ሥርዐት ተሠራ፤ ለወንድ ልጅና ለሴት ልጅ የታዘዙ እነዚህ ቀኖች እስኪፈጸሙ የተቀደሰውን ሁሉ አትንካ፤ ወደ መቅደስም ሁሉ አትግባ። እስራኤልም በዘመኑ ሁሉ ይጠብቁት ዘንድ የተጻፈው ሕግና ሥርዐት ይህ ነው።'),
  ('3292730c-e1d2-5deb-af72-b91bea355a53', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 14, 14, 'በመጀመሪያው ኢዮቤልዩ በመጀመሪያ ሱባዔ አዳምና ሚስቱ በኤዶም ገነት ሰባት ዓመት ሲሠሩና ሕጉን ሲጠብቁ ኖሩ። ሥራንም ሰጠነው፤ ለማገልገልም ተገልጦ የሚታየውን ሥራ ሁሉ እያስተማርነው ኖርን፤ እርሱም እየሠራ ኖረ።'),
  ('784f0456-59ac-5fad-a55f-c4bac0b179e8', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 15, 15, 'እርሱ ግን ዕራቁቱን ነበረ፤ ዕራቁቱንም እንደ ሆነ አያውቅም ነበር፥ አያርፍምም ነበር። ተክልንም ከወፎችና ከአራዊት፥ ከእንስሳትም ይጠብቅ ነበር።'),
  ('fca5ff13-b474-5687-ae30-41c9f47b6890', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 16, 16, 'ፍሬውንም ለቅሞ ይበላ ነበር፥ የተረፈውንም ለእርሱና ለሚስቱ ያኖር ነበር፤ የሚጠብቀውንም ያኖር ነበር፤ ሰባቱን ዓመት ጠንቅቆ ቈጥሮ በዚያ የፈጸማቸው የሰባቱ ዓመት ፍጻሜ ባለቀ ጊዜ፥'),
  ('cc56d6a2-89d3-53a9-abf2-1f757ba8fcd0', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 17, 17, 'በሁለተኛው ወር በዐሥራ ሰባተኛው ቀን እባብ መጥቶ ወደ ሔዋን ቀረበ። እባቡም ሔዋንን፥ “በገነት ካሉ ዛፎች ፍሬ ሁሉ እግዚአብሔር፦ ከእርሱ አትብሉ ብሎ አዝዞአችኋልን?” አላት።'),
  ('f801df39-066a-52f6-ad13-fa68168900a5', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 18, 18, 'እርስዋም እንዲህ አለችው፥ “እግዚአብሔር፦ በገነት ካለ ዛፍ ፍሬ ሁሉ ብሉ፥ በገነት መካከል ካለ ዛፍ ፍሬ ግን አትብሉ፥ እንዳትሞቱም አትንኩ” አለን።'),
  ('e67e49af-8d13-5179-aa33-138f8e8da4aa', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 19, 19, 'እባብም ሔዋንን፥ “ከእርሱ በምትበሉበት ቀን ዐይኖቻችሁ እንደሚበሩ፥ አማልክትም እንደምትሆኑ፥ ክፉውንና በጎውንም እንደምታውቁ እግዚአብሔር ያውቃልና ነው እንጂ ሞትን የምትሞቱ አይደለም” አላት።'),
  ('f9870b02-3e45-5c3b-a787-41cf74bf3436', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 20, 20, 'ሔዋንም ዛፉ ያማረ እንደ ሆነ፥ ለማየትም ደስ የሚያሰኝ፥ ፍሬውም ለመብላት የሚያስጐመጅ እንደ ሆነ ባየች ጊዜ ከእርሱ ወስዳ በላች። ኀፍረቷንም በቀደመው በበለሱ ቅጠል ሸፈነች። ለአዳምም ሰጠችውና በላ። ዐይኖቹም አዩ፤ ዕራቁቱንም እንደ ሆነ ባየ ጊዜ የበለስ ቅጠል ወስዶ ሰፋ፤ ግልድም አድርጎም ኀፍረቱን ሸፈነ።'),
  ('196d42b3-9ba3-5467-a9b0-941e1e4f85b9', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 21, 21, 'እግዚአብሔርም እባቡን ረገመው፤ ለዘለዓለምም ፈረደበት።'),
  ('ecc80b69-9830-5f38-a03b-4e34cc555049', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 22, 22, 'ሔዋንንም የእባቡን ቃል ሰምታ በልታለችና ፈረደባት፤ “ኀዘንሽንና ጣርሽን ፈጽሜ አበዛዋለሁ፤ በኀዘን ልጆችን ውለጂ፥ መመለሻሽም ወደ ባልሽ ይሁን፤ እርሱም ይግዛሽ” አላት።'),
  ('299c810e-cf3b-5104-a7a6-29eafc1bde46', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 23, 23, 'አዳምንም፥ “የሚስትህን ቃል ሰምተህ ከእርሱ እንዳትበላ ካዘዝሁህ ከዚያ ዛፍ በልተሃልና በአንተ ምክንያት ምድር የተረገመች ትሁን፤ እሾህና አሜከላ ይብቀልብህ፤ አንተ ከምድር ተገኝተሃልና ወደ ምድርም ትመለሳለህና ከእርስዋ ወደ ተገኘህባት ወደ ምድር እስክትመለስ ድረስ በፊትህ ወዝ እንጀራህን ብላ” አለው።'),
  ('482a8b5a-1484-5f79-aa61-38d8630b3144', 'abd0e24b-d83c-5b0e-a2f0-7450e1e81e68', '24036f38-c2a4-5d16-a89c-c507104677b0', 24, 24, 'የቍርበት ልብስንም አደረገላቸው፤ አለበሳቸውም ከኤዶም ገነትም አሰናበታቸው።'),
  ('e29d9d99-1319-5292-a130-7203624fd8df', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 1, 1, 'በዚያችም ቀን አዳም ከኤዶም ገነት ሲወጣ ለበጎ መዓዛ ነጭ ዕጣን፥ ቀንዓትና ልባንጃ፥ ስንቡልም ኀፍረቱን በሸፈነበት ቀን በጥዋት ፀሓይ ሲወጣ ዐጠነ።'),
  ('de161f52-5a9f-53f2-a00c-1fbc81855f05', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 2, 2, 'በዚያችም ቀን የአራዊትና የእንስሳት ሁሉ፥ የሚመላለሰውና የሚንቀሳቀሰው፥ የወፎችም ሁሉ አፍ ከመናገር ተከለከለ። ከዚያ አስቀድሞ አንዱ ከአንዱ ጋር በአንድ አነጋገርና በአንድ ቋንቋ ይናገሩ ነበርና።'),
  ('0465bede-6cf5-567c-ab59-cbb1a3c3ffe4', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 3, 3, 'በኤዶም ገነት የነበረውንም ሥጋዊ ሁሉ ከኤዶም ገነት አሰናበተ።'),
  ('12eeefde-854c-5015-a47a-f3f3aaaaf59a', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 4, 4, 'ሥጋ ለባሹ ሁሉም በየወገናቸውና በየተፈጥሮአቸው ወደ ተፈጠረላቸው ቦታ ተበተኑ።'),
  ('d5264185-cc94-54ea-a2a4-c2bfc7b5f9a7', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 5, 5, 'ለአዳም ብቻ ከአራዊትና ከእንስሳት ሁሉ ተለይቶ፥ ኀፍረቱን ይሸፍን ዘንድ ልብስን ሰጠው። ስለዚህ የሕግን ፍርድ በሚያውቁ ሰዎች ሁሉ ላይ ኀፍረታቸውን እንዲሰውሩ እንጂ፥ አሕዛብም እንደሚገለጡ እንዳይገለጡ በሰማይ ጽላት ታዘዘ።'),
  ('979f79da-2e14-5849-a5ad-26bcf2768c1a', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 6, 6, 'በአራተኛው ወር መባቻ አዳምና ሚስቱ ከኤዶም ገነት ወጥተው በተፈጠሩባት ምድር በኤልዳ ምድር ኖሩ። አዳምም የሚስቱን ስም ሔዋን አላት፤ እስከ መጀመሪያው ኢዮቤልዩም ድረስ ልጅ አልነበራቸውም።'),
  ('a42cd3d3-a5d2-5034-a041-39d5001a04d6', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 7, 7, 'ከዚህም በኋላ በግብር ዐወቃት፤ እርሱ ግን በኤዶም ገነት እንደ ተማረ ምድርን ያርሳት ነበር።'),
  ('98005365-d287-527b-a9fc-d0bf027a2ed5', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 8, 8, 'በሦስተኛው ሱባዔ በሁለተኛው ኢዮቤልዩ ቃየንን ወለደች፤ በአራተኛውም ሱባዔ አቤልን ወለደችው፤ በአምስተኛውም ሱባዔ ልጅዋን አዋንን ወለደቻት።'),
  ('7422d5fb-3dbd-5ca0-a011-7ba9737c08f5', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 9, 9, 'እግዚአብሔር ከአቤል እጅ መሥዋዕትን ተቀብሎአልና፥ ከቃየን እጅ ግን መሥዋትን አልተቀበለምና በሦስተኛው ኢዮቤልዩ መጀመሪያ ቃየን አቤልን ገደለው፤ በምድረ በዳም ገደለው፤ ስለ ተገደለም እየተካሰሰ ደሙ ከምድር እስከ ሰማይ ጮኸ።'),
  ('1179c58f-27b5-57b7-a41c-d6794750d31d', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 10, 10, 'እግዚአብሔርም ስለ ገደለው ስለ አቤል ቃየንን ዘለፈው፤ ስለ ወንድሙ ስለ አቤል ደም በምድር ላይ ተቅበዝባዥ አደረገው፥ በምድርም ረገመው።'),
  ('237aac8f-bf4f-5770-a30c-1839a7d0b9ff', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 11, 11, 'ስለዚህ ወንድሙን በተንኰል የሚገድል ሰው የተረገመ እንደ ሆነ በሰማይ ጽላት ተጻፈ። ያዩም ሁሉ ይሁን አሉ። አይቶም ያልተናገረ ሰው እንደ እርሱ የተረገመ ይሁን።'),
  ('c24ae8e3-6181-5137-afae-0f11afd59b37', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 12, 12, 'ስለዚህም እኛ በሰማይና በምድር፥ በብርሃንና በጨለማ በሁሉም የሚደረገውን ኀጢአት ሁሉ በአምላካችን በእግዚአብሔር ፊት እንናገር ዘንድ መጣን አሉ፤ አዳምና ሚስቱም ስለ አቤል አራት የዘመን ሱባዔ እያለቀሱ ኖሩ።'),
  ('2c90d0d6-43ea-5b63-a502-24743777d49c', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 13, 13, 'አዳምም በአምስተኛው ሱባዔ በአራተኛው ዓመት ደስ አለው። ዳግመኛ ሚስቱን በግብር ዐወቃት፤ ወንድ ልጅም ወለደችለት። “ቃየን ስለ ገደለው ስለ አቤልም እግዚአብሔር በምድር ሌላ ዘር አስነሥቶልናል” ብሎአልና ስሙን ሴት አለው።'),
  ('49758b35-741b-5722-a522-c091b2addf5e', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 14, 14, 'በስድስተኛው ሱባዔ ልጁን አዙራን ወለዳት፥ ቃየንም እኅቱ አዋንን ሚስት ትሆነው ዘንድ አገባት፤ በአራተኛውም ኢዮቤልዩ መጨረሻ ኤኖሕን ወለደችለት።'),
  ('a3466e7a-ec4d-58a9-a549-58e5d7e1dae0', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 15, 15, 'በአምስተኛው ኢዮቤልዩ በመጀመሪያው ሱባዔ በአንደኛው ዓመት በምድር ቤቶች ተሠሩ። ቃየንም ከተማ ሠራ፤ ስምዋንም በልጁ በኤኖሕ ስም ጠራት።'),
  ('b8315313-c3f2-55a9-a2ea-65a5c7f1759c', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 16, 16, 'አዳምም ሚስቱ ሔዋንን በግብር ዐወቃት። ዳግመኛም ዘጠኝ ልጆችን ወለደችለት።'),
  ('9788c1d1-3f1f-5caf-af4a-458a4da24fd7', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 17, 17, 'ሴትም በአምስተኛው ኢዮቤልዩ በአምስተኛው ሱባዔ እኅቱን አዙራን ሚስት አድርጎ አገባት።'),
  ('77996838-cc26-531b-a6b1-98b7fbe60f35', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 18, 18, 'በአራተኛውም ዓመት ሄኖስን ወለደችለት። እርሱም በምድር ላይ የእግዚአብሔርን ስም መጥራት የጀመረ ነው።'),
  ('e033d9bf-faa3-5586-a4f6-3108caae3fa9', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 19, 19, 'በሰባተኛው ኢዮቤልዩ በሦስተኛው ሱባዔ ሄኖስ ሚስት ትሆነው ዘንድ እኅቱ ኖአምን አገባ፤ በአምስተኛውም ሱባዔ በሦስተኛው ዓመት ወንድ ልጅ ወለደችለት፤ ስሙንም ቃይናን አለው።'),
  ('805525d9-b5be-50a7-a1c6-30413ddc8ed2', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 20, 20, 'በስምንተኛው ኢዮቤልዩ መጨረሻ ቃይናን እኅቱን ሙአሊሊትን ሚስት አድርጎ አገባት፤ በዘጠነኛው ኢዮቤልዩ በመጀመሪያው ሱባዔ በዚህም ሱባዔ በሦስተኛው ዓመት ወንድ ልጅን ወለደችለት፤ ስሙንም መላልኤል አለው።'),
  ('26d4088a-7172-5154-a384-dcf8e6d7a900', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 21, 21, 'በዐሥረኛው ኢዮቤልዩ በሁለተኛው ሱባዔ መላልኤል ሚስት ትሆነው ዘንድ የአባቱን ወንድም የበራኪሄልን ልጅ ዲናን አገባ። በሦስተኛውም ሱባዔ በስድስተኛው ዓመት ወንድ ልጅን ወለደችለት፥ ስሙንም ያሮድ አለው። በዘመኑ ትጉሃን የተባሉ የእግዚአብሔር መላእክት በምድር የሰው ልጆችን ያስተምሩ ዘንድ፥ በምድርም ፍርድንና ቅንነትን ያደርጉ ዘንድ ወደ ምድር ወርደዋልና።'),
  ('5416dc6d-1f50-5ada-a767-b6ecab7a9b15', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 22, 22, 'ያሮድም በዐሥራ አንደኛው ኢዮቤልዩ ሚስት አገባ፤ ስምዋም ባረካ ይባላል፤ ይህችውም የአባቱ'),
  ('55d86503-5dd0-5099-a9c0-1bc04ae8785a', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 23, 23, 'ሰዎች በየወራቸው እንደ ሥርዐታቸው የዘመናትን ጊዜ ያውቁ ዘንድ እንደ ወራቸው ሥርዐት የሰማይን ምልክት በመጽሐፍ ጻፈ።'),
  ('2751584b-07f6-59d2-a78f-38de973fa600', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 24, 24, 'እርሱም አስቀድሞ ምስክርን ጻፈ። ለሰው ልጆችም በየወገናቸው አሰማባቸው፤ እርሱም በሱባዔ የሚቈጠሩ ቍጥሮችን ተናገረ፤ የዘመኖችንም ቀኖች እርሱ ተናገረ፤ ወሮችንም ሠራ፤ እኛም እንደ ነገርነው ዘመኖችን የሚቈጥሩባቸው ሱባዔዎችን ተናገረ። የተደረገውንና ገና የሚደረገውንም ቍርጥ ፍርድ እስከሚደረግበት ቀን ድረስ በዘመናቸው በሰው ልጆች ላይ የሆነውንና የሚሆነውን ሌሊት በራእይ አየ፤ ዐወቀም።'),
  ('2d449b8f-cb5f-534b-aac2-134cd42ba90a', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 25, 25, 'ለምስክርነትም ጻፈው። በሰው ልጆችም ሁሉ ላይ በየትውልዳቸው በምድር ምስክር ሊሆን አኖረው።'),
  ('e37ea1b8-af54-54c7-a7f1-320700c8df36', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 26, 26, 'በዐሥራ ሁለተኛውም ኢዮቤልዩ በሰባተኛው ሱባዔ ሚስት አገባ። ስምዋም አድኒ ይባላል፥ ይህችውም የዳንኤል ልጅ የአባቱ እኅት ልጅ ናት፤ ለእርሱም ሚስት ልትሆነው አገባት።'),
  ('19497a78-1e4c-59ba-a0eb-7d82f3d93561', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 27, 27, 'በዚህም ሱባዔ በስድስተኛው ዓመት ወንድ ልጅን ወለደችለት። ስሙንም ማቱሳላ ብሎ ጠራው።'),
  ('cb5633b3-6540-54e1-a72b-b6404666cd5a', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 28, 28, 'ከዚህም በኋላ ከአምላክ መላእክት ጋር ስድስት የኢዮቤላት ዘመኖችን ኖረ። በምድርም ያለውን ሁሉ፥ በሰማይም ያለውን የፀሓይን ሥልጣን አሳዩት።'),
  ('57912a03-f74f-5f9a-a397-74b0b3435e8b', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 29, 29, 'ሁሉንም ጻፈ። ከሰው ልጆች ጋር በኀጢአት አንድ ሆነው በደል በሠሩት በትጉሃንም አዳኘባቸው። እነዚህ ከሰው ልጆች ጋር ይረክሱ ዘንድ፥ በግብርም አንድ ይሆኑ ዘንድ ጀምረዋልና፤ ሄኖክም በሁሉ ላይ አዳኘባቸው።'),
  ('3e4f5f1b-b093-5273-a1df-88c453a93ebb', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 30, 30, 'ከሰው ልጆችም መካከል ተወሰደ። ለጌትነትና ለክብርም ወደ ኤዶም ገነት ወሰድነው፤ እነሆ፥ እርሱ በዚያ የዘለዓለም ቅጣትንና ቍርጥ ፍርድን፥ የአዳምንም ልጆች ኀጢአት ሁሉ ይጽፋል።'),
  ('5bac4b84-0368-5246-a42c-26658baa60c1', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 31, 31, 'ለሰው ሁሉ ልጅ ያሰማ ዘንድ፥ ቍርጥ ፍርድም እስከሚደረግባት ቀን ድረስ የሰውን ሁሉ ሥራ ይናገር ዘንድ እርሱ ለምልክት ተሰጥቶአልና ስለ እርሱ በኤዶም ምድር ላይ ሁሉ የጥፋት ውኃን አመጣ።'),
  ('f240f74f-43ed-59d4-a29a-09cf3a95a6c5', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 32, 32, 'እርሱም እግዚአብሔር የሚቀበለውን ዕጣን በሠርክ አስቀድሞ ዕጣን በሚቃጠልበት በተቀደሰው ተራራ ላይ ዐጠነ፤ ለእግዚአብሔር በምድር አራት ቦታዎች አሉትና፥ እነዚህም የኤዶም ገነትና ደብረ ዘይት፥ ይህም ዛሬ አንተ በውስጡ ያለህበት ደብረ ሲናና ምድርን ለማንጻት በሚደረግ በአዲስ ፍጥረት የሚነጻ ደብረጽዮን ናቸው።'),
  ('6e8736ba-2624-5bfc-ac32-ab03903af46d', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 33, 33, 'ስለዚህም ምድር ከበደልና ከርኵሰት ሁሉ ለልጅ ልጅ ዘመን ትነጻለች።'),
  ('f6a2d020-03eb-5f73-ab4b-f575d73bdb5d', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 34, 34, 'በዐሥራ አራተኛው ኢዮቤልዩ ማቱሳላ ሚስቱን አድናን አገባ፤ ይህችውም የአባቱ እኅት ልጅ የአዝራኤል ልጅ ናት።'),
  ('7b561150-d3c0-598a-af3c-d43ceb43d3e4', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 35, 35, 'በስድስተኛው ሱባዔ በአንደኛው ዘመን ልጅን ወለደ። ስሙንም ላሜህ አለው።'),
  ('dbfe6982-bf8e-54cc-af76-c99a2c9b9b85', '02ca4088-0dc8-5ade-a2b5-297d8b74ca42', 'dc11eaed-75f3-5327-afab-3618d4db9187', 36, 36, 'በዐሥራ አምስተኛው ኢዮቤልዩ በሦስተኛው ሱባዔ ላሜህ ሚስት አገባ፤ ስምዋም ቤቴናስ ይባላል፥ ይህችውም የአባቱ የእኅት ልጅ የበራኪኤም ልጅ ናት፤ ሚስት ትሆነው ዘንድም አገባት።'),
  ('ca6e9665-85c3-56e7-a389-ffa9d0c6ed06', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 1, 1, 'በዚህም ሱባዔ ወንድ ልጅን ወለደችለት፥ ከሥራዬ ሁሉና ከኀዘኔ ሁሉ እግዚአብሔርም ከረገማት ምድር የሚያረጋጋኝ ነው ሲል ስሙን ኖኅ አለው።'),
  ('d3441218-7c18-50bb-ab03-11ea309da6d1', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 2, 2, 'በዐሥራ ዘጠነኛው ኢዮቤልዩ መጨረሻ በሰባተኛው ሱባዔ በስድስተኛው ዓመት አዳም ሞተ። ልጆቹም ሁሉ በተፈጠረበት ምድር ቀበሩት።'),
  ('a043aaa8-85b6-58b0-aacd-23f8a964a88c', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 3, 3, 'እርሱም አስቀድሞ በምድር ተቀበረ፤ ከሺህ ዓመትም ሰባ ዓመትን አጐደለ። ይህችውም በሰማይ ምስክር እንደ አንዲት ቀን ነበረች።'),
  ('bb990950-fd3f-5b6a-a023-d178ee2466dd', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 4, 4, '“ከእርሱ በምትበሉበት ቀን ትሞታላችሁ” ተብሎአልና ስለዚህ ዕውቀትን የሚያሳውቅ ዕፅን ስለ በላ ተጻፈ፤ በእርስዋ ሞቶአልና ስለዚህ ነገር የአንዲቱን ቀን ዓመቶች አልጨረሰም።'),
  ('1b20cec6-a030-5979-afa3-10bee1b7300d', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 5, 5, 'በዚህ ኢዮቤልዩ መጨረሻ ከአንድ ዓመት በኋላ ቃየን ሞተ፤ ቤቱ በላዩ ተናደ፤ በቤቱም ውስጥ በድንጋዮች ሞተ። አቤልን በድንጋይ ገድሎታልና በእውነት ፍርድ በድንጋይ ሞተ።'),
  ('5fd38259-ffde-5be3-a48c-a13092b96c9c', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 6, 6, 'ስለዚህ ሰው ባልንጀራውን በሚገድልበት መሣሪያ ይሞት ዘንድ እንዳቈሰለውም ያቈስሉት ዘንድ በሰማይ ጽላት ተጻፈ።'),
  ('61cde81a-f3a0-53c7-ab9d-b9fdf9eea3ff', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 7, 7, 'በሃያ አምስተኛው ኢዮቤልዩ ኖኅ ሚስት አገባ። ስምዋም አምዛራ ይባላል። ይህችውም'),
  ('28a73914-0961-5b79-ab34-3deadae6abf2', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 8, 8, 'በመጀመሪያው ዓመት በስድስተኛው ሱባዔ ያፌትን ወለደችለት።'),
  ('2dd6f3ea-e0a7-583b-aaf9-4d222ccae3d1', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 9, 9, 'የአዳም ልጆች በምድር ላይ ይበዙ ዘንድ በጀመሩ ጊዜ እንዲህ ሆነ፤ ሴቶች ልጆች ተወለዱላቸው። የእግዚአብሔር መላእክትም በዚህ ኢዮቤልዩ በአንዲቱ ዓመት እነዚህን አዩአቸው። እነዚያ ላዩአቸው መልከ መልካሞች ነበሩና ከመረጡአቸው ሁሉ ሚስቶች ሊሆኑአቸው ወሰዱአቸው፤ ወንዶች ልጆችንም ወለዱላቸው፤ እነዚህም ረዓይት ናቸው።'),
  ('9fde3b5c-a494-5718-ae42-0f896e420ba1', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 10, 10, 'ኀጢአትም በምድር ላይ በዛች፤ ሥጋ ለባሹም ሁሉ ከሰው ጀምሮ እስከ እንስሳና እስከ አራዊት እስከ ወፎችም፥ በምድር ላይ እስከሚኖረውም ሁሉ ድረስ መንገዱን አጠፋ። ሁሉም መንገዳቸውንና ሥርዐታቸውን አጠፉ። እርስ በርሳቸውም ይበላሉ ጀመር። ኀጢአትም በምድር ላይ በዛች። የሰዎችም ሁሉ ዐሳብ፥ በዘመኑ ሁሉ እንዲህ ክፉ ሆነ።'),
  ('cfb88465-702a-5547-a6fe-330cbb30e46d', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 11, 11, 'እግዚአብሔርም ምድርን ተመለከታት፤ እነሆም፥ ጠፍታ ነበር፤ ሰውም ሁሉ ሥርዐቱን አጠፋ፥ ሁላቸውም በምድር ላይ ያለውን ሁሉ በእግዚአብሔር ፊት አከፉት፤ እርሱም ሰውንና በምድር ላይ የፈጠረውን የሥጋ ወገንን ሁሉ አጠፋዋለሁ አለ።'),
  ('1f78cf2f-dabe-5796-a6de-edba4d8ee35d', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 12, 12, 'ኖኅ ብቻ በእግዚአብሔር ፊት ባለምዋልነትን አገኘ። ወደ ምድር በሰደዳቸው መላእክቱ ግን ተቈጣ፤ ከሥልጣናቸውም ለይቶ ፈጽሞ ያጠፋቸው ዘንድ አዘዘ። በምድር ጥልቅ ውስጥም አስረን እናግዛቸው ዘንድ አዘዘን።'),
  ('947e0775-03cb-51e7-a6f0-e8de6521f751', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 13, 13, 'እነርሱም እነሆ፥ በመካከላቸው ተግዘዋል፤ ብቻቸውንም ነበሩ። ከፊቱም በሰይፍ ያጠፋቸው ዘንድ፥ ከሰማይ በታችም ያርቃቸው ዘንድ በልጆቻቸው ላይ ቃል ወጣ።'),
  ('5af43cb6-1527-574c-aab5-abc0417fe424', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 14, 14, '“እነርሱ ሥጋውያን ናቸውና መንፈሴ በሰው ላይ ለዘለዓለም አያድርም። ዕድሜያቸውም መቶ ሃያ ዓመት ይሁን” አለ።'),
  ('b1c6c7b9-02c8-5a26-a4ec-31ccec435629', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 15, 15, 'እያንዳንዳቸው ባልንጀሮቻቸውን ይገድሉ ዘንድ በመካከላቸው ሰይፍን ሰደደ። ሁሉም በሰይፍ እስኪጠፉ ድረስ አንዱ ሌላውን ይገድል ዘንድ ጀመሩ፤ ከምድርም ጠፉ፤ አባቶቻቸው ግን ይመለከቱ ነበር።'),
  ('6144c894-7b7f-5a28-a87f-8d811a93f9f4', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 16, 16, 'ከዚህ በኋላ መንገዳቸውን ባፋለሱ ሁሉ ላይ ፍርድ ሊሆን እስከ ታላቋ የፍርድ ቀን ድረስ በምድር ጥልቅ ውስጥ ተጋዙ። ሥራቸውም በእግዚአብሔር ፊት ነው፤ ከቦታቸውም ሁሉን አጠፋ፥ በኀጢአታቸውም ሁሉ ያልተፈረደበት ከእነርሱ አንድ ስንኳ አልቀረም።'),
  ('cc7bd78c-0ef3-5f3c-ab9e-53f9548ea847', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 17, 17, 'በፍጥረታቸው ሁሉ እስከ ዘለዓለም ድረስ እንዳይበድሉ፥ ሁሉም በየወገኑ በዘመኑ ሁሉ የጽድቅ ሥራን እንዲሠራ ለፍጥረቱ ሁሉ አዲስና እውነተኛ ፍጥረትን ፈጠረላቸው።'),
  ('ca66a213-721a-5e42-ac54-1316e57827d6', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 18, 18, 'የሁሉም ቅጣት ተዘጋጀ፥ በሰማይም ጽላት ያለ ዐመፃ ተጻፈ። ሁሉም ጸንተው ይኖሩባት ዘንድ ከተሠራችላቸው ሥርዐታቸው የወጡ ናቸው።'),
  ('22e22679-2702-58c2-a1a2-f44b3f5baa40', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 19, 19, 'ጸንተው ባይኖሩባትም ለፍጥረቱ ሁሉ ለየወገኑም ሁሉ ፍርድ ተጻፈ። በሰማይና በምድር፥ በብርሃንና በጨለማ፥ በሲኦልና በጥልቅም፥ በጨለማም ምንም የለም።'),
  ('fa655ef0-14fb-5bf9-aa05-9a36b3a463f7', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 20, 20, 'ፍርዳቸውም ሁሉ ተዘጋጀ፥ የተቀረፀና የተጻፈም ነው። ስለዚህም ታላቁን እንደ ታላቅነቱ፥ ታናሹንም እንደ ታናሽነቱ እያንዳንዱን እንደ ኀጢአቱ ይፈርድበታል።'),
  ('32178164-a649-509d-aa66-5c7501041c7c', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 21, 21, 'እርሱ ፊት አይቶ የሚያደላ አይደለም። ለእያንዳንዱም ፍርድ አደርጋለሁ ባለ ጊዜ እርሱ መማለጃን የሚቀበል አይደለም፤ እያንዳንዱም በምድር ያለ ሰው ያለውን ሁሉ ቢሰጥ ፊትን አይቶ አያደላም፤ የእውነት ዳኛ ነውና ከእርሱ መማለጃ አይቀበልም።'),
  ('37cdb359-0066-59c1-a4d5-272fba6e2497', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 22, 22, 'ይህ በእስራኤል ልጆች ላይ ተጽፎ ተሠራ። በእውነትም ወደ እርሱ ከተመለሱ በደላቸውን ሁሉ ይቅር ይላቸዋል። ኀጢአታቸውንም ሁሉ ያስተሰርይላቸዋል።'),
  ('8f7d8f0b-f88f-5c14-a4cd-26e6f9910cf0', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 23, 23, 'ከኀጢአታቸውም ሁሉ የተመለሱ ሰዎች ሁሉ በየዓመቱ አንድ ጊዜ ይቅር ይባሉ ዘንድ ተጽፎ ተሠራ። ከጥፋት ውኃም አስቀድሞ ሥርዐታቸውንና ምክራችውን ባጠፉ ሰዎች ሁሉ ላይ ተጻፈ።'),
  ('d06c8ec9-5743-51eb-a26c-630f1dcce698', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 24, 24, 'በእርሱ ምክንያት ከጥፋት ውኃ ስላዳናቸው ልጆቹ እርሱ ባለምዋልነትን አግኝቶአልና ከኖኅ ብቻ በቀር እነርሱ ባለምዋልነትን አላገኙም። ስለ እርሱም እንደ ታዘዘ በመንገዱ ሁሉ ልቡ እውነተኛ ናትና ከተሠራለት ሕግ ሁሉ አልወጣም።'),
  ('0ed394a2-d522-535e-ac8b-b73692e0f5e6', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 25, 25, 'እግዚአብሔርም፥ “በምድር ላይ ያለው ሁሉ ከሰው ጀምሮ እስከ እንስሳና አራዊት፥ እስከ አዕዋፍና በምድር ላይ እስከሚንቀሳቀሰው ድረስ ይጥፉ” አለ።'),
  ('9c0fc966-3715-528b-a1a6-6b87e22de630', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 26, 26, 'ከጥፋት ውኃም ያድነው ዘንድ ኖኅን ለእርሱ መርከብን እንዲሠራ አዘዘው።'),
  ('86ca8a16-64d4-59fe-a58a-f815356afc6d', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 27, 27, 'ኖኅም ዓመታት በሚቈጠሩበት በሁለተኛው ኢዮቤልዩ በአምስተኛው ሱባዔ በአምስተኛው ዓመት እንዳዘዘው ሁሉ መርከብን ሠራ።'),
  ('06407779-94c8-5514-ad36-eed80df7991b', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 28, 28, 'በስድስተኛውም ዓመት በሁለተኛው ወር እስከ ዐሥራ ስድስተኛው ቀን ድረስ እርሱ ገባ። ያገባንለትም ሁሉ ወደ መርከብ ገባ።'),
  ('19a7951a-eb19-5db2-a57d-0c01a13ca6da', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 29, 29, 'እግዚአብሔርም በዐሥራ ሰባተኛው ቀን ማታ መርከቡን በውጭ ዘጋው፤ እግዚአብሔርም ሰባቱን የሰማይ ሻሻቴና ሰፊ የሆነ የጥልቁን ምንጮች አፍ በሰባት ስቍረት ከፈተ።'),
  ('93685df7-c943-5143-abf6-09208eac6809', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 30, 30, 'ሻሻቴዎችም ከሰማይ አርባ ቀንና አርባ ሌሊት ዝናብን ያወርዱ ዘንድ ጀመሩ።'),
  ('66713dde-7f23-5d89-a409-7f428de9af0a', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 31, 31, 'የጥልቁም ምንጮች ዓለሙ ሁሉ ውኃን እስኪሞላ ድረስ ውኃዎችን ያወጡ ነበር፤ ውኃዎችም በምድር ላይ በዙ፤ ውኃውም በረጅሙ ተራራ ሁሉ ላይ ዐሥራ አምስት ክንድ ከፍ ከፍ አለ።'),
  ('45b2edfd-2362-525c-a810-5118d672813b', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 32, 32, 'ውኃዎችም ከፍ ከፍ አሉ። መርከቢቱም በምድር ላይ ከፍ ከፍ አለች። በውኃውም ላይ ትመላለስ ነበር፤ ውኃዎችም በምድር ላይ አምስት ወር ማለት መቶ አምሳ ቀን ቈዩ። መርከቢቱም ሄደች፥ ከአራራት ተራራዎችም በአንዱ ሉባር በሚባል ተራራ ራስ ላይ ዐረፈች።'),
  ('ca5be7d1-53b6-5e1b-a477-78dc8af9f8ae', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 33, 33, 'በአራተኛውም ወር ሰፊ የሆነ የጥልቁ ምንጮች ተገቱ። የሰማዩም ሻሻቴ ተገታ።'),
  ('4b93ee71-c2b0-5b3a-a582-99b5836227d3', '8c6632e9-c18d-5bd1-ae76-ad0eadde4e0e', '9fe2969b-7ec2-5fd6-a719-543f3808eae0', 34, 34, 'በሰባተኛውም ወር መባቻ የምድሩ ጥልቅ አፍ ሁሉ ተከፈተ። ውኃዎችም ወደ ታችኛዪቱ ጥልቅ ይወርዱ ጀመር።'),
  ('48e19bc0-383c-58e1-a7c1-cf18c5164cfd', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 1, 1, 'በዐሥረኛው ወር መባቻም የተራሮች ራሶች ታዩ፤ በመጀመሪያው ወር መባቻም ምድር ታየች፤ ውኃዎችም በአምስተኛው ሱባዔ በሰባተኛው ዓመት ከምድር ላይ ደረቁ። በዐሥራ ሰባተኛውም ቀን በሁለተኛው ወር ምድር ደረቀች።'),
  ('cdcd322f-ad38-502d-ad6e-fe1b329bb0d6', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 2, 2, 'በሃያ ሰባተኛውም ቀን መርከቢቱን ከፈታት፤ ከውስጥዋም አራዊትንና ወፎችን፥ የሚንቀሳቀሰውንም ሁሉ ሰደደ። በሦስተኛውም ወር መባቻ ኖኅ ከመርከብ ወጣ። በዚህም ተራራ ላይ መሠዊያን ሠራ፤ ለምድርም አስተሰረየ። ከኖኅ ጋር በመርከብ ካሉት በቀር በእርስዋ ያለው ሁሉ ጠፍቶአልና የፍየል ጠቦት ሠውቶ በደሙ የምድርን ኀጢአት ሁሉ አስተሰረየ።'),
  ('944f9f48-d7b9-5276-ad1d-6396ece396b3', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 3, 3, 'ስቡንም በመሠዊያው ላይ አጤሰ። ላምን ፍየልንና የበግ አውራን፥ ጨውን፥ ርግብንና ዋኖስንም ሠውቶ በመሠዊያው ላይ ስቡን አሻተተ። በዘይት የታሸ መሥዋዕትንም በእነርሱ ላይ ጨመረ።'),
  ('43bc9177-a0ad-5a11-affd-821d89e5ed28', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 4, 4, 'ደሙንና ወይኑንም አምጥቶ በሁሉ ላይ ዕጣን ጨመረበት። እግዚአብሔርም የሚወደውን በጎ መዓዛ አድርጎ አቀረበ።'),
  ('d5f4cf34-04aa-5daa-a005-d327a3143546', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 5, 5, 'እግዚአብሔርም በጎ መዓዛውን ተቀበለው፤ የጥፋትም ውኃ ምድርን እንዳያጠፋ ከእርሱ ጋር ቃል ኪዳን አደረገ። እንዲህም አለ፥ “በምድርም ዘመን ሁሉ ዘርና አዝመራ አይቋረጥም፤ ብርድና ሙቀት፥ በጋና ክረምት፥ ቀንና ሌሊት ሥርዐታቸውን አይለውጡም። ለዘለዓለሙም አይቋረጡም።'),
  ('2d3d987f-53ca-5a4b-ab86-f4f03eba9ba9', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 6, 6, '“እናንተም ብዙ፥ በምድርም የብዙ ብዙ ሁኑ፥ በላይዋም ብዙ፥ ለበረከትም ሁኑ፤ ከእናንተም የተነሣ መፍራትንና መንቀጥቀጥን በምድርና በባሕር ውስጥ ባሉ ሁሉ ላይ አመጣለሁ።'),
  ('c8024f1a-9ec6-5785-ae47-f3f8c07c306a', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 7, 7, 'እነሆ፥ አውሬዎችንና ከብቶችን ሁሉ፥ በክንፍ የሚበሩትንና በምድርና በባሕር ውስጥ የሚንቀሳቀሱትን ዓሣዎችን ሰጠኋችሁ፥ ሁሉንም ትበሉ ዘንድ ልምላሜውን ለምግብነት ሰጠኋችሁ።'),
  ('905a2da4-ebd8-5cea-a663-e79da15ba703', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 8, 8, 'ነገር ግን ደም የነፍስ ማደሪያ ነውና ከሰውነታችሁ መካከል ደማችሁን እንዳልፈልግ ደመ ነፍስ ያለችበትን ሥጋ አትብሉ። ከሰውም ሁሉ እጅ፥ ከአራዊትም ሁሉ እጅ የሰውን ደም እመራመራለሁ፤ የሰውንም ደም ያፈሰሰ ደሙ ይፈስሳል፥ እግዚአብሔርም አዳምና ሔዋንን በእርሱ መልክ ፈጥሮአቸዋልና እናንተ ብዙ፤ በምድርም ላይ የብዙ ብዙ ሁኑ” አላቸው።'),
  ('5249107e-cbd9-515d-ac85-e36cffb9e2c3', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 9, 9, 'ኖኅና ልጆቹም በሥጋው ሁሉ ያለ ብርንዶውን ሁሉ እንዳይበሉ ማሉ። በምድር ዘመን ሁሉ በዚህ ወራት በዘለዓለማዊ አምላክ በእግዚአብሔር ፊት ቃል ኪዳን ገባ።'),
  ('db2ce2f7-c015-53ec-a0f8-0887f48bb9be', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 10, 10, 'ስለዚህም፥ “አንተ'),
  ('54421592-1523-553c-ab58-8eaaafce4f70', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 11, 11, 'በምድርም ዘመን ሁሉ የወፎችንና የአውሬዎችን ሥጋ ሁሉ እንዳትበሉ በዘመኑ ሁሉ ትጠብቁአት ዘንድ ይህች ምስክር በእናንተ ላይ የተጻፈች ናት።'),
  ('f9f8407c-98ef-596f-ad72-8b1bde7f545e', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 12, 12, 'በምድርም ዘመን ሁሉ የአውሬውን፥ የከብቶችንና የወፎችን ሥጋ ብርንዶውን የበላ ሰው እርሱና ዘሩ ከምድር ይጠፋሉ።'),
  ('2097e3ed-d33b-52d1-a90b-77f6818a4405', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 13, 13, 'አንተም በዘመኑ ሁሉ በአምላካችን በእግዚአብሔር ፊት ስማቸውና ዘራቸው ጸንቶ ይኖር ዘንድ ብርንዶውን ሁሉ እንዳይበሉ የእስራኤልን ልጆች እዘዛቸው።'),
  ('296c6f01-334b-51de-a128-fccd797c0075', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 14, 14, 'በቀኑ ሁሉ በመሠዊያው አንጻር በደም ስለ እናንተ እየለመኑ እንዲኖሩ ለልጅ ልጅ ይጠብቁት ዘንድ የዘለዓለም ሕግ ነውና ለዚህ ሕግ የዘመን ፍጻሜ የለውም። ይጠብቁትም ዘንድ እንዳይጠፉ ማታና ጥዋት ስለ እነርሱ ሁልጊዜ በእግዚአብሔር ፊት ኀጢአታቸውን ያስተሰርያሉ።'),
  ('00c91537-abf1-5cc9-ae6f-c02b9912e9ac', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 15, 15, '“ዳግመኛም በምድር ላይ ጥፋት እንዳይሆን ለኖኅና ለልጆቹ የቃል ኪዳኑን ምልክት ሰጣቸው፤ እርስዋንም ዳግመኛ ለማጥፋት በዘመኑ ሁሉ በምድር ላይ የጥፋት ውኃ እንዳይሆን ለዘለዓለም ለቃል ኪዳኑ ምልክት ቀስቱን በደመና ውስጥ ሰጠ።'),
  ('b9ad41b9-caa3-5a2c-a9b3-2f9a8ee6501b', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 16, 16, '“ስለዚህም በዘመኑ ሁሉ ለአዲስ ኪዳን በየዓመቱ አንድ ጊዜ በዚህ ወር የሱባዔያትን በዓል የሚያደርጉ ይሆኑ ዘንድ ተሠራ፤ በሰማይ ጽላትም ተጻፈ።'),
  ('e627b509-150f-51ff-aa9a-f6d4357fdb3c', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 17, 17, 'ይህችም በዓል ከፍጥረት ቀን ጀምሮ እስከ ኖኅ ዘመን ድረስ በሰማይ ስትሠራ ኖረች፤ ይኸውም ሃያ ሰባት ኢዮቤልዩና አምስት የዓመት ሱባዔ ነው። ኖኅና ልጆቹም፥ ኖኅ እስከሚሞትባት ቀን ድረስ ሰባት ኢዮቤልዩና አንድ የዓመት ሱባዔ ጠበቁት።'),
  ('e274437e-8b86-5fd6-a7e1-8fdaad6bd8dc', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 18, 18, 'ኖኅ ከሞተ በኋላም እስከ አብርሃም ዘመን ድረስ ልጆቹ ሕግን አፈረሱ፤ ብርንዶውንም በሉ። ነገር ግን አብርሃም ብቻ ሕግን ጠበቀ፤ ይስሐቅና ያዕቆብም እስከ አንተ ዘመን ድረስ ጠበቁት። በዘመንህም በዚህ ተራራ እስካድሳቸው ድረስ የእስራኤል ልጆች ሕግን ዘነጉ።'),
  ('7ccc2dbb-24ca-5d54-ab89-0e966000035b', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 19, 19, 'አንተም የእስራኤልን ልጆች እዘዛቸው፤ ይህችንም በዓል በትውልዳቸው ሁሉ ለእነርሱ እንደ ታዘዘ ይጠብቁአት። በሱባዔ የምትደረግ በዓል ናትና በዓመት አንድ ቀን በዚህ ወር ይህችን በዓል ያድርጉ።'),
  ('30d73541-2e58-55d6-a368-d7f685d80233', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 20, 20, 'የመጀመሪያውም አዝመራ የሚሰበሰብባት በዓል ናትና። ይህችውም ሁለት ቀን በዓል የሚያደርጉባት ሁለት አይነት በዓል ናት። በየጊዜዋም ታደርጋት ዘንድ በጻፍሁልህ በዚህ በመጀመሪያው የሕግ መጽሐፍ ጽፌልሃለሁና ስለ እርስዋ ሥራዋ እንደ ተጻፈና እንደ ተቀረፀ ከዓመት አንድ ቀን ጠብቃት።'),
  ('f1ad18af-e221-528a-a744-fb19c3f373bc', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 21, 21, 'የታሰቡም ይሆኑ ዘንድ፥ የእስራኤልም ልጆች በየወገናቸው ለእያንዳንዱ ዓመት በዚህ ወር አንድ ቀን ያደርጉአት ዘንድ ቍርባኑን ነገርሁህ።'),
  ('7dc9e4b0-f187-5a8e-ac4b-02999805ed1f', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 22, 22, '“በመጀመሪያው ወር መባቻ፥ በአራተኛውም ወር መባቻ፥ በሰባተኛውም ወር መባቻ፥ በዐሥረኛውም ወር መባቻ እነዚህ የመታሰቢያ ቀኖች ናቸው። በአራቱም ክፍለ ዓመት፥ ጊዜ ያላቸው ቀኖች ናቸው፤ እነዚህም'),
  ('2146367e-8392-5723-a905-4a9e118b3a75', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 23, 23, 'ኖኅም እነርሱ ለእርሱ መታሰቢያ እስኪሆኑለት ድረስ በዓላትን ለልጅ ልጅ ለዘለዓለም ሠራቸው።'),
  ('1051c1ea-8eb6-57c0-a539-4b04f8e910be', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 24, 24, 'በመጀመሪያው ወር መባቻ ለራሱ መርከብን ይሠራ ዘንድ ተነገረው፤ በእርስዋም ምድር ደረቀች፤ መስኮቱንም ከፍቶ ምድርን አየ።'),
  ('9a30b9a0-d0af-5ce4-a54f-50b473cbc031', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 25, 25, 'በአራተኛው ወር መባቻ የታችኛው የጥልቁ ምንጭ አፍ ተዘጋ። የሰማዩም ሻሻቴ ተገታ።'),
  ('641cf263-9353-5a94-a056-63572307a38e', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 26, 26, 'በሰባተኛው ወር መባቻ በምድር ያለ የምንጭ ውኃ ጕድጓድ ሁሉ ተከፈተ፤ ውኃዎችም ወደ ታችኛው ጥልቅ ይወርዱ ጀመር።'),
  ('a9a2f711-070d-585a-ade5-0e7c8d2975b3', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 27, 27, 'በዐሥረኛውም ወር መባቻ የተራሮች ራሶች ታዩ፥ ኖኅም ደስ አለው፤ ስለዚህም እነርሱን እስከ ዘለዓለም ድረስ ለመታሰቢያ በዓላት አደረጋቸው። እነዚህ እንዲህ የተሠሩ ናቸው፤ ወደ ሰማይ ጽላትም ያወጡአቸዋል።'),
  ('950d20c6-7a74-5f59-afee-562b978c170f', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 28, 28, 'ከእነርሱም እያንዳንድዋ ከዚችኛዪቱ እስከዚያችኛዪቱ መታሰቢያ፥ ከመጀመሪያዪቱ እስከ ሁለተኛዪቱ፥ ከሁለተኛዪቱ እስከ ሦስተኛዪቱ፥ ከሦስተኛዪቱ እስከ አራተኛዪቱ ድረስ ዐሥራ ሦስት ሱባዔ ናቸው።'),
  ('b9c0b2ae-8971-5b29-a165-c525141f4402', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 29, 29, 'የትእዛዛት ቀኖች ሁሉ ቀን የሚቈጠርባቸው አምሳ ሁለት ሱባዔ ይሆናሉ። ፍጹም የሆነ ዓመቱ ሁሉ እንዲህ ተቀርፆና ተቈጥሮ በሰማይ ጽላት ተጻፈ። አንድ ዓመትና ሁለት ዓመት፥ ሦስት ዓመትም መተላለፍ የለውም።'),
  ('8c291e46-11ac-5ad8-a2c7-74a99147da1a', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 30, 30, 'አንተም የእስራኤልን ልጆች በዓመቱ በዚህ ቍጥር ሦስት መቶ ስድሳ አራት ቀንን ይጠብቁ ዘንድ እዘዛቸው፤ ፍጹም ዓመትም ይሆናል። ጊዜውንም ከቀኑና ከበዓሉ አሳልፈው አያጥፉ። ሁሉ እንደ ምስክርነታቸው ይደርስባቸዋልና ቀኑን አያስቀሩ፤ በዓሉንም አያጥፉ።'),
  ('62fb5354-a991-50c9-a332-117562cc6479', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 31, 31, 'ቢተላለፉአቸውም፥ እንደ እርሱ ትእዛዝም ባያደርጉአቸው ያን ጊዜ ሁሉም ጊዜዎቻቸውን ያጠፋሉ።'),
  ('d4714e04-f4fc-5f8f-a5c7-bb64893d5cea', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 32, 32, 'ዓመታትም ከዚህ ወደዚያ ይለዋወጣሉ፤ ጊዜያትም ይጠፋሉ፤ ዓመታቱም ይለዋወጣሉ፤ ሥርዐታቸውንም ያፈርሳሉ፤ የእስራኤልም ልጆች ሁሉ ይዘነጋሉ። የዓመታትንም መንገድ አያገኙም፤ መባቻውን ይረሳሉ፤ ጊዜውንና ሱባዔውን፥ የዘመኑንም ሥርዐት ሁሉ ያፈርሳሉ።'),
  ('faa978b3-0371-5e35-adb2-95fc321e07b2', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 33, 33, 'እኔ አውቃለሁና፥ እንግዲህ ወዲህ እኔ እነግርሃለሁ፤ እንዲህ ያለ መጽሐፍ በፊቴ ተጽፎአልና፥ የምነግርህ ከልቤ አይደለም፤ ከሳቱ በኋላ አእምሮአቸውንም ካጡ በኋላ የቃል ኪዳኑን በዓል እንዳይረሱ፥ በአሕዛብ በዓላትም እንዳይሄዱ የዘመኑ አከፋፈል በሰማይ ጽላት ተጻፈ።'),
  ('862799b8-9e94-57df-a597-25e83ef1c774', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 34, 34, '“እርስዋ ጊዜያትን ትለውጣለችና፥ ከዓመታትም ለዓመት ዐሥር ቀን ትቀድማለችና፥ በጨረቃ አጐዳደል ጨረቃን የሚመለከቱ ይሆናሉ።'),
  ('77c9b56a-b314-5270-a3a4-3cb814994a27', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 35, 35, 'ስለዚህ ሥርዐትን ከለወጡ በኋላ ዓመታት ይመጡላቸዋል፤ ምስክር የምትሆን ቀንንም የተናቀች ያደርጋሉ። የረከሰችውምን ቀን በዓል ያደርጋሉ፤ ሁሉንም ይቀላቅላሉ፤ የተቀደሱትን ቀናት የረከሱ፥ የረከሱትንም ቀናት ለቅድስና ያደርጋሉ፤ ወራቶችንና ሱባዔዎችን፥ በዓላቱንና ኢዮቤላቱን ይስታሉና።'),
  ('2d8a0642-a3d1-5d04-a683-e2524edc5d1e', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 36, 36, 'ስለዚህም እኔ አዝዝሃለሁ፤ ልጆችህ አንተ ከሞትህ በኋላ ሦስት መቶ ስድሳ አራቱን ቀን ብቻ ዓመትን እንዳያደርጉ ሥርዐትን ይለውጣሉና ታዳኝባቸው ዘንድ አዳኝብሃለሁ።'),
  ('ac2103c3-8cf7-5db6-af18-839f4ca7a73a', '5aa2fb1c-00a3-5f5f-a962-634cabdafd14', '11b75956-c410-5eef-ad20-9e0d9d8e7560', 37, 37, 'ስለዚህም የወሩን መባቻና ሱባዔውን፥ ጊዜውንና በዓላቱን ይስታሉ፤ ከሰው ሁሉ ጋር ብርንዶውን ሁሉ ይበላሉ።”'),
  ('394a5b1b-6983-5780-a98e-9fec4e243145', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 1, 1, 'በዚህ ኢዮቤልዩ በሰባተኛው ሱባዔ በመጀመሪያው ዓመት መርከቢቱ ባረፈችበት ስሙ ሉባር በሚባል ከአራራት ተራሮች በአንዱ ተራራ ላይ ኖኅ ወይንን ተከለ።'),
  ('2cce422a-2f1e-5b47-a9e8-ac30e7e980c1', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 2, 2, 'በአራተኛውም ዓመት አፈራ፤ ፍሬውንም ጠበቀ፤ በዚያውም ዓመት በሰባተኛው ወር ፍሬውን ለቀመ። ከእርሱም ጠጅ ጥሎ በዕቃ አኖረው፥ እስከ አምስተኛውም ዓመት እስከ መጀመሪያው ወር መጀመሪያዪቱ ቀን ድረስ ጠበቀው።'),
  ('df4706c1-fc85-575c-a31e-aaca0183739d', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 3, 3, 'ይህችንም ቀን በደስታ በዓል አደረገ፥ ለእግዚአብሔርም የሚቃጠል መሥዋዕትን ሠዋ። የራሱንም ኀጢአት ያስተሰርይበት ዘንድ ከላሞች አንድ ወይፈንን፥ አንድ የበግ አውራን፥ ዓመት የሆናቸው ሰባት በጎችን፥ አንዲት የፍየል ጠቦትንም ሠዋ።'),
  ('aafed223-b363-55b2-a26f-10be6a6a3dff', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 4, 4, 'ስለ ልጆቹም አስቀድሞ ጠቦትን ሠዋ፤ ከደሙም በሠራው መሠዊያ ላይ ባለው ሥጋ ላይ አኖረ። የሚቃጠል መሥዋዕትንም በሠዋበት መሠዊያ ላይ ስቡን ሁሉ አጤሰ። ላሙንና የበጉን አውራ፥ በጎቹንም ሠውቶ ሥጋቸውን ሁሉ በመሠዊያው ላይ አኖረ። በዘይት የተለወሰ መሥዋዕታቸውንም ሁሉ በላያቸው አኖረ።'),
  ('a4576495-cb4d-53a9-aa06-21e6997cf911', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 5, 5, 'ከዚህም በኋላ በመሠዊያው ላይ ባለው እሳት ላይ ወይኑን ረጨ። አስቀድሞ ዕጣኑን በመሠዊያው ላይ አኖረ፤ እግአብሔር የሚወደውንም በጎ መሥዋዕት ሠዋ። መሥዋዕቱም ወደ አምላኩ ወደ እግዚአብሔር ዐረገ፤ ከዚህም ወይን ጠጥቶ ደስ አለው። ልጆቹንም ደስ አላቸው።'),
  ('d148f579-f569-5baa-a340-40c7ab2722f2', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 6, 6, 'በመሸም ጊዜ ወደ ድንኳኑ ገብቶ ሰክሮ ተኛ፤ በድንኳኑም ተኝቶ ዕርቃኑን ጣለ።'),
  ('bd72133b-fe33-5d78-a0d5-bed1c89ad12c', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 7, 7, 'ካምም አባቱ ኖኅን ዕራቁቱን እንደ ሆነ አየ፤ ወጥቶም በውጭ ለነበሩ ለሁለቱ ወንድሞቹ ነገራቸው።'),
  ('42d17b9d-9762-5ef6-a2e1-e3a72521c6f4', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 8, 8, 'ሴምም ልብሱን ይዞ ተነሣ፤ እርሱና ያፌትም ልብሳቸውን ከጫንቃቸው አውርደው አለበሱት፥ ፊታቸውንም ወደ ኋላ መልሰው የአባታቸውን ኀፍረት ሸፈኑ።'),
  ('96c1a643-f5f0-5833-ac7c-4ea4c7ca4972', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 9, 9, 'ኖኅም ከእንቅልፉ በነቃ ጊዜ ታናሹ ልጁ በእርሱ ላይ ያደረገበትን ሁሉ ዐወቀ፥ ልጁንም ረገመው፥ “የተረገመ ከነዓን ለወንድሞቹ ተገዥ ባሪያ ይሁን” አለ።'),
  ('8deb5f81-9540-5ebc-afe0-c4bada8bc2a7', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 10, 10, 'ሴምንም መረቀው፤ እንዲህም አለ፥ “የሴም አምላክ እግዚአብሔር ይመስገን፤ ከነዓንም ባሪያው ይሁን፤ እግዚአብሔርም የያፌትን ሀገር ያስፋለት፥ እግዚአብሔርም በሴም ድንኳን ይደር፤ ከነዓንም ባሪያው ይሁን።”'),
  ('f58b11a6-b89e-5bf4-a00b-5aa561f53f4e', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 11, 11, 'ካምም አባቱ ታናሹን ልጁን እንደ ረገመው ዐወቀ። ልጁንም ረግሞታልና ለእርሱ ክፉ ነገር ሆነበት፤ እርሱም ከአባቱ ተለየ፤ ልጆቹም ከእርሱ ጋር ነበሩ። እነዚህም ኩሽና ሜስራይም፥ ፉጥና ከነዓን ናቸው። እርሱም ከተማን አቀና፤ የከተማዪቱንም ስም በሚስቱ ስም አኤልታማክ ብሎ ጠራት።'),
  ('0f168cba-68ff-5f0d-a816-c0191a4c980f', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 12, 12, 'ያፌትም አይቶ በወንድሙ ቀና፤ እርሱም ከተማን አቀና፤ ስምዋንም በሚስቱ ስም አዶታኔስስ ብሎ ጠራት።'),
  ('23f75623-d241-548d-a708-2b494c76690a', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 13, 13, 'ሴም ግን ከአባቱ ከኖኅ ጋር ተቀመጠ፤ በአባቱም እጅ በተራራው ላይ ከተማን አቀና፤ እርሱም ስምዋን በሚስቱ በሴዴቄተልባብ ስም ጠራ።'),
  ('36d18a4c-15d1-5b62-a5ff-335856972955', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 14, 14, 'እነዚህም ሦስቱ ከተሞች፥ እነሆ፥ በሉባር ተራራ አቅራቢያ ናቸው። ሴዴቄተልባብም በተራራው አንጻር በምሥራቅ ናት፥ አኤልታማክም በሰሜን አንጻር ናት፤ አዶታኒስስም በምዕራብ ናት።'),
  ('153e87ab-1903-5c01-a2ba-1773de6801b6', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 15, 15, 'የሴምም ልጆች እነዚህ ናቸው፥ ኤላምና አሱር፥ አርፋክስድም ሉድና አራምም፥ እነዚህ የጥፋት ውኃ ከሆነበት ከአራተኛው ዓመት በኋላ የተወለዱ ናቸው። ያፌትም ጎሜርንና ማጎግን፥ ያዋንንና ቶቤልን፥ ሞሳክንና ቴራስን ወለደ። እነዚህ ሁሉ የኖኅ ልጆች ናቸው።'),
  ('5b5c9480-91b4-5cfd-a446-cfd0a6281ea6', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 16, 16, 'ኖኅም በሃያ ስምንተኛው ኢዮቤልዩ ለልጅ ልጆቹ ሥርዐትንና ትእዛዝን፥ የሚያውቀውንም ፍርድ ሁሉ ያዝዝ ጀመረ። እውነትንም ያደርጉ ዘንድ፥ የሰውነታቸውንም ኀፍረት ይሸፍኑ ዘንድ፥ የፈጠራቸው እግዚአብሔርንም ያመሰግኑ ዘንድ፥ አባትና እናታቸውንም ያከብሩ ዘንድ፥ እያንዳንዳቸውም ባልንጀራቸውን ይወድዱ ዘንድ፥ ሰውነታቸውንም ከዝሙትና ከርኵሰት፥ ከበደልም ይጠብቁ ዘንድ ያዝዛቸው ጀመር።'),
  ('fedffe38-4317-5ed9-ad3b-bdce2d223324', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 17, 17, 'ትጉሃን ከታዘዘላቸው ሕግ ወጥተው ከሰው ልጆች ጋር ስላደረጉት ዝሙት በእነዚህ በሦስቱ ኀጢአቶች በምድር ላይ የጥፋት ውኃ ተደርጎአልና።'),
  ('7bc30f9a-eced-50e2-aea4-7feda0f7fbc2', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 18, 18, 'ከመረጡአቸው ሴቶችም ሁሉ ሚስቶችን አገቡ፥ አስቀድመውም ርኵሰትን ሠሩ። ኀይለኞች ልጆችንም ወለዱ፤ ሁሉም አይመሳሰሉም ነበሩ።'),
  ('0a424b28-d3d5-57d8-a25c-0e1eb5580786', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 19, 19, 'እያንዳንዱም ባልንጀራውን ይበላው ነበር። አርበኛውም ናፊልን ገደለው፤ ናፊልም ኢልዮንን ገደለው፥ ኢልዮንም የሰውን ልጅ ገደለው። ሰውም ባልንጀራውን ገደለው፤ ሁሉም ዐመፅን ያደርግ ዘንድ፥ ንጹሕ ደምንም ያፈስስ ዘንድ ተመለሰ። ምድርም ዐመፅን ተሞላች፥ ከእነዚህም ሁሉ በኋላ በአውሬዎችና በወፎች፥ በምድር ላይም በሚንቀሳቀሰውና በሚመላለሰው ሁሉ ላይ በደሉ።'),
  ('eb1b9f4a-b189-5abc-adac-06e1dde81524', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 20, 20, 'በምድርም ላይ ብዙ ደም ፈሰሰ፤ የሰውም ልቡናውና ፈቃዱ በዘመኑ ሁሉ ከንቱና ክፉ ነገርን ያስቡ ጀመር።'),
  ('413b23b8-6e24-5f54-a3a4-f5a38d02b522', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 21, 21, 'እግዚአብሔርም ስለ ክፉ ሥራቸው በምድር ሁሉ ፊት ሁሉን አጠፋ። በምድርም ስላፈሰሱት ደም ሁሉን ደመሰሰ፤ “እኔና እናንተ ልጆች፥ ከእኛም ጋር ወደ መርከብ የገባው ሁሉ ቀረን።'),
  ('d3bdfe6a-2958-5b25-a86f-eacc4d973ad2', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 22, 22, 'በጥፋት ሥራ ጸንታችሁ ትኖሩ ዘንድ ጀምራችኋልና እናንተ በእውነት ሥራ ጸንታችሁ የምትኖሩ እንዳልሆናችሁ እነሆ፥ እኔ የቀደመ ሥራችሁን አየሁ። እያንዳንዳችሁ ከባልንጀራችሁ ትለያላችሁ፤ እርስ በርሳችሁም ትቀናናላችሁ።'),
  ('a3926f83-f81b-5292-aa75-237b34364fec', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 23, 23, 'ልጆች፥ አንዱ ከአንዱ ጋር በአንድነት እንደማትኖሩ እኔ አያለሁ፤ አጋንንትም በእናንተና በልጆቻችሁ ላይ እነሆ፥ ማሳት ጀመሩ።'),
  ('7444a794-6d1b-57a5-ad89-e7e10270c569', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 24, 24, 'አሁንም እኔ ከሞትሁ በኋላ በምድር ላይ የሰውን ደም ታፈስሳላችሁ፤ እናንተም ከገጸ ምድር ትጠፋላችሁ ብዬ እኔ ስለ እናንተ እፈራለሁ። የሰውን ደም የሚያፈስስ ሁሉና ብርንዶ የሚበላ ሁሉ፥ ሁሉም ከዚህ ዓለም ይጠፋሉና፤ ብርንዶንም የሚበላ ደምንም የሚያፈስስ ሁሉ በዚህ ዓለም አይቀርምና።'),
  ('d87a6a0f-027a-5875-a6e0-979b9ba214f5', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 25, 25, 'ወደ መቃብር ይሄዳሉና፥ ቍርጥ ፍርድ ወዳለበት ወደ ሲኦልም ይወርዳሉና፥ ሁሉም በክፉ ሞት ተይዘው ወደ ጨለማው ጥልቅ ይጣላሉና፥ ከሰማይ በታች ልጅ፥ የልጅ ልጅም በሕይወት አይቀርለትም።'),
  ('9b64c459-79fe-5764-a5cf-f32c4856c2d8', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 26, 26, '“ማንኛውንም አውሬና እንስሳ፥ በምድር ላይ የሚበርረውንም ባረዳችሁ ጊዜ በዘመናችሁ ሁሉ ከማንኛውም ደም፦ ደም ሁሉ በእናንተ ላይ አይታይ።'),
  ('f9186b53-a334-5bba-afab-91f875812917', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 27, 27, 'በምድር ላይ የሚፈስሰውን ደም በመቅበር ስለ ሰውነታችሁ ምጽዋት መጽውቱ፤ ከደም ጋር የሚበላም አትሁኑ። ሌሎችም በፊታችሁ ደም እንዳይበሉ ተጠንቀቁ። እኔ እንደዚህ ታዝዣለሁና ደሙን ቅበሩ።'),
  ('e06c4bae-c50b-53a4-a536-406929637149', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 28, 28, 'በእናንተና በልጆቻችሁ ከሰው ሁሉ ጋር እመሰክርባችኋለሁ። በምድር ላይ ደምን ከሚያፈስስ ሰው ሁሉ ጋር በሰውነታችሁ ደማችሁን የሚመረምሩአችሁ እንዳይሆኑ ነፍስን ከሥጋ ጋር አትብሉአት፤ ምድር በትውልዱ ሁሉ ደምን ባፈሰሰ ሰው ደም የምትነጻ ስለሆነ ምድር በላይዋ ከፈሰሰ ደም አትነጻምና።'),
  ('60e91d3d-6543-5cb0-af8c-5e834254e40f', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 29, 29, '“አሁንም ልጆች፥ ስሙኝ፥ በምድር ሁሉ በእውነት ፊት ጸንታችሁ ትኖሩ ዘንድ፥ ክብራችሁም ከጥፋት ውኃ ባዳነኝ በአምላኬ በእግዚአብሔር ፊት ይገለጥ ዘንድ ፍርድንና ጽድቅን ፍረዱ።'),
  ('a76b4369-988a-52c6-af0a-d5c49051e3d5', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 30, 30, 'እነሆ፥ እናንተም ሄዳችሁ ከተሞችን ታቀናላችሁ፤ በውስጣቸውም በምድር ላይ ያለውን ተክል ሁሉ ትተክላላችሁ። ተክሉም ሁሉ በሦስተኛው ዓመት የሚያፈራውን ፍሬ ሁሉ ለመብላት የማይለቀም ይሆናል።'),
  ('58292c14-9298-5189-a593-93e66421c4a4', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 31, 31, 'በአራተኛውም ዓመት ፍሬው ይቀደሳል፤ ሰማይንና ምድርን በፈጠረ በልዑል እግዚአብሔር ፊት ተቀባይነት ያለውንም የፍሬውን መጀመሪያ ይሠዋሉ፥ የወይኑንና የዘይቱን መጀመሪያ፥ እንደ አዝመራው መጀመሪያ በሚቀበለው በእግዚአብሔር መሠዊያ በፈሳሽነት ያቀርባሉ፤ የቀረውንም የቤተ እግዚአብሔር አገልጋዮች መሥዋዕቱን በሚቀበልበት በመሠዊያው ፊት ይብሉት።'),
  ('1c7be388-5f13-5d65-a310-d3e45a43c0ef', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 32, 32, 'እናንተ በእውነትና በሚገባ ትተዉት ዘንድ በአምስተኛው ዓመት ዕረፍትን አድርጉ፤ እናንተም ትከብራላችሁ፤ ተክላችሁም ሁሉ የበጀ ይሆናል። የአባታችሁ አባት ሄኖክ ልጁ ማቱሳላን እንዲሁ አዝዞታልና፤ ማቱሳላም ልጁ ላሜህን አዝዞታልና፤ ላሜህም አባቶቹ ያዘዙትን ሁሉ ለእኔ አዝዞኛልና።'),
  ('77cbf6a4-ca73-5260-a153-2609c45de23b', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 33, 33, 'እኔም፥ ልጆች ሆይ፥ ሄኖክ ልጁን እንዳዘዘው አዝዛችኋለሁ፤ በመጀመሪያው ኢዮቤልዩ በሕይወት ሳለ በሰባተኛው ትውልድ ማቱሳላ እስከሚሞትባት ቀን ድረስ ልጆቹንና የልጆቹን ልጆች አዝዞ አዳኘ።”'),
  ('5bef901f-cc3d-5a24-a4bb-189a4509c941', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 34, 34, 'በሃያ ዘጠነኛው ኢዮቤልዩ በመጀመሪያው ሱባዔ በመጀመሪያው ዓመት አርፋክስድ ሚስት አገባ፤ ስምዋም ራሱእያ ይባላል፤ ይህችውም የኤላም ልጅ የሱሳን ልጅ ናት። በሦስተኛው ዓመት በዚህ ሱባዔ ወንድ ልጅን ወለደችለት፤ ስሙንም ቃይናም አለው፤ ልጁም አደገ፤ አባቱም መጽሐፍን አስተማረው።'),
  ('6907f306-7932-5f1c-a9d2-1fcc59373b3d', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 35, 35, 'ከተማንም የሚይዝበት ቦታን ይፈልግ ዘንድ ሄደ፤ የቀደሙ ሰዎችም በድንጋይ የቀረፁትን መጽሐፍ አገኘ። በእርስዋም ያለውን አንብቦ ተረጐመ። የፀሓይንና የጨረቃን፥ የከዋክብትንም ሰገል ከሰማይ ምልክቶች ጋር የሚመለከቱበት የትጉሃን ትምህርት ሁሉ በእርስዋ ስለ ነበር በእርስዋ በተጻፈው በደለ።'),
  ('eb2f031c-08e4-534c-aa84-0d3754e4a9d0', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 36, 36, 'እርሱም ጻፋት፥ የእርስዋንም ነገር አልተናገረም። ስለ እርስዋ በእርሱ እንዳይቈጣ የእርስዋን ነገር ለመናገር ኖኅን ይፈራዋልና።'),
  ('07b0201c-e406-5492-a3f9-98be39090d29', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 37, 37, 'በሠላሳኛው ኢዮቤልዩ በሁለተኛው ሱባዔ በመጀመሪያው ዓመት ሚስትን አገባ፤ ስምዋም ሜልካ ይባላል፤ ይህችውም የያፌት ልጅ የአበዳይ ልጅ ናት።'),
  ('fed87870-aebb-5d93-a831-02057c34a1cc', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 38, 38, 'በአራተኛውም ዓመት ወንድ ልጅን ወለደችለት፦ ስሙንም ሳላ አለው፤ መልእክትን ተልኬአለሁ ብሎአልና፤ ሳላም አደገ፤ በሠላሳ አንደኛውም ኢዮቤልዩ በአምስተኛው ሱባዔ በመጀመሪያው ዓመት ሚስትን አገባ ስምዋም ሙአክ ይባላል፤ ይህችውም የአባቱ ወንድም የኬሴድ ልጅ ናት።'),
  ('530d5517-5a6d-506d-ad00-8bcf6bf8d044', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 39, 39, 'በአምስተኛውም ዓመት ወንድ ልጅን ወለደችለት፤ ስሙንም ኤቦር አለው። እርሱም በሠላሳ ሁለተኛው ኢዮቤልዩ በሰባተኛው ሱባዔ በሦስተኛው ዓመት ሚስትን አገባ፤ ስምዋም አዙራድ ይባላል፥ ይህችውም የአብሮድ ልጅ ናት።'),
  ('c0db889d-b8d3-555f-a585-776e04789368', '8e9ea004-b535-5aa4-a695-7959bbc4d428', '5b3e5f43-8fed-5340-ac20-9e02e61c7319', 40, 40, 'በስድስተኛውም ዓመት ወንድ ልጅን ወለደችለት፤ ስሙንም ፋሌክ አለው፤ በተወለደበት ዘመን የኖኅ ልጆች ምድርን ሊካፈሉ ጀምረዋልና፤ ስለዚህም ስሙን ፋሌክ ብሎ ጠራው፤ እርስ በርሳቸውም አስተካክለው ተካፈሉ፥ ለኖኅም ነገሩት።'),
  ('d2426042-aa7c-5e5d-ad4b-b5f36c159a90', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 1, 1, 'በሠላሳ ሦስተኛውም ኢዮቤልዩ መጀመሪያ እንዲህ ሆነ፤ ለካምና ለሴም ለያፌትም ርስት ልትሆናቸው ከአንደኛው ሱባዔ በመጀመሪያው ዓመት ወደ እነርሱ ከተላክን ከእኛ አንዱ ባለበት ምድርን ሦስት አድርገው ከፈሉአት፤ ልጆቹንም ጠራ፤ እነርሱና ልጆቻቸውም ወደ እርሱ ቀረቡ፤ ሦስቱ ልጆቹም የሚይዙትን ምድር በዕጣ ከፈለ።'),
  ('50eb8244-81dd-5f08-aa87-501486623af1', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 2, 2, 'እጃቸውንም ዘርግተው ከአባታቸው ከኖኅ እጅ መጽሐፉን ተቀበሉ። ርስት አድርጎ የሚይዘው የሴም ዕጣም ለልጆቹና ለልጅ ልጆቹ ለዘለዓለም በመጽሐፍ የምድር መካከል ወጣ። ከአርበኞች ተራራ መካከል ከውኃውም መውጫ ጀምሮ እስከ ጢና ወንዝ ድረስ ወጣ።'),
  ('eb441ea4-e106-5079-a8a7-334c0b05c93c', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 3, 3, 'ክፍሉም በዚህ ወንዝ መካከል ወዳለ ወደ ምዕራብ ይደርሳል፤ ይህም ወንዝ ከእርስዋ እስከሚወጣበት እስከ ጥልቁ ውኃ እስኪቀርብ ድረስ ወደዚያ ይሄዳል። ውኃውም ወደ ሚኦት ባሕር ይፈስሳል፤ ይህም ወንዝ እስከ ታላቁ ባሕር ድረስ ይሄዳል፤ በደቡብም በኩል ያለው ሀገር ሁሉ ለያፌት ደረሰ፤ በሰሜን በኩል ያለውም ሀገር ሁሉ ለሴም ደረሰ።'),
  ('9e58a8ef-10f7-5f8e-a37c-b8eef62316c9', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 4, 4, 'ወደ ኮራሶ እስኪቀርብ ድረስ ይሄዳል። ይኸውም ወደ ሰሜን የሚመለከት ሕፅነ ልሳን ነው። ክፍሉም ወደ ታላቁ ባሕር ይደርሳል። ይህች ባሕር ልሳነ ባሕረ ግብፅ ትባላለችና ወደ ሰሜን ወደምታሳይ ወደ ልሳን መግቢያ እስኪቀርብ ድረስ አቅንቶ ይሄዳል።'),
  ('265e86e9-7cb1-5aa0-ac21-a75048b85635', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 5, 5, 'ከዚያም ወደ ሰሜን ታዘነብላለች፤ ወደ ታላቁ ባሕር መግቢያ ወደ ውኃውም ዳርቻ ትደርሳለች፤ ወደ አፍራም ግራ ትደርሳለች፤ ግዮን ወደሚባል ፈሳሽ ውኃም እስክትቀርብ ድረስ ትደርሳለች፤ ወደ ግዮንም ውኃ ቀርባ ወደዚህ ፈሳሽ ዳርቻ ትደርሳለች።'),
  ('75bcb534-c4c4-512c-adc7-60352aa56ac0', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 6, 6, 'ወደ ኤደን ገነት ወደ ሰሜንም ቀኝ እስክትቀርብ ድረስ ወደ ምሥራቅ ትሄዳለች፤ ከኤዶም ምድር ሁሉ ምሥራቅ፥ ከሀገሩም ሁሉ ምሥራቅ ወደ ምሥራቅ ይመለሳል። ስሙ ራፋ ወደሚባል ተራራ ምሥራቅ እስኪቀርብ ድረስ ይመጣል፤ ወደ ጢና ወንዝ መውጫ ዳርቻም ይወርዳል።'),
  ('92884368-c10b-56fe-ad88-8c9868808a11', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 7, 7, 'ይህችም ክፍል ለዘለዓለም ሊይዙአት ለሴምና ለልጆቹ፥ ለልጅ ልጆቹም እስከ ዘለዓለም ድረስ በዕጣ ወጣች።'),
  ('0be960e7-3d0b-550c-aae6-4c40cf521a6c', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 8, 8, 'ኖኅም ይህ ክፍል የሴምና የልጆቹ ዕጣ ነውና ደስ አለው። “የሴም አምላክ እግዚአብሔር ይመስገን፥ እግዚአብሔርም በሴም ማደሪያ ይደር” ብሎአልና በአፉ በትንቢት የተናገረውን ነገር ሁሉ ዐሰበ። የኤዶም ገነት ከከበሩ የከበረች፥ የእግዚአብሔርም ማደሪያ እንደ ሆነች ዐውቆአልና። ደብረ ሲና በምድረ በዳ መካከል ናት፥ ደብረ ጽዮንም በምድር ዕንብርት መካከል ናት፥ እነዚህ ሦስቱ ሁሉ አንዱ በአንዱ አንጻር ለቅድስና ተፈጠሩ።'),
  ('3922c587-2432-57f7-add5-1be712495eff', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 9, 9, 'በአፉ ቃለ እግዚአብሔርን እንዲናገር ያደረገውን የአማልክት አምላክ እግዚአብሔርን እስከ ዘለዓለም ድረስ አመሰገነው፤ የተባረከ ክፍልና በረከት ለሴምና ለልጆቹ፥ ለልጅ ልጆቹም እስከ ዘለዓለም ድረስ እንደ ደረሳቸው ዐወቀ።'),
  ('4d3cc142-8c8e-51fe-a734-561ea621d63e', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 10, 10, 'የኤዶም ምድር ሁሉ፥ የኤርትራ ባሕር ዳርም ሁሉ፥ የምሥራቅ ምድር ሁሉ በኤርትራና በተራሮቹ በኩል ያለው ሕንድ፥ የባሳን ሀገር ሁሉና የሊባኖስም ሀገር ሁሉ፥ የካፍቱር ደሴቶችና የሳኔር ተራራ ሁሉ፥ አማናና የደቡባዊው አሱር ተራራ፥ የኤላም ሀገር ሁሉ፥ አሱርና ባቢል፥ ሱሳንም ማእዳይና የአራራት ሀገር ሁሉ፥ በደቡብ በኩል ከአለው ከአሱር ተራራ ማዶ የባሕሩ ወደብ እንደ ደረሱት ዐወቀ። የተባረከችና ሰፊ የሆነች፥ በውስጥዋም ያለ ሁሉ እጅግ ያማረ ምድር፤'),
  ('04cefeef-4c58-56bc-a22f-bf3f3b8d953e', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 11, 11, 'ሁለተኛውም ዕጣ ወደ ግዮን ማዶ በገነት ቀኝ በሰሜን በኩል ለካም ወጣ፥ ወደ ሰሜንም ይደርሳል። ዋዕይ ወደ ጸናበት ተራራም ሁሉ ይደርሳል፤ በአጤል አንጻር ወዳለ ወደ ምዕራብ ይደርሳል። ወደ ማዕከክ ባሕር እስኪቀርብ ድረስም ወደ ምዕራብ ይደርሳል። ይህችውም የሚጠፋው ሁሉ ወደ እርስዋ የሚወርድባት ሀገር ናት። ወደ ደቡብ ወደ ጋዴት ዳርቻ ይወጣል። ወደ ግዮን ወንዝም እስኪቀርብ ድረስ ወደ ባሕሩ ዳርቻ ወደ ታላቁ ባሕር ይመጣል።'),
  ('1a70bd32-3639-56e3-a958-3116b6c33121', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 12, 12, 'ግዮን የተባለው ወንዝም በኤዶም ገነት ቀኝ እስኪቀርብ ድረስ ይሄዳል። ለዘለዓለም ለሚይዛት ለካምና ለልጆቹ፥ ለወገናቸውም እስከ ዘለዓለም ድረስ በዕጣ የወጣች ሀገር ይህች ናት።'),
  ('a5fc7a65-5d81-532b-a2ad-982bfbb59cac', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 13, 13, 'ለያፌትም ሦስተኛው ዕጣ ወጣ። ጢና ወደሚባል ወንዝ ማዶ ወደ ፈሳሾች መውጫ ወደ ደቡብ ወጣ። ወደ ደቡብ ምሥራቅ፥ ወደ ጎግ አውራጃም ሁሉና ወደ ምሥራቃቸው ሁሉ ይደርሳል፥ ከደቡብም ወደ ደቡብ ይደርሳል። ወደ ቄልጥ ተራራና ወደ ደቡብ፥ ወደ ማሉቅም ባሕር ይደርሳል። እስከ ባሕሩ መውጫ ዳርቻ ድረስ ወደ ጋዴት ምሥራቅም ይመጣል። ወደ ፋራ መግቢያም እስኪቀርብ ድረስ ይሄዳል። ወደ ምሥራቅ ወደ ማኡታ ባሕር ወደሚሄደው ወደ አፌራግም ይመለሳል፤ ወደ ውኃው ዳርቻ ወደ ራፋ ተራራ እስኪቀርብም ድረስ ጢና ወደተባለው ወንዝ ወደ ደቡብ ምሥራቅ ይሄዳል። ደቡብንም ይዞራል።'),
  ('2e8d0e65-777c-5702-a50f-ee74df48a245', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 14, 14, 'ለዘለዓለሙ በርስትነት ዕጣ የሚይዛት፥ ለያፌትና ለልጆቹ፥ ለወገኖቹም የወጣችለት ምድር ይህች ናት። ታላላቅ ደሴቶችዋም አምስት ናቸው። በደቡብ በኩል ያለችውም ሀገር ሰፊ ናት። ነገር ግን የያፌት ሀገር ቀዝቃዛ ናት፤ የካምም ሀገር በረሃ ናት፤ የሴም ሀገር ግን ከውርጭና ከዋዕይ ጋር የተቀላቀለች ናትና ቆላም ደጋም አይደለችም።'),
  ('4a4cb067-0144-5081-ae61-99ad9f112319', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 15, 15, 'ካም በልጆቹ መካከል አካፈለ። የመጀመሪያው ዕጣም ለኩሽ ወደ ምሥራቅ ወጣ፥ ምዕራቡ ለምጽራይም ወጣ፥ ምዕራቡም ለፉጥ ወጣ፤ ምዕራቡም ለከነዓን ወጣ፤ በምዕራቡም በኩል ባሕር ነበር።'),
  ('522c37fc-f926-59ca-a23a-4f9d8db8eba3', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 16, 16, 'ሴምም በልጆቹ መካከል አካፈለ። መጀመሪያው ዕጣ ለኤላምና ለልጆቹ እስከ ሕንደኬ ምድር ሁሉ ምሥራቅ እስኪቀርብ ድረስ ወደ ጤግሮስ ወንዝ ምሥራቅ ወጣ፤ ኤርትራም በእጁ ነበር። የዲዳን ውኃ፥ የሞብሪ ተራሮች፥ የኤላ ሀገር ሁሉ፥ የሱሳም ሀገር ሁሉ፥ በፊርኖክ በኩል ያለው ሁሉ፥ እስከ ኤርትራ ባሕርና እስከ ጢና ወንዝ።'),
  ('5ac0d1c9-401e-5de8-ac83-ed574ab0be57', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 17, 17, 'ለአሶርም ሁለተኛው ዕጣ ወጣ፤ የአሱርና ነነዌ ሀገር ሁሉ፥ ሰናዖርም፥ ሳድም እስከ ሕንደኬ አቅራቢያ ድረስ። ወደ ወድፋ ፈሳሽም ይደርሳል።'),
  ('c50b0175-de17-5a1c-aea7-ef311ed33a81', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 18, 18, 'ለአርፋክስድም ሦስተኛው ዕጣ ወጣ። የከላውዴዎን አውራጃ ሀገር ሁሉ፥ ለኤርትራ ባሕር የቀረበው የኤፍራጥስ ምሥራቅም፥ ወደ ግብፅ እስከምትመለከተው እስከ ልሳነ ባሕር አቅራቢያ ድረስ የምድረ በዳው ውኃ ሁሉ፥ የሊባኖስና የሳኔር ሀገር፥ አማናም፥ እስከ ኤፍራጥስ ድረስ።'),
  ('ef279395-9a8d-5180-abe9-90578ec382c5', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 19, 19, 'ለአራምም አራተኛው ዕጣ ወጣ፤ በጤግሮስና በኤፍራጥስ መካከል የመስጴጦምያ ሀገር ሁሉ በከላውዴዎን ደቡብ ወዳለ እስከ አሱር አቅራቢያ ድረስ፥ የአራራትም ሀገር ሁሉ የእርሱ ነው።'),
  ('26047af7-3e71-588b-add3-1e76be2d1d3c', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 20, 20, 'ለሉድም አምስተኛው ዕጣ ወጣ፤ የአሱር ተራራ ሁሉ፥ ወደ ታላቁ ባሕር እስኪቀርብ ድረስ የእርሱ ዕጣ ነው። ወደ ወንድሙ ወደ አሶር ምሥራቅም ይደርሳል።'),
  ('e9bfced7-e259-5e9a-add4-131fa55c1794', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 21, 21, 'ያፌትም ምድረ ርስትን በልጆቹ መካከል ከፈለ። መጀመሪያውም ዕጣ ከደቡብ አንጻር ጀምሮ እስከ ጢና ወንዝ ድረስ በምሥራቅ በኩል ለሴሜር ወጣ። በደቡብም በኩል የደቡብ ዙሪያ ሁሉ ለሚአት ባሕር እስኪቀርብ ድረስ ለማጎግ ወጣ።'),
  ('e21c6b47-4d4c-5200-a1e5-01ca726eaf58', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 22, 22, 'ከምዕራቡ ጀምሮ እስከ ደሴቶችና እስከ ደሴቶችም ዳርቻ ድረስ ለሁለቱ ወንድሞቹ ሁሉ ይይዝ ዘንድ ለማዳይ ደረሰ።'),
  ('4416b93f-c06d-51b0-a767-95fee83fc166', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 23, 23, 'ለኢዮእያንም አራተኛው ዕጣ ወጣ፥ ደሴቱ ሁሉ፥ በሉድም አንጻር ያሉ ደሴቶች ሁሉ።'),
  ('76d062b9-8f76-515a-aea2-736a628016a4', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 24, 24, 'ለቶቤልም እስከ ሁለተኛዪቱ ልሳን ድረስ ወደ ሉድ ዕጣ በምትቀርብ በልሳን መካከል አምስተኛው ዕጣ ወጣ። የሁለተኛዪቱም ልሳን አውራጃ እስከ ሦስተኛዪቱ ልሳን ድረስ ነው።'),
  ('631b4ba2-49a5-5d79-a3cf-503de997be73', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 25, 25, 'ለሞሳክም ስድስተኛው ዕጣ ወጣ። እስከ ጋዴር ምሥራቅም እስኪቀርብ ድረስ የሦስተኛዪቱ ልሳን አውራጃ ሁሉ።'),
  ('433bf013-469e-53fb-a1b9-639555fde014', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 26, 26, 'ለቲራስም ሰባተኛው ዕጣ ወጣ። በባሕር መካከል ያሉ፥ ለካም ዕጣ የሚቀርቡ ታላላቁ አራቱ ደሴቶች፤ የክማቱሪ ደሴቶችም በርስትነት ዕጣ ለአርፋክስድ ልጆች ወጡ፤ የኖኅም ልጆች ለልጆቻቸው በአባታቸው በኖኅ ፊት እንዲህ አድርገው ከፈሉ። በዕጣው ያልወጣለትን ክፍል ይይዝ ዘንድ የሚፈልገውን እያንዳንዱን አምሎ ረገመ።'),
  ('e36eca4f-9f06-59f5-ae66-8558e807592a', '8cceb20f-0fec-5427-a917-179537ee8ff8', '46452f1f-32c1-547f-a38c-fcc84068892a', 27, 27, 'ሁሉም ይሁን አሉ። ስለሚያጸይፍ ክፉ ኀጢአታቸው ሁሉ፥ ምድርንም በበደልና በርኵሰት፥ በዝሙትና በኀጢአትም ስለ ሞሉአት እግዚአብሔር አምላክ በሰይፍና በእሳት ይፈርድባቸው ዘንድ እስከ ፍርድ ቀን ድረስ በራሳቸውና በልጆቻቸው፥ በዘራቸውም እስከ ዘለዓለም ይሁን አሉ።'),
  ('d2a4ece2-ec48-5854-a082-7a6c79c7ff6f', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 1, 1, 'በዚህ ኢዮቤልዩ በሦስተኛው ሱባዔ ርኩሳን አጋንንት የኖኅን የልጅ ልጆች ያስቱአቸውና አእምሮአቸውን እያሳጡ ያጠፉአቸው ጀመሩ።'),
  ('141cb728-9413-518d-aa1d-84dc5de6325d', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 2, 2, 'የኖኅም ልጆች ወደ አባታቸው ወደ ኖኅ መጡ። የልጅ ልጆቹንም የሚያስቱና የሚያደነቁሩ፥ የሚገድሉም የአጋንንትን ነገር ነገሩት።'),
  ('468639ea-5b40-5da8-a78c-aa1cc594c6d7', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 3, 3, 'ኖኅም ወደ ፈጣሪው ወደ እግዚአብሔር እንዲህ ሲል ጸለየ፥ “ምሕረትህን አድርገህ ያዳንኸኝ፥ ልጆችንም ከጥፋት ውኃ ያዳንኻቸው፥ የጥፋትን ልጅ እንዳጠፋኸው እንድጠፋ ያላደረግኸኝ፥ በእኔ ላይ ያለ ይቅርታህ ብዙ ነውና፥ ቸርነትህም በሰውነቴ በዝታለችና፥ በሥጋ ውስጥ ሁሉ ያሉ የነፍሳት ፈጣሪ ሆይ፥ ይቅርታህ በልጆች ላይ ከፍ ከፍ ይበል፤ ክፉዎች አጋንንትም ከዚህ ዓለም እንዳያጠፉአቸው በላያቸው አይሠልጥኑ።'),
  ('352b069d-f2de-5605-a4d5-f6794b38c33e', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 4, 4, 'አንተም እኔን ባርከኝ። የብዙ ብዙ እንሆን ዘንድ፥ ምድርንም እንሞላት ዘንድ፥ ልጆችን ባርካቸው። አንተም በሕይወት ያሉ የእነዚህ ረቂቃን አጋንንት አባቶቻቸው ትጉሃን ያደረጉትን ታውቃለህ። ይዘህ በፍርድ ቦታ አግዛቸው፤ እነርሱ ክፉዎች ናቸውና፥ ለማጥፋትም ተፈጥረዋልና አምላኬ ሆይ፥ የእኔን የባሪያህን ልጆች አያጥፉ፤ በሕይወት በሚኖሩ ሰዎች ነፍስም አይሠልጥኑ፥ አንተ ብቻ ፍርዳቸውን ታውቃለህና ከዛሬ ጀምሮ እስከ ዘለዓለም ድረስ በጻድቃን ልጆች ላይ አይሠልጥኑ።”'),
  ('892206e5-a764-5820-a516-47abc875116a', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 5, 5, 'አምላካችንም ሁሉን አስረን እናግዝ ዘንድ አዘዘን። የአጋንንትም አለቃ መስቴማ መጥቶ፥ “አቤቱ ፈጣሪዬ፥ ከእነርሱ በፊቴ ጥቂት አስቀርልኝ፤ ቃሌንም ይስሙ፤ እኔ የማዝዛቸውንም ሁሉ ያድርጉ፤ ከእነርሱ ካልቀሩልኝ በሰው ልጆች ላይ የፈቃዴን ሥልጣን ማድረግ አልችልምና። የሰው ልጆች ክፋታቸው ብዙ ስለ ሆነ ከፍርዴ አስቀድሞ እነርሱ ለማጥፋትና ለማሳት ናቸውና።”'),
  ('80dc2bcb-9163-5a2d-a775-3229c6cb6c04', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 6, 6, '“በፊቱ ዐሥረኛው ነገድ ይቅሩ፤ ዘጠኙን ነገድ ግን ወደ ፍርድ ቦታ ያውርዱአቸው” አለ። እርሱም በቀና ሥራ ጸንተው የሚኖሩ እንዳይደሉ፥ በእውነትም የሚጣሉ እንዳይደሉ ያውቃልና የሚድኑበትን ሁሉ ለኖኅ እናስተምረው ዘንድ ከእኛ አንዱን አዘዘው።'),
  ('b90f4b87-5bf4-58e5-a564-371e16780520', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 7, 7, 'እኛም እንደ ቃሉ አደረግን፤ ፈጽመው የከፉ አጋንንትን በፍርድ ቦታ አስረን አጋዝን። ዐሥረኛውን ነገድ ግን በሰይጣን ፊት በምድር ይገዙ ዘንድ አስቀረን። በምድር እንጨቶችም ያድን ዘንድ የደዌያቸውን መድኀኒት ከማሳታቸው ጋር ለኖኅ ነገርነው።'),
  ('88f5015d-1555-525f-a706-815362fc5879', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 8, 8, 'ኖኅም በየመድኀኒቱ ዓይነት ሁሉ እንዳስተማርነው በመጽሐፍ ሁሉን ጻፈ። ክፉዎች አጋንንትም የኖኅን ልጆች እንዳይከታተሉ ተጋዙ።'),
  ('58339c0a-cec1-5d2a-a850-c6a04ff097d3', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 9, 9, 'ከልጆቹ ሁሉ ይልቅ ፈጽሞ እርሱን ይወደው ነበርና የጻፋቸውን መጻሕፍት ሁሉ ለታላቁ ልጁ ለሴም ሰጠው። ኖኅም እንደ አባቶቹ ሞተ፤ አራራት በሚባልም ሀገር በሉባር ተቀበረ፤ ኖኅም በሕይወቱ ዘጠኝ መቶ አምሳ ዓመት ጨረሰ። ይህም ዐሥራ ዘጠኝ ኢዮቤልዩ ሁለት ሱባዔና አምስት ዓመት ነው። ፍጹም በሆነባት ሥራው በምድር የኖረው ሕይወቱ ከሄኖክ በቀር ከሰው ልጆች ይልቅ የከበረ ነበር። የሄኖክ ሥራ በፍርድ ቀን የትውልዱን ሁሉ ሥራ ይነግር ዘንድ ለዘለዓለም ትውልድ ምስክር ሊሆን ተፈጥሮአልና።'),
  ('ee60fee8-80b0-5a6d-a328-c7a5f6f5f13c', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 10, 10, 'በሠላሳ ሦስተኛው ኢዮቤልዩ ከሁለተኛው ሱባዔ በመጀመሪያው ዓመት ፋሌክ ስምዋ ሎምና የሚባል ሚስትን አገባ፤ ይህችውም የሴናዖር ልጅ ናት። በዚሁም ሱባዔ በአራተኛው ዓመት ወንድ ልጅን ወለደችለት። ከአራራት ምድር ወደ ምሥራቅ ወደ ሰናዖር ሀገር ስለ ተሰደዱ በሰናዖር ሀገር ከተማንና አምባን ይሠሩ ዘንድ የሰው ልጆች በጽኑ ምክር እነሆ፥ ክፉዎችን ሆኑ ብሎአልና ስሙን ራግው አለው። ወደ ሰማይ እንወጣበታለን ሲሉ በዘመኑ ከተማንና ግንብን ሠርተዋልና፤ መሥራትም ጀምረዋልና።'),
  ('6e71a76c-75d5-52f8-a7e4-093885ad619f', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 11, 11, 'በአራተኛውም ሱባዔ ጡቡን ሠርተው በእሳት ተኰሱ። ጡቡም እንደ ድንጋይ ሆነላቸው፤ የሚመርጉበት ጭቃውም ከባሕርና በሰናዖር ሀገር ከውኃዎች ምንጭ የሚወጣ የባሕርን አረፋ ሆነላቸው።'),
  ('50759529-a568-5773-a7b4-e30b91ab8331', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 12, 12, 'በአርባ ሦስት ዓመትም ሠሩት። እየሠሩም ነበሩ። ወርዱም ሁለት መቶ ሦስት ጡብ ነበር፤ የጡቡም ከፍታ የርዝመቱ አንድ ሦስተኛ ነበር። ቁመቱ አምስት ሺህ አራት መቶ ሠላሳ ሦስት ክንድ ከሁለት ስንዝር ወደ ላይ ወጣ። አቆልቋዩም ዐሥራ ሦስት ምዕራፍ ነበር።'),
  ('d3712754-a531-547e-a8b5-583418f117f6', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 13, 13, 'አምላካችን እግዚአብሔርም እኛን እንዲህ አለን፥ “እነሆ፥ አንድ ቋንቋ የሆነ ሕዝብ ግንብ ይሠራ ጀመር፤ አሁንም ከእነርሱ ፈጽመን እንዳናጠፋ ኑ እንውረድ፤ የአንዱንም ቋንቋ አንዱ እንዳይሰማ፥ ቋንቋቸውን እንደባልቀው፤ በየከተማውና በየአሕዛቡ ይበተኑ፤ ከዚህ በኋላም እስከ ፍርድ ቀን ድረስ አንዲት ምክር በላያቸው አትኑር።”'),
  ('15c49ef3-53cc-5650-aa9c-633709d3c54b', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 14, 14, 'እግዚአብሔርም ወረደ፤ እኛም የሰው ልጆች የሠሩትን ከተማውንና ግንቡን እናይ ዘንድ ከእርሱ ጋር ወረድን፤ ቋንቋቸውንም ደባለቀ፤ አንዱም የአንዱን ነገር አልሰማም። ከዚያም በኋላ ከተማውንና ግንቡን መሥራት ተዉ።'),
  ('295e3461-05c4-5f61-a444-4b9858db52c5', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 15, 15, 'ስለዚህም አምላክ በዚያ የሰው ልጆችን ቋንቋ ሁሉ ደባልቆአልና የሰናዖር ሀገር ሁሉ ባቢል ተባለች፤ ከዚያም በየከተማቸውና በየቋንቋቸው፥ በየወገናቸውም ተበተኑ።'),
  ('f76c20b6-edee-5d9e-a99b-92102e143e2b', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 16, 16, 'እግዚአብሔርም ታላቅ ነፋስን አምጥቶ ግንባቸውን በምድር ላይ ገለበጠ፤ እነሆ፥ እርሱም በሰናዖር ሀገር በአሦርና በባቢሎን መካከል ነው። ስምዋንም ድቀት አላት። በሠላሳ አራተኛውም ኢዮቤልዩ በአራተኛው ሱባዔ በአንደኛው ዓመት መጀመሪያ ከሰናዖር ሀገር ተበተኑ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('efccecae-1de3-5ac6-ac42-d6faa2150bd4', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 17, 17, 'ካምና ልጆቹም ለእርሱ ወደ ተያዘች በደቡብ ሀገር በዕጣ ወዳገኛት ሀገር ሄዱ። ከነዓንም እስከ ግብፅ ውኃ መፍሰሻ ድረስ ያለችውን የሊባኖስን ሀገር እጅግ ያማረች እንደ ሆነች አየ። ወደ ርስቱም ሀገር ወደ ባሕሩ መግቢያ አልሄደም፤ እርሱም ከምሥራቅ ጀምሮ እስከ ምዕራብ በሊባኖስና በባህሩ'),
  ('bb66b62b-0da1-5cb0-a140-0d78235b1351', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 18, 18, 'አባቱ ካምና ወንድሞቹ ኩሳ፥ ሚጽራይምም፥ “የአንተ ዕጣ ባልሆነች ሀገር ኖረሃልና፥ በዕጣም አልወጣችልንምና እንዲህ አታድርግ አሉት። እንደዚህ ብታደርግ አንተና ልጆችህ በዚህ ምድር ትጠፋላችሁ፤ በክርክርም ኖራችኋልና በክርክር የተረገማችሁ ትሆናላችሁ፤ ልጆችህም በጠብ ይጠፋሉ፤ አንተም ለዘለዓለም ትጠፋለህ።'),
  ('6c066728-698f-5d6b-a5a1-9be0c5639ef1', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 19, 19, 'ለሴምና ለልጆቹ በዕጣቸው ወጥቶአልና በሴም ሀገር አትኑር፤ አንተም የተረገምህ ነህ። በአባታችን በኖኅና በቅዱሱ ፈራጅ ፊት ለመርገም በመሐላ ከተዘጋጀን ከኖኅ ልጆች ሁሉ ተለይተህ አንተ የተረገምህ ትሆናለህ” አሉት። እርሱ ግን አልሰማቸውም፤ ከኤማት ጀምሮ እስከ ግብፅ መግቢያ ድረስ በሊባኖስ ሀገር ኖረ፤ ልጆቹም እስከዚህ ቀን ድረስ በዚያ ኖሩ። ስለዚህ ያች ሀገር የከነዓን ሀገር ተባለች።'),
  ('126fe861-e5c4-5ab7-a6fd-48d3e9edcfbf', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 20, 20, 'ያፌትና ልጆቹ ግን ወደ ባሕር ሄዱ፤ ድርሻቸው በሆነ ሀገርም ኖሩ።'),
  ('14a0c082-1b56-51d0-ae33-34475a1a3117', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 21, 21, 'ማዳይም ባሕር ያለባትን ሀገር አየ፤ ነገር ግን በፊቱ ደስ አላሰኘችውም፤ የሚስቱ ወንድሞች ከሆኑ ከኤላምና ከአሱር፥ ከአርፋክስድም ለምኖ እስከዚህች ቀን ድረስ የሚስቱ ወንድሞች አቅራቢያ በሚሆን በሜቄዶን ሀገር ኖረ። የእርሱን ቦታና የልጆቹን ቦታ ሜቄዶንንም በአባታቸው በማዳይ ስም ጠራው።'),
  ('ca08101e-6fd4-5bba-ae14-d391bfd4fccf', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 22, 22, 'በሠላሳ አምስተኛውም ኢዮቤልዩ በሦስተኛው ሱባዔ በመጀመሪያው ዓመት ራግው ስምዋ ዑራ የምትባል ሚስትን አገባ፤ ይህችውም የኬሴድ ልጅ የዑር ልጅ ናት። ወንድ ልጅንም ወለደችለት፤ ስሙንም ሴሩግ ብሎ ጠራው።'),
  ('1bc55888-0326-52e4-a332-41e6570c368b', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 23, 23, 'በዚህ ኢዮቤልዩ በሰባተኛው ሱባዔ የኖኅ ልጆች ሰውን ለመማረክና ለመግደል፥ እያንዳንዱም ወንድሙን ለመግደል፥ የሰውንም ደም በምድር ላይ ለማፍሰስ፥ ደምንም ለመብላት፥ የጸኑ ከተማዎችንና አንባዎችን፥ ግንቦችንም ለመሥራት ሕዝብ በሕዝብ ላይ ለመነሣት፥ በመንግሥትም ላይ አስቀድሞ ለመሾም፥ ሕዝቡ በሕዝቡ ፊት፥ አሕዛቡም በአሕዛቡ ፊት ወደ ሰልፍ ለመሄድ፥ ከተማም ከከተማ ጋር ለመጣላት፥ ሁሉም ክፉ ሥራ ለመሥራት፥ የጦር መሣሪያንም ለመግዛት፥ ለልጆቻቸውም ሰልፍን ለማስተማር መዋጋት ጀመሩ። አንዱ አገር ሌላውን አገር ይማርክ፥ ሴት ባሪያንና ወንድ ባሪያንም ይገዙ ጀመር።'),
  ('5b7d5bbd-06a1-58bc-a558-25e012cdcc57', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 24, 24, 'የኬሴድ ልጅ ዑርም በከላውዴዎን ያለች የዑርን ከተማ ሠራ፤ ስምዋንም በእርሱ ስምና በአባቱ ስም ጠራ። ጣዖቶችንም ሠሩ፤ እያንዳንዱም ለራሱ ቀርፆ ለሠራው ጣዖት ይሰግድ ነበር፤ ጣዖትንና ምስልን፥ ርኵሰትንም ይሠሩ ጀመር፤ ክፉዎች አጋንንትም ኀጢአትንና ርኵሰትን ይሠሩ ዘንድ ይረዱና ያስቱ ነበር።'),
  ('c450eaa4-345b-57b3-aec3-760c52341c5e', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 25, 25, 'አለቃው መስቴማም ይህን ሁሉ ለመሥራት ይበረታ ነበር፤ ኀጢአትንና በደልን ሁሉ፥ ፈጽሞም ለማጥፋትና ክህደትን ሁሉ ለማሠራት፥ በምድርም ደምን ለማፍሰስ ከእጁ በታች ያሉ የአጋንንትን እጅ ይልክ ነበር።'),
  ('21c24a1d-e830-51f9-a698-98e9ebf0503a', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 26, 26, 'ስለዚህም ሰው ሁሉ በደልንና ኀጢአትን ሁሉ ወደ መሥራት ተመልሶአልና፥ የሴሩሕ ስም ሴሩግ ተባለ። እርሱም አደገ፤ ለሚስቱም እናት አባት አቅራቢያ በሆነ በከላውዴዎን ዕጣ በዑር ኖረ። ጣዖትንም ያመልክ ነበር፤ እርሱም በሠላሳ ሰባተኛው ኢዮቤልዩ በአምስተኛው ሱባዔ በመጀመሪያው ዓመት ሚስትን አገባ፤ ስምዋም ሜልካ ይባላል፤ ይህችውም የአባቱ የእኅት ልጅ የካቤር ልጅ ናት፥ በዚህ ሱባዔ በመጀመሪያው ዓመት ናኮርን ወለደችለት።'),
  ('8d4a839e-dc1b-59b1-a5fa-dd0518c79f52', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 27, 27, 'እርሱም አደገ፤ በከላውዴዎን ዕጣ በዑርም ኖረ። አባቱም በሰማይ ምልክት ለማምዋረትና ለመጠንቆል የከዋክብትን ምርምር አስተማረው።'),
  ('006e282e-19eb-5722-a071-2841fcc75c55', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 28, 28, 'በሠላሳ ሰባተኛው ኢዮቤልዩ በስድስተኛው ሱባዔ በመጀመሪያው ዓመት ሚስትን አገባ፤ ስምዋም ኢዮስካ ይባላል። ይህችም የከለዳውያን ወገን የኔስቴግ ልጅ ናት። በዚህ ሱባዔ በሰባተኛው ዓመት ታራ የሚባል ወንድ ልጅን ወለደችለት።'),
  ('9c3b273e-79b7-5bb9-aa7c-e270388ba85f', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 29, 29, 'አለቃው መስቴማም ምድርን ለማጥፋት፥ በምድር ላይ የተዘራውን ዘር ይበሉ ዘንድ ወፎችንና ቁራዎችን ሰደደ። ቁራዎችም ሳያርሱ የሰው ልጆች አዝመራን ይቀሙ ዘንድ ከምድር ላይ ዘሩን ይለቅሙ ጀመር። ስለዚህም አሞራዎችና ወፎች ያስቸግሩአቸው ነበርና፥ ዘራቸውንም ይበሉባቸው ነበርና ስሙን ታራ አለው።'),
  ('b7bc80df-ac76-55c1-a324-54ac983062bf', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 30, 30, 'ከወፎቹም ፊት የተነሣ ዓመቶች ድርቅ ይሆኑ ጀመር፤ የእንጨቱንም ፍሬ ሁሉ ከዛፎቹ ላይ እየለቀሙ ይበሉ ነበር፥ በዘመናቸው ከምድር ፍሬ ሁሉ ጥቂት ማዳን ቢችሉም በታላቅ ኀይል ነበር። በሠላሳ ዘጠነኛውም ኢዮቤልዩ በሁለተኛው ሱባዔ በመጀመሪያው ዓመት ታራ ሚስት አገባ፤ ስምዋም ኤድና ይባላል፤ ይህችውም የአባቱ የእኅት ልጅ የምትሆን የአብራም ልጅ ናት። በዚህም ሱባዔ በሰባተኛው ዓመት ወንድ ልጅን ወለደችለት። የልጁ ልጅ ሳይፀነስ ሙቶአልና ስሙን በእናቱ አባት ስም አብራም አለው።'),
  ('923499f1-42a6-5bd6-a198-90c966908901', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 31, 31, 'ያም ልጅ ሰው ሁሉ ጣዖታቱን በመከተልና ኀጢአትን በመሥራት እንደሚስት የምድርን ስሕተት ያውቅ ጀመር።'),
  ('9bfdfec9-63ae-5bf3-a5a6-7132006cc278', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 32, 32, 'አባቱም መጽሐፍን አስተማረው፤ የሁለት ሱባዔ ዓመት ልጅም ነበረ። ከእርሱም ጋር ለጣዖት እንዳይሰግድ አባቱን ከመከተል ተለየ።'),
  ('151bb354-eec1-54b0-a027-1e3d4498582c', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 33, 33, 'ከሰዎች ልጆች ስሕተትም ያድነው ዘንድ፥ ዕጣውም ርኵሰትንና ፌዝን በመከተል ወደ ስሕተት እንዳይሆን ሁሉን ወደ ፈጠረ ወደ እግዚአብሔር ይጸልይ ጀመር።'),
  ('3a4574b3-fe97-5963-ab56-ce9185d062b4', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 34, 34, 'በምድርም ዘርን ለመዝራት ጊዜው ደረሰ፤ ዘራቸውንም ከአሞራዎች ይጠብቁ ዘንድ ሁሉም በአንድነት ወጡ።'),
  ('a2f2b53b-bab1-57f6-acca-a62c6a2ee182', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 35, 35, 'አብራምም ከወጡ ልጆች ጋር ወጣ። እርሱም የዐሥራ አራት ዓመት ልጅ ነበረ፤ ብዙዎች ቁራዎችም ዘርን ይለቅሙ ዘንድ መጡ። አብራምም በምድር ላይ ሳያርፉ በፊታቸው ይሮጥ ነበር፤ ዘርንም ለመልቀም በምድር ላይ ሳያርፉ፥ “ወደ መጣችሁበት ቦታ ተመለሱ እንጂ ወደ ምድር አትውረዱ” እያለ ይጮኽ ነበር፤ እነርሱም ተመለሱ።'),
  ('71a5c229-59be-58d4-afa9-a52db33681a7', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 36, 36, 'በዚያችም ቀን ብዙዎች ቁራዎችን ለመከላከል ሰው አስቀመጡ። አብራምም ባለበት በዚያ እርሻ ሁሉ ከቁራዎች ሁሉ አንድም ቁራ አላረፈም።'),
  ('69e2f060-d95a-5d87-a857-9d8bf25e7f33', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 37, 37, 'በእርሻዎቹ ውስጥ ከእርሱ ጋር ያሉት ሰዎች ሁሉ ሲጮኽና አሞራዎችን ሁሉ፦ ተመለሱ ሲላቸው ይሰሙት ነበር፤ ስሙም በከላውዴዎን ምድር ሁሉ ከፍ ከፍ አለ።'),
  ('f8f75c00-39d3-5f7b-aa95-2176096cb356', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 38, 38, 'የሚዘሩም ሰዎች ሁሉ በዚህ ዓመት ወደ እርሱ ይመጡ ነበር። የዘሩ ወራትም እስኪፈጸም ድረስ ከእነርሱ ጋር ይሄድ ነበር። ምድራቸውንም ዘሩ፤ በዚያም ዓመት የሚበቃ እህልን አገቡ፤ በልተውም ጠገቡ።'),
  ('62016601-8b31-5fec-ad30-d4560b61b83d', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 39, 39, 'አብራምም በአምስተኛው ሱባዔ በአንደኛው ዓመት የበሬ ዕቃ ለሚሠሩት ሰዎች እንጨት መጥረብን አስተማረ።'),
  ('6d958df8-663c-5298-a7d1-ad20753bb52b', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 40, 40, 'በምድርም ላይ የበሬ ዕቃ ሠሩ፤ በላዩም ዘርን ያኖር ዘንድ በድግሩ አንጻር እርፍን ሠራ፤ ዘሩም በእርፉ ጫፍ ወርዶ በምድር ይሸፈን ነበር። ከዚህም በኋላ ከአሞራዎቹ ፊት የተነሣ አልፈሩም ነበር፤ በእርፉም ድግር ሁሉ ላይ እንዲህ አደረጉ፤ በምድርም ላይ የእርፉን ድግር አኖሩ።'),
  ('1107555a-c725-5649-af5d-e8b3ef5df33a', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 41, 41, 'ዘርንም ዘሩ፤ ሰዎችም ሁሉ አብራም እንዳዘዛቸው ሁሉን አደረጉ። ከዚያ በኋላ ከአሞራዎቹ የተነሣ አልፈሩም።'),
  ('952454a3-5262-5667-ab5d-5094538e6eb9', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 42, 42, 'በስድስተኛው ሱባዔ በሰባተኛው ዓመት አብራም አባቱ ታራን፥ “አባ አባቴ፥” ብሎ ጠራው። እርሱም፥ “ልጄ ሆይ፥ እነሆኝ፥” አለው። እርሱም፥ “ምንም እስትንፋስ የላቸውምና አንተ ከምታመልካቸውና በፊታቸው ከምትሰግድላቸው ከእነዚህ ከጣዖታቱ ለእኛ ምን ረድኤትና ደስታ አለን? ድዳዎች ናቸውና፥ ልቡናንም የሚያስቱ ናቸውና አታምልኩአቸው።'),
  ('27507399-99ac-51cb-adb1-43c4ba44b071', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 43, 43, 'ሰማይን የፈጠረ፥ በምድርም ላይ ዝናብንና ጠልን የሚያወርደውን፥ በምድር ላይ ሁሉን የሚያደርገውን፥ ሁሉንም በቃሉ የፈጠረውን፥ ሕይወትም ሁሉ ከእርሱ የሚገኘውን የሰማይን አምላክ አምልኩ።'),
  ('e8ca5122-a8dc-5877-ae21-6c00ae94a84c', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 44, 44, 'እስትንፋስ የሌላቸው ጣዖታቱን እናንተ ለምን ታመልካላችሁ? እነርሱ የሰው ሥራ ናቸውና፥ እናንተ በጫንቃችሁ ትሸከሙአቸዋላችሁና፥ ለሚሠሩአቸው ሰዎች ታላቅ ተዋርዶ ናቸው እንጂ ከእነርሱ ረድኤት አይገኝምና፥ ለሚያመልኩአቸውም ሰዎች የልቡና ስሕተት ናቸውና አታምልኩአቸው።”'),
  ('13083546-0d6a-569a-aef8-a997195ed7be', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 45, 45, 'አባቱም፥ “ልጄ ሆይ፤ እኔም አውቃለሁ፤ ነገር ግን በፊታቸው እንዳገለግል ላደረጉኝ ለሕዝቡ ምን አደርጋለሁ? እውነት ነገርንም ብነግራቸው፥ ያመልኩአቸውና ያመሰግኑአቸው ዘንድ ልቡናቸው እነርሱን ተከትላለችና ይገድሉኛል፤ ልጄ ሆይ፥ እንዳይገድሉህ ዝም በል” አለው።'),
  ('85364e81-e30b-5fe0-aa84-1c6b9a5919be', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 46, 46, 'ለሁለቱ ወንድሞቹም ይህን ነገር ነገራቸው፤ እነርሱም ተቈጡት፤ እርሱም ዝም አለ።'),
  ('13e1d491-4717-5db4-abfb-0b526ad6c76b', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 47, 47, 'በአርባው ኢዮቤልዩ በሁለተኛው ሱባዔ በሰባተኛው ዓመት አብራም ሚስት አገባ፤ ስምዋም ሶራ ይባላል፤ ይህችውም የአባቱ ልጅ ናት፤ ሚስትም ሆነችው።'),
  ('bb0102ea-9f2c-5498-a486-83db1e53b8ef', 'cc4ddfd5-e2f0-5f3c-af70-630386238a5c', '883e2dd1-d5bb-5044-a7df-f6cac51f4faa', 48, 48, 'ወንድሙ አራንም በሦስተኛው ሱባዔ በሦስተኛው ዓመት ሚስት አገባ። በዚህም ሱባዔ በሰባተኛው ዓመት ልጅ ወለደችለት፤ ስሙንም ሎጥ አለው። ወንድሙ ናኮርም ሚስትን አገባ።'),
  ('38c8bb43-af97-5eb9-a355-84c795319e18', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 1, 1, 'አብራም በሕይወት በኖረበት በስድሳኛው ዓመት፥ ይኸውም በአራተኛው ሱባኤ በአራተኛው ዓመት፥ አብራም ሌሊት ተነሥቶ የጣዖታቱን ቤት አቃጠለ። በቤት ያለውንም ዕቃ ሁሉ አቃጠለ። ያወቀ ሰው ግን አልነበረም።'),
  ('26754722-0a5e-5cbd-a625-f1ec16d66497', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 2, 2, 'በሌሊትም ተነሥተው ጣዖቶቻቸውን ከእሳት ውስጥ ያወጡ ዘንድ ወደዱ።'),
  ('fc61313d-67ef-564f-a227-e011c866efa8', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 3, 3, 'አራንም ያድናቸው ዘንድ ተወረወረ፤ በላዩም እሳት ነደደበት፤ በእሳትም ተቃጥሎ የከላውዴዎን ዕጣ በምትሆን በዑር በአባቱ በታራ ፊት ሞተ። የከላውዴዎን ዕጣ በምትሆን በዑርም ቀበሩት።'),
  ('a4b295c1-baee-53cb-a4c8-024e44e177b0', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 4, 4, 'ታራም የከላውዴዎን ዕጣ ከምትሆን ከዑር ወጣ። እርሱና ልጆቹ ወደ ሊባኖስ ምድርና ወደ ከነዓን ምድር፥ ወደ ካራንም ምድር ይመጡ ዘንድ ወጣ።'),
  ('c6256181-9ce7-585a-a59d-a6db09a7f54f', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 5, 5, 'አብራምም ከአባቱ ጋር በካራን ሁለት የዓመቶች ሱባዔ ተቀመጠ።'),
  ('38dbedf2-f453-5a8f-aa29-cc5234698eb9', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 6, 6, 'በስድስተኛው ሱባዔ በአምስተኛው ዓመት አብራም ተነሣ፤ በሰባተኛው ወር መባቻ ከማታ እስከ ጥዋት ድረስ ከዋክብትን ይቈጥር ዘንድና ስለ ዝናም የዓመቱ ጠባይ ምን እንደሚሆን ያይ ዘንድ በሌሊት ወጥቶ ተቀመጠ።'),
  ('3274ba65-5ae8-533f-ad97-cbedbe9c9f46', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 7, 7, 'ብቻውንም ተቀምጦ ይቈጥር ነበር፥ ቃልም ወደ ልቡ መጣ፤ “የከዋክብት ምልክት ሁሉ፥ የፀሐይና የጨረቃም ምልክት ሁሉ በእግዚአብሔር እጅ ነው። ጥዋትም ማታም ያዘንብ ዘንድ ቢወድ፥ እንዳያዘንብም ቢወድ እኔ ለምን እመራመራለሁ? ሁሉም በእጁ ነው” አለ።'),
  ('eb3b42e5-3d7b-515f-a0b3-bd79d51f4133', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 8, 8, 'በዚህችም ሌሊት ጸለየ፥ እንዲህም አለ፥ “አምላኬ አምላኬ ሆይ፥ ልዑል አምላክ፥ አንተ ብቻ ለእኔ አምላክ ነህ፤ አንተ ሁሉን ፈጠርህ፤ የእጅህ ፍጥረት ሁሉ ጸንቶ ይኖራል፤ እኔ አንተንና መንግሥትህን ወደድሁ፤ ከክፉዎች በሰው ልቡና ከሚሠለጥኑ ከመናፍስት እጅ አድነኝ፤ አምላኬ ሆይ፥ አንተን ከመከተል አያስቱኝ፤ እኔንም ዘሬንም ከዛሬ ጀምሮ እስከ ዘለዓለም ድረስ ለዘለዓለም እንዳንስት አድርገን።'),
  ('8cdfb83e-b6cb-5727-a10d-5c5e9b8c68fa', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 9, 9, 'ወደ እነርሱም እመለስ ዘንድ ፊቴን ወደሚሹ ወደ ከላውዴዎን ዑር ልመለስን? ወይስ በዚህ ቦታ ልቀመጥ? ያገለግል ዘንድ በባሪያህ እጅ የቀናውን መንገድ በፊትህ አቅና። አምላኬ ሆይ፥ በልቡናዬ ስሕተት አልሂድ።”'),
  ('213327fc-03e8-55d0-aa88-802488a814cc', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 10, 10, 'እርሱም ይህን ተናግሮና ጸልዮ በጨረሰ ጊዜ፥ እነሆ፥ የእግዚአብሔር ቃል በእኔ እጅ እንዲህ ሲል ወደ እርሱ ተላከ፥ “አንተ ከሀገርህ፥ ከዘመዶችህና ከአባትህ ቤት ወጥተህ እኔ ወደማሳይህ ሀገር ሂድ፤ እጅግም ብዙ ወገን አደርግሃለሁ፤ እባርክህማለሁ፤ ስምህንም ከፍ ከፍ አደርጋለሁ፤ በምድሩም ሁሉ የተባረክህ ትሆናለህ።'),
  ('6a1f61ff-d3d7-5d8d-a5c7-56150f81ab42', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 11, 11, 'የምድር አሕዛብም ሁሉ በአንተ ይባረካሉ፤ የሚመርቁህን እመርቃቸዋለሁ፤ የሚረግሙህንም እረግማቸዋለሁ። ለአንተና ለልጆችህ፥ ለልጅ ልጆችህም፥ ለዘርህም ሁሉ አምላክ እሆናቸዋለሁ፤ ከአንተም በኋላ ከዛሬ ጀምሮ እስከ ልጅ ልጅ ዘመን ድረስ አምላክህ እኔ ነኝና አትፍራ።”'),
  ('fe35f909-8dd6-52b2-a77a-c722f7ab5064', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 12, 12, 'እግዚአብሔር አምላክም እንዲህ አለኝ፥ “ከውድቀት ቀን ጀምሮ ከሰው ልጅ ሁሉ ቋንቋ ተለይቶአልና የተገለጠች ቋንቋን ይሰማና ይናገር ዘንድ አፉንና ጆሮውን ክፈት።”'),
  ('1fcf80ae-09a9-51ce-ad62-2b46e79009e8', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 13, 13, 'እኔም አፉንና ጆሮውን፥ ከንፈሩንም ከፈትሁ፤ በትውልድ ቋንቋው በዕብራይስጥ ቋንቋም ከእርሱ ጋር እናገር ጀመርሁ፤ የአባቶቹንም መጽሐፍ ወሰደ፤ እነዚያም በዕብራይስጥ ቋንቋ የተጻፉ ነበሩ። ደግሞም ጻፋቸው፤ ከዚያም ቀን ጀምሮ ይማራቸው ጀመር። የጸነነውንም ሁሉ እኔ እነግረው ነበር፤ ዝናብም በሚዘንብባቸው በስድስቱ ወሮች ተማራቸው።'),
  ('1199b9ae-9337-5721-aff0-ea243f4eedd9', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 14, 14, 'በስድስተኛው ሱባዔ በሰባተኛው ዓመት እንዲህ ሆነ፤ ከአባቱ ጋር ተነጋገረ፤ ከካራን ወደ ከነዓን ሄዶ አይቶአት ወደ እርሱ ይመለስ ዘንድ እንደሚሄድ ነገረው።'),
  ('22967721-25c5-511d-af9c-65ef416e1405', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 15, 15, 'አባቱ ታራም እንዲህ አለው፥ “በሰላም ሂድ፤ የሰላም አምላክም ጎዳናህን ያቅናልህ፤ እግዚአብሔርም ከአንተ ጋር ይሁን፤ ከክፉ ሁሉ ይጠብቅህ፤ በሚያዩህ ሰዎች ፊት ቸርነትንና ይቅርታን፥ መወደድንም ይስጥህ፤ በአንተም ላይ ክፉ ነገርን ለማድረግ የሰው ልጆች ሁሉ አይሠልጥኑብህ፤ በሰላም ሂድ።'),
  ('952e6ed7-fb69-514c-a321-26f535ef81a5', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 16, 16, 'በእርስዋም ለመኖር ለዐይኖችህ ያማረች ምድርን ብታይ፥ መጥተህ ወደ አንተ ውሰደኝ፤ ለአንተ ልጅ ይሆንህ ዘንድ የወንድምህን የአራን ልጅ ሎጥንም ከአንተ ጋር ውሰደው፤ እግዚአብሔርም ከአንተ ጋር ይሁን፤ በሰላም እስክትመለስም ድረስ ወንድምህ ናኮርን በእኔ ዘንድ ተወው፤ ሁላችንም በአንድነት ከአንተ ጋር እንሄዳለን።”'),
  ('7a40a23c-9756-5418-a1e5-b43f56e0be63', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 17, 17, 'አብራምም ሚስቱን ሶራንና የወንድሙን የአራን ልጅ ሎጥን ይዞ ከካራን ወደ ከነዓን ሄደ። ወደ ሱርም መጣ፤ እስከ ሰቂሞንም ድረስ ተመላለሰ፤ በረጅም ግራር ሥር አደረ፤ ከኢማት መግቢያ ጀምሮ ረጅም ግራር እስካለበት ድረስ ሀገሪቱ እጅግ ያማረች እንደ ሆነች እነሆ፥ አየ።'),
  ('6f4a85c3-5a41-5ca7-a5ab-eeffe926b4db', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 18, 18, 'እግዚአብሔርም፥ “ለአንተና ለልጆችህ ይህችን ሀገር እሰጣችኋለሁ” አለው። በዚያም መሠዊያን ሠራ፤ ለተገለጠለት ለእግዚአብሔርም በመሠዊያው ላይ የሚቃጠል መሥዋዕትን አቀረበ።'),
  ('8c12a943-b2ce-5f00-ac4a-29b0405067d7', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 19, 19, 'ከዚያም ተነሥቶ በምዕራብ አንጻር ወዳለች ወደ ቤቴል ተራራና በምሥራቅ አንጻር ወዳለች ወደ ጋይ ሄደ፤ በዚያም ድንኳኑን ተከለ፤ ባያትም ጊዜ፥ እነሆ፥ ሀገሪቱ ሰፊ ነበረች፤ እጅግም ያማረች ነበረች፤ ሁሉም በእርስዋ ላይ ይበቅላል፤ ወይን፥ በለስ፥ ሮማን፥ ወይራ፥ ግራር፥ ቡጥን፥ ዘይት፥ ዋንዛ፥ ሰኖባር፥ የሊባኖስም ዛፍ፥ የዱርም ዛፍ ሁሉ የሚበቅልባት ናት፤ ውኃውም በተራራው ላይ ነበር።'),
  ('b4050bd5-86ac-5439-ab6f-cd55a05caf0e', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 20, 20, 'የከላውዴዎናውያን ዕጣ ከምትሆን ከዑር አውጥቶ ወደዚህ ተራራ ያመጣውን እግዚአብሔርንም አመሰገነው።'),
  ('22a5dcf7-8dcd-5760-a02c-dd77f5dbbbbe', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 21, 21, 'በሰባተኛው ሱባዔ በመጀመሪያው ዓመት በመጀመሪያው ወር መባቻ እንዲህ ሆነ። በዚያ ተራራ መሠዊያን ሠራ፤ የእግዚአብሔርንም ስም ጠራ፥ “አንተ አምላኬ ሆይ፥ የዘለዓለም አምላክ አንተ ነህ” አለ። እግዚአብሔር ከእርሱ ጋር ይኖር ዘንድ በሕይወቱም ዘመን ሁሉ እንዳይለየው በመሠዊያው ላይ ለእግዚአብሔር የሚቃጠል መሥዋዕትን አቀረበ።'),
  ('211a5beb-d0d9-59a6-ac5e-229c3b2ba62b', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 22, 22, 'ከዚያም ተነሥቶ ወደ ደቡብ ሄደ፤ እስከ ኬብሮንም ደረሰ። ኬብሮንም ያንጊዜ ተሠርታ ነበር። በዚያም ሁለት ዓመት ተቀመጠ። ሎጥም እስኪገባ ድረስ ወደ ደቡብ ሀገር ሄደ።'),
  ('db6944bc-f777-5682-a3ff-d68216536b78', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 23, 23, 'በምድርም ድርቅ ሆነ፤ አብራምም በዚህ ሱባዔ በሦስተኛው ዓመት ወደ ግብፅ ሄደ፤ ሚስቱ ከእርሱ ሳትወሰድ በግብፅ አምስት ዓመት ኖረ። የግብፅ ክፍል የምትሆን ጠናይስም ያንጊዜ ከኬብሮን በኋላ በሰባት ዓመት ተሠርታ ነበር።'),
  ('45cc2dc6-930b-57c9-a5fc-abf34d5dbb95', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 24, 24, 'ፈርዖንም የአብራምን ሚስት ሶራን በወሰዳት ጊዜ እንዲህ ሆነ፤ ስለ አብራም ሚስት ስለ ሶራ እግዚአብሔር ፈርዖንን በደዌ ገረፈ፤ ቤተ ሰቡንም ሁሉ በጽኑ መቅሠፍት ገረፈ።'),
  ('28d03d9e-d5bd-56b6-a94d-4216eaa6d6b3', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 25, 25, 'አብራምም በገንዘብ፥ በበጎችና በላሞች፥ በአህዮችና በፈረሶች፥ በግመሎችም፥ በወንዶች ባሪያዎችና በሴቶች ባሪያዎች፥ በብርና በወርቅ እጅግ የከበረ ነበረ። የወንድሙ ልጅ ሎጥም በገንዘብ እንደ እርሱ የከበረ ነበረ።'),
  ('85e7453f-201b-5502-ad62-882759df52a8', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 26, 26, 'ፈርዖንም የአብራምን ሚስት ሶራን መለሰ። ከግብፅም ተነሥቶ በቤቴል ምሥራቅና በምዕራብ መካከል ወደ አለው ቀድሞ ድንኳኑን ተክሎበት ወደ ነበረው ወደ ጋይ የመሠዊያ ቦታ ሄደ።'),
  ('912cc6c5-99b3-50d8-aa28-b241c88c375b', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 27, 27, 'በሰላም የመለሰው አምላኩ እግዚአብሔርንም አመሰገነው።'),
  ('26b03664-229e-5266-a6be-7edb914e12fa', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 28, 28, 'በአርባ አንድ ኢዮቤልዩ፥ በመጀመሪያው ሱባዔ በሦስተኛው ዓመት እንዲህ ሆነ፤ ወደዚህ ቦታ ተመለሰ፤ በመሠዊያውም ላይ የሚቃጠል መሥዋዕትን አቀረበ፤ የእግዚአብሔርንም ስም ጠራ፥ “ልዑል አምላክ የምትሆን አንተ እግዚአብሔር ሆይ፥ ለዘለዓለም አምላኬ ነህ” አለ።'),
  ('fbce1130-3e77-532f-a8a0-a1f43caaf8f6', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 29, 29, 'በዚህ ሱባዔ በአራተኛው ዓመት ሎጥ ከእርሱ ተለየ፤ በሰዶምም ኖረ። የሰዶም ሰዎች ግን እጅግ ኀጢአተኞች ነበሩ። የወንድሙም ልጅ ከእርሱ ስለ ተለየ በልቡ አዘነ። ሎጥ በተማረከበት በዚያ ዓመት ልጅ አልነበረውምና።'),
  ('87f7df25-c32e-5eb6-a36b-bc24a071708a', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 30, 30, 'ሎጥም ከእርሱ ከተለየ በኋላ በዚህ ሱባዔ በአራተኛው ዓመት እግዚአብሔር አብራምን አለው፥ “በዚያ ትኖር ዘንድ ካለህበት ከዚያ ቦታ ሁነህ ዐይኖችህን ወደ ሰሜንና ሊባ፥ ወደ ባሕርና ምሥራቅ አቅና፤ ይህችን የምታያትን ሀገር ሁሉ ለአንተና ለልጆችህ እስከ ዘለዓለም ድረስ እሰጣችኋለሁና።'),
  ('d57b3db5-f036-5bbb-a00d-80ea051c2040', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 31, 31, 'ልጆችህንም እንደ ባሕር አሸዋ አደርጋለሁ፤ ሰው የባሕር አሸዋን መቍጠር ይችል እንደ ሆነ ልጆችህም ይቈጠራሉ፤ ተነሥተህ ቁመቷንና ወርድዋን ዙራት፤ ሁሉንም ተመልከት፤ ለልጆችህ እሰጣታለሁና።”'),
  ('eeb32101-1bad-53d4-a782-e602225ba0e8', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 32, 32, 'አብራምም ወደ ኬብሮን ሄደ፤ በዚያም ተቀመጠ።'),
  ('5d0a07dd-e595-5ab2-aaeb-c5b2fe2b16ce', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 33, 33, 'በዚያም ዓመት የኤላም ንጉሥ ኮሎዶጎሞር መጣ፤ የሰናዖርም ንጉሥ አምራፌል፥ የሲላሳር ንጉሥ አሪኦክ፥ የአሕዛብ ንጉሥም ቲርጋል መጡ፤ የገሞራንም ንጉሥ ወጉት።'),
  ('2ac958e7-ac48-5823-a446-1138cf497687', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 34, 34, 'የሰዶም ንጉሥ ግን ሸሸ፤ በጨው ባሕር በኩል በሲዲም ሸለቆ ብዙ ሰዎች በጦር ቈስለው ወደቁ፤ ሰዶምንና አዳማን ሴቦኢምንም ማረኩ፤ የአብራምን የወንድሙን ልጅ ሎጥንም ማረኩ፤ ገንዘቡንም ሁሉ ዘረፉ፤ እስከ ዳንም ድረስ ሄደ። ከጦር ያመለጠ አንድ ሰውም መጥቶ የወንድሙ ልጅ ሎጥ እንደ ተማረከ ለአብራም ነገረው። አሽከሮቹንም አስታጠቀ።'),
  ('058cbe79-6461-5755-aa36-5bd4238c998b', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 35, 35, 'ከቀዳምያት ሁሉ ለእግዚአብሔር ዐሥራትን እንዲሰጡ በአብርሃምና በልጆቹ ሥርዐት ተሠራ። እግዚአብሔርም ለዘለዓለም ይይዙት ዘንድ በፊቱ ለሚያገለግሉ ለካህናቱ እንዲሰጡአቸው የዘለዓለም ሥርዐትን ሠራ።'),
  ('e0d3e8b3-5564-5f85-aac7-37d76ce699ae', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 36, 36, 'ከሁሉም ከእህሉም፥ ከወይኑም፥ ከዘይቱም፥ ከላሞችም፥ ከበጎችም፥ ከፍየሎችም ለእግዚአብሔር ዐሥራት ይሰጡ ዘንድ ለልጅ ልጅ ለዘለዓለም ሠርቶታልና ለዚህ ሕግ የተወሰነ ዘመን የለውም።'),
  ('912d0a5b-d0d5-50ea-afba-324c1a3528a0', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 37, 37, 'እርሱም በፊት ደስ ብሎአቸው ሊበሉትና ሊጠጡት ለካህናት ሰጠ።'),
  ('374d1d3e-c1cd-5b81-a06b-6ca14063defd', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 38, 38, 'የሰዶምም ንጉሥ ወደ እርሱ ደረሰ፤ በፊቱም ሰገደ፥ “ጌታችን አብራም ሆይ ፥ ያዳንኸውን ሰው ስጠን፤ ምርኮው ግን ለአንተ ይሁንልህ” አለው።'),
  ('1caaa429-f9f1-500c-a428-156c1834e91b', 'e9cff146-bfa3-5a03-a6f3-0e273c8f9328', '194928c0-37aa-5a01-ac2b-ff2789a0fd81', 39, 39, 'አብራምም፥ “እኔ አብራምን አበለጸግሁት የምትል እንዳትሆን፥ ጐልማሶች ከበሉት በቀር ከአንተ ገንዘብ ሁሉ የክር ፈትልና የጫማ ጠፍር እንዳልወስድ ገናና ወደ ሆነ አምላኬ እኔ እጆችን አነሣለሁ፤ ነገር ግን ከእኔ ጋር የሄዱ ሰዎች አውናንና ኤሴኬል፥ መምሬም እነርሱ ፈንታቸውን ይውሰዱ” አለው።'),
  ('9d1997fd-f7e7-5ea1-abec-3723c9bb9846', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 1, 1, 'ከዚህ ነገር በኋላ በዚህ ሱባዔ በአራተኛው ዓመት በሦስተኛው ወር መባቻ፥ “አብራም፥ አትፍራ፤ ጠበቃህ እኔ ነኝ፤ ዋጋህም እጅግ ይበዛል፥” ሲል የእግዚአብሔር ቃል በሕልም ወደ አብራም መጣ።'),
  ('0487ef05-b13e-5b73-ab4b-09be50b4fc39', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 2, 2, 'እርሱም እንዲህ አለ፥ “አቤቱ፥ ምን ትሰጠኛለህ? እኔ ልጅ ሳልወልድ እሄዳለሁ፤ የደማስቆ ሰው የሚሆን የአማቲየል'),
  ('a07ca3af-0ef0-5df2-ac2d-752587346b36', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 3, 3, 'እርሱም፥ “ከአብራክህ የሚወለድ ልጅ እርሱ ይወርስሃል እንጂ ይህ አይወርስህም” አለው።'),
  ('e34fed2b-9405-5236-af7b-987c4fa600aa', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 4, 4, 'ወደ ውጭም አውጥቶ፥ “ወደ ሰማይ ተመልከት፤ መቍጠር ይቻልህ እንደ ሆነ ከዋክብትን ቍጠር” አለው። ሰማይን አየ፤ ከዋክብትንም ተመለከተ፤ እርሱም፥ “ዘርህ እንደዚህ ይሆናል” አለው። እግዚአብሔርንም አመነው፤ ጽድቅ ሆኖም ተቈጠረለት።'),
  ('6b7cabfb-9104-5755-a144-705f2f29e9fa', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 5, 5, '“ለዘለዓለም ይዘሃት ልትኖር'),
  ('d6708c60-9322-5d46-a0d4-e0bfbfc98afa', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 6, 6, 'እርሱም፥ “አቤቱ አቤቱ፥ እንደምወርሳት በምን አውቃለሁ?” አለ።'),
  ('b8147506-eb92-5abf-a7ef-aecc18680c87', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 7, 7, 'እርሱም፥ “የሦስት ዓመት ወይፈን፥ የሦስት ዓመት ፍየል፥ የሦስት ዓመት በግ፥ ዋኖስና ርግብንም አምጣልኝ” አለው።'),
  ('503bd2cf-af73-50dd-a3b0-9bb50464e77b', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 8, 8, 'ይህንም ሁሉ በወር እኩሌታ አመጣ። እርሱ ግን የኬብሮን አቅራቢያ በምትሆን በመምሬ ባለ ግራር ሥር ተቀምጦ ነበር።'),
  ('9c3f2951-7021-5db2-a2f3-cac6ff0015cc', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 9, 9, 'በዚያም መሠዊያን ሠራ፥ ይህንም ሁሉ ሠዋ፤ በመሠዊያውም ላይ ደማቸውን አፈሰሰ፤ ከሁለት ከሁለትም አደረጋቸው፤ በየመልካቸውም በአንጻራቸው አኖራቸው፤ አዕዋፍን ግን ጨርሶ አልቈረጣቸውም። ወፎችም ወደ መሥዋዕቱ ይወርዱ ነበር።'),
  ('4fb466d2-6db1-5a48-a3ed-aa8feb310eb7', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 10, 10, 'አብራም ግን ይከለክላቸው ነበር፤ ወፎችም ይበሉአቸው ዘንድ አልተወም ነበር።'),
  ('2aa584b1-2953-50ac-a21a-9c7c861e784f', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 11, 11, 'ፀሐይም በገባ ጊዜ እንዲህ ሆነ፥ በአብራም እንቅልፍ መጣበት ፤ እነሆም፥ የሚያስፈራ ጽኑ ጨለማ በላዩ ወደቀበት።'),
  ('8f96cce9-568a-5dbc-ac46-84d152975f56', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 12, 12, 'ለአብራምም እንዲህ ተብሎ ተነገረ፥ “ዘርህ በአሕዛብ ሀገር ስደተኞች እንደሚሆኑ፥ አራት መቶ ዓመትም እንደሚገዙአቸውና መከራ እንደሚያጸኑባቸው ፈጽመህ ዕወቅ፤ የሚገዙአቸውንም ወገኖች እኔ እፈርድባቸዋለሁ።'),
  ('3870fd7a-2b23-5616-a934-7849ddc1c997', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 13, 13, 'ከዚህ በኋላ ከብዙ ገንዘብ ጋር ከዚያ ይወጣሉ። አንተም ወደ አባቶችህ በሰላም ትሄዳለህ፤ በበጎ እርግናም ትቀበራለህ።'),
  ('0f2ef90e-2689-5723-a6cc-3df87bd7454c', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 14, 14, 'በአራተኛው ትውልድ ወደዚህ ይመለሳሉ፤ እስከ ዛሬ ድረስ የአሞራውያን ኀጢአት አልተፈጸመምና።”'),
  ('86c8c871-f051-5b59-ad26-48bdb6c41d84', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 15, 15, 'ከእንቅልፉም ነቅቶ ተነሣ፤ ፀሐይም ገባ፤ እሳትም ይነድ ጀመር፤ እነሆ፥ ምድጃው እየጤሰ የእሳቱ ነበልባል በመሠዊያው መካከል አለፈ።'),
  ('bde305e1-4859-5e91-ae10-dadc2a9ee1bc', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 16, 16, 'በዚያችም ሌሊት እግዚአብሔር ከአብራም ጋር እንዲህ ሲል ቃል ኪዳን አደረገ፥ “ከግብፅ ወንዝ ጀምሮ እስከ ታላቁ ወንዝ፤ እስከ ኤፍራጥስ ወንዝ ድረስ፥ ይህችን ሀገር ለልጆችህ እሰጣለሁ፤ የቄኔዎስንና የቄኔዜዎስን፥ የቀድሞኔዎስን፥ የፌርዜዎስንና የራፋይምን፥ የፌኮሬዎስን፥ የኤዌዎስንና የአሞሬዎስን፥ የከናኔዎስንና የጌርጌሴዎስን፥ የኢያቡሴዎስንም ሀገር እሰጥሀለሁ።”'),
  ('2e98ed03-0e1c-565b-a24a-013a0e9ef0bf', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 17, 17, 'አብራምም ሄዶ መሠዊያውን አዘጋጀ፤ አዕዋፍንና መሥዋዕታቸውን፥ ወይናቸውንም አቀረበ፤ እሳትም በላው።'),
  ('9c8b9992-dc39-5008-a193-2ae9bd0f91ae', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 18, 18, 'በዚያችም ወር ከኖኅ ጋር ቃል ኪዳን እንደ አደረግን በዚችም ዕለት ከአብራም ጋር ቃል ኪዳን አደረግን።'),
  ('06c7f08d-4584-51b7-ae3d-b3cb03fba61e', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 19, 19, 'አብራምም ይህችን በዓልና ሥርዐቷንም እስከ ዘለዓለም ድረስ ለራሱ አጸናት፤ አብራምም ደስ አለው፤ ይህንም ነገር ሁሉ ለሚስቱ ለሶራ ነገራት፤ ልጅ እንደሚወለድለትም አመነ። እርስዋ ግን ልጅ አትወልድም ነበር፤ ሶራም ባልዋን አብራምን መከረችው፦'),
  ('147d94cc-971f-5ca8-a508-483c57ce996f', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 20, 20, 'አብራምም የሚስቱ የሶራን ቃል ሰማ፥ “እንዳልሽ አድርጊ” አላት። ሶራም ግብፃዊት አገልጋይዋን አጋርን አምጥታ ሚስት ትሆነው ዘንድ ለባልዋ ለአብርሃም ሰጠቻት።'),
  ('4b9846e1-69f0-589b-aa5e-bae6b224ef1e', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 21, 21, 'ወደ እርስዋም ገባ፥ ፀነሰች፥ ወንድ ልጅንም ወለደች። በዚህ ሱባዔ በአምስተኛው ዓመት ስሙን ይስማኤል ብሎ ጠራው። በዚያም ዓመት የአብራም ዕድሜ ሰማንያ ስድስት ዓመት ነበር።'),
  ('440b1b32-9acf-5f14-a48b-cd414f93a461', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 22, 22, 'በዚህ ኢዮቤልዩ በአራተኛው ሱባዔ በአምስተኛው ዓመት በሦስተኛው ወር በወሩ እኩሌታ መጀመሪያ ስለ ደረሰው የስንዴ አዝመራ አብራም በዓልን አደረገ።'),
  ('30f47f0b-0201-5f25-a306-614bd3ab34f0', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 23, 23, 'በመሠዊያውም ላይ የእህሉን መጀመሪያ አዲስ መሥዋዕት አድርጎ ለእግዚአብሔር አቀረበ፤ ወይፈኑንና የበጉን ሙክት፥ በጉንም በመሠዊያው ላይ የሚቃጠል መሥዋዕት አድርጎ ለእግዚአብሔር አቀረበ። መሥዋዕታቸውንና ወይናቸውንም ከነጭ ዕጣን ጋር አቀረበ።'),
  ('3018c4a7-f53a-5433-a013-2e45f05eeeb2', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 24, 24, 'እግዚአብሔርም ለአብራም ተገለጠለት፤ እንዲህም አለው፥ “ሁሉን ቻይ አምላክ እኔ ነኝ። በፊቴ የምትወደድ ሁን፤ ፍጹምም ሁን፤ በእኔና በአንተ መካከልም ቃል ኪዳን እሰጣለሁ፤ እጅግም አከብርሃለሁ።”'),
  ('bbf78a0e-d29f-5e87-aa0b-9af30fc48d85', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 25, 25, 'አብራምም በግንባሩ ወደቀ፤ እግዚአብሔርም እንዲህ ብሎ ተናገረው፥ “እነሆ፥ ሥርዐቴ ከአንተ ጋር ነው፤ ለብዙ አሕዛብም አባት አደርግሃለሁ።'),
  ('6fc537cc-7aef-54de-aae8-f70db003c9fd', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 26, 26, 'እንግዲህ ወዲህ ስምህ አብራም አይባል፤ የብዙ ሕዝብ አባት አድርጌሃለሁና ከዛሬ ጀምሮ እስከ ዘለዓለም ድረስ ስምህ አብርሃም ይባል። አንተንም በአሕዛብ መካከል ፈጽሜ አከብርሃለሁ፤ ነገሥታቱም ከአንተ ይወለዳሉ።'),
  ('17ffbbee-abee-5c6c-a156-7ebd9b0587cf', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 27, 27, 'በእኔና በአንተ መካከል፥ ከአንተም በኋላ በልጆችህ መካከል በወገናቸው የዘለዓለም ሥርዐት ልትሆን፥ ቃል ኪዳኔን አጸናለሁ፤ ለአንተና ከአንተም በኋላ ለዘርህ አምላክ እሆን ዘንድ ለዘለዓለም በምትገዛት፥ ተሰደህ በሄድህባት በከነዓን ቃል ኪዳኔን አጸናለሁ፤ አምላካቸውም እሆናቸዋለሁ።”'),
  ('ec3f52c3-6233-5d68-a727-1987cd1e3efa', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 28, 28, 'እግዚአብሔርም አብርሃምን እንዲህ አለው፥ “አንተ ቃል ኪዳኔን ጠብቅ፤ ከአንተም በኋላ ልጆችህ ይጠብቁ፤ ወንዶች ልጆቻችሁን ሁሉ ትገዝራላችሁ፤ የሰውነታችሁንም ሸንኮፍ ሁሉ ትገዝራላችሁ፤ በእኔና በእናንተ መካከልም ለልጅ ልጅ ለዘለዓለም የኪዳኔ ምልክት ይሆናል።'),
  ('57fce27f-def4-51bc-ae08-0e4208b2d14d', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 29, 29, 'በስምንተኛውም ቀን ወንድ ልጅን ሁሉ በየወገናችሁ ትገዝራላችሁ። በቤት የተወለደው፥ ከአሕዛብም ልጆች ሁሉ በወርቅ የገዛችሁት፥ ከዘርህም ያይደለ ቢሆን ይገዘሩ፤ በቤትህ የተወለደም፥ በወርቅህም የገዛኸው ቢሆን ይገዘሩ።'),
  ('a98bed38-4163-503f-a952-1ac56bdaf6fb', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 30, 30, 'ለዘለዓለም ሥርዐቴ ሊሆን ቃል ኪዳኔ በሰውነታችሁ ጸንቶ ይኖራል። ግዙር ያልሆነ ወንድ ልጃችሁ ሁሉ፥ በስምንተኛዪቱም ቀን የሰውነቱን ሰንኮፍ ያልተገዘረ ሁሉ ቃል ኪዳኔን አፍርሶአልና ያ ሰው ከወገኑ ተለይቶ ይጥፋ።”'),
  ('d15c9699-83f4-5f09-a9ca-47528d686a8f', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 31, 31, 'እግዚአብሔርም አብርሃምን እንዲህ አለው፥ “ሚስትህ ሶራ ስምዋ ሳራ ነውና ከእንግዲህ ወዲያ ስምዋ ሶራ ተብሎ አይጠራ፤ እባርካታለሁ፤ ከእርስዋም ልጅ እሰጥሃለሁ፤ እርሱንም እባርከዋለሁ፤ ታላቅ ወገንም ይሆናል፤ የአሕዛብ ነገሥታትም ከእርሱ ይወለዳሉ።”'),
  ('a4055c09-2442-529d-afe0-bc560914d499', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 32, 32, 'አብርሃምም በግንባሩ ወደቀ። ደስ ብሎትም በልቡ እንዲህ አለ፥ “በመቶ ዘመኔ ልጅ እወልዳለሁን? ዘጠና ዓመት የሆናት ሳራስ ልጅ ትወልዳለችን?”'),
  ('247b13a5-9939-519f-a982-daf7e19583f7', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 33, 33, 'አብርሃምም እግዚአብሔርን እንዲህ አለው፥ “ይስማኤል በፊትህ ቢኖር በወደድሁ ነበር።”'),
  ('f300f145-0759-5613-a59c-93c1ecec2c9a', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 34, 34, 'እግዚአብሔርም አለው፥ “ይሁን፥ ሳራም ወንድ ልጅን ትወልድልሃለች፤ ስሙንም ይስሐቅ ብለህ ትጠራዋለህ፤ ቃል ኪዳኔንም የዘለዓለም ቃል ኪዳን ሊሆን ከእርሱ ጋር አጸናለሁ፤ ከእርሱም በኋላ ለልጆቹ አጸናለሁ።'),
  ('98411cfe-7e33-5ebf-a1bb-93ecfb0ecaaf', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 35, 35, 'ስለ ይስማኤልም ሰማሁህ፤ እነሆ፥ እባርከዋለሁ፥ አገነዋለሁ፤ እጅግም አበዛዋለሁ፤ ዐሥራ ሁለት መሳፍንትንም ይወልዳል፤ በታላቅም ሕዝብ ላይ እሾመዋለሁ።'),
  ('bdaf303d-ed49-5ca8-a212-0141ae731ce6', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 36, 36, 'ቃል ኪዳኔን ግን በዚህ ወራት በሁለተኛው ዓመት ሳራ ከምትወልድልህ ከይስሐቅ ጋር አጸናለሁ።” ከእርሱም ጋር ይህን ተናግሮ ከጨረሰ በኋላ እግዚአብሔር አብርሃም ካለበት ወጣ።'),
  ('d2ba7a4e-05e5-5994-a7ac-4ecf653424c4', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 37, 37, 'አብርሃምም እግዚአብሔር እንዳለው አደረገ፤ ልጁ ይስማኤልንና በቤት የተወለደውን ሁሉ፥ በወርቁ የገዛውንም፥ በቤቱም ያለ ወንድ ልጅን ሁሉ ወስዶ የሰውነታቸውን ሰንኮፍ ገረዘ።'),
  ('c708ef8f-a604-5f6f-a5cb-e07739007a28', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 38, 38, 'በዚህችም ቀን አብርሃም ተገረዘ፤ ቤተ ሰቦቹም፥ በወርቅ የገዛቸውም ሁሉ፥ ከአሕዛብም የተወለዱ ሁሉ ከእርሱ ጋር ተገረዙ። ይህም ሕግ ለልጅ ልጅ ሁሉ የዘለዓለም ነው።'),
  ('d0d25dd2-5621-5d93-a218-a64ea7c92b43', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 39, 39, 'ይህ የዘለዓለም ሥርዐት ነውና፥ በሰማይ ጽላትም ተጽፎአልና ቀን ማሳጠር የለም፤ ከስምንቱ ቀንም አንዲት ቀን መተላለፍ የለም።'),
  ('77fe4504-6d3d-53a0-a22b-48df573b2bb1', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 40, 40, 'እስከ ስምንት ቀንም ድረስ የሰውነቱን ሰንኮፍ ያልተገረዘ ሰው ሁሉ ከጥፋት ልጆች ወገን ነውና እግዚአብሔር ለአብርሃም ከገባው ቃል ኪዳን ልጆች ወገን አይደለም።'),
  ('fe3ba21a-f27f-5ab3-a62f-e639c0bfb0a6', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 41, 41, 'ለእግዚአብሔር ይሆን ዘንድ ምልክት የለውም፤ የአምላካችን የእግዚአብሔርን ቃል ኪዳን ስላፈረሰ ከምድር ለመጥፋትና ለመደምሰስ፥ ከምድርም ለመነቀል የተገባ ነውና። መላእክተ ገጽ ሁሉና የምስጋና መላእክት ሁሉ ከተፈጠሩበት ቀን ጀምሮ ተፈጥሮአቸው እንዲህ ነውና።'),
  ('dc313ec1-d744-5cc6-a77e-b94f30be374d', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 42, 42, 'በመላእክተ ገጽና በምስጋና መላእክት አንጻር ከእርሱ ጋርና ከቅዱሳን መላእክት ጋር ይሆኑ ዘንድ እስራኤልን ቀደሰው።'),
  ('2efc777e-baa1-5519-a053-03c7db670453', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 43, 43, 'አንተም የእስራኤልን ልጆች እዘዝ፤ የዚህን ቃል ኪዳኔንም ምልክት ይጠብቁ፤ ለልጆቻቸውም የዘለዓለም ሥርዐት ይሁን፤ ለዘለዓለም በእስራኤል ልጆች ሁሉ ላይ ይጠብቁት ዘንድ ለቃል ኪዳን ሥርዐት ሠርቶአልና ከምድር እንዳይጠፉ ይሁኑ። ይስማኤልንና ልጆቹን፥ ወንድሞቹንና ዔሳውንም እግዚአብሔር ወደ እርሱ አላቀረባቸውም፤ ምንም የአብርሃም ልጆች ቢሆኑና ቢወድዳቸውም እነርሱን አልመረጠም።'),
  ('7345f70d-c9fd-529d-aaf3-9e6f1a8745f9', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 44, 44, 'ሕዝብ ይሆኑት ዘንድ እስራኤልን ለይቶ መረጠ። ብዙ አሕዛብና፥ ብዙ ሕዝብ ሁሉ የእርሱ ናቸውና፥ ሁሉም ለእርሱ ይገባልና ከሰው ልጆች ሁሉ ለይቶ ሰበሰበው። ነገር ግን ከእርሱ በኋላ ያስቱአቸው ዘንድ መናፍስትን በሁሉ ላይ አሠለጠነ።'),
  ('cf1c279c-7b34-5ec3-ac62-07e2cc0ed6f1', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 45, 45, 'በእስራኤል ላይ ግን ገዢአቸው እርሱ ብቻ ነውና፥ መልአክም ቢሆን መንፈስም ቢሆን ማንንም አላሠለጠነም። እርሱም ይጠብቃቸዋል። ከመላእክትና ከመናፍስት እጅ፥ ከሥልጣናትም ሁሉ እጅ ይጠብቃቸው ዘንድ ይመራመራቸዋል። እነርሱ ልጆቹ ይሆኑት ዘንድ እርሱም ከዛሬ ጀምሮ እስከ ዘለዓለም ድረስ አምላክ ይሆናቸው ዘንድ ይባርካቸዋል።'),
  ('8d310a80-ff76-54f1-a21e-370fdc6ba6aa', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 46, 46, 'አሁንም የእስራኤል ልጆች ይህችን ሥርዐት ሐሰት እንደሚያደርጉ እኔ እነግርሃለሁ። በሰውነታቸው ከመገረዛቸው የተነሣ ልጆቻቸውን ሳይገርዙ ይቀራሉና፤ የቤልሆርም ልጆች ሁሉ ልጆቻቸውን እንደ ተወለዱ ሳይገርዙ ይተዋሉ።'),
  ('559c12db-0c71-5f9b-a60f-6fc109b4399e', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 47, 47, 'ቃል ኪዳኑን አፍርሰዋልና፥ ከቃሉም ወጥተዋልና ያች ጽኑ መዓት ከእግዚአብሔር ታዝዛ በእስራኤል ልጆች ትደረጋለች። የዚህንም ምልክት ሥርዐቱን እንዳልፈጸሙ ከምድር ፈጽሞ ለመጥፋት ሰውነታቸውን እንደ አሕዛብ አድርገዋልና ተበሳጭተው ተሳደቡ።'),
  ('f7ed7a54-bc37-5105-aaf5-5654ce601c29', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 48, 48, 'በዚችም ምድር ለሚሠራው ስሕተት፥ ኀጢአትም ሁሉ ፈጽሞ ይሰረይ ዘንድ እንግዲህ ወዲህ የኀጢአት ስርየትና ይቅርታ የላቸውም።'),
  ('14069a98-3fec-5232-afee-ab2539917b4c', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 49, 49, 'በአራተኛው ወር መባቻ በመምሬ ባለው በግራሩ ሥር ለአብርሃም ተገለጥንለት፤ ከእርሱም ጋር ተነጋገርን። ከሚስቱ ከሳራም ልጅ እንደሚሰጠው ነገርነው፤ ሳራም ይህን ነገር ከአብርሃም ጋር እንደ ተነጋገርን ሰምታለችና ሳቀች። እኛም ዘለፍናት፤ እርስዋም ፈርታ ስለ ተነገረው ነገር እንደ ሳቀች አስተባበለች።'),
  ('9ed50352-93a5-5363-aed5-bcaa6f219e8e', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 50, 50, 'የልጅዋንም ስም ስሙ ይስሐቅ ተብሎ በሰማይ ጽላት እንደ ተሠራና እንደ ተጻፈ ነገርናት። ያንጊዜም ወደ እርስዋ በተመለስን ጊዜ እርስዋ ወንድ ልጅን ፀነሰች።'),
  ('607c9e6b-96c0-56dd-a18f-9afbd4743c99', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 51, 51, 'በዚያም ወር እግዚአብሔር በገሞራና በሰዶም፥ በሰቡኢምና በዮርዳኖስ አውራጃ ሁሉ ፍርዱን አደረገ። በእሳትና በድኝ አቃጠላቸው፤ እጅግ ክፉዎችና ኀጢአተኞች እንደ ሆኑ በሰውነታቸውም እየሴሰኑ እንደሚረክሱ፥ በምድር ላይም ርኵሰትን እንደሚሠሩ፥ እነሆ፥ ሥራቸውን ሁሉ እንደ ነገርሁህ እስከዚህች ቀን ድረስ አጠፋቸው።'),
  ('1dd2c303-5df2-5b1d-abf2-9a912cdf5738', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 52, 52, 'እንደዚሁም እግዚአብሔር እንደ ሰዶም ርኵሰት በሠሩባቸው ቦታዎች ሁሉ እንደ ሰዶም ፍርድ ያደርጋል።'),
  ('9c683e90-a70c-586d-aa0f-6fa0ed91b93c', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 53, 53, 'እግዚአብሔርም አብርሃምን አስቦታልና ሎጥን አዳነው፤ ከጥፋትም መካከል አወጣው። ከአዳም ዘመን ጀምሮ እስከዚያ ቀን ድረስ በምድር ላይ ያልተደረገ ኀጢአትን እርሱ ከልጆቹ ጋር በምድር አደረገ፤ አባት ከልጁ ጋር ተኝቶአልና።'),
  ('68afa75a-7e88-5a84-a54a-278dd52ec691', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 54, 54, 'ያጠፋቸውና ይነቅላቸው፥ ቅጣታቸውንም እንደ ሰዶም ቅጣት ያደርግ ዘንድ፥ በፍርድ ቀንም በምድር የሰውን ዘር ሁሉ እንዳያስቀርለት፥ እነሆ፥ ታዘዘ። በልጆቹም ሁሉ ላይ በሰማይ ጽላት ተቀረፀ።'),
  ('4d139ec1-d49e-5568-aae1-ec23d69ac01d', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 55, 55, 'በዚህም ወር አብርሃም ከኬብሮን ተጕዞ ሄዶ በጌራሮን ተራሮች ባሉ በቃዴስና በሱር መካከል ተቀመጠ።'),
  ('e8e26667-e525-5e7e-a1b2-f9938fbca224', '5fa74936-ce60-5af8-a1ff-14ff9100544e', '4c122b94-001c-5706-a519-9ad91e2f9a48', 56, 56, 'በአምስተኛው ወር እኩሌታም ከዚያ ተጕዞ በመሐላ ጕድጓድ አጠገብ ተቀመጠ።'),
  ('3a6870cd-4ade-5d6f-a006-7c4d3251dbc7', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 1, 1, 'በስድስተኛው ወር እኩሌታም እግዚአብሔር ሳራን ጐበኛት፤ እንዳለውም አደረገላት። ፀንሳም ወንድ ልጅን ወለደች። በሦስተኛውም ወር፥ በወሩ እኩሌታ እግዚአብሔር ለአብርሃም በነገረው ቀን በመጀመሪያው መኸር በዓል ይስሐቅ ተወለደ።'),
  ('6af8863c-57e7-5e05-a948-08058e75fb7a', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 2, 2, 'አብርሃምም ልጁን በስምንተኛዪቱ ቀን ገረዘው፤ እርሱም ለዘለዓለም ሥርዐት ሊሆን እንደ ተሠራ በገባው ቃል ኪዳን አስቀድሞ ተገረዘ።'),
  ('11ef0d8b-449f-5a51-aad3-e2ae86e805e4', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 3, 3, 'በአራተኛው ሱባዔ በስድስተኛው ዓመት ወደ አብርሃም ወደ መሐላ ጕድጓድ መጣን። ወደ እርስዋም እንመለስ ዘንድ ለሳራ እንደ ነገርናት ተገለጥንለት፤ እርስዋም ወንድ ልጅን ፀነሰች።'),
  ('b06d41d8-9d04-593e-a738-855bbd75f4d8', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 4, 4, 'በሰባተኛው ወር ተመለስን፤ ሳራንም በፊታችን ፀንሳ አገኘናት፤ ሳራንም ባረክናት። ዳግመኛም ሰባት ልጅ እስኪወልድና ሳይሞት እስኪያይ ድረስ እንደማይሞት የታዘዘለትን ሁሉ ነገርናት።'),
  ('b41d663b-0185-5eba-ab29-a90f88fd4a1e', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 5, 5, 'በይስሐቅም ስምና ልጅ ይጠራለታል። የልጅ ልጆቹም ሁሉ ሕዝብ ይሆናሉ፤ ከአሕዛብም ጋር ይቈጠራሉ።'),
  ('c81bfdb3-1ec4-5f4f-af9b-65d9265ce1d7', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 6, 6, 'ከይስሐቅም ልጆች አንዱ ለቅዱስ ዘርዕ ይሆናል፤ የልዑል ዕድል ፋንታም ይሆናልና ከአሕዛብ ጋር አይቈጠርም።'),
  ('00bbc02b-dd78-5a6c-adfa-b411595c3247', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 7, 7, 'ዘሩም ሁሉ ከሕዝቡ ሁሉ ተለይቶ ለእግዚአብሔር የክብር ሕዝብ ይሆን ዘንድ፥ ለመንግሥትና ለክህነት፥ ለቅዱስ ሕዝብም ይሆን ዘንድ እርሱ ወደሚያመልከው አምላክ'),
  ('9865bcc0-f3b9-52c1-a2b7-e26135a61270', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 8, 8, 'መንገዳችንንም ሄድን፤ የነገርነውንም ሁሉ ለሳራ ነገርናት፤ ሁለቱም ሁሉ በአንድነት እጅግ ብዙ ደስ አላቸው።'),
  ('270dc6e9-124d-52d3-abb5-6640e37237e8', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 9, 9, 'ላዳነውና በተሰደደበት ምድር ደስ ላሰኘው ለእግዚአብሔር በዚያ መሠዊያን ሠራ።'),
  ('bca0c834-c103-5718-af51-814952384415', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 10, 10, 'በዚህም ወር በመሐላው ጕድጓድ መሠዊያ አቅራቢያ ሰባት ቀን የደስታ በዓል አደረገ።'),
  ('5593ef5c-3e6d-5154-a777-32ab26100b7c', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 11, 11, 'በዚህችም በዓል ለእርሱና ለአገልጋዮቹ ዳስ ሠራ፤ እርሱም አስቀድሞ በምድር የዳስ በዓልን አደረገ።'),
  ('d1624921-a8c5-56a9-a9e6-ba72b0426391', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 12, 12, 'በዚህም በሰባቱ ቀን ሁልቀን በየዕለቱ ሁለት ላሞች፥ ሁለት የበግ ሙክቶችና ሰባት በጎች፥ ስለ ኀጢአትም አንድ የፍየል ጠቦት፥ ስለ ልጆቹና ስለ እርሱ ያስተሰርይበት ዘንድ ለእግዚአብሔር የሚቃጠል መሥዋዕት በመሠዊያው ላይ ያቀርብ ነበር።'),
  ('f070c750-e88f-574e-aa3f-5fd7c963577f', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 13, 13, 'ለድኅነት መሥዋዕትም ሰባት የበግ ሙክት፥ ሰባት የፍየል ጠቦት፥ ሰባት በጎች፥ ሰባት የፍየል ሙክት አቀረበ። መሥዋዕታቸውንና ወይናቸውንም በስባቸው ሁሉ ላይ አቀረበ። ለበጎ መዓዛም የተመረጠ ዕጣንን በመሠዊያው ላይ ጥዋት ጥዋት ያጥን ነበር።'),
  ('220123d9-83d4-52f1-abd2-3b9058a0162b', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 14, 14, 'በሰርክም ሽቱን ያጥን ነበር። ነጭ ዕጣንን፥ ቀንዓትን፥ ልባንጃን፥ ናርዶስን፥ ከርቤና ሰንቡልን፥ ቀበርቾንም እነዚህን ሰባቱን ሁሉ ያጥን ነበር፤ የተወቀጠውንና የተመረጠውን፥ የተስተካከለውንና የተቀላቀለውን፥ ንጹሑንም ያቀርብ ነበር።'),
  ('d0db5f1d-9272-58d4-a174-a4afba947030', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 15, 15, 'እርሱም በፍጹም ልቡ፥ በፍጹም ነፍሱም ደስ እያለው በቤቱ ካሉት ሁሉ ጋር ሰባት ቀን ይህን በዓል አደረገ፤ ከእርሱም ጋር ባዕድ ወይም ያልተገረዘ ሰው ማንም አልነበረም።'),
  ('a7f144b4-2f15-5386-aacb-9e3de1473ffc', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 16, 16, 'ለዘለዓለም ትውልድ የጽድቅ ተክል ከእርሱ እንደሚሆን ስላወቀና ስለ ተረዳ ለፈቃዱ ፈጥሮታልና የፈጠረውን አምላኩን አመሰገነው። ሁሉን እንዳደረገ እንደ እርሱም ይሆን ዘንድ ከእርሱ ቅዱስ ዘር ይሆናል።'),
  ('1afa3d93-455c-50df-a78b-9e4f4fd4ced2', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 17, 17, 'ይህችንም በዐል ባረካት፥ ደስም አለው፤ ስምዋንም የእግዚአብሔር በዓል ብሎ ጠራት። ልዑል አምላክም ደስ ብሎት የሚቀበላት የእግዚአብሔር በዓል አላት።'),
  ('0bc141a4-dafa-5f38-a364-acc7c12e52d9', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 18, 18, 'ለዘለዓለም ባረክነው፤ ከእርሱ በኋላም ዘሩን ሁሉ እንደ ሰማይ ጽላት ምስክር ያቺን በዓል በጊዜዋ አድርጎአልና በምድር ትውልድ ሁሉ ባረክነው።'),
  ('1bfd0146-e914-55f3-a450-b4c3dfcc5c07', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 19, 19, 'ስለዚህም በዘመናትና በዓመታት ሁሉ በትውልዳቸው የዘለዓለም ሕግ ሊሆን በእግዚአብሔር ፊት ተቀባይነት ያለው የዳስ በዓልን በደስታ ሰባት ቀን የሚያደርጉ ይሆኑ ዘንድ ለእስራኤል በሰማይ ጽላት ተጻፈ።'),
  ('7e8b50b4-b6cc-51d8-a33b-b8ded1b4e169', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 20, 20, 'በዓሉን ያደርጉት ዘንድ፥ በጥላም ይቀመጡ ዘንድ፥ በራሳቸውም አክሊል ይደፉ ዘንድ፥ ከወንዙም የአኻያውን ቅጠል ቅርንጫፍ ይይዙ ዘንድ፥ በእስራኤል የዘለዓለም ሥርዐት ሆኖ ተጽፎአልና ለዚህ ሥርዐት የተወሰነ ዘመን የለውም።'),
  ('8aa1c67b-b4ba-5d99-a45d-e1f94dcaa990', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 21, 21, 'አብርሃምም ለጋውን የሰሌን ጫፍ፥ ያማረ የእንጨቱንም ፍሬ ይዞ በየቀኑ በዘንባባው ሰባት ጊዜ መሠዊያውን ይዞር ነበር።'),
  ('88258ed9-705c-5e3c-a8a5-c269fb683db1', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 22, 22, 'ጥዋት ጥዋትም ሁሉን የፈጠረ አምላኩን በደስታ ያመሰግን ነበር።'),
  ('a1fcaafa-4f4d-5ec1-a8d0-79d33e0b164b', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 23, 23, 'በዚህ ኢዮቤልዩ በአምስተኛው ሱባዔ በአንደኛው ዓመት ይስሐቅ ጡት ጣለ።'),
  ('20645614-bffd-5535-a576-ef54f4f2ca2b', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 24, 24, 'አብርሃምም ልጁ ይስሐቅ ጡት በጣለባት ቀን በሦስተኛው ወር ታላቅ በዓል አደረገ። የግብፃዊቷ የአጋር ልጅ ይስማኤልም በአባቱ በአብርሃም ፊት በቦታው ተቀምጦ ነበር።'),
  ('a1d306f3-7b8a-579e-a162-62d593facb5c', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 25, 25, 'አብርሃምም ደስ አለው። ሁለቱን ልጆቹን አይቶአልና፥ ልጅንም ሳይወልድ አልሞተምና።'),
  ('93ae5849-cff7-5482-a99e-3056137df14f', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 26, 26, 'ሎጥ ከእርሱ በተለየባት ቀን የተናገረውንም ነገር አሰበ። ምድርን ይወርሳት ዘንድ በምድር እግዚአብሔር ዘርን ሰጥቶታልና ደስ አለው። የሁሉን ፈጣሪም በአፉ አመሰገነው።'),
  ('dbbca1bb-aede-56a5-a4e5-887972dbdf04', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 27, 27, 'ሳራም ይስማኤልን ሲጫወትና ሲዘፍን አየችው፤ አብርሃምንም እጅግ ደስ ብሎት አየች። ይስማኤልንም ባየችው ጊዜ ቀንታ አብርሃምን፥ “የዚህች የባሪያ ልጅ ከልጄ ከይስሐቅ ጋር ርስት አይወርስምና ይህችን ባሪያ ከልጅዋ ጋር አስወጥተህ ስደዳት” አለችው።'),
  ('2264cb31-f297-5bc0-a5ad-c2ccf2ea2a7b', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 28, 28, 'ከእርሱ ለይቶ ይሰዳቸው ዘንድ ስለ ባሪያውና ስለ ልጁ በአብርሃም ፊት ኀዘን ሆነ።'),
  ('2f45d523-a157-5996-ae4e-77afbf7f4aa3', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 29, 29, 'እግዚአብሔርም አብርሃምን፥ “ስለ ሕፃኑና ስለ ብላቴናዪቱ በፊትህ ኀዘን አይሁን፥ በይስሐቅ ስምና ዘር ይጠራልሃልና፥ ሳራ የነገረችህን ነገር ሁሉ ስማና አድርግ። ስለዚያች ባሪያ ልጅ ግን አትዘን፤ ከልጆችህ ወገን ነውና ታላቅ ወገን አደርገዋለሁ” አለው።'),
  ('1bfa7e1e-d626-5835-a8c5-bcb18de216a3', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 30, 30, 'አብርሃምም በጥዋት ገሥግሦ ሄዶ ውኃ ያለበትን ረዋትና ዳቦውን አምጥቶ ለአጋር አሸከማት፤ ልጁንም አሳዝሎ ሸኛት፤ በቤርሳቤህ ምድረ በዳም እየተቅበዘበዘች ሄደች።'),
  ('1c388a87-3d8b-5581-a4c1-d2e642ab79e0', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 31, 31, 'ውኃውም ከረዋቷ አለቀ፤ ልጁም ተጠማ፤ መሄድም ተሳነው፤ ሕፃኑም ወደቀ፤ እናቱም አነሣችው፤ ሄዳም በአንዲት የዘይት እንጨት ሥር አኖረችው፥ “የልጄንም ሞት አላይም” ብላለችና ጦር ወርውረው የሚያደርሱበት አንድ ምዕራፍ ያህል ርቃ ሄዳ ፊት ለፊት ተቀመጠች፤ በዚያም ተቀምጣ አለቀሰች።'),
  ('e4a1c538-6ed8-5b08-a28a-c187c10d835c', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 32, 32, 'ከቅዱሳን መላእክት አንዱ መልአክ፥ “አንቺ አጋር፥ ለምን ታለቅሻለሽ? እግዚአብሔር ቃልሽን ሰምቶአልና፥ ሕፃኑንም አይቶታልና ተነሥተሽ ሕፃኑን አንሥተሽ በእጅሽ ያዢው” አላት።'),
  ('ba6f9617-c19b-52c6-a09d-c63499c6498a', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 33, 33, 'ዐይኖችዋንም ገልጣ የውኃ ጕድጓድ አየች፤ ሄዳም ረዋቷን ውኃ ሞላች፤ ልጅዋንም አጠጣች፤ ተነሥታም ወደ ፋራን ምድረ በዳ ሄደች።'),
  ('7769ffc5-09fc-5cbb-a268-b6dfdb0d1ac7', 'dc7a81b7-ec62-557b-a37c-c01f842c9513', 'cd7fac4e-9e5a-59a5-a842-77ffae84257c', 34, 34, 'ሕፃኑም አድጎ አዳኝ ሆነ፤ እግዚአብሔርም ከእርሱ ጋር ነበረ። እናቱም ከግብፅ ሴቶች ሚስት አጋባችው፤ ወንድ ልጅንም ወለደችለት። “በለመንሁት ጊዜ እግዚአብሔር ለእኔ ቅርቤ ነው” ብላለችና ስሙን ናቢኦት አለችው።'),
  ('f63ea7a1-75d0-5ff8-aa4f-eed69f80519d', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 1, 1, 'በዚህ ኢዮቤልዩ በሰባተኛው ሱባዔ በመጀመሪያው ዓመት በመጀመሪያው ወር እንዲህ ሆነ። በዚህ ወር በዐሥራ ሁለተኛው ቀን እግዚአብሔር እንደሚወደው ስለ አብርሃም በሰማይ ቃሎች ተሰሙ፤ በሚናገረው ነገር ሁሉ የታመነ እንደ ሆነ በመከራውም ሁሉ የታመነ ነውና።'),
  ('547b8742-410c-5c60-ae6e-0ac806fd9e1c', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 2, 2, 'መኰንን መስቴማ መጥቶ በአምላክ ፊት ቆሞ እንዲህ አለ፥ “እነሆ፥ አብርሃም ልጁ ይስሐቅን ይወደዋል፥ ከሁሉም ይልቅ እርሱ ደስ ያሰኘዋል፤ በመሠዊያው ላይ መሥዋዕት አድርጎ ያቀርበው ዘንድ ንገረው።'),
  ('f1e1d3c1-7332-52d1-a64d-1857489db1bb', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 3, 3, 'ይህን ነገር ቢያደርግ አንተ ታያለህ፤ በምትፈትነው ሁሉ እርሱ የታመነ እንደ ሆነ ታውቃለህ።” እግዚአብሔር ግን አብርሃም በነገረው መከራ ሁሉ የታመነ እንደ ሆነ ያውቃል፤ በሀገሩ በድርቅ ፈትኖታልና፤ በነገሥታቱም ገንዘብ ፈትኖታልና፤ ዳግመኛም በሚስቱ መቀማት ፈትኖታልና፤ በመገረዝም ፈትኖታልና፤ በሰደዳቸው ጊዜ በልጁ በይስማኤልና በባሪያው በአጋር ፈትኖታልና፥ በፈተነው መከራ ሁሉ የታመነ ሆኖ ተገኝቶአልና፥ ሰውነቱም ቸል አላለችምና።'),
  ('985dc0aa-d6c1-5f12-aad2-47a976e37f36', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 4, 4, 'የታመነ ነውና፥ እግዚአብሔርንም ይወዳልና፥ ሥራውን አላቈየም።'),
  ('b208a0e5-81b8-511f-ac59-1d1957be2fbf', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 5, 5, 'እግዚአብሔርም አብርሃምን፥ “አብርሃም፥ አብርሃም፥ አብርሃም” ብሎ ጠራው፥ አብርሃምም፥ “አቤት፥ አለሁ” አለ። እርሱም፥ “የምትወደውን ልጅህን ይስሐቅን ይዘህ ከፍ ወዳለች ተራራ ሂድ፤ እኔ ከምነግርህ ከተራሮች ወደ አንዲቱ ተራራ አውጣው” አለው።'),
  ('75723449-a061-5921-a684-0e75726ae078', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 6, 6, 'ከዚያም በነግህ ገሠገሠ፤ አህያውንም ጭኖ፥ ሁለቱንም ብላቴኖቹን፥ ልጁ ይስሐቅንም፥ ከእርሱ ጋር ይዞ፥ ለመሥዋዕት የሚሆን እንጨትንም ፈልጦ አሸክሞ ሦስት ቀን እግዚአብሔር ወዳዘዘው ቦታ ሄደ።'),
  ('b41fd81c-d96c-5e32-aea2-30007bace42b', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 7, 7, 'ቦታውንም በሩቁ ሆኖ አየ፤ ውኃ ወዳለበት ጕድጓድም ደረሰ፤ ብላቴኖቹን፥ “አህያውን ይዛችሁ ከዚህ ቈዩኝ፤ ልጄና እኔ ሄደን፥ ሰግደን ወደ እናንተ እንመለሳለን” አላቸው።'),
  ('60a1bbc3-ef0f-5bbc-a652-1f04c32673b9', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 8, 8, 'የመሥዋዕቱንም እንጨት ለልጁ ለይስሐቅ አሸክሞ፥ ወቅለምቱንና እሳቱን በእጁ ይዞ፥ እስከዚያ ቦታ ድረስ ሁለቱ ሁሉ በአንድነት ሄዱ።'),
  ('dc9c9325-3b00-590c-aca8-2347a3e1dca7', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 9, 9, 'ይስሐቅም አባቱን፥ “አባቴ” አለው፥ እርሱም፥ “ልጄ፥ እነሆኝ፥ አለሁ” አለው። “እነሆ፥ እሳቱና ወቅለምቱ፥ እንጨቱም አለ፤ አባቴ፥ ለሚቃጠል መሥዋዕት የሚሆነው በግ ወዴት ነው?” አለው።'),
  ('20d59e16-d5ab-5c71-a116-dd0fd69a69ba', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 10, 10, 'እርሱም፥ “ልጄ ሆይ፥ ለሚቃጠል መሥዋዕት የሚሆነውን በግ እግዚአብሔር ያውቃል” አለው። ወደ እግዚአብሔርም ተራራ ቦታ ቀረበ፤ መሠዊያም ሠራ፤ እንጨቱንም በመሠዊያው ላይ አደረገ፤ ልጁን ይስሐቅንም አስሮ በመሠዊያው ላይ ባለ እንጨት ላይ አስተኛው። ልጁን ይስሐቅንም ይሠዋው ዘንድ ወቅለምቱን ለማንሣት እጁን ዘረጋ።'),
  ('f00ab599-021b-5c7e-af07-8d06e5718aaf', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 11, 11, 'እኔም በፊቱ ቆምሁ ፤ በመኰንን መስቴማም ፊት ቆምሁ።'),
  ('dc693c53-0211-52e4-a8a1-95a2238547cd', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 12, 12, 'እግዚአብሔርም፥ “እርሱ እግዚአብሔርን የሚፈራ እንደ ሆነ ዐውቄአለሁና በይስሐቅ ላይ እጁን እንዳያወርድ፥ በእርሱም ምንም ክፉ ነገር እንዳያደርግ ንገረው” አለ።'),
  ('2882b3f5-8610-5a4c-a599-aaa158e310a2', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 13, 13, 'በሰማይም ሆኜ፥ “አብርሃም፥ አብርሃም” ብዬ ጠራሁት። እርሱም ደንግጦ፥ “እነሆ፥ እኔ አለሁ” አለኝ። “በሕፃኑ ላይ እጅህን አታውርድ፤ አንተ እግዚአብሔርን የምትፈራ እንደ ሆንህ ዛሬ ዐውቄአለሁና፤ ከእኔም ለበኵር ልጅህ አልራራህምና በእርሱ ላይ ምንም አታድርግ” አልሁት፤ መኰንን መስቴማም አፈረ።'),
  ('f4b5afe0-677b-526d-a12e-609f9135962a', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 14, 14, 'አብርሃምም ዐይኖቹን አቅንቶ አየ። እነሆ፥ ቀንዱን በዕፀ ሳቤቅ የተያዘ አንድ በግ ሲወርድለት አየ። አብርሃምም ሄዶ ያን የበግ አውራ አምጥቶ ስለ ልጁ ፋንታ ለሚቃጠል መሥዋዕት አቀረበው።'),
  ('6011a889-6241-5996-af37-70d09f6178f7', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 15, 15, 'አብርሃምም ያን ቦታ፥ “እግዚአብሔርን ያየሁበት” ይባል ዘንድ፥ “እግዚአብሔር የታየበት ቦታ” አለው፤ ተራራውም ደብረ ጽዮን ነው።'),
  ('26da86a2-151c-5d01-ac7d-2c0fe49cfa1c', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 16, 16, 'እግዚአብሔርም አብርሃምን በሰማይ ሆኖ ዳግመኛ በስሙ ጠራው፤ በእግዚአብሔር ስም እንነግረው ዘንድ እንደ ታየነው፤ እግዚአብሔር “በራሴ ማልሁ አለ” አልነው።'),
  ('c7882f1c-f5d6-536e-ac3f-093a5ffe1711', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 17, 17, '“ይህን ነገር አድርገሃልና፥ ለምትወድደው ለበኵር ልጅህ ከእኔ አልራራህለትምና ፈጽሜ እንድባርክህ፥ በባሕር ዳር እንዳለ አሸዋና እንደ ሰማይ ኮከብ ዘርህን ፈጽሜ እንዳበዛው፥'),
  ('79fda8eb-5fe4-5451-a9c9-5d936273c867', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 18, 18, 'ልጆችህም የጠላቶቻቸውን ሀገር እንዲወርሱ፥ ቃሌን ስለ ሰማህ ፋንታ በዚህ ዓለም ያሉ አሕዛብንም ሁሉ እንዲወርሱ እኔ ባዘዝሁህ ሁሉ አንተ ለእኔ የታመንህ እንደ ሆንህ ለሁሉ ነገርሁ፤ በሰላም ሂድ” አለው።'),
  ('b8659d93-1c1e-5800-a7d3-08cd2c478dad', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 19, 19, 'አብርሃምም ወደ ብላቴኖቹ ሄደ። ከዚያም ተነሥተው በአንድነት ወደ ቤርሳቤህ ሄዱ። አብርሃምም በመሐላ የውኃ ጕድጓድ አደረ። ያችንም በዓል በሄደባቸውና በሰላም በተመላለሰባቸው በሰባቱ ቀኖች መጠን በዘመኑ ሁሉ ሰባት ቀን የደስታ በዓል አደረጋት። የእግዚአብሔርም በዓል አላት።'),
  ('9a766d77-14df-5c67-a8d9-a3bcceef68fa', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 20, 20, 'ሰባት ቀን በደስታ ይህችን በዓል ለማድረግ በልጆቹና በእስራኤል ላይ እንደ ታዘዘ በሰማይ ጽላት እንዲህ ተሠርቶአል፤ ተጽፎአልም።'),
  ('85b19d7e-3e4f-556f-af3c-32e03687b9a3', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 21, 21, 'በአርባ ሁለተኛው ኢዮቤልዩ በመጀመሪያው ሱባዔ በአንደኛው ዓመት አብርሃም ተመልሶ በኬብሮን አንጻር ሁለት የዓመት ሱባዔ ኖረ። ይህችውም ቃርያታርባቅ ናት።'),
  ('d207bb30-f1d8-5bd1-a21b-edd42d1f957c', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 22, 22, 'በዚህ ኢዮቤልዩ በሦስተኛው ሱባዔ በመጀመሪያው ዓመት የሳራ የሕይወት ዘመን ተፈጸመ፤ በኬብሮንም ሞተች።'),
  ('879c0b0b-3c74-5c1b-a4da-28af1608baa8', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 23, 23, 'አብርሃምም አልቅሶ ይቀብራት ዘንድ ሄደ። ልቡናው ይታገሥ እንደ ሆነ እንዲሁም በአፉ በተናገረው ነገር ቸል አይል እንደ ሆነ ፈተንነው። በዚህም የታገሠ ሆኖ ተገኘ፤ በውስጡ ሬሳውን ሊቀብር የመቃብር ቦታ ይሰጡት ዘንድ ከኬጢ ልጆች ጋር በልቡና ትዕግሥት ተናግሮአልና አልተበሳጨም።'),
  ('e140a94b-e0be-541a-a711-83df753faf91', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 24, 24, 'እግዚአብሔርም በሚያዩት ሰዎች ሁሉ ፊት ባለምዋልነትን ሰጠው፤ ከኬጢ ልጆችም በየዋሃት ለመነ፤ በግራሩ አንጻር ያለች ባለ ደርብ ዋሻን ሰጡት። ይህችውም ኬብሮን ናት። በአርባ ብርም ሸጡለት።'),
  ('0c225142-f544-576a-a38d-db3628ed74b7', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 25, 25, 'እነርሱም፥ “ያለ ዋጋ እንስጥህ” ብለው ለመኑት፥ እርሱ ግን የቦታውን ዋጋ ብሩን ፈጽሞ ሰጥቶአልና ከእነርሱ ያለ ዋጋ አልወሰደም፤ ዳግመኛም ሰገደላቸው።'),
  ('b4319333-d5d7-5a15-a807-2bcbcf85ad90', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 26, 26, 'ከዚህ በኋላ ደርብ ባላት ዋሻ ሬሳዋን ቀበረ። ሳራም በሕይወት የኖረችበት መላ ዘመንዋ መቶ ሃያ ሰባት ዓመት ሆነ፤ እነዚህም ሁለት ኢዮቤልዩ አራት ሱባዔና አንድ ዓመት ናቸው። ሳራም በሕይወት የኖረችባቸው የዘመኖችዋ ቀን ይህ ነው።'),
  ('ea3b21af-216c-56c0-a643-ac2808b30ae7', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 27, 27, 'አብርሃምም በተፈተነበት የታመነና ልቡናው የታገሠ ሆኖ የተገኘበት ይህ መከራ ዐሥር ነው፤ ለእርሱ ይሰጣት ዘንድ፥ ከእርሱም በኋላ ለልጁ ይሰጣት ዘንድ እግዚአብሔር ስለ ከነዓን የነገረውን ነገር እንቢ አላለም፤ በዚያም ሬሳውን ይቀብር ዘንድ ቦታን ለመነ። የታመነና የሚታገሥ ሆኖ ተገኝቶአልና በሰማይ ጽላት የእግዚአብሔር ወዳጅ ተብሎ ተጻፈ።'),
  ('c8c3122a-39e0-5d2c-a20c-e76f6620ccd1', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 28, 28, 'በአራተኛው ዓመት ለልጁ ለይስሐቅ ሚስትን አጋባው፥ ስምዋም ርብቃ ይባላል፤ ይህችውም የአብርሃም ወንድም የናኮር ልጅ የባቱኤል ልጅና የላባ እኅት ናት። የአብርሃም ወንድም የናኮር ሚስት የሚልካ ልጅ ባቱኤልም ርብቃንና ላባን ወለዳቸው።'),
  ('0cdf86e4-cc74-5b7f-a60a-4cbbdadae7cb', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 29, 29, 'አብርሃምም ከሳራ አስቀድሞ አጋር በሞተች ጊዜ በቤቱ ከተወለዱ ልጆች ወገን የምትሆን ሦስተኛ ሚስትን አገባ፤ ስምዋም ኬጡራ ይባላል፤ እርስዋም ዘንበሬንና ዮከሳንን፥ ማዳይንና ምድያንን፥ ኢያዝቦቅንና ስሂያን እነዚህን ስድስቱን ወለደችለት።'),
  ('88024c53-aeca-542a-a1dd-a5372d34df1d', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 30, 30, 'በሁለተኛው ሱባዔ ዘመን በስድስተኛው ሱባዔ በሁለተኛው ዓመት ርብቃ ለይስሐቅ ሁለት ልጆች፥ ያዕቆብንና ዔሳውን ወለደችለት።'),
  ('7c1bddb8-3116-5f78-a764-1c51632906fd', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 31, 31, 'ያዕቆብም ፍጹም ቅን ነበረ፥ ዔሳው ግን ጨካኝ አርበኛና ጠጕራም ነበረ፤ ያዕቆብም በቤት ይውል ነበር። እነዚህም ጐልማሶች አደጉ።'),
  ('39b326de-bb48-55e5-a5ca-e4ead2870b1e', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 32, 32, 'ያዕቆብ መጻፍን ተማረ፤ ዔሳው ግን አርበኛና አዳኝ ነበረና አልተማረም። ሰልፍንና ክፉ ሥራንም ሁሉ ተማረ፤ አብርሃምም ያዕቆብን ይወድ ነበር፤ ይስሐቅ ግን ዔሳውን ይወድ ነበር።'),
  ('c4457153-d96e-52d1-a7d3-b2eb5f9dd2fe', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 33, 33, 'አብርሃም የዔሳውን ሥራ አየ፤ ነገር ግን በያዕቆብ ስምና ልጅ እንዲጠራለት ዐወቀ።'),
  ('34c8dcc6-955d-5175-a82b-d63e47e15f4d', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 34, 34, 'ርብቃንም ጠርቶ እርስዋ ከዔሳው ይልቅ ያዕቆብን ፈጽማ እንድትወደው አይቶአልና የያዕቆብን ነገር አዘዛት።'),
  ('1fe3a9e5-3009-5a58-a162-8d0e31234b9e', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 35, 35, '“ልጄ ሆይ፥ ያዕቆብን ልጄን ጠብቂ፤ እርሱ ስለ እኔ ፋንታ በሰዎች ልጆች መካከል ለበረከት ይሆናልና፤ ለሴምም ዘር መመኪያ ይሆናልና፤ በምድር ገጽ ከሚኖሩ ሰዎች ሁሉ ለሕዝቡ ጠበቃ ሊሆንለት እግዚአብሔር እርሱን እንዲመርጥ አውቃለሁና።'),
  ('5c0d39db-303b-5193-af42-2e7bf935d546', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 36, 36, 'እነሆ፥ ልጄ ይስሐቅ ከያዕቆብ ይልቅ ዔሳውን ይወድዳል፤ አንቺ ደግ ሰው ያዕቆብን ስትወጂው እኔ አይቻለሁ፤ ዳግመኛም ለእርሱ ደግ ነገር ማድረግን ጨምሪለት።'),
  ('aa819ef4-35dc-5d20-a95e-90f002d55699', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 37, 37, 'ከዛሬ ጀምሮ ለዘለዓለም እስከሚነሣ ትውልድ ሁሉ ድረስ በምድር ላይ እርሱ ለበረከት ይሆነኛልና ዓይኖችሽ ወደ ተወዳጁ ይሁኑ። ከልጆች ሁሉ ይልቅ እርሱን ፈጽሜ ወድጃለሁና፥ ለዘለዓለም ይከብራልና ዘሩም ምድርን ሁሉ የሚሞላ ይሆናልና እጆችሽ ይጽኑ። ልብሽም በልጅሽ በያዕቆብ ደስ ይበለው፤ ሰው የባሕር አሸዋ መቍጠር ይችል እንደ ሆነ እንደዚሁም የእርሱ ዘር ይቈጠራል።'),
  ('2c6df844-d97d-599a-a455-c8d0a50620ed', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 38, 38, 'እግዚአብሔር እኔንና ዘሬን የባረካቸው በረከቶች ሁሉ በዘመኑ ሁሉ ለያዕቆብና ለዘሩ ይሁኑ፤ በዘሩም ስሜ ይከብራል፤ የአባቶች የሴምና የኖኅ፥ የሄኖክና የመላልኤል፥ የሄኖስና የሴት የአዳምም ስም ይባረካል፤ እነርሱም ሰማይን ለመመሥረት፥ ምድርንም ለማጽናት፥ በጠፈር ላይ ያሉ ብርሃናትንም ለማደስ ይሆናሉ” አላት።'),
  ('840d7699-042e-5912-a622-684b50b3ff53', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 39, 39, 'ያዕቆብንም ጠርቶ በእናቱ በርብቃ ፊት ሳመው፤ መረቀውም፤ እንዲህም አለው፥ “ልቡናዬ የወደደችህ ልጄ ተወዳጁ ያዕቆብ ሆይ፥ ከጠፈር በላይ ያለ አምላክ ይባርክህ።'),
  ('203b10b9-1fb9-5152-a6c7-80b44aace53d', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 40, 40, 'አዳምንና ሄኖክን፥ ኖኅንና ሴምን የባረከባቸውን በረከቶችን ሁሉ ይስጥህ። የነገረኝን ሁሉና እሰጥሃለሁ ያለኝንም ሁሉ፥ በምድር ላይ እንደ ሰማይ ዘመን በአንተና በዘርህ ላይ እስከ ዘለዓለም ድረስ ያጽናልህ።'),
  ('874b8aee-2cb9-50c5-aeac-c7160d39b6a5', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 41, 41, 'ከዛሬ ጀምሮ እስከ ዘለዓለም ድረስ አምላክህ እግዚአብሔርን ከመከተል ያርቁህ ዘንድ የሰይጣን መናፍስት በአንተና በዘርህ ላይ አይሠልጥኑብህ።'),
  ('330b15cb-324c-50f1-a1d0-a128174d3ff2', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 42, 42, 'እግዚአብሔር አምላክ አባት ይሁንህ፥ አንተም ልጅ ሁነው። ለሕዝቡም በዘመኑ ሁሉ አለቃ ሁን፥ ልጄ በሰላም ሂድ።”'),
  ('c41d8991-f662-5527-ae3a-88511544b720', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 43, 43, 'ሁለቱም በአንድነት ከአብርሃም ዘንድ ወጡ፤ ርብቃም ያዕቆብን በፍጹም ልቡናዋ፥ በፍጹም ነፍስዋም ከዔሳው ይልቅ እጅግ ወደደችው፤ ይስሐቅም ከያዕቆብ ይልቅ ዔሳውን ይወድደው ነበር።'),
  ('632ecb5b-a05b-53bb-ab4c-aecbf0989ceb', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 44, 44, 'በአርባ ሁለተኛው ኢዮቤልዩ፥ በሰባተኛው ሱባዔ በመጀመሪያው ዓመት አብርሃም ይስማኤልንና ዐሥራ ሁለቱን ልጆቹን፥ ይስሐቅንና ሁለቱን ልጆቹን፥ ስድስቱን የኬጡራ ልጆችንና ልጆቻቸውንም ጠራ።'),
  ('d071f059-73cf-5bf7-ac4d-464e73085bcf', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 45, 45, 'የእግዚአብሔርን ሕግ ይጠብቁ ዘንድ፥ ጽድቅንም ይሠሩ ዘንድ፥ በሰልፉም ሁሉ እንደ እርሱ ሊሆኑ እያንዳንዱ ባልንጀራውን ይወድ ዘንድ፥ እያንዳንዳቸውም በእያንዳንዳቸው ላይ ጸንተው ይኖሩ ዘንድ አዘዛቸው።'),
  ('c8948326-5fb0-5b39-a4e9-681a2385c7f7', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 46, 46, 'በምድርም ላይ ፍርድንና ጽድቅን ለማድረግ ከእነርሱ ጋር በገባው ቃል ኪዳን ልጆቻቸውን ይገርዙ ዘንድ፥ ከዝሙትና ከርኵሰት ሁሉ እንጠበቅ ዘንድ፥ ከመካከላችንም ርኵሰትንና ዝሙትን እናርቅ ዘንድ፥ እግዚአብሔር ካዘዘን ሥርዐት ሁሉ ወደ ቀኝም ወደ ግራም እንዳይተላለፉ አዘዛቸው።'),
  ('e376ef7e-a9ac-5201-a0e8-4b01ffe54473', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 47, 47, 'ሴት ሁላ፥ ወይም ድንግልና ያላት ልጅ ብትሰስንባችሁ በእሳት አቃጥሉአት፤ ዐይናቸው ባየውና ልባቸው ባሰበውም አይሰስኑ። የከነዓን ዘሮች ከምድር ይጠፋሉና ከከነዓን ሴቶች ልጆች ሚስትን አያግቡ።'),
  ('04cc324c-4906-5ae3-ac67-ccadaea6a831', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 48, 48, 'የረዓይትን ፍርድና የሰዶምን ፍርድ፥ ስለ ክፋታቸው ስለ ዝሙትና ርኵሰት እንደ ተፈረደባቸው፥ በዝሙትም እርስ በርሳቸው በሠሩት ጥፋት እንደ ሞቱ ነገራቸው።'),
  ('17d8dae7-933b-5654-adab-d3fb25e892c8', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 49, 49, 'እናንተም ከዝሙትና ከርኵሰት ሁሉ፥ በኀጢአትም ከመተዳደፍ ሁሉ ተጠበቁ። ስማችንን ለመርገም እንዳትሰጡ፥ ኑሮአችሁንም ሁሉ ለትምክሕት እንዳታደርጉ፥ ልጆቻችሁንም ሁሉ በሰይፍ ለመጥፋት እንዳታደርጉ ተጠበቁ። እንደ ሰዶምም የተረገማችሁ ትሆናላችሁ። ልጆቻችሁም ሁሉ እንደ ገሞራ ልጆች ይሆናሉ።'),
  ('718fd80e-3565-513b-a0e2-5693395c9a4b', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 50, 50, 'ልጆች፥ እኔ አዳኝባችኋለሁ፤ የሰማይን አምላክ ውደዱት፥ ትእዛዙንም ሁሉ ጠብቁ፤ ጣዖታቸውንና ኀጢአታቸውን ተከትላችሁ አትሂዱ። ተመትተው የተሠሩ ጣዖታትንና ቅርፆችን ለእናንተ አትሥሩ፤ ከንቱ ናቸውና፤ ምንም ምን እስትንፋስ የላቸውም፤ የሰው እጅ ሥራ ናቸውና። የሚታመኑባቸውም ሁሉ ከንቱ ናቸውና አታምልኩአቸው፤ አትስገዱላቸውም።'),
  ('eab2bed1-6ce8-51df-a7cc-78bd32ebbbbe', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 51, 51, 'እናንተ ግን ልዑል አምላክን አምልኩ፥ ሁልጊዜ ስገዱለት፥ ሁልጊዜም የእርሱን ፊት ተስፋ አድርጉ፤ በእናንተ ደስ ይለው ዘንድ፤ ምሕረቱንም ይሰጣችሁ ዘንድ፥ የበልጉንና የመከሩንም ዝናም ያወርድላችሁ ዘንድ፥ ሥራችሁንም ሁሉ፥ በምድርም የሠራችሁትን ሁሉ ይባርክላችሁ ዘንድ፥ ፍርድንና ጽድቅንም፥ ቅንነትንም በፊቱ አድርጉ።'),
  ('e3b931eb-9ca3-5954-a1d1-8e8b4e9ff8ad', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 52, 52, 'እህልህንና ውኃህን ይባርክልሃል፤ የአብራክህን ዘር፥ የምድርህንም ዘር፥ የላሞችህን መንጋና የበጎችህን መንጋ ይባርክልሃል። በምድርም ለበረከት ትሆናለህ።'),
  ('fe2ffb58-e260-5967-a984-d94ab445233b', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 53, 53, 'የምድርም አሕዛብ ሁሉ ይወዱአችኋል። እኔ እንደ ተናገርሁት የተባረኩ ይሆኑ ዘንድ ልጆቻቸሁን በስሜ ይባርካሉ።'),
  ('a198f7a2-3686-5518-a2ff-8fca57318abf', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 54, 54, 'ለልጁ ለይስማኤልና ለኬጡራ ልጆችም ስጦታን ሰጥቶ ከልጁ ከይስሐቅ ለይቶ አሰናበታቸው። ሁሉን ግን ለልጁ ለይስሐቅ ሰጠው።'),
  ('426034ac-b9d5-56c7-a280-713b4f102266', '0b02bffd-6477-55f0-a83f-b4c274911b36', '7a56e8ea-fc71-5b3f-a539-eb3506da63b9', 55, 55, 'ይስማኤልና ልጆቹም፥ የኬጡራ ልጆችም የልጅ ልጆቻቸውም በአንድነት ሄዱ። ከፋራን ጀምሮ በምድረ በዳ አንጻር በምሥራቅ በኩል እስከ ባቢሎን መግቢያ ድረስ በሀገሩ ሁሉ ኖሩ፤ እነዚህም ከእነዚህ ጋር አንድ ሆኑ። ስማቸውም ዓረብና ይስማኤላውያን ተብሎ ተጠራ።'),
  ('7080ad80-e170-56d4-a923-72da2efe084b', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 1, 1, 'በዚህ ኢዮቤልዩ በሰባተኛው ሱባዔ በስድስተኛው ዓመት አብርሃም ልጁ ይስሐቅን ጠርቶ እንዲህ ብሎ አዘዘው፥ “እኔ አረጀሁ፥ ዘመኔን ጠግቤአለሁና የምሞትበትን ቀን አላውቅም።'),
  ('d64064c2-eab8-531d-a52d-a97dc7d43cba', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 2, 2, 'እነሆ፥ እኔ የመቶ ሰባ አምስት ዓመት ሰው ነኝ፤ በሕይወቴ ዘመን ሁሉ እግዚአብሔርን ሳስበው፥ በፍጹም ልቤም የአምላኬን ፈቃድ አደርግ ዘንድ፥ በመንገዱም ሁሉ መሄድን አቀና ዘንድ ስፈልግ ኖርሁ። ሕያውና ቅዱስ፥ ከሁሉም ይልቅ የታመነና ጻድቅ አምላክ ነውና የፈጣሪዬን ፈቃድ ለማድረግ እጠብቅ ዘንድ ነፍሴ ጣዖትን ጠላች።'),
  ('856026f9-01aa-5385-ab63-ea936404a307', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 3, 3, 'የጽድቅ አምላክ ነውና፥ ሕጉን በሚያፈርሱ ሰዎች ሁሉ፥ ቃል ኪዳኑንም በሚንቁ ሰዎች ፍርድን የሚያደርግ ነውና በእርሱ ዘንድ ዐመፅ፥ ለሰው ፊትም ማድላትና መማለጃ መቀበል የለም።'),
  ('73489a9c-a20f-527c-a9db-bee65dbbba32', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 4, 4, '“ልጄ ሆይ፥ አንተም ትእዛዙንና ሥርዐቱን፥ ፍርዱንም ጠብቅ። ርኵሳንን፥ የተቀረጹ ጣዖታቱንና፥ ተመትተው የተሠሩትንም ጣዖታት ተከትለህ አትሂድ። የአውሬውንና የእንስሳውን፥ በሰማይ የሚበሩ የወፎችንም ሁሉ ደም አትብላ።'),
  ('ed9799c5-50ba-53d0-a008-088a9b0e15bd', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 5, 5, 'ብታርድም ተቀባይነት ያለው የሚቃጠል የሰላም መሥዋዕትን ሠዋ፤ ደማቸውንም በመሠዊያው ላይ አፍስስ፤ የሚቃጠለውንም መሥዋዕት ስብ ከስንዴው ጋር ወደ መሠዊያው አቅርብ፤ በዘይት የተለወሰውንም መሥዋዕት ከመጠጡ ቍርባን ጋር ሁሉንም በአንድነት በእግዚአብሔር ፊት ለበጎ መዓዛ የሚቃጠል መሥዋዕት አድርገህ፥ እንደ ድኅነቱ መሥዋዕት ስብ በሆዱ ውስጥ እንዳለው ስብ በመሠዊያው ላይ ባለው እሳት ታኖረዋለህ።'),
  ('595d2c14-9c39-5e04-a2b7-915f38e82099', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 6, 6, 'በሆድ ዕቃውም ውስጥ ያለውን ስብ ሁሉ፥ ሁለቱን ኵላሊቱንም፥ በእነርሱ ላይ ያለውንም ስብ ሁሉ፥ በወርቹ ላይ ያለውንም ስብ፥ ግልገል ጉበቱንም፥ ከኵላሊቱ ጋር እንደ ተጠቀለለ፥'),
  ('19d7270d-0399-5a02-ad6b-314cbdc93b4b', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 7, 7, 'ይህንም ሁሉ በእግዚአብሔር ፊት ተቀባይነት ያለው በጎ መዓዛ አድርገህ ለእግዚአብሔር ለበጎ መዓዛ ለሚቀርበው ከሚቃጠለው የእህል መሥዋዕትና ከመጠጡ ቍርባን ጋር ታቀርባለህ። ሥጋውንም በዚያች ሌሊትና በማግሥቱ ብላ።'),
  ('dfefba59-c6f5-5004-afc2-35978839f6af', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 8, 8, 'በማግሥቱም እስኪበላ ድረስ ፀሓይ አይግባ፤ እግዚአብሔር አይቀበለውምና ለሦስተኛው ቀን አይትረፍ፤ የተመረጠም አይደለምና፥ ከዚያ በኋላ አይበላም። የሚበሉትም ሁሉ ኀጢአታቸውን ይሸከማሉ።'),
  ('da6f5002-0da5-50d9-a981-b2374b763132', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 9, 9, 'በቀደሙ አባቶች መጽሐፍ ውስጥ በሄኖክና በኖኅ ቃል ውስጥ እንዲህ የሚል ጽሕፈት አግኝቻለሁና፥ በመሥዋዕትህም ሁሉ ጨው ትጨምራለህ፤ በእግዚአብሔር ፊት በሚሠዋው መሥዋዕት ሁሉ የጨው ቃል ኪዳን አይቋረጥም።'),
  ('1872c435-06f1-56d1-a189-2db09b59404b', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 10, 10, '“ወደ መሠዊያው እነዚህን እንጨቶች ብቻ ታገባ ዘንድ መሥዋዕት ስለሚሠዋባቸው እንጨቶች ተጠንቀቅ፥ እነዚህም፦ ሰኖባር፥ ቀረጥ፥ ሰገድ፥ ሽነት፥ ወይራ፥ ዋንዛ፥ ዶቅማ፥ ጠዶ፥ ዘይት፥ ባርሰነት፥ ጥድ፥ አርቦቅ፥ ቀጋ፥ ሾላ ናቸው።'),
  ('304a7829-0b02-52db-a834-6966403d8926', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 11, 11, 'ከእነዚህ እንጨቶች አይነታቸውን መርምረህ በመሠዊያው ላይ ከሚቃጠለው መሥዋዕት በታች አኑር፥ የነቀዘውንና የበሰበሰውን እንጨት ሁሉ አታኑር። ነገር ግን ፈጽሞ ምንም ነውር የሌለባቸውን የጸኑትንና ያማሩትን እንጨቶች፤ የአዲሱንም ተክል እንጨት አኑር።'),
  ('43306236-22d9-564a-a71a-04b20287164c', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 12, 12, 'መዓዛው ተለይቶታልና፥ እንደ ቀደመው በእርሱ መዓዛ የለምና አሮጌውን እንጨት አታኑር። ነገር ግን መዓዛው ልዩ ነውና፥ መዓዛውም ወደ ሰማይ ያርጋልና ከእነዚህ እንጨቶች በቀር ሌላ አይኑር።'),
  ('afc2abe2-ec73-586c-a944-db4c1860d2b0', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 13, 13, 'ይህን ትእዛዝ ጠብቅ፤ ልጄ ሆይ፥ ሥራህን ሁሉ ታቀና ዘንድ ያዘዝሁህን አድርግ። በየጊዜውም ሰውነትህን ንጹሕ አድርግ፤ መሥዋዕት ለመሠዋት ወደ መሠዊያው ሳትወጣ በውኃ ታጠብ፤ ወደ መሥዋዕቱም ሳትቀርብ እጅህንና እግርህን ታጠብ።'),
  ('6271daab-682a-5d25-a5d2-fe47efc74f3a', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 14, 14, 'መሥዋዕቱንም ማቅረብ በጨረስህ ጊዜ ተመልሰህ እጅህንና እግርህን ታጠብ። በሰውነታችሁና በልብሳችሁም ላይ ደም ሁሉ አይታይ።'),
  ('587448da-1c02-59e0-ab6f-df8779fee268', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 15, 15, 'ልጄ ሆይ፥ ከደም ፈጽመህ ተጠበቅ፤ አፈር አልብሰው፤ ደም ነፍስ ናትና እንግዲህ ወዲህ ደም አትብሉ። ምንም ደም አትብላ፤ ያለ ፍርድ በከንቱ እንዳይፈስስ በሰው ደም ሁሉ ላይ መማለጃ አትቀበል፤ የሚፈስስ ደም ምድርን ያጠፋታልና፤ በደም አፍሳሹ ደም ካልሆነም በቀር ደም ያለ ሰው ደም አትነጻምና።'),
  ('bdf80afd-2334-5151-a429-ec80b13d2955', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 16, 16, 'በሰው ደም መማለጃንና እጅ መንሻን አትቀበል። በልዑል አምላክ በእግዚአብሔር ፊት ደም በደም ይመለሳል። ከክፉ ነገርም ሁሉ ትጠበቅ ዘንድ፥ ከሞትም ሁሉ ያድንህ ዘንድ ጥበቃው ለበጎ ነገር ይሆናል።'),
  ('8888d833-d007-5ac9-ad04-e75a9cd20791', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 17, 17, '“ልጄ ሆይ፥ የሰው ሁሉ ሥራ ኀጢአትና ክፋት እንደ ሆነ፥ ሥራቸውም ሁሉ የረከሰና የተናቀ፥ የተጠላም እንደ ሆነ፥ ከእነርሱም ጋር ጽድቅ እንደሌለ አያለሁ።'),
  ('5bf196e0-2079-5c71-a90d-01badeba8dac', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 18, 18, 'በመንገዳቸው እንዳትሄድ፥ ፍለጋቸውንም እንዳትከተል ተጠበቅ። በልዑል አምላክ ፊትም እስከ ሞት የሚያደርስ ስሕተትን አትሳት። ከአንተም ፊቱን ይሰውራል፥ ወደ ኀጢአትህም ኀይል ይመልስሃል። ከምድር ይነቅልሃል። ዘርህንም ከሰማይ በታች ያጠፋል፤ ስምህና ዘርህም ከምድር ሁሉ ይጠፋሉ።'),
  ('3277a44c-a9c9-583c-afad-2d21173d1a49', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 19, 19, 'ከሥራቸው ሁሉና ከርኵሰታቸው ሁሉ ራቅ፤ የልዑል አምላክን ሕግም ጠብቅ፤ ፈቃዱንም ፈጽም። ሥራህን ሁሉ አቅና፤ በሥራህ ሁሉ ይባርክሃል። በምድር ሁሉ፥ በምድር ትውልድም ሁሉ የጽድቅ ተክልን ከአንተ ያስነሣል። ከሰማይ በታች በዘመኑ ሁሉ የእኔ ስም፥ የአንተም ስም ይታወቃል።'),
  ('e0fcaf21-519a-58a7-a143-ca2a97ee74cf', 'abf09448-8cd3-5858-a60f-d5c88ffad7ac', '2baf9f3f-45a7-5419-a7fe-982f02a7fffe', 20, 20, '“ልጄ ሆይ፥ በሰላም ሂድ፤ የእኔ አምላክ፥ የአንተም አምላክ ልዑል እግዚአብሔር ፈቃዱን ለመፈጸም ያጽናህ። ልጅህን ሁሉ፥ የልጅ ልጅህንም ለዘለዓለም ትውልድ በምድር ሁሉ ለበረከት ትሆን ዘንድ በጽድቅ በረከት ሁሉ ይባርክ፤” ከእርሱም ዘንድ ደስ እያለው ወጣ።'),
  ('235260ca-250c-5cb9-a3c7-2a9124218e16', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 1, 1, 'በአርባ አራተኛው ኢዮቤልዩ፥ በመጀመሪያው ሱባዔ አብርሃም በሞተበት በሁለተኛው ዓመት እንዲህ ሆነ፤ በመጀመሪያው የአዝመራ በዓል የዚችን ሱባዔ በዓል ያደርጉ ዘንድ ይስሐቅና ይስማኤል ከቤርሳቤህ ወደ አባታቸው ወደ አብርሃም መጡ።'),
  ('d08a0a74-cdea-5dc4-ac4d-4cff055b2858', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 2, 2, 'አብርሃምም ሁለቱ ልጆቹ መጥተዋልና ደስ አለው። በቤርሳቤህ ያለ የይስሐቅ ገንዘቡ ብዙ ነበረና፤ ይስሐቅም ገንዘቡን ጐብኝቶ ወደ አባቱ ይመለስ ነበር።'),
  ('4b04281b-66db-5b45-aa00-e47868845d14', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 3, 3, 'በዚህም ወራት ይስማኤል አባቱን ያይ ዘንድ መጣ። ሁሉም በአንድነት መጡ።'),
  ('c720d4f8-bf27-5ec6-ad76-0f8af194504d', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 4, 4, 'ይስሐቅም የሚቃጠል መሥዋዕትን ሠዋ፤ አባቱ በኬብሮን በሠራው መሠዊያም ላይ አቀረበ። የድኅነት መሥዋዕትንም ሠዋ፤ በወንድሙ በይስማኤል ፊትም የደስታ ፍሪዳን አረደ።'),
  ('b1c44844-0520-568d-a2e1-2b0077b7c2ad', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 5, 5, 'ርብቃም ከአዲሱ ስንዴ ትኩስ ዳቦ ጋገረች፤ በልቶም ሳይሞት የሁሉን ፈጣሪ እንዲያመሰግን ከመጀመሪያው የምድር ፍሬ ለአባቱ ለአብርሃም ያገባ ዘንድ ለልጅዋ ለያዕቆብ ሰጠችው።'),
  ('578a1650-ae2d-52b3-ae9f-f921989d799d', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 6, 6, 'ይስሐቅም አብርሃም ይበላና ይጠጣ ዘንድ ያማረውን የድኅነት መሥዋዕት በያዕቆብ እጅ ሰደደለት። በልቶና ጠጥቶም ምድርንና ሰማይን፥ የምድርን ስፋትም ሁሉ የፈጠረ ልዑል አምላክን አመሰገነው። ይበሉና ይጠጡ ዘንድ፥ ፈጣሪያቸውንም ያመሰግኑ ዘንድ ለሰው ልጆች ሰጣቸው።'),
  ('4358fbbd-d6b6-50d5-ac0d-a732df14750d', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 7, 7, 'አብርሃምም እንዲህ አለ፥ “ይህችን ቀን አሳይተኸኛልና እነሆ፥ እኔ ለአንተ እገዛለሁ። እነሆም፥ እኔ የመቶ ሰባ አምስት ዓመት ሰው ነኝ፤ አርጅቻለሁም፤ ዘመኔም ተፈጽሞአል፤ ዘመኖችም ሁሉ ሰላም ሆኑልኝ፤ የጠላት ሰይፍም ድል አልነሣኝም።'),
  ('001d522b-6705-5c96-a28c-94e1b5f534f0', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 8, 8, 'በሰጠኸኝም ሁሉና፥ በልጆች በሕይወት በኖርሁበት ዘመን ሁሉ እስከዚች ቀን ድረስ፥ አምላኬ ሆይ፥ በዚህ ዓለም ከአሕዛብ ሁሉ ተለይቶ ከዛሬ ጀምሮ ለዘለዓለም በምድር ላይ እስከሚነሣው ትውልድ ዘመን ሁሉ ድረስ የተመረጠ ሕዝብና ርስት ይሆንህ ዘንድ፥ ይቅርታህ ለባሪያህና ለልጆቹ ይሁን።”'),
  ('de0b8e14-280f-5253-a067-a39b70fe567b', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 9, 9, 'ያዕቆብንም ጠርቶ እንዲህ አለው፥ “ልጄ ያዕቆብ ሆይ፥ ሁሉን የፈጠረ አምላክ ይባርክህ፤ በፊቱም ጽድቅንና ፈቃዱን ለማድረግ ያበርታህ። እንደ ፈቃዱም በዘመኑ ሁሉ የርስቱ ሕዝብ ትሆኑት ዘንድ አንተንና ዘርህን ይምረጥ።'),
  ('fe0e2415-7262-51b7-aed2-157fe0bafa78', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 10, 10, 'አንተም ልጄ ያዕቆብ፥ ቀርበህ ሳመኝ፤” ቀርቦም ሳመው።'),
  ('1432cda2-836f-5fe9-a2f2-11aab00e1029', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 11, 11, 'እንዲህም አለ፥ “አንተም ልጄ ያዕቆብ፥ የተባረክህ ነህ። ልጆችህም ሁሉ ለልዑል እግዚአብሔር ለዘለዓለም የተባረኩ ናቸው። ጻድቅ ዘርንም ይስጥህ፤ ከልጆችህም በምድር ሁሉ መካከል ይቀድስ። አሕዛብ ይገዙልህ፤ አሕዛብም ሁሉ በዘርህ ፊት ይስገዱ፤ በሰውም ፊት አርበኛ ሁን፤ በሴት ልጆችም ሁሉ መካከል ሠልጥነህ ኑር።'),
  ('e7b80eb4-7030-529a-a07e-4f4879e1ba78', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 12, 12, 'ያንጊዜ ቅዱስ ሕዝብ ለመሆን መንገዶችህና የልጆችህ መንገዶች እውነተኛ ይሆናሉ። ልዑል አምላክ እኔን የባረከባቸውን፥ ኖኅንና አዳምንም የባረከባቸውን በረከቶች ሁሉ ይስጥህ። በልጅ ልጅ ዘመን ሁሉ እስከ ዘለዓለም ድረስ ዘርህን ለመቀደስ በአንተ ላይ ይረፉ።'),
  ('6e3374c1-a1f5-591b-a9c4-10579492152a', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 13, 13, 'ባለማወቅ ከሠራኸው ኀጢአትህ ሁሉ ስርየትን ታገኝ ዘንድ ከኀጢአትና ከርኵሰት ሁሉ ያንጻህ፤ ያበርታህም፤ ሀገሩን ሁሉ ትወርስ ዘንድ ይባርክህ። ለዘለዓለም ለርስቱ ሕዝብ ትሆነው ዘንድ ቃል ኪዳኑን ከአንተ ጋር ያጽና።'),
  ('0d22f336-f17a-52dc-a565-ee0d73bcb026', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 14, 14, 'በምድር ዘመን ሁሉ ለአንተም ለዘርህም በእውነትና በጽድቅ አምላክ ይሁንህ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('0b389b21-c2cd-5708-a9b4-8e6ec0fb69e0', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 15, 15, '“አንተም ልጄ ያዕቆብ፥ ቃሌን አስብ፤ የአባትህን የአብርሃምንም ትእዛዝ ጠብቅ፤ ከአሕዛብም ተለይ፤ ከእነርሱም ጋር አትብላ፥ እንደ ሥራቸውም አትሥራ። ሥራቸው የረከሰ ነውና፥ አካሄዳቸውም ሁሉ የረከሰና የተናቀ ነውና፤ መሥዋዕታቸውም የሚያጸይፍ ነውና ባልንጀራ አትሁናቸው።'),
  ('3f6e9423-e56a-5af0-a644-17ab95650665', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 16, 16, 'ለሬሳዎች ፍሪዳ ያርዳሉ፤ ለአጋንንትም ይሰግዳሉ፤ በመቃብርም ይበላሉ፥ ሥራቸውም ሁሉ ከንቱና ብላሽ ነው። ለማሰብም ልብ የላቸውም። ዐይናቸውም የሚያይ አይደለም። ሥራቸው ምንድን ነው?'),
  ('7a2ba644-972b-50cf-a709-448f2848b180', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 17, 17, 'እንጨቱን፦ ፈጣሪዬ አንተ ነህ፥ ድንጋዩንም፦ ጌታዬ አንተ ነህ፥ የምታድነኝም አንተ ነህ እያሉ እነርሱ እንዴት ይስታሉ? ልብም የላቸውም።'),
  ('e0ca8c5d-6916-5669-a942-80f279adbe29', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 18, 18, '“አንተ ልጄ ያዕቆብ፥ ልዑል አምላክ ይርዳህ፤ የሰማይ አምላክም ይባርክህ፤ ከርኵሰታቸውና ከስሕተታቸው ሁሉ ያርቅህ።'),
  ('1762d27b-347e-5f60-a8fb-ab21ae1081c4', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 19, 19, 'ልጄ ያዕቆብ፥ ከከነዓን ሴቶች ልጆች ዘር ሚስት እንዳታገባ ተጠበቅ። ዘሩ ሁሉ ከምድር ለጥፋት ነውና፥ በካም በደል ከነዓን ስትዋልና። ልጁና የልጅ ልጁ ሁሉ ከምድር ይደመሰሳልና፤ በፍርድ ቀንም ከእነርሱ የሚድን የለምና።'),
  ('8038a285-8871-5a6a-ab65-8c3e673460cc', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 20, 20, 'ጣዖት ለሚያመልኩና ለተጠሉ ሰዎች ሁሉ በሕያዋን ምድር ምንም ተስፋ የላቸውምና፥ ወደ ሲኦልም ይወርዳሉና፥ ወደ ፍርድ ቦታም ይሄዳሉና፥ በምድርም ላይ ምንም መታሰቢያ የላቸውምና የሰዶም ልጆች ከምድር እንደ ተወሰዱ እንዲሁ ጣዖት የሚያመልኩ ሁሉ ይወሰዳሉ።'),
  ('19692417-1365-525d-af1a-12e0931fab37', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 21, 21, '“ልጄ ያዕቆብ ሆይ፥ አትፍራ፤ የአብርሃም ልጅ ሆይ፥ አትደንግጥ፤ ልዑል አምላክ ከጥፋት ይጠብቅህ፤ ከስሕተትም ሥራ ሁሉ እርሱ ያድንህ።'),
  ('5e383d79-0a36-58b2-a01e-fce9d4329aa7', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 22, 22, 'ይህንም ቤት በምድር ላይ ስሜን በእርሱ አኖር ዘንድ ለእኔ ሠራሁ፤ ለአንተና ለዘርህም ለዘለዓለም ተሰጠች። የአብርሃምም ቤት ትባላለች።'),
  ('53e8b95b-a5f3-5ea8-ac2f-1127a151c9b5', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 23, 23, 'ቤቴን ትሠራለህና፥ ስሜንም በአምላክ ፊት እስከ ዘለዓለም ታጸናለህ፥ ዘርህም፥ ስምህም በምድር ትውልድ ሁሉ ጸንቶ ይኖራል፤” ይህንም አዝዞና መርቆ ጨረሰ።'),
  ('bca106ab-66f6-5ac9-aea0-90a13d71c7c1', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 24, 24, 'ሁለቱም ሁሉ በአንድ አልጋ በአንድነት ተኙ። ያዕቆብም በአባቱ አባት በአብርሃም አጠገብ ተኛ። ሰባት ጊዜም ሳመው፤ ሩኅሩኅ ልቡናውም በእርሱ ደስ አለው። በፍጹም ልቡናውም ባረከው።'),
  ('bd7c6db7-0040-5463-a874-05c44661eb3e', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 25, 25, 'እንዲህም አለ፥ “ለዘለዓለም ልወርሳትና ለዘለዓለም ይባረክ ዘንድ ቅዱስ ልጅን ልወልድ ያችን ሀገር ትሰጠኝ ዘንድ ከከለዳውያን ዑር ያወጣኸኝ የሁሉ አምላክና የሁሉ ፈጣሪ ልዑል አምላክ ሆይ፥'),
  ('5d6fb77f-7cc8-5cbd-adb0-e34ec38d61da', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 26, 26, 'በፍጹም ልቤና በይቅርታዬ በእርሱ ደስ የሚለኝ ልጄ ያዕቆብን ባርከው። ይቅርታህና ብዙ ቸርነትህ በዘመኑ ሁሉ በእርሱና በዘሩ ይሁን። ከዛሬ ጀምሮ እስከ ዘለዓለም ድረስ አትለየው፤ ቸልም አትበለው።'),
  ('d8eb13b5-7b2f-5672-a8a5-a0556e451451', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 27, 27, 'ይጠብቁት ዘንድ፥ ትባርከውም ዘንድ፥ ለርስትህ የሚሆን ሕዝብን ትቀድሰው ዘንድ፥ በእርሱና በዘሩ ላይ ዐይኖችህ የተገለጡ ይሁኑ። ከዛሬም ጀምሮ እስከ ዘለዓለም ድረስ በበረከትህ ሁሉ ባርከው።'),
  ('1c3b7fde-7d74-5ef0-aef4-aa4d8bb2571e', 'e8840ebe-202e-5cec-a30a-36024e9f1fbb', 'f9d1fba3-e116-5c16-abf0-9abaf40e9b53', 28, 28, 'ቃል ኪዳንህንና ይቅርታህን ከእርሱ ጋር፥ ከዘሩም ጋር፥ በምድር ትውልድ ሁሉ በፍጹም ፈቃድህ አድስ።” ሁለቱንም ሁሉ የያዕቆብን ጣቶች በዐይኖቹ ላይ አኖረ፤ የአማልክት አምላክን አመሰገነው፥ ፊቱንም ሸፈነ።'),
  ('627a9c9c-ae45-5953-abd9-f87e7ac2b1a3', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 1, 1, 'እግሩን ዘርግቶ የዘለዓለም እንቅልፍ አንቀላፋ፤ በሞትም ወደ አባቶቹ ተስበሰበ። በዚህም ሁሉ ያዕቆብ በአጠገቡ ተኝቶ ነበር፤ የአባቱ አባት አብርሃምም እንደ ሞተ አላወቀም ነበር።'),
  ('fde59f72-5d0b-54f9-a3a7-dc609b94f8ca', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 2, 2, 'ያዕቆብም ከእንቅልፉ ነቃ። እነሆ፥ አብርሃም ቀዘቀዘ፤ እንደ በረድም ሆነ። እርሱም፥ “አባ፥ አባ፥” አለ። የመለሰለትም ቃል አልነበረም፤ አብርሃምም እንደ ሞተ ዐወቀ።'),
  ('1f696ae2-6b99-5b37-a255-b588375be3a2', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 3, 3, 'ከአጠገቡም ተነሥቶ ፈጥኖ ሄደ። ለእናቱ ለርብቃም ነገራት። ርብቃም በሌሊት ወደ ይስሐቅ ሄዳ ነገረችው፤ በአንድነትም ሄዱ። ያዕቆብም ከእነርሱ ጋር ነበረ። በእጁም መብራት ይዞ ነበር። በሄዱም ጊዜ አብርሃምን ሬሳው ተጋድሞ አገኙት። ይስሐቅም በአባቱ ፊት ወድቆ አለቀሰ፤ ሳመውም።'),
  ('a1d172f6-f675-5082-a937-1c2926241d49', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 4, 4, 'በአብርሃምም ቤት ጩኸት ተሰማ። ልጁ ይስማኤልም ተነሥቶ ወደ አባቱ ወደ አብርሃም ሄደ፥ ለአባቱ ለአብርሃምም አለቀሰለት። እርሱና የአብርሃም ቤተ ሰብ ሁሉ ትልቅ ልቅሶን አለቀሱ። ልጆቹ ይስሐቅና ይስማኤልም ደርብ ባላት ዋሻ በሚስቱ በሳራ አጠገብ ቀበሩት። ቤተ ሰቦቹም ሁሉ አርባ ቀን አለቀሱለት።'),
  ('0a2734bc-b5b5-547e-a2fc-f0e0daf6cba4', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 5, 5, 'ይስሐቅና ይስማኤል፥ ልጆቻቸውም ሁሉ የኬጡራም ልጆች በቦታቸው አለቀሱለት። የአብርሃም ልቅሶ ኀዘንም ተፈጸመ።'),
  ('89af15e6-27b9-5f56-a58f-c4e56d4eeb97', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 6, 6, 'እርሱም ሦስት ኢዮቤልዩና አራት ሱባዔ ኖረ፤ ይኸውም መቶ ሰባ አምስት ዓመት ነው፥ በሕይወት የኖረበትም ዘመን ተፈጸመ። አረጀ፤ ዘመኑንም ፈጸመ። የቀደሙ ሰዎች በሕይወት የሚኖሩበት ዘመናቸው ዐሥራ ዘጠኝ ኢዮቤልዮች ነበሩ።'),
  ('6f5f3fe5-6229-5b5d-ab0c-f66555f983c0', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 7, 7, 'ከጥፋት ውኃ በኋላ ግን ከኢዮቤልዮች ለማጕደልና ፈጥኖ ለማርጀት፥ ከአብርሃም በቀር በሥራቸው ክፋት ከብዙ መከራ የተነሣ ዘመናቸውን በመሰልቸት ከዐሥራ ዘጠኝ ኢዮቤልዮች ያጐድሉ ጀመር።'),
  ('806cc5b8-f601-5ef5-ab7a-dbaa2eeeb1c1', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 8, 8, 'አብርሃም ግን ከእግዚአብሔር ጋር በሥራው ፍጹም ነበረና ዘመኑ ሁሉ በእውነት ደስ ያሰኘው ነበረ።'),
  ('349aa707-4b40-5e46-a2d1-ddc3a360e743', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 9, 9, 'እነሆም፥ ከመከራ ብዛት የተነሣ ፈጥኖ እስኪያረጅ ድረስ፥ አራቱን ኢዮቤልዮች በሕይወት አልጨረሰም። ዕድሜንም ጠገበ፥ ከዛሬ ጀምሮ እስከ ፍርድ ቀን ድረስ የሚነሡ ልጆች ሁሉ ሁለት ኢዮቤልዩ ሳይጨርሱ ፈጥነው ያረጃሉ።'),
  ('35a84f67-996f-5fd3-a55c-af03b128ad98', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 10, 10, 'ከእርጅናቸውም የተነሣ ዕውቀታቸው የምትለያቸው ትሆናለች፤ ፍጹም ዕውቀታቸውም ትለያቸዋለች።'),
  ('2c433204-61f7-5752-a920-453f31e6432c', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 11, 11, 'በዚያም ወራት ሰው አንድ ኢዮቤልዩና የኢዮቤልዩ እኩሌታ ቢኖር ስለ እርሱ፥ “ብዙ ዘመን ኖረ” ይባላል።'),
  ('6d5c4fa2-411c-5afd-a74f-62493c01efcb', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 12, 12, 'ነገር ግን የዘመኑ አብዛኛው በሽታ፥ ድካምና መከራ ነው፤ ሰላምም አይኖረውም፤ በመቅሠፍት ላይ መቅሠፍት፥ በቁስል ላይ ቁስል፥ በመከራ ላይ መከራ፥ በክፉ ምስክርነት ላይ ክፉ ምስክርነት፥ በበሽታ ላይ በሽታ ይሆናል።'),
  ('7ef1ff1a-8b0c-5805-a3cf-b2593d3ebee5', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 13, 13, 'እንደዚሁም ክፉ ፍርድ ሁሉ ይሆናል፥ ይህም ከዚህ ደዌ ጋር ነው፥ ጓታ፥ ውርጭ፥ በረድ፥ ዋግ፥ እንቅልፍ፥ ግዳጅ፥ የሆድ በሽታ፥ ድርቅ፥ ሞት፥ ሾተል፥ መማረክ፥ መቅሠፍት ሁሉ፥ መከራውም፥ ይህም ሁሉ በዝሙት ርኵሰትና በመተዳደፍ፥ በሚያስጸይፍ ሥራቸውም ምድርን በምታረክስ በዚህች ክፉ ትውልድ ላይ ይመጣል።'),
  ('3713e9f0-2b79-53d1-a13a-2780f6341685', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 14, 14, 'ያን ጊዜም እንዲህ ይላሉ፥ “የቀደሙ አባቶቻችን ዘመናቸው ብዙ ነበረ፤ እስከ ሺህ ዓመት ድረስ ብዙ ነበር፤ መልካምም ነበር፤።'),
  ('f388f10f-a5b4-5229-a2c0-0f56ea36782e', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 15, 15, 'እነሆ፥ የእኛ የሕይወታችን ዘመን ግን ሰው ብዙ ዘመን ኖረ ቢባል ሰባ ዓመት ነው፤ እጅግም ቢበዛ ሰማንያ ዓመት ነው። ሁሉም ክፉ ነው፤ በዚያችም ክፉ ትውልድ ዘመን ምንም ሰላም አይኖርም።'),
  ('d13c36c0-5bc3-538c-a5f6-0dd77c6a896f', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 16, 16, 'በዚያችም ትውልድ ልጆች አባቶቻቸውን፥ ሽማግሌዎቻቸውንም የሚሳደቡ ይሆናሉ። ስለ ኀጢአትና ስለ ዐመፅ፥ ስለ አንደበታቸውም አነጋገር እነርሱ ስለሚሠሩአቸው ታላላቅ ክፋቶች፥ ትእዛዙንና ሥርዐቱን፥ ሕጉንም ሁሉ ይጠብቁና ያደርጉ ዘንድ፥ በእነርሱና በእርሱ መካከል እግዚአብሔር ያደረገውን ቃል ኪዳን ስለ መተዋቸው ይሳደባሉ።'),
  ('ce270acf-c135-51e2-a903-5f874f6bb54c', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 17, 17, 'ሁሉም ክፉ ሥራን እስከ መሥራት ደርሰው ወደ ቀኝም ወደ ግራም ፈቀቅ አይሉም። አንደበትም ሁሉ በደልን ይናገራል። ሥራቸውም ሁሉ ርኩስ ነው፥ የሚያጸይፍም ነው። መንገዳቸውም ነውር ነው፤ የረከሰም ነው፤ ጥፋትም ነው።'),
  ('44988b9e-56bd-5dd0-a663-a856a6b23d1c', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 18, 18, '“እነሆ፥ ምድር ስለ ሥራቸው ሁሉ ትጠፋለች። የወይን ዘር የላቸውም፤ ዘይትም የላቸውም፤ ሥራቸው ሁሉ ክህደት ነውና፥ አራዊትና እንስሳት፥ ወፎችና የባሕር ዓሣዎች ሁሉ ከሰው ልጆች አስቀድመው ሁሉም በአንድነት ይጠፋሉ።'),
  ('e4751fee-b684-5f11-a3b5-dd79bed03ef0', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 19, 19, 'እነዚህ ከእነዚህ ጋር፥ ወጣቶች ከሽማግሌዎች ጋር፥ ሽማግሌዎችም ከወጣቶች ጋር፥ ድሃ ከባለጸጋ ጋር፥ ታናሹ ከታላቁ ጋር፥ ጦም አዳሪው ከዳኛው ጋር፥ ስለ ሕግና ስለ ቃል ኪዳን ይጣላሉ።'),
  ('e22d4c35-565b-5d86-a56d-5dc70a801ffc', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 20, 20, 'ትእዛዙንና ቃል ኪዳኑን፥ በዓሉንና የወር መባቻውን፥ ሱባዔውንና ኢዮቤልዩን፥ ፍርዱንም ሁሉ ዘንግተዋልና፤ ከሰንከልካላ መንገዳቸው ይመልሱአቸው ዘንድ ለሰልፍ ሰይፍ ይዘው ይነሣሉ። ሕግን የሚጠብቁ ግን ብዙ ደም በምድር ላይ እስኪፈስስ ድረስ አይመለሱም። እነዚህ በእነዚህ ላይ ይነሣሉ። በጽድቅ መንገድ ያልዳኑ ሰዎች ግን ከክፋታቸው አይመለሱም።'),
  ('d766a234-8177-5f92-ae99-9cc2ce23d943', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 21, 21, 'እያንዳንዱ በቅሚያ ለመበልጸግ የባልንጀራውን ገንዘብ ሁሉ ይወስድ ዘንድ ይነሣሉና፤ በታላቅ ስምም ይጠራሉ። ነገር ግን በእውነት አይደለም፥ በጽድቅም አይደለም፤ በርኵሰታቸውና በጥፋታቸው በነውራቸውም ቅድስተ ቅዱሳኑን ያረክሳሉ።'),
  ('ee99f97e-34f8-5b2a-a423-2956f11abfa3', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 22, 22, '“በዚያችም ትውልድ ሥራ ከእግዚአብሔር ጽኑ መቅሠፍት ይሆናል። ለሰይፍና ለቅጣት፥ ለመማረክና ለመቀማት፥ ለጥፋትም ይሰጣቸዋል፤ በእነርሱ ላይ ምሕረትና ይቅርታ የሌላቸውን የአሕዛብ ወገኖች ያስነሣባቸዋል።'),
  ('8c8added-82d6-581a-a2ac-5f51beb0bb48', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 23, 23, 'ከሰው ልጆች ሁሉ ይከፉ ዘንድ፥ ክፉዎችና ኀይለኞች ናቸውና ለሽማግሌም ቢሆን፥ ለሕፃንም ቢሆን፥ ለማንም ለማን ፊት አያደሉም፤ በእስራኤልም ላይ ክርክርን፥ በያዕቆብም ላይ በደልን ያደርጋሉ፤ ብዙ ደምም በምድር ላይ ይፈስሳል፤ የሚሰበስብም የለም፤ የሚቀብርም የለም።'),
  ('1c900874-cd60-59f1-a9e4-b1430c4eff6e', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 24, 24, '“በዚያም ወራት ጮኸው ይጣራሉ፤ ከኀጢአተኞች ከአሕዛብ እጅ ይድኑ ዘንድ ይጸልያሉ። ነገር ግን የሚያድን የለም። የሕፃናቱም ራስ በሽበት ይነጣል። የሦስቱ ሱባዔ ሕፃንም መቶ ዘመን እንደ ሆነው ሽማግሌ ሆኖ ይታያል። ቁመታቸውም በመከራና በጭንቀት ይጐብጣል።'),
  ('4a995c18-5fa3-539b-a9aa-41693d90ce80', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 25, 25, 'በእነዚያም ወራቶች ልጆች ሕጉን ለመመርመር፥ ሥርዐቱንም ለመፈለግ፥ ወደ እውነት መንገድም ለመመለስ ይጀምራሉ። ቀኖችም ይበዙና ይረዝሙ ጀመር፤ የሰው ልጆችም ከትውልድ ወደ ትውልድ ይበዙ ጀመር፤ ቀናቸውም ወደ ሺህ ዓመት እስኪቀርብ ድረስ ከብዙ ቀናትም እስከ ብዙ ዓመታት እስኪቀርብ ቀን ከቀን ይበዛ ጀመር።'),
  ('21d49fec-ce6d-535f-a370-d86d3d630585', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 26, 26, 'ሽማግሌ የለም፤ ዕድሜንም የሚጠግብ የለም፤ ሁሉም ሕፃናትና ልጆች ይሆናሉና። ሁሉም ዘመናቸውን ይፈጽማሉ፥ በሰላምና በደስታም ይኖራሉ።'),
  ('136265e1-1981-5598-a403-327c64126243', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 27, 27, 'ባላጋራ አይኖርም፤ ዘመኖቻቸው ሁሉ የበረከትና የፈውስ ዘመኖች ይሆናሉና የሚያጠፋ ክፉ አይኖርም።'),
  ('43db3235-aa8b-5ec9-a41d-86e5b6f53510', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 28, 28, '“ያንጊዜም እግዚአብሔር ባሪያዎቹን ያድናል፤ ይነሣሉም፥ በዓለምም ብዙ ሰላምን ያያሉ፤ ጠላቶቻቸውንም አስወጥተው ይሰዳሉ። ጻድቃንም አይተው ያመሰግናሉ። እስከ ዘለዓለም ድረስ ፈጽሞ ደስ ይላቸዋል። በጠላቶቻቸውም የተደረገውን ፍርድ ሁሉና መርገማቸውን ሁሉ ያያሉ። አጥንቶቻቸውም በምድር ያርፋሉ፤ ነፍሶቻቸውም ደስታን ያበዛሉ።'),
  ('a19aed23-e919-59f3-a6d9-b5f9548946e9', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 29, 29, 'ፍርድን የሚያደርግ እግዚአብሔርም እንዳለ ያውቃሉ ለሚወዱትም ሁሉ በመቶዎችና በሺሆች ለሚቈጠር ዘመን ይቅርታን ያደርጋል።'),
  ('1c894f72-d104-5ac2-a1e1-f1b0d5c49bff', '811a8f69-d682-5677-a4c0-dc4d24774e64', '1dc7410e-d8f4-5489-a8b5-d57eec2f19c9', 30, 30, 'ሙሴ ሆይ፥ አንተም ይህን ነገር ጻፍ፤ እንዲህ ተብሎ የተጻፈ ነውና፤ ለዘለዓለም ትውልድም ሥርዐት ሊሆን በሰማይ ጽላት ይጽፋሉ።'),
  ('e65b01f7-7574-511e-a66e-ba0fa210a4ac', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 1, 1, 'አብርሃም ከሞተ በኋላ እንዲህ ሆነ፤ እግዚአብሔር ልጁን ይስሐቅን ባረከው፤ ከኬብሮንም ተነሥቶ ሄዶ በዚህ ኢዮቤልዩ በሦስተኛው ሱባዔ በአንደኛው ዓመት በዐዘቅተ ራእይ አጠገብ ሰባት ዓመት ኖረ።'),
  ('a7fee050-e4c8-59e3-acf4-d5a53e4a09e8', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 2, 2, 'በአራተኛው ሱባዔ በመጀመሪያው ዓመት በአብርሃም ዘመን ከሆነው ከቀደመው ድርቅ ሌላ በሀገሩ ሁሉ ድርቅ ሆነ። ያዕቆብ የምስር ንፍሮ ቀቀለ፥ ዔሳውም ከምድረ በዳ ርቦት መጣ።'),
  ('e8647e0c-492d-542e-a8d7-2f8795f2dfcd', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 3, 3, 'ወንድሙ ያዕቆብን፥ “ከዚህ ከዳቦውና ከምስሩ ወጥ ስጠኝ” አለው።'),
  ('b1fe8c64-328f-524d-a7fc-3496cfcf494d', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 4, 4, '“ብኵርናህን ስጠኝ፤ እኔም ዳቦውን፥ ከዚህም ምስር ወጥ እሰጥሃለሁ” አለው።'),
  ('9544fcf3-5e02-503d-adc9-156498077660', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 5, 5, 'ዔሳውም በልቡ፥ “እኔ በራብ እሞታለሁ፤ ይህ ብኵርና ምን ያደርግልኛል?” አለ፥ ለያዕቆብም፥ “ብኵርናውን ሰጠሁህ” አለው።'),
  ('4b22c747-5571-5590-a3dd-a71a125bfc29', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 6, 6, 'ያዕቆብም፥ “አሁን ማልልኝ” አለው። እርሱም ማለለት። ያዕቆብም ለወንድሙ ለዔሳው ዳቦውንና የምስሩን ወጥ ሰጠው፤ እስኪጠግብ ድረስ በላ፤ ዔሳውም ብኵርናውን አቃለለ።'),
  ('5b51c956-5f30-525a-a3df-3ce65c697b00', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 7, 7, 'ስለዚህም ለበኵርናው ያዕቆብ ዳቦውንና የምስር ወጡን ስለ ሰጠው የዔሳው ስም ኤዶም ተባለ።'),
  ('0241c6d5-aadf-521c-a57b-df6d06cf421c', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 8, 8, 'ያዕቆብ ከበረ፤ ዔሳው ግን ከቅድምናው ተዋረደ።'),
  ('c2188caa-b899-541c-abdb-365fdf3183c9', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 9, 9, 'በሀገርም ድርቅ ሆነ፥ በዚህ ሱባዔ በሁለተኛው ዓመት ይስሐቅ ወደ ግብፅ ይወርድ ዘንድ መጣ፤ ወደ ፍልስጥኤሙ ንጉሥ ወደ አቤሜሌክ ወደ ጌራሮ ሄደ።'),
  ('d34eaae4-483b-5b96-a804-5cf4e3f7afaf', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 10, 10, 'እግዚአብሔርም ተገለጠለት እንዲህም አለው፥ “ወደ ግብፅ አትውረድ፥ እኔ ባልሁህ ሀገር ኑር፥ ወደዚያች ሀገር ሂድ፤ እኔም ከአንተ ጋር እኖራለሁ፥ ለአንተና ለዘርህ ይህችን ሀገር መላዋን እሰጥሃለሁና እባርክሃለሁ፤ ለአባትህ ለአብርሃም የማልሁለትንም መሓላ አጸናለሁ፥ ዘርህንም እንደ ሰማይ ኮከብ አበዛልሃለሁ፤ ይህችን ሀገር ሁሉ ለዘርህ እሰጣለሁ።'),
  ('c36cd2cd-8d4b-5b3d-a3e8-73699cb15245', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 11, 11, 'አባትህ የእኔን ነገር ስለ ሰማ ቃሌንና ትእዛዜን ሕጌንና ሥርዐቴን፥ ቃል ኪዳኔንም ስለ ጠበቀ የምድር አሕዛብ ሁሉ በዘርህ ይባረካሉ።'),
  ('5c69c180-ead9-5464-ac55-6c7ac89064bf', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 12, 12, 'አሁንም ቃሌንና ትእዛዜን ስማ፤ በዚችም ሀገር ኑር።” ሦስት የዓመት ሱባዔ በጌራሮ ኖረ። አቤሜሌክም ስለ እርሱና ስለ ገንዘቡ ሁሉ፥ “እርሱን፥ ገንዘቡንም የነካ ሁሉ ሞትን ይሙት” ብሎ አዘዘ።'),
  ('77d257e4-2253-5f07-aa02-ba93b7f4e6fc', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 13, 13, 'ይስሐቅም በፍልስጥኤም ከበረ፤ ገንዘብም በዛለት፤ ላሞችና በጎች፥ ግመሎችና አህዮችም በዙለት። ብዙ ጥሪትም ነበረው። በፍልስጥኤም ሀገርም ዘር ዘራ።'),
  ('9676c2d7-9d47-5f5b-a643-5574cd355179', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 14, 14, 'መቶ ዳውላ እህልም አገባ። ይስሐቅም ፈጽሞ ከበረ። የፍልስጥኤም ሰዎችም ቀኑበት። አብርሃም በሕይወት ሳለ የአብርሃም አሽከሮች የቈፈሩትን ጕድጓድ፥ አብርሃም ከሞተ በኋላ የፍልስጥኤም ሰዎች አፈር ሞልተው ደፍነውት ነበር።'),
  ('3e4e612e-cca1-5e9b-a45b-54aab1f0ec6a', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 15, 15, 'አቤሜሌክም ይስሐቅን፥ “ከእኛ ፈጽመህ ከብረሃልና ከእኛ ዘንድ ሂድ” አለው።'),
  ('c1d23427-4beb-513a-a149-cc76a1f3d1c2', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 16, 16, 'ይስሐቅም በሰባተኛው ሱባዔ በአንደኛው ዓመት ከዚያ ተነሥቶ ወደ ጌራሮ ቆላ ሄደ።'),
  ('58c22d1a-dfc7-5b16-a378-9a56345ce417', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 17, 17, 'የአባቱም የአብርሃም አሽከሮች የቈፈሩአቸውን፥ አባቱ አብርሃም ከሞተ በኋላ የፍልስጥኤም ሰዎች ደፍነዋቸው የነበሩትን የውኃ ምንጮች ተመልሰው ቈፈሩ። ስማቸውንም አባቱ አብርሃም ባወጣላቸው ስም ጠራቸው። የይስሐቅም አሽከሮች በፋንጋ ጕድጓዶችን ቈፈሩ፤ በዚያም የጠራ ውኃ አገኙ።'),
  ('75e23b33-58e0-5035-a15e-5551ea684d08', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 18, 18, 'የጌራሮ እረኞች ከይስሐቅ እረኞች ጋር፥ “ይህ ውኃ የእኛ ነው” እየተባባሉ ተጣሉ። ይስሐቅም፥ “ከእኛ ጋር ተጣልተዋልና፤” ሲል የዚያን ጕድጓድ ስም “ዕፁብ” አለው። ሌላም ጕድጓድ ቈፈሩ፤ በእርሱም ተጣሉ፤ ስሙንም “ጸብእ” አለው።'),
  ('05176a92-20c5-5f92-aee8-e797ecd4eb7d', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 19, 19, 'ከዚያም ተነሥተው ሄደው ሌላ ጕድጓድ ቈፈሩ፥ በእርሱ ግን አልተጣሉም፤ ስሙንም “ስፉሕ” አለው።'),
  ('935f5ab6-5e7a-5e76-aecf-eeeb5eac6d27', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 20, 20, 'ይስሐቅም፥ “ዛሬ እግዚአብሔር አሰፋልን፤ በምድርም ከበርን” አለ። ከዚያም በአርባ አራተኛው ኢዮቤልዩ በመጀመሪያው ሱባዔ በመጀመሪያው ዓመት ወደ ቤርሳቤህ ወጣ።'),
  ('074dac67-02f0-5ab2-a662-2ac71b4a67cf', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 21, 21, 'በዚያችም ሌሊት በመጀመሪያው ወር መባቻ እግዚአብሔር ተገለጠለት፤ እንዲህም አለው፥ “የአባትህ የአብርሃም አምላክ እኔ ነኝ፤ እኔ ከአንተ ጋር እኖራለሁና አትፍራ፤ አከብርሃለሁ፤ ስለ ወዳጄ ስለ አብርሃም ዘርህን እንደ ባሕር አሸዋ ፈጽሜ አበዛዋለሁ።”'),
  ('426604bb-63b8-5536-ad5e-0543c48dc35c', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 22, 22, 'እርሱም አባቱ አብርሃም ቀድሞ መሠዊያ በሠራበት በዚያ ቦታ መሠዊያ ሠርቶ የእግዚአብሔርን ስም ጠራ። ለአባቱ ለአብርሃም አምላክም መሥዋዕትን ሠዋ፤ ጕድጓድንም ቈፈረ፤ ጥሩ ውኃንም አገኘ።'),
  ('14ae4c0b-2f16-5903-a7af-629dffbc214d', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 23, 23, 'የይስሐቅም ብላቴኖች ሌላ ጕድጓድ ቈoፈሩ፤ ውኃ ግን አላገኙም። ሄደውም ውኃ እንዳላገኙ ለይስሐቅ ነገሩት።'),
  ('f6642f7f-2cf4-5f2a-a046-c42b96908945', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 24, 24, 'ይስሐቅም፥ “በዚች ቀን ለፍልስጥኤም ሰዎች ማልሁ፤ ይህም ነገር ለእኛ ሆነ” አለ። ለአቤሜሌክና ለሁለተኛው ለአኮዘት፥ ለጠባቂው ለፋኮልም በዚያ ምሎአልና የዚያን ቦታ ስም “ዐዘቅተ መሐላ” ብሎ ጠራው።'),
  ('916218a2-6c96-5c9b-a8a1-dbdeb9b89d45', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 25, 25, 'ይስሐቅም ከእነርሱ ጋር ሰላምን ለማድረግ በዚያች ቀን በግፍ እንደ ማለላቸው ዐወቀ፤ ይስሐቅም በዚያች ቀን የፍልስጥኤምን ሰዎች ረገማቸው። እንዲህም አለ፥ “በመቅሠፍትና በቍጣ ቀን የፍልስጥኤም ሰው ርጉም ነው፤ እግዚአብሔር ከአሕዛብ ሁሉ መካከል ለይቶ ለሽሙጥና ለመርገም፥ ለመቅሠፍትና ለቍጣ ይስጣቸው፤ ያጠፋቸውም ዘንድ በኀጢአተኞች አሕዛብና በኬጤኤም እጅ ይጣላቸው።'),
  ('99165dfc-2fb7-5f31-aef5-981d7e7c067f', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 26, 26, 'ለልጆች በዘመናቸው በምድር ላይ የዕለት ጠላትና የቈየ ጠላት ይሆኑባቸዋልና ከጠላት ሰይፍና ከኬጤኤም ያመለጡትን ጻድቃን ወገኖች ከሰማይ በታች በፍርድ ያጥፉአቸው።'),
  ('2048cbb3-31c7-5692-a166-961b4cfb4f3f', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 27, 27, 'የፍልስጥኤም ዘር ሁሉ ከምድር ተነቃቅሎ ለመጥፋትና ለመራቅ የተዘጋጀ ነውና ለእነርሱ የሚቀርላቸው የለም። በቍጣ ፍርድ ቀንም የሚድን የለም።'),
  ('4158c355-17cb-5ef0-a622-9fb6269919e3', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 28, 28, 'ላልተገረዘ ሁሉ በምድር ላይ የሚቀርለት ምንም ስምና ዘር አይኖረውም፤ እስከ ሰማይም ቢወጣ ከዚያ ይወርዳልና፥ በምድርም ቢጸና፥ ከዚያ ይነቀላልና፤ በአሕዛብም መካከል ቢሰወር ከዚያ ይጠፋልና፤'),
  ('05240a69-bd09-5f80-a31d-e5fb324f7aa5', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 29, 29, 'ወደ ሲኦልም ቢወርድ በዚያ ቅጣቱ ይበዛልና፤ በዚያ ምንም ሰላም የለውምና።'),
  ('f4cb4405-06b7-509f-ac2b-ae689a565684', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 30, 30, 'ሰውነቱን ለማጥፋት በሚፈልጉአት ሰዎች እጅ ተማርኮም ቢሄድ በጎዳና መካከል ይገድሉታልና፥ በምድር ሁሉ የሚቀርለት ስምና ዘር የለውም። ወደ ዘለዓለም መርገም ይሄዳልና።'),
  ('c6f5b5c9-278a-5f34-a50c-27ee32dc9388', '99ad0a5b-5b57-5b22-a1df-8c32d29e00c3', 'cdededf6-d8c0-5250-a03e-0519f63ede30', 31, 31, 'ከምድር ይጠፋ ዘንድ በፍርድ ቀን ለእርሱ ለማድረግ ስለ እርሱ በሰማይ ጽላት እንደዚህ ተጽፎአል፤ ተቀርጾአልም።”'),
  ('c9466fa2-28ea-59bc-a02d-2e3c79130680', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 1, 1, 'በዚህ ኢዮቤልዩ፥ በዚህ ሱባዔ በሁለተኛው ዓመት ርብቃ ልጅዋን ያዕቆብን ጠርታ ተናገረችው፤ እንዲህም አለችው፥ “ልጄ ሆይ፥ ከከነዓን ሴቶች ሁለት ሚስቶችን እንዳገባ እንደ ወንድምህ እንደ ዔሳው ከከነዓን ልጆች ሚስት አታግባ። ሥራቸው ሁሉ ዝሙትና መዳራት ነውና በሚያጸይፍ ሥራቸው ሁሉ ሰውነቴን አሳዘኗት፤ ሥራቸው ክፉ ነውና በእነርሱ ምንም እውነት የለም።'),
  ('3303de4c-0f79-5f60-a325-aa6bf0fc5648', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 2, 2, 'ልጄ ሆይ፥ እኔ እጅግ እወድሃለሁ። ልቡናዬና ቸርነቴ በቀኑ ጊዜና በሌሊቱ ጥበቃ ይመርቁሃል።'),
  ('45894b91-c474-5879-abfe-6a858a2605a0', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 3, 3, 'አሁንም፥ ልጄ ሆይ፥ ቃሌን ስማ፤ የእኔን የእናትህንም ፈቃድ አድርግ። ከአባትህ ቤት በቀር፥ ከአባትህም ወገን በቀር ከዚህ ሀገር ሴቶች ልጆች ሚስትን አታግባ። የምታገባትንም ከአባቴ ወገን አግባ። ልዑል አምላክም ይባርክሃል፤ ልጆችህም የእውነት ልጆች ይሆናሉ፤ ዘርህም ቅዱስ ይሆናል።”'),
  ('f9acf603-5bf0-5976-a312-9a252150ebc3', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 4, 4, 'ከዚህ በኋላ ያዕቆብ ከእናቱ ከርብቃ ጋራ ተነጋገረ፤ እንዲህም አላት፥ “እናቴ፥ እነሆ፥ እኔ የዘጠኝ ሱባዔ ዓመት ሰው ነኝ፤ ምንም ምን ሴት አላውቅም፤ አልዳሰስሁም፤ አላጨሁምም። ከከነዓን ወገን ልጆች ምንም ምን ሴት እንዳላገባ እንደ አዘዘኝ ከአባታችን ከአብርሃም ነገር የተነሣ አስባለሁና፥ ከከነዓን ልጆች ወገን ሁሉ ሚስት አገባ ዘንድ አላስብም። ከአባቴ ወገን ልጆች ከዘመዶች ሚስት አገባለሁና።'),
  ('5797f644-be6d-5333-ad06-3c505155568f', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 5, 5, 'ለወንድምሽ ለላባ ሴቶች ልጆች እንደ ተወለዱለት አስቀድሜ ሰማሁ። ከእነርሱም ሚስት አገባ ዘንድ ልቡናዬን በእነርሱ ላይ አሳረፍኩ።'),
  ('208266b6-1c92-58de-a90c-8ba217d008ea', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 6, 6, 'ስለዚህም እንዳልበድል፥ በመንገዴም ሁሉ በሕይወቴ ዘመን እንዳልጠፋ በሰውነቴ ተጠበቅሁ፤ ስለ መዳራትና ስለ ዝሙት አባቴ አብርሃም አብዝቶ አዝዞኛልና፥ ከዚህም ሁሉ ጋር ይህን አዝዞኛልና። ወንድሜ የሁለቱን ሚስቶቹን እኅት አንዲቱን አግባ እያለ ሲከራከረኝና ሲናገረኝ ሃያ ሁለት ዓመቱ ነው።'),
  ('b12c9048-9283-5cdb-af58-388d77127a37', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 7, 7, '“እኔም ወንድሜ እንዳደረገው አደርግ ዘንድ አልወድም፤ ባለ ዘመኔ ሁሉ ከከነዓን ሴቶች ልጆች ሁሉ ሚስት እንዳላገባ፥ ወንድሜ ክፉ ሥራ እንደ ሠራ እኔም ክፉ ሥራ እንዳልሠራ በፊትሽ እምላለሁ። እናቴ፥ አትፍሪ፤ ፈቃድሽን እንደማደርግ፥ በቅንነትም እንደምሄድ፥ መንገዴንም ለዘለዓለም እንደማላጠፋ እመኚ።”'),
  ('38c61441-ab0e-5169-a328-c6ce49f1c420', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 8, 8, 'ከዚህም በኋላ አንገቷን ወደ ሰማይ አቀናች፤ እጆችዋንም ዘረጋች፤ አፍዋንም ከፍታ ሰማይንና ምድርን የፈጠረ ልዑል አምላክን አመሰገነችው፤ ፍጹም ምስጋናንም አቀረበችለት።'),
  ('b6ef6e3b-7a89-5fed-a0ca-a7ac45b1a227', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 9, 9, 'እንዲህም አለች፥ “ንጹሕ ልጅና ቅዱስ ዘርን ያዕቆብን የሰጠኝ አምላኬ እግዚአብሔር ይመስገን፤ ስሙም ለዘለዓለም ይባረክ። የአንተ ነውና በዘለዓለም ትውልድ ሁሉ እስከ ብዙ ዘመን ድረስ ልጁ ለአንተ ይሁን።'),
  ('8bc4cef4-7f92-565e-ae74-1d2e309bb654', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 10, 10, 'አቤቱ፥ ባርከው። እመርቀውም ዘንድ በአንደበቴ የጽድቅ በረከትን አኑር።”'),
  ('75bee19a-39a2-51d0-aefb-7a354a70d7ad', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 11, 11, 'ያንጊዜም መንፈስ ቅዱስ ወርዶ በአንደበቷ አናገራት፤ ሁለቱን እጆችዋንም በያዕቆብ ራስ ላይ አኖረች። እንዲህም አለች፥ “የጽድቅ ጌታ፥ የዓለማት አምላክ አንተ የተመሰገንህ ነህ።'),
  ('8b54e4ba-e3bf-508c-a2b9-ace6a81c4f13', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 12, 12, 'ልጄ ሆይ ከሰው ልጅ ሁሉ ለይቶ አንተን ይባርክ። የጽድቅን መንገድ ይስጥህ፤ ለዘርህም ጽድቅን ይግለጥለት፤ በሕይወትህ ሳለህም ልጆችህን ያብዛልህ፤ በዓመቱም ወሮች ቍጥር ዐሥራ ሁለት ይሁኑ። ልጆቻቸውም ይብዙ፤ ከሰማይ ከዋክብት ይልቅ ይብዙ፤ ቍጥራቸውም ከባሕር አሸዋ ይብዛ። ለአብርሃም ይሰጣት ዘንድ፥ ከእርሱም በኋላ በዘመኑ ሁሉ ለዘሩ ይሰጣቸው ዘንድ እንደ ተናገረ ያችን የተወደደች ምድር ይስጣቸው።'),
  ('648137b4-825b-55e8-afc4-6b7da7508308', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 13, 13, 'ለዘለዓለም እጅ አድርገው ይዘዋት ይኑሩ። ልጄ ሆይ፥ በሕይወት ሳለሁ የተባረከ ልጅን ልይ፤ ዘርህ ሁሉ የተባረከና፥ የተቀደሰ ዘር ይሁን፤ በሕይወቷ ሳለች የእናትህን ልቡና እንዳሳረፍህ የእናትህ ማኅፀን እንዲህ ትመርቅህ፤ ማኅፀኔና ጡቴ አንተን ይመርቁ፤ አፌና አንደበቴም ፈጽመው አንተን ያመስግኑ፤ ፈጽመህ ብዛ፤ በዓለሙም ሁሉ ምላ። ዘርህም በሰማይና በምድር ስፋት በዓለሙ ሁሉ ፍጹም ይሁን፤ ዘርህንም ደስ ይበለው።'),
  ('72f02bb1-f027-5719-a637-4473ec3115de', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 14, 14, 'በታላቅ ሰላም ቀንም ሰላም ይሁንለት። ስምህና ዘርህ እስከ ብዙ ዘመን ድረስ ይኑር፤ ልዑል አምላክም አምላካቸው ይሁን፤ የጽድቅ አምላክም ከእነርሱ ጋር ይኑር። መቅደሱም በዓለሙ ሁሉ በእነርሱ ይሠራ። የሚመርቅህ የተመረቀ ይሁን፤ በሐሰት የምትረግምህ ሰውነት ሁሉ የተረገመች ትሁን፤”'),
  ('8acdd2b0-7372-5b2f-ab25-4cea8e35a604', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 15, 15, 'እርሷም ሳመችው፤ እንዲህም አለችው፥ “የእናትህ ልቡና እንደሚወድህ፥ ማኅፀንዋም በአንተ ደስ እንደሚለው፥ እንደሚመርቅህም የዓለሙ ሁሉ ጌታ አንተን ይውደድህ።” ከዚያ በኋላ ከመመረቅ ዝም አለች።'),
  ('3a87a996-6bad-5d7d-a456-4d5cdd4a821a', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 16, 16, 'በዚህ ሱባዔ በሰባተኛው ዓመት ይስሐቅ ታላቁን ልጁን ዔሳውን ጠርቶ እንዲህ አለው፥ “ልጄ ሆይ፥ እኔ አረጀሁ፤ እነሆ፥ ዐይኖች ለማየት ፈዝዘዋል፤ የምሞትባትን ቀን አላውቅም።'),
  ('e2c842c9-e92c-5e3f-a914-bcb0190f674e', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 17, 17, 'አሁንም የምታድንበትን ጦርህንና ጎራንጎሬህን፥ ቀስትህንም ይዘህ ወደ ምድረ በዳ ውጣ። አደንም አድነህና አጥምደህ አምጣልኝ፤ ልጄ! ሰውነቴ የምትወድደውን መብል አዘጋጅተህ እበላ ዘንድ አምጣልኝ፤ ሳልሞትም ሰውነቴ ትመርቅህ” አለው። ርብቃም ይስሐቅ ለዔሳው ሲነግረው ነገሩን ትሰማ ነበር።'),
  ('898afb89-d01f-56ae-add8-fbc2f4d39774', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 18, 18, 'ዔሳውም አጥምዶ ይይዝና ለአባቱ ያመጣ ዘንድ ወደ ምድረ በዳ ገሥግሦ ሄደ።'),
  ('3a3b280e-5151-5c62-a1c2-a7ebc3e62e4b', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 19, 19, 'ርብቃም ልጅዋን ያዕቆብን ጠርታ እንዲህ አለችው፥ “አባትህ ይስሐቅ፦ አደን አድነህ አምጥተህ የምበላውን አዘጋጅልኝ፤ በልች ሳልሞት በእግዚአብሔር ፊት ልመርቅህ ብሎ ከወንድምህ ከዔሳው ጋር ሲነጋገር ሰማሁት።'),
  ('d7920382-5d07-5c91-aeac-6cafbcb369a7', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 20, 20, 'አሁንም፥ ልጄ ሆይ፥ እኔ የማዝዝህን ነገር ስማ፤ ወደ መንጋህ ሄደህ የአማሩ ሁለት የፍየል ጠቦቶችን አምጣልኝ፤ እንደሚወድደውም አድርጌ ለአባትህ ምግብ ላዘጋጃቸው፤ ሳይሞትም በእግዚአብሔር ፊት ይመርቅህ ዘንድ፥ ለአባትህ አቅርበህለት ይብላ፤ የተመረቅህም ትሆናለህ።”'),
  ('0145d819-c064-50fa-a958-2cf80f8f22f9', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 21, 21, 'ያዕቆብም እናቱ ርብቃን እንዲህ አላት፥ “አባቴ ስለሚበላውና ደስ ስለሚያሰኘው ሁሉ አልሸልግም። ነገር ግን እናቴ! ቃሌን እንዳያስተውለው እፈራለሁ። ይዳስሰኝም ዘንድ ይወድ ይሆናል። እኔ ጠጕር እንደሌለኝ፥ ወንድሜ ዔሳውም ጠጕራም እንደ ሆነ አንቺ ታውቂያለሽ፤ በፊቱ የምንቀውና ያላዘዘኝን የምሠራ ይመስለዋል፤ ይቈጣኛል፤ በረከትን ያይደለ ርግማንን በእኔ ላይ አመጣለሁ።”'),
  ('9cd4eba8-45a0-5620-a96c-8bbf976a9191', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 22, 22, 'እናቱ ርብቃም፥ “ልጄ ሆይ፥ ነገሬን ስማ እንጂ መርገምህ በእኔ ይሁን” አለችው፤ ያዕቆብም የእናቱን የርብቃን ቃል ሰማ፤ ሄዶም ያማሩና የሰቡ ሁለት የፍየል ጠቦቶችን አመጣ፤ ወደ እናቱም አቀረባቸው፤ እናቱም ይስሐቅ እንደሚወደው አድርጋ አዘጋጀቻቸው።'),
  ('ccf94b61-22ba-561a-a78a-aa22ae767a61', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 23, 23, 'ርብቃም የሚወደድ ከእርስዋ ዘንድ በቤቷ ያለውን የታላቁን ልጅዋን የዔሳውን ልብስ አምጥታ ለታናሹ ልጅዋ ለያዕቆብ አለበሰችው፤ የፍየሉን ጠቦት፤ ቍርበቶችንም በእጁ ላይ አኖረች፤ በሰውነቱና በአንገቱ ላይ አለበሰችው። ያዘጋጀቻቸውን ዳቦውንና ወጡንም ለልጅዋ ለያዕቆብ ሰጠችው።'),
  ('35f934f9-0816-51a0-a687-7b6bf37ed1fc', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 24, 24, 'ያዕቆብም ወደ አባቱ ወደ ይስሐቅ ገብቶ፥ “እኔ ልጅህ እንዳልኸኝ አደረግሁልህ፥ ተነሥተህ ተቀመጥ፤ አባቴ ሆይ፥ ሰውነትህ ትመርቀኝ ዘንድ አጥምጄ ከአመጣሁልህ ብላ” አለው።'),
  ('35cdaa67-412c-59e0-a791-8502d1637dcd', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 25, 25, 'ይስሐቅም ልጁን፥ “ልጄ ሆይ! እንዲህ ፈጥነህ ያመጣህበት ምክንያት ምንድን ነው?” አለው። ያዕቆብም፥ “አምላክህ በፊቴ ያስገኘልኝን አመጣሁ” አለው።'),
  ('478447fd-492b-5361-ad18-ecb5ce85bb37', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 26, 26, 'ይስሐቅም፥ “አንተ ልጄ ዔሳው እንደ ሆንህ፥ እንዳይደለህም ቅረበኝ፤ ልዳስህ” አለው።'),
  ('d7137344-eacd-5c17-a47e-e913282f0c84', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 27, 27, 'ያዕቆብም ወደ አባቱ ወደ ይስሐቅ ቀረበ፤ ዳሰሰውም። “ቃልህስ የያዕቆብን ቃል ይመስላል፤ እጆችህ ግን የዔሳውን እጆች ይመስላሉ” አለው፤'),
  ('f4eedd0d-dd2a-5eaf-af34-847e1a5d1f3b', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 28, 28, 'ከእግዚአብሔር ታዝዞ ልቡናው ወደ ያዕቆብ የሚመለስበት ጊዜ ነውና አላወቀውም።'),
  ('926dc6f3-b3b6-5de7-aad4-61273822257d', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 29, 29, 'ይመርቀውም ዘንድ እጆቹ እንደ ዔሳው እጆች ጠጕራም ናቸውና ይስሐቅ አላወቀም።'),
  ('03d82cb1-e554-59ba-a4ab-83074ca36c83', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 30, 30, '“አንተ ልጄ ዔሳው ነህን?” አለው፤ እሱም፥ “አዎ፥ እኔ ልጅህ ዔሳው ነኝ” አለው። “ሰውነቴ ትመርቅህ ዘንድ ልጄ አድነህ ካመጣኸው አቅርብልኝ ልብላ” አለው።'),
  ('3bb09ac6-8d76-5034-a0ab-9045cbb4c9b0', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 31, 31, 'መብሉንም አቀረበለትና በላ። ወይንንም አቀረበለትና ጠጣ።'),
  ('63af8507-a623-5945-a184-1774a531468b', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 32, 32, 'አባቱ ይስሐቅም፥ “ልጄ ሆይ! ቀርበህ ሳመኝ” አለው።'),
  ('7a722fc2-ab85-5c77-a1ac-d11a9a8eda90', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 33, 33, 'ቀርቦም ሳመው። ደስ የሚያሰኝ የልብሱን መዓዛ አሸተተ። መረቀውም። እንዲህም አለ፥ “እነሆ፥ የልጄ የልብሱ መዓዛ እግዚአብሔር እንደ ባረከው እንደ መስክ መዓዛ ነው። እግዚአብሔር ይስጥህ፤ ከሰማይ ጠልና ከምድር ጠል ያብዛህ፤ ስንዴውንና ዘይቱን ያብዛልህ።'),
  ('2ccf0502-0337-5741-a6d1-4f3b30d4be0a', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 34, 34, 'አሕዛብ ይገዙልህ፤ ሕዝቡም ይስገዱልህ፤ ለወንድምህም ጌታ ሁነው፤ የእናትህም ልጆች ይስገዱልህ። እግዚአብሔር እኔን የባረከባቸው፥ አባቴ አብርሃምንም የባረከባቸው በረከቶች ሁሉ ለአንተ ይሁኑህ፤ እስከ ዘለዓለምም ድረስ ለልጆችህ ይሁኑ። የሚረግምህ የተረገመ ነው፥ የሚመርቅህም የተመረቀ ነው” አለው።'),
  ('0007e1d2-d0f1-55f0-aab0-c41a0ffb0987', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 35, 35, 'ይስሐቅ ልጁን ያዕቆብን መርቆት ከጨረሰ በኋላ እንዲህ ሆነ።'),
  ('ab3a358e-a0f5-5ba8-a06b-db3fc48543af', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 36, 36, 'ከወጣም በኋላ እንዲህ ሆነ፤ ያዕቆብም ከአባቱ ከይስሐቅ ዘንድ ወጥቶ ተሸሸገ። ወንድሙ ዔሳው ግን ከአደኑ ደረሰ፤ እርሱም መብልን አዘጋጅቶ ለአባቱ አቀረበ፤ አባቱንም፥ “አባቴ ሆይ፥ ሰውነትህ ትመርቀኝ ዘንድ አደን አድኜ ከአመጣሁልህ ተነሥ ብላ” አለው።'),
  ('1f24e39b-ef7f-5f7a-a451-db3f050452d6', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 37, 37, 'አባቱ ይስሐቅም፥ “አንተ ማን ነህ?” አለው። “እኔ የበኵር ልጅህ ዔሳው ነኝ፤ እንዳዘዝኸኝ አደረግሁ” አለው።'),
  ('b789d848-24c3-541c-a938-b5c1aa676354', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 38, 38, 'ይስሐቅም እጅግ ፈጽሞ ተደነቀ፥ “አደን አድኖ አምጥቶልኝ አንተ ሳትመጣ ከሁሉ በልች የመረቅሁት ይህ ማን ነው? የተመረቀ ይሁን፤ ዘሩም እስከ ዘለዓለም ድረስ የተመረቀ ይሁን” አለው።'),
  ('353956e6-d9ea-58be-ae7e-b8486cac6cc4', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 39, 39, 'ዔሳውም የአባቱን የይስሐቅን ነገር በሰማ ጊዜ እንዲህ ሆነ። በታላቅ ቃል እጅግ ምርር ብሎ ጮኸ፤ አባቱን፥ “አባቴ ሆይ፥ እኔንም መርቀኝ” አለው።'),
  ('5d300d56-02ab-505e-a6b8-73cb7f6d4714', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 40, 40, '“ወንድምህ በተንኰል መጥቶ በረከትህን ወሰደብህ፤” አለው።'),
  ('ab101c9a-c896-5f48-a6b4-5b196276479c', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 41, 41, '“ያዕቆብ ተብሎ በተጠራበት ስሙ እንዳሰነካከለኝ ዛሬ ዐወቅሁ። እነሆ፥ ይህ ሁለተኛው ነው። ቀድሞ ብኵርናዬን ወሰደብኝ፤ ዛሬም በረከቴን ወሰደብኝ፤ አባቴ፥ ምርቃትን አላስቀረህልኝምን?” አለ።'),
  ('e1bde305-bb90-589f-aee7-a58be9dbab09', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 42, 42, 'ይስሐቅም ለዔሳው እንዲህ ብሎ መለሰለት፥ “እነሆ፥ ለአንተ ጌታ አድርጌ ሾምሁት፤ ወንድሞቹንም ሁሉ ተገዢ ይሆኑት ዘንድ ሰጠሁት። ወይኑንና ስንዴውን፥ ዘይቱንም በማብዛት አፀናሁት። ልጄ ሆይ፥ ዛሬ ለአንተ ምን ላድርግልህ?”'),
  ('f98db6b3-938a-55dc-afc8-9155ab9429b9', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 43, 43, 'ዔሳውም አባቱ ይስሐቅን፥ “አባቴ፥ በረከትህ አንዲት ብቻ ናትን? አባቴ ሆይ፥ እኔንም ባርከኝ” አለው። ዔሳውም ቃሉን አሰምቶ አለቀሰ።'),
  ('5c67d08b-00e0-54af-a6fc-d545834f466e', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 44, 44, 'ይስሐቅም መለሰለት እንዲህም አለው፥ “እነሆ፥ ኑሮህ ከምድር ጠል፥ በላይም ከሰማይ ጠል ይሁን፥ በሰይፍህም ኑር፤ ለወንድምህ ተገዛ።'),
  ('9593d27c-b087-52c6-ab81-240c564e903c', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 45, 45, 'እምቢ ብትል ግን፥ ቀንበሩንም ከአንገትህ ብታርቅ ያንጊዜ ለሞት የሚያበቃ በደልን ሁሉ ትበድላለህ። ዘርህም ሁሉ ከሰማይ በታች ይጠፋል።”'),
  ('d30a3879-4e77-57a5-af48-84f64a27b6d6', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 46, 46, 'ዔሳውም አባቱ ስለ መረቀው ምርቃት ያዕቆብን ይጣላው ነበር። በልቡም እንዲህ አለ፥ “የአባቴ የልቅሶው ቀን አሁን ይደርሳል፤ ወንድሜ ያዕቆብን እገድለዋለሁ።” የታላቁ ልጅዋ የዔሳውም ነገር ለርብቃ በሕልም ተነገራት።'),
  ('7db6df18-8b75-57f7-abb8-1e25320f7d82', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 47, 47, 'ርብቃም ልካ ታናሹን ልጅዋን ያዕቆብን ጠራችው፤ እንዲህም አለችው፥ “እነሆ፥ ወንድምህ ዔሳው ይገድልህ ዘንድ ቂም ይዞአል፤ አሁንም፥ ልጄ ሆይ፥ ቃሌን ስማ፤ ተነሥተህ ወደ ወንድሜ ወደ ላባ ወደ ካራን ሽሽ፤ የወንድምህ ቍጣ እስኪመለስ ድረስ ጥቂት ቀን ከእርሱ ጋር ተቀመጥ። ከአንተ ቍጣውን ይተዋል፤ ያደረግኸውንም ይረሳዋል፤ እኔም ልኬ በዚያ እቀበልሃለሁ።”'),
  ('e7044b0e-d623-5ab3-a1dd-a5b6e9909096', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 48, 48, 'ያዕቆብም፥ “አልፈራም፤ ይገድለኝ ዘንድ ቢወድድም እገድለዋለሁ” አለ።'),
  ('2b24b386-77b5-556e-a28e-da8887ed204a', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 49, 49, '“ሁለታችሁን ልጆችን ሁሉ በአንዲት ቀን አጥቼ የወላድ መካን እንዳልሆን ሂድ” አለችው።'),
  ('1aa47121-aaa8-5d05-ae03-2f95cc432844', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 50, 50, 'ያዕቆብም እናቱን ርብቃን እንዲህ አላት፥ “አባቴ እንደ አረጀ እነሆ፥ አንቺ ታውቂያለሽ፤ ዐይኖቹም ፈዝዘዋልና አያይም።'),
  ('eb8322ef-d73d-50da-ad8c-23d1166b230a', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 51, 51, 'ከእናንተ ተለይቼ ትቼው ብሄድ በፊቱ ክፉ ይሆናል፤ አባቴም ተቈጥቶ ይረግመኛልና አልሄድም፤ ቢያሰናብተኝ ግን ያንጊዜ እሄዳለሁ፤” አላት።'),
  ('b5f3105e-fc78-593a-ad9f-84c2429f9e17', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 52, 52, 'ርብቃም ያዕቆብን፥ “እኔ ገብች እነግረዋለሁ፤ ያሰናብትሃልም” አለችው።'),
  ('a2bae680-3356-54fd-a84e-03b2f27d0cc2', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 53, 53, 'ርብቃም ወደ ይስሐቅ ገብታ ይስሐቅን እንዲህ አለችው፥ “ዔሳው ለእርሱ ሚስት አድርጎ ከአገባቸው ከሁለቱ ከኬጢ ልጆች የተነሣ ኑሮዬን ጠላሁ፤ ያዕቆብ እንደነዚህ ከአሉ ከሀገሪቱ ሴቶች ልጆች ለእርሱ ሚስት ከአገባ የከነዓን ሴቶች ልጆች ክፉዎች ናቸውና እንደ ምን እኖራለሁ?”'),
  ('a6eed647-b9b9-54fc-a725-75b61dda032e', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 54, 54, 'ይስሐቅም ልጁን ያዕቆብን ጠርቶ መረቀው፤ መከረውም፥ “ከከነዓን ሴቶች ልጆች ሁሉ ሚስት አታግባ፥ ተነሥተህ ወደ መስጴጦምያ ወደ እናትህ አባት ወደ ባቱኤል ቤት ሂድ፤'),
  ('c13f8ff5-f3a7-5c6e-a01f-6837bd90ff7e', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 55, 55, 'ከዚያም ከእናትህ ወንድም ከላባ ሴቶች ልጆች ሚስት አግባ። የሰማይ አምላክ ይባርክህ። ፈጽሞም ያብዛህ። የአሕዛብ ጌታ ሁን። ተሰድደህ ትኖርባት የነበረች ሀገርን፥ እግዚአብሔርም ለአብርሃም የሰጣትን ምድር ሁላ ትወርሳት ዘንድ የአባቴን የአብርሃምን በረከት ለአንተና ከአንተም በኋላ ለዘርህ ይስጥህ። ልጄ ሆይ፥ በሰላም ሂድ” አለው፥'),
  ('9cb907e4-38eb-5e2f-a17a-dc879c6a8e1e', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 56, 56, 'ይስሐቅም ያዕቆብን አሰናበተው። ወደ ያዕቆብ እናት ወደ ርብቃ ወንድም ወደ ሶርያዊው ሰው ወደ ባቱኤል ልጅ ወደ ላባ ዘንድ ወደ መስጴጦምያ ሄደ።'),
  ('9779c367-cff9-57e2-a211-9ef87874e453', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 57, 57, 'ያዕቆብ ወደ መስጴጦምያ ለመሄድ ከተነሣ በኋላ እንዲህ ሆነ። ልጅዋ ከሄደ በኋላ የርብቃ ልብዋ አዝኖ ታለቅስ ነበር።'),
  ('8a41f1ef-6209-599c-a79c-19f6b0e09fc9', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 58, 58, 'ይስሐቅም ርብቃን፥ “እኅቴ ሆይ ስለ ልጂሽ ስለ ያዕቆብ አታልቅሺ። በሰላም ሄዶ በሰላም ይመለሳልና፤ ልዑል አምላክም ከክፉ ሁሉ ይጠብቀዋልና፤ ከእርሱም ጋር ይኖራል፤ በዘመኑም ሁሉ አይለየውም፤ ወደ እኛ በሰላም እስኪመለስ ድረስ በሄደበት ሁሉ ጎዳናው እንዲቀናለት አውቃለሁና።'),
  ('7fda2f57-6396-5f01-af82-ee57f2fa3ad8', 'b277ba61-f624-54f0-adf9-c83bd23ca6eb', '8d8c88f3-39d7-5108-a60e-06f32ed0db41', 59, 59, 'በሰላም እናየዋለን፤ እኅቴ ሆይ፥ ስለ እርሱ አትፍሪ። እርሱ በመንገዱ የቀና ነውና፥ ፍጹምም ነውና፤ የታመነ ሰውም ነውና፤ አይወድቅምና አታልቅሺ” አላት። ይስሐቅም ስለ ልጅዋ ስለ ያዕቆብ ርብቃን ያረጋጋት ነበር። እርሱንም መረቀው።'),
  ('31384bf0-f5e0-50bc-ac05-db10f06d7de9', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 1, 1, 'ያዕቆብ በአርባ አራተኛው ኢዮቤልዩ በሁለተኛው ሱባዔ በመጀመሪያው ዓመት ወደ ካራን ይሄድ ዘንድ ከዐዘቅተ መሐላ ወጣ። በተራራ ወዳለች ወደ ሎዛም ደረሰ። ይህችውም ቤቴል ናት።'),
  ('9d731aca-0ccb-58ad-af5d-34db9dd5e52b', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 2, 2, 'በዚህ ሱባዔ በመጀመሪያው ወር መባቻ በመሸ ጊዜ ወደ ቦታው ደረሰ። በዚያችም ሌሊት ከመንገዱ ወደ ምዕራብ አለፍ አለ። ፀሐይ ገብቶ ነበርና በዚያ ተኛ። ከዚያ ቦታ ድንጋዮችም አንድ ድንጋይ አምጥቶ በዚያ ዛፍ ሥር አኖረው። እርሱም ብቻውን ይሄድ ነበር።'),
  ('275f5713-810d-5e23-af58-0a01fcf43c1a', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 3, 3, 'በዚያችም ሌሊት ተኝቶ ሳለ ሕልምን አየ። እነሆ፥ መሰላል በምድር ላይ ተተክላ ጫፍዋ እስከ ሰማይ ደርሶ፥ እነሆ፥ የእግዚአብሔር መላእክት ሲወጡባትና ሲወርዱባት፥ እነሆም፥ እግዚአብሔር በውስጥዋ ተቀምጦ አየ።'),
  ('f21a69d0-2311-5315-a380-8c112aa8f69d', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 4, 4, 'ከያዕቆብም ጋር ተነጋገረ። እንዲህም አለ፥ “የአባትህ የአብርሃም አምላክ የይስሐቅም አምላክ እኔ ነኝ። ይህችን አንተ የተኛህባትን ምድር ለአንተ፥ ከአንተም በኋላ ለዘርህ እሰጣታለሁ። ዘርህም እንደ ባሕር አሸዋ ይሆናል። በምዕራብና በምሥራቅ፤ በሰሜንና በደቡብ ትበዛለህ። የአሕዛብም ሀገሮች ሁሉ በአንተና በዘርህ ይባረካሉ፥'),
  ('2e609187-ccbe-53b5-a348-b9ba9d782db1', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 5, 5, 'እነሆ፥ እኔም ከአንተ ጋር እኖራለሁ፤ ሁልጊዜም እጠብቅሃለሁ። ያልሁህን ሁሉ እስካደርግልህ ድረስ አልለይህምና ከሄድህበት ወደዚህች ሀገር በሰላም እመልስሃለሁ።”'),
  ('ba4a141f-363e-5cbc-a29a-a25300167ad7', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 6, 6, 'ያዕቆብም ተኝቶ ነበር። እንዲህም አለ፥ “ይህ ቦታ በእውነት የእግዚአብሔር ቤት ነው፤ እኔ ግን አላወቅሁም ነበር” አለ'),
  ('2600e08e-b0fd-52d5-a202-e0cee649f80e', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 7, 7, 'እርሱም ፈራ እንዲህም አለ፥ “ይህ ቦታ ግሩም ነው፥ የእግዚአብሔር ቤት ነው እንጂ ምንም ተራ ቦታ አይደለም። ይህችም የሰማይ ደጃፍ ናት” አለ።'),
  ('ba8888b2-9b98-5fb9-a5b9-c4b136dee441', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 8, 8, 'ያዕቆብም ሲነጋ ገሥግሦ ተነሥቶ፥ በራስጌው ትራስ አድርጎ ያኖረውን ድንጋይ ወሰደ፤ ለምልክትም ሐውልት አድርጎ አቆመው፥ በራሱም ላይ ዘይትን አፈሰሰበት።'),
  ('819fced4-6bbe-51ff-af18-2aef3e71cdc8', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 9, 9, 'የዚያንም ቦታ ስም ቤቴል አለው። ቀድሞ ግን የሀገሩ ስም ሎዛ ነበረ።'),
  ('5c77931d-d6ca-5d7e-a6fb-0ee94be0ccda', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 10, 10, 'ያዕቆብም ለእግዚአብሔር እንዲህ ብሎ ስእለት ተሳለ፤ “እግዚአብሔር ከእኔ ጋር ቢኖር፥ እኔ በምሄድባትም በዚህች መንገድ ቢጠብቀኝ፥ እበላ ዘንድ እንጀራን ቢሰጠኝ፥ እለብስም ዘንድ ልብስን ቢሰጠኝ፥ ወደ አባቴም ቤት በሰላም ብመለስ፥ እግዚአብሔር አምላኬ ይሆነኛል።'),
  ('b7c1ba43-1603-5f40-ad0b-22808265253c', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 11, 11, 'ይህም በዚህ ቦታ ለምልክት ሐውልት አድርጌ ያቆምሁት ድንጋይ የእግዚአብሔር ቤት ይሆናል፤ ከዚህም ከሰጠኸኝ ሁሉ እኔ ለአንተ ለአምላኬ ዐሥራት እሰጣለሁ።”'),
  ('c0850b74-ff9c-577c-a7e1-855bdc073ef1', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 12, 12, 'እግሩንም አንሥቶ ወደ መስጴጦምያ ወደ ምሥራቅ ወደ ርብቃ ወንድም ወደ ላባ ተጓዘ።'),
  ('3fe45929-0e0a-522c-a6ab-f54e1ae99edf', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 13, 13, 'ከእርሱም ጋር ኖረ፤ ስለ ልጁ ስለ ራሔልም አንድ ሱባዔ ተገዛለት፤ በሦስተኛው ሱባዔ በመጀመሪያው ዓመት፥ “ስለ እርስዋ ለአንተ ሰባት ዓመት የተገዛሁላትን ሚስቴን ስጠኝ” አለው።'),
  ('0a94fb38-97d3-57a3-a6c3-862e9e8e58a7', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 14, 14, 'ላባም ያዕቆብን፥ “እኔ ሚስትህን እሰጥሃለሁ” አለው። ላባም ሰርግ አደረገ፤ ትልቂቱን ልጁን ልያን ወስዶ ለያዕቆብ ሚስት ትሆነው ዘንድ ሰጠው፤ የምታገለግላት ባሪያውን ዘለፋንም ሰጣት።'),
  ('3b7d34a2-a84c-513c-a2f0-8b1c62586f94', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 15, 15, 'ያዕቆብ ግን ራሔል መስላዋለችና አላወቀም ነበር፤ ወደ እርስዋም ገባ፤ እርስዋ ግን እነሆ ልያ ነበረች።'),
  ('7a1809f9-9fa2-545c-a466-c46b256badf8', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 16, 16, 'ያዕቆብም በላባ ተቈጣ። “የተገዛሁልህ ስለ ልያ ያይደለ፤ ስለ ራሔል አይደለምን? ለምን እንዲህ አደረግኸኝ? ለምንስ በደልኽኝ? ልጅህን ውሰድ፤ በእኔ ክፉ አድርገሃልና እኔ እሄዳለሁ” አለው።'),
  ('0b975df7-60fe-5dc4-a995-a9abce706030', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 17, 17, 'የልያ ዐይንዋ ልም ነበረና ያዕቆብ ከልያ ይልቅ ራሔልን ይወድ ነበር፤ ነገር ግን መልክዋ እጅግ መልካም ነበረ። ራሔል ግን ዐይነ መልካም ነበረች፤ መልክዋም ያማረ እጅግ ደመ ግቡ ነበረች።'),
  ('a90a6560-f505-5ff7-a0d5-4072401d70c7', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 18, 18, 'ላባም ያዕቆብን እንዲህ አለው፥ “እንዲህ አይደለም፤ በሀገራችን ታላቂቱ ሳለች ታናሽቱን መስጠት የለም። ይህንም ማድረግ አግባብ አይደለም። ታላቂቱ ሳለች ታናሽቱን ልጁን የሚሰጥ እንደሌለ በሰማይ ጽላት እንዲህ ታውቆአል፤ ተጽፎአልም፤ ታላቂቱን ልጅ አስቀድሞ ይሰጣል። ከእርስዋም በኋላ ታናሽቱን ይሰጣልና።'),
  ('5332cb45-bd49-5608-ab89-4a470a3fb174', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 19, 19, 'እንዲህ በሚያደርግም ሰው ስለ እርሱ በደልን በሰማይ ጽላት ይጽፉበታል።'),
  ('3f661d23-c721-5dc6-a50c-9693d7fc430c', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 20, 20, 'ይህ ሥራ በእግዚአብሔር ፊት ክፉ ነውና ይህን ሥራ የሚሠራ ሰው የሚጸድቅ አይደለም።'),
  ('18091229-1725-5438-a7d5-e545fc85db69', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 21, 21, 'አንተም ለእስራኤል ልጆች፦ እጅግ ክፉ ነውና ይህን ነገር እንዳያደርጉ፤ አስቀድመው ታላቂቱን ሳይሰጡ ታናሽቱን እንዳይሰጡ እዘዝ።'),
  ('f23a9d0f-c89d-5f32-ad3d-484ab5e8eb9b', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 22, 22, 'ላባም ያዕቆብን፥ “የዚህች የሰርግዋ በዓል ሰባቱ ቀን ይለፍ። ዳግመኛም ሰባት ዓመት ትገዛልኝ ዘንድ፥ በመጀመሪያው ሱባዔ እንዳደረግህ በጎችን ትጠብቅልኝ ዘንድ ራሔልን እሰጥሀለሁ” አለው።'),
  ('8290985d-3b4f-577c-a952-264cafe41e17', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 23, 23, 'የልያ ሰርግ በዓል ሰባቱ ቀን በአለፈ ጊዜ ሁለተኛ ሰባት ዓመት ይገዛለት ዘንድ ላባ ለያዕቆብ ራሔልን ሰጠው። ለራሔልም የዘለፋን እኅት ባላን አገልጋይ ትሆናት ዘንድ ሰጣት። ልያ በብላሽ ተሰጥታለችና ስለ ራሔል ዳግመኛ ሰባት ዓመት ተገዛ።'),
  ('9593cdcf-ba62-52ca-a879-91289eda0399', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 24, 24, 'እግዚአብሔርም የልያን ማኅፀን ከፈተ፤ ፀነሰች፤ ለያዕቆብም ወንድ ልጅን ወለደች፤ በሦስተኛው ሱባዔ በመጀመሪያው ዓመት በዘጠነኛው ወር በዐሥራ አራተኛው ቀን ስሙን ሮቤል አለው።'),
  ('7f71a8eb-6ce4-5589-a457-524e30f882d4', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 25, 25, 'እግዚአብሔርም ልያ እንደምትጠላ፥ ራሔል ግን እንደምትወደድ አይቶአልና የራሔል ማኅፀን ተዘጋ።'),
  ('f2d22b4a-768f-56e2-a78f-a1e3a27ae4a2', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 26, 26, 'ያዕቆብም ዳግመኛ ወደ ልያ ገባ፤ ፀነሰች፤ ሁለተኛም ወንድ ልጅን ወለደችለት፤ ስሙንም በዐሥረኛው ወር በሃያ አንደኛው ቀን ስምዖን አለው።'),
  ('8b047c54-efeb-5176-a091-d8a62b6e3014', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 27, 27, 'በዚህ ሱባዔ በሦስተኛው ዓመት ያዕቆብ ዳግመኛ ወደ ልያ ገባ፤ ፀነሰች፥ ሦስተኛ ወንድ ልጅንም ወለደችለት፤ በመጀመሪያው ወር መባቻ ስሙን ሌዊ አለው።'),
  ('907aba55-a8e6-532a-a41c-608a7276d09f', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 28, 28, 'በዚህ ሱባዔ በስድስተኛው ዓመት ያዕቆብ ዳግመኛ ወደ ልያ ገባ፤ ፀነሰች፤ አራተኛ ወንድ ልጅንም ወለደችለት፤ በአራተኛው ሱባዔ በሦስተኛው ወር በዐሥራ አምስተኛው ቀን በመጀመሪያው ዓመት ስሙን ይሁዳ አለው።'),
  ('b135dd61-4493-53ff-a184-b788e39137bd', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 29, 29, 'እርስዋ አትወልድም ነበርና በዚህ ሁሉ ራሔል በልያ ትቀና ነበር። ያዕቆብንም፥ “ልጅ ስጠኝ” አለችው።'),
  ('c5b31b83-9fbe-5dcb-ab7e-a3a8f1068b7e', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 30, 30, 'ያዕቆብም፥ “የማኅፀንሽን ፍሬ የከለከልሁሽ እኔ ነኝን? እኔ አስተውሁሽን?” አላት።'),
  ('68bd5c4d-7857-52c1-a69a-26f8d1092614', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 31, 31, 'ራሔልም ልያ ለያዕቆብ አራት ልጆች ሮቤልንና ስምዖንን፥ ሌዊንና ይሁዳን እንደ ወለደች ባየች ጊዜ፥ “ወደ ባሪያዬ ወደ ባላን ግባ፤ ትፀንሳለች፤ ወንድ ልጅንም ትወልድልኛለች” አለችው።'),
  ('b0dff9f1-b0f2-5b17-a3b4-95504f600ec3', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 32, 32, 'ያዕቆብም ወደ ባላን ገባ፤ እርስዋም ፀነሰች፤ ወንድ ልጅንም ወለደችለት፤ በሦስተኛው ሱባዔ በስድስተኛው ዓመት በስድስተኛው ወር በዘጠነኛው ቀን ስሙን ዳን አለው።'),
  ('57cf09a5-faae-585a-a94d-147d237b5559', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 33, 33, 'ያዕቆብም ዳግመኛ ወደ ባላን ገባ፤ እርስዋም ፀነሰች፤ ለያዕቆብም ዳግመኛ ወንድ ልጅን ወለደችለት። በአራተኛው ሱባዔ በሁለተኛው ዓመት በሰባተኛው ወር በአምስተኛው ቀን ራሔል ስሙን ንፍታሌም አለችው።'),
  ('0e57790a-9822-5d00-afa1-6d2d9696161e', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 34, 34, 'ልያም እንደ መከነች፥ ልጅም እንደማትወልድ በአየች ጊዜ እርስዋ በራሔል ቀናች፤ እርስዋም አገልጋይዋን ዘለፋን ለያዕቆብ ሚስት ትሆነው ዘንድ ሰጠችው። እርስዋም ጸነሰች፤ ወንድ ልጅንም ወለደችለት። በአራተኛው ሱባዔ በሦስተኛው ዓመት በስምንተኛው ወር በዐሥራ ሁለተኛው ቀን ስሙን ጋድ አለችው።'),
  ('7664620a-4f16-5c80-af30-ad659ba92a71', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 35, 35, 'ዳግመኛም ወደ እርስዋ ገባ፤ እርስዋም ፀነሰች፤ ሁለተኛ ወንድ ልጅንም ወለደችለት፤ በአራተኛው ሱባዔ በአምስተኛው ዓመት በዐሥራ አንደኛው ወር በሁለተኛው ቀን ልያ ስሙን አሴር አለችው።'),
  ('fa7833a6-aad4-5fc9-a95c-89aa596b041e', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 36, 36, 'ያዕቆብም ወደ ልያ ገባ፤ እርስዋም ፀነሰች፤ ለያዕቆብም ወንድ ልጅን ወለደችለት፤ በአራተኛው ሱባዔ በአራተኛው ዓመት በአምስተኛው ወር በአራተኛው ቀን ስሙን ይሳኮር አለችው፤ ለሞግዚትም ሰጠችው።'),
  ('cb5193e2-0906-5097-a679-aea6b4bd2912', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 37, 37, 'ያዕቆብም ዳግመኛ ወደ እርስዋ ገባ፤ ፀነሰች፤ ወንድና ሴት ሁለት ልጆችን ወለደችለት። በአርባ አራተኛው ኢዮቤልዩ በስድስተኛው ሱባዔ በሰባተኛው ዓመት በሰባተኛው ወር የወንዱን ስም ዛብሎን አለችው፤ የሴቲቱን ስም ዲና አለቻት።'),
  ('706e4090-680c-5b46-a98d-7ea8fcf41506', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 38, 38, 'እግዚአብሔርም ራሔልን ይቅር አላት፤ ማኅፀንዋም ተከፈተ፤ ፀነሰችም ወንድ ልጅንም ወለደች፤ በአራተኛው ሱባዔ በስድስተኛው ዓመት በአራተኛው ወር መባቻ ስሙን ዮሴፍ አለችው።'),
  ('9be4896e-886e-5f12-a0de-9de20c34585b', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 39, 39, 'ዮሴፍም በተወለደ ጊዜ ያዕቆብ ላባን፥ “ሚስቶችንና ልጆችን ስጠኝ፤ ወደ አባቴ ወደ ይስሐቅ ልሂድ፤ ስለ ሁለቱ ልጆችህ ለአንተ የተገዛሁላቸውን ዘመኖች ፈጽሜአለሁና ቤት እሠራለሁ፤ ወደ አባቴም ቤት እሄዳለሁ” አለው።'),
  ('f93c62d5-553e-5006-aad5-d848621a2657', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 40, 40, 'ላባም ያዕቆብን፥ “በደመወዝህ ከእኔ ጋር ተቀመጥ፤ ዳግመኛም መንጋዎችን ጠብቅልኝ፤ ደመወዝህንም ውሰድ፤” አለው።'),
  ('b34306e6-f597-50f8-af14-a3aeec1a19d1', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 41, 41, 'አመድማ፥ ዥንጕርጕር፥ ነጭ ሆኖ የተወለደው ደመወዝ ሊሆነው ከፍየሉ ጠቦትና ከበጉ ጠቦት፥ በጉን ሁሉ ደመወዝ ይሰጠው ዘንድ እርስ በርሳቸው ተዋዋሉ።'),
  ('f773d414-26e5-5c8c-aa31-d74ffea12df0', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 42, 42, 'በጎቹም ሁሉ ምልክት ያለውን ሁሉ አመድማውን፥ ዥንጕርጕሩን ይወልዱ ጀመር። ዳግመኛም በጎቹ በእነዚያ አምሳል ይወልዱ ጀመር። ምልክት ያለው ሁሉ ለያዕቆብ፥ ምልክት የሌለውም ለላባ ሆነ።'),
  ('0bd14539-de7f-5015-a4ba-f434207ed28c', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 43, 43, 'የያዕቆብም ገንዘቡ እጅግ በዛ፤ ላሙንና በጉን፥ አህያውንና ግመሉን ገዛ። ወንድ ልጅንና ሴት ልጅን ወለደ።'),
  ('b970099e-bc18-5d54-a095-f1e71e824dd4', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 44, 44, 'ላባና ልጆቹም በያዕቆብ ቀኑበት። ላባም በጎቹን ከእርሱ ሰበሰበ፤ በክፉ አስተያየትም ይመለከተው ጀመር።'),
  ('cacddc49-46fa-53aa-adbd-6326cd4754c6', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 45, 45, 'ራሔልም ዮሴፍን ከወለደች በኋላ እንዲህ ሆነ፤ ላባ በጎቹን ይሸልት ዘንድ ሄደ። የሦስት ቀን ጎዳና ያህል ከእርሱ ርቀው ነበሩ።'),
  ('3fb1f5d9-f388-5735-a9ef-fc25370b314b', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 46, 46, 'ያዕቆብም ላባ በጎቹን ይሸልት ዘንድ እንደሚሄድ አይቶ ልያንና ራሔልን ጠርቶ ከእርሱ ጋር ወደ ከነዓን ይመጡ ዘንድ ከልባቸው የሚገባ ነገር ነገራቸው። በሕልም ያየውን ሁሉ፥ ወደ አባቱም ቤት ይመለስ ዘንድ የነገረውን ሁሉ ነግሮአቸዋልና።'),
  ('6de55c58-2ecd-507d-aa61-87b53e643b97', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 47, 47, 'እነርሱም፥ “ወደምትሄድበት ቦታ ሁሉ ከአንተ ጋር እንሄዳለን” አሉት።'),
  ('5e645b20-496a-5c78-ac53-9033afbf6b5d', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 48, 48, 'ያዕቆብም የአባቱን የይስሐቅን አምላክ የአያቱን የአብርሃምን አምላክ አመሰገነው።'),
  ('6fdec52f-f2a9-5fa3-ae2a-f0a45fbc063d', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 49, 49, 'ተነሥቶም ሚስቶቹንና ልጆቹን በበቅሎ አስቀመጠ፤ ገንዘቡንም ሁሉ ያዘ። ወንዙንም ተሻግሮ ወደ ገለዓድ ምድር ደረሰ።'),
  ('e1b5af01-0f76-5f75-aa1f-0f3bd422a47e', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 50, 50, 'ያዕቆብም ለላባ አሳቡን ሰወረው፤ አልነገረውም። በአራተኛው ሱባዔ በሰባተኛው ዓመት በመጀመሪያው ወር በሃያ አንደኛው ቀን ያዕቆብ ወደ ገለዓድ ተመለሰ። ላባም በኋላው ተከተለው።'),
  ('d2edc44d-a4b6-5cfd-a27f-19024111b462', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 51, 51, 'በሦስተኛው ወር በዐሥራ ሦስተኛው ቀን ያዕቆብን በገለዓድ ተራራ አገኘው። በሕልም ሌሊት ተናግሮታልና ላባ በያዕቆብ ላይ ክፉ ነገርን ያደርግ ዘንድ እግዚአብሔር አላሰናበተውም፤ ላባም ለያዕቆብ ነገረው።'),
  ('31b77772-7cfe-5f86-a652-48ff0b34ff68', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 52, 52, 'በዚያም ወር በዐሥራ አምስተኛው ቀን ያዕቆብ ለላባ፥ ከእርሱም ጋር ለመጡ ሰዎች ሁሉ ፍሪዳ አረደ።'),
  ('3268b92f-c87f-5665-afd3-b22942d4a68a', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 53, 53, 'አንዱም አንዱን በተንኰል እንዳይፈልገው በዚያች ቀን በገለዓድ ተራራ ያዕቆብ ለላባ ማለለት፤ ላባም ለያዕቆብ ማለለት። በዚያም ምስክር ይሆን ዘንድ ኮረብታን ሠራ፤ ስለዚህም የዚያ ቦታ ስም “ፍስሐተ ስምዕ” ተባለ፤'),
  ('9fe10b71-0449-502e-a472-2c1cd2ea7e31', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 54, 54, 'ቀድሞ የገለዓድ ምድር የራፋኢም ምድር ተብሎ ይጠራ ነበር፤ የራፋኢም ምድር ነበረና። ቁመታቸው ዐሥር ክንድ፥ ዘጠኝ ክንድም፥ ሰባት ክንድም፥ ስምንት ክንድም የሚሆኑ የራፋኢም ልጆች ተወለዱ። መኖሪያቸውም ከአሞን ልጆች ሀገር ጀምሮ እስከ ኤርሞን ተራራ ድረስ ነበር።'),
  ('7e660b9b-fdcc-5970-a2eb-35755e4f6488', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 55, 55, 'የመንግሥታቸውም ከተማ ቆሬናኤምና አስጣሮስ፥ አድራኦና ሜሱር፥ ቢዖንም ነበሩ። እነርሱ እጅግ ክፉዎች ነበሩና ከክፉ ሥራቸው የተነሣ እግዚአብሔር አጠፋቸው።'),
  ('eb5d01cb-98db-51fc-a94f-a239bfbde9fb', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 56, 56, 'ስለ እነርሱ ፋንታ ክፉ ኀጢአተኛ የሚሆን አሞሬዎን በሀገራቸው ኖረ። ዛሬ የእነርሱን ኀጢአት ሁሉ የፈጸመ ሰው የለም። ከዚህም በኋላ በምድር የዘመን ብዛት የላቸውም።'),
  ('0e78a266-8bea-56d3-aea3-d8ff9cf42a37', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 57, 57, 'ያዕቆብም ላባን አሰናበተው፤ ወደ ምሥራቅ ምድር መስጴጦምያ ሄደ። ያዕቆብም ወደ ገለዓድ ምድር ተመለሰ። በዘጠነኛው ወር ከወሩም በዐሥራ አንደኛው ቀን ኢያቦቅን ተሻገረ። በዚያም ቀን ወንድሙ ዔሳው ወደ እርሱ ደረሰና ተወቃቀሱ።'),
  ('0b0359c8-6076-5aa3-a4ae-dd65d3346ae0', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 58, 58, 'ከእርሱም ተለይቶ ወደ ሰዒር ምድር ሄደ። ያዕቆብ ግን በድንኳን አደረ።'),
  ('dd92f7fa-2529-5ae0-a924-16341653126c', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 59, 59, 'በዚህ ኢዮቤልዩ በአምስተኛው ሱባዔ በመጀመሪያው ዓመት ዮርዳኖስን ተሻግሮ በዮርዳኖስ ማዶ አደረ። በኮረብታው አጠገብ ከአለ ባሕር ጀምሮ እስከ ዶታንና እስከ ቤተ ሶን ድረስ፥ እስከ ዖመ አቅራቢትም ድረስ በጎቹን ያሰማራ ነበር። ለአባቱ ለይስሐቅም ከገንዘቡ ልብሱንና ምግቡን፥ ሥጋውንና መጠጡን፥ ወተቱንና ቅቤውን፥ ዳቦውንም፥ ከቆላውም ተምር ሁሉ ይሰድ ነበር።'),
  ('3fac5769-6d89-593f-a7d2-11c92073638c', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 60, 60, 'ለእናቱ ለርብቃም በዐሥራ ሁለቱ ወር ጊዜዎች መካከል፥ በዘርና በአዝመራ መካከል፥ በበልግና በመከር፥ በክረምትና በበጋ መካከል በዓመት አራት ጊዜ ወደ አብርሃም ድንኳን ይልክላት ነበር።'),
  ('53d1ef7f-2cc2-51fa-abc0-5eab4577f17a', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 61, 61, 'ይስሐቅም ከዐዘቅተ መሐላ ተመልሶ ወደ አባቱ ወደ አብርሃም ድንኳን ወጥቶ ነበረና፤ ከልጁ ከዔሳው ተለይቶ በዚያ ኖረ።'),
  ('9a79b96e-08d2-5a44-a2e5-baf78a4dd536', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 62, 62, 'ያዕቆብም ወደ መስጴጦምያ በሄደ ጊዜ ዔሳው ማአሊትን ሚስት አድርጎ አገባ። ይህችውም የይስማኤል ልጅ ናት። የአባቱን መንጋዎች ሁሉና ሚስቶቹንም ሰበሰበ።'),
  ('bd5c8ef5-22e5-510a-a0ac-2bb5568c863c', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 63, 63, 'ወጥቶም በሴይር ተራራ ኖረ። አባቱን ይስሐቅንም በዐዘቅተ መሐላ ብቻውን ተወው።'),
  ('ce0c11bd-7c2f-531d-a222-90b7deaa23dc', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 64, 64, 'ይስሐቅም ከዐዘቅተ መሐላ ወጥቶ በኬብሮን ተራራ በአባቱ በአብርሃም ግንብ ኖረ።'),
  ('3e7e8f47-a1ca-5d88-a93f-6e485f941518', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 65, 65, 'ከዚያም ያዕቆብ ለእናቱና ለአባቱ ሁሉን ይሰድ የነበረውን በየጊዜውም የፈለጉትን ሁሉ ይልክ ነበር።'),
  ('eff9e7fa-3bfb-533e-a36a-0841fc8b4bea', '331ac20c-40a5-521d-ae96-0a8ec09f1bc3', 'bc5674c4-9288-50f7-a7d3-263108c4c8da', 66, 66, 'ያዕቆብንም በፍጹም ልቡናቸው፥ በፍጹም ነፍሳቸውም ይመርቁት ነበር። በስድስተኛው ሱባዔ በመጀመሪያው ዓመት ወደ ሰቂማ ምሥራቅ ወደ ሳሌም በአራተኛው ወር በሰላም ወጣ።'),
  ('d0c21f03-d0a3-5bfb-a980-0b444a072f6d', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 1, 1, 'በዚያም የያዕቆብን ልጅ ዲናን ወደ ሀገሩ ገዥ ወደ ኤውያዊው ሰው ወደ ኤሞር ልጅ ወደ ሴኬም ቤት ነጥቀው ወሰዱአት። ከእርስዋም ጋር ተኛ፤ አስነወራትም፤ እርስዋም የዐሥራ ሁለት ዓመት ትንሽ ልጅ ነበረች። ሚስትም ሆና ትሰጠው ዘንድ ከአባቷና ከወንድሞችዋ ማለደ።'),
  ('af71ff88-e5b0-50ff-acef-87ef0d703ea1', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 2, 2, 'ያዕቆብም ተቈጣ። እኅታቸውንም ዲናን አስነውረዋታልና ልጆቹ በሰቂማ ሰዎች ተቈጡ፤ ከእነርሱም ጋር በተንኰል ተናገሩ፤ አታልለውም በዘበዙአቸው።'),
  ('db9be231-e5ee-5516-af50-7255f62b86aa', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 3, 3, 'ስምዖንና ሌዊ ድንገት ወደ ሰቂማ ገብተው በሰቂማ ሰዎች ሁሉ ቅጣትን አደረጉ።'),
  ('d93b0107-c35e-5c21-a97f-624fbdf969d9', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 4, 4, 'በውስጥዋም ያገኙትን ሰው ሁሉ ገደሉ። አንድ ሰው ስንኳን አላስቀሩም። ቈስለውም ሳሉ ሁሉን ገደሉ፤ እኅታቸውን ዲናን አስነውረዋልና።'),
  ('d969b65b-acb7-56aa-a1ed-3b3f8f36b139', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 5, 5, 'ከእንግዲህ ወዲህ ከዛሬ ጀምሮ የእስራኤልን ልጅ ለማስነወር እንዲህ አታድርጉ። በእስራኤል ኀፍረትን ስለአደረጉ የሰቂማን ሰዎች ሁሉ በሰይፍ ያጠፏቸው ዘንድ በሰማይ ጽላት በእነርሱ ቅጣት ተጽፎአልና።'),
  ('c15e30f6-07c7-5567-ac39-6b4e91f11883', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 6, 6, 'በሰይፍ ያጠፉአቸው ዘንድ፥ በእነርሱም ላይ ቅጣትን ያደርጉ ዘንድ፥ የእስራኤልን ድንግል ማስነወር በእስራኤል ዘንድ ከእንግዲህ ወዲህ እንዲህ እንዳይደረግ እግዚአብሔር በያዕቆብ ልጆች እጅ ጣላቸው።'),
  ('f5eac7aa-782c-5341-ae11-9851f5fd2539', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 7, 7, 'በእስራኤል ዘንድ ልጁንም ቢሆን፥ እኅቱንም ቢሆን ከአሕዛብ ልጆች ለተወለደ ሰው ሁሉ ይሰጥ ዘንድ የወደደ ሰው ቢኖር፥ ሞትን ይሙት። ኀጢአትን ሠርቶአልና፥ በእስራኤልም ዘንድ ኀፍረትን አድርጎአልና በድንጋይ ደብድበው ይግደሉት።'),
  ('570e5e50-5232-5b72-a961-ead483b0b0e3', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 8, 8, 'ሴቲቱንም የአባቷን ወገን ስም አስነቅፋለችና በእሳት ያቃጥሏት፤ ከእስራኤልም ተለይታ ትጥፋ። እስራኤል ለእግዚአብሔር የተቀደሰ ነውና በምድር ትውልድ ዘመን ሁሉ በእስራኤል ዘንድ ሴሰኛ ኀጢአተኛም አይገኝ።'),
  ('bbfce58b-117c-5464-a755-951fe0b1771d', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 9, 9, 'ነውር የሠራ ሰው ሁሉ ሞትን ይሙት፤ በድንጋይም ይደብድቡት። ስለ እስራኤልም ልጆች ሁሉ በሰማይ ጽላት እንዲህ ተሠርቶአል፤ ተጽፎአልምና የእስራኤልን ልጅ የሚያስነውር ሁሉ ሞትን ይሙት፤ በድንጋይም ይደብድቡት።'),
  ('c4a68793-c990-59aa-a5c0-6eaf09951b5c', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 10, 10, 'ለዚህም ሕግ የተወሰነ ዘመን የለውም፤ የሚተውበትም የለም። ልጁን ለጣዖት ሰጥቶአልና፥ ራሱንም ለማሳደፍ እግዚአብሔርን በድሎአልና በእስራኤል ሁሉ ዘንድ ልጁን ያስነወረ ሰው ይጠፋል እንጂ ይቅር የሚባልበት የለም።'),
  ('4c1bbc80-1d3f-5d7b-a8d5-ae542daf63fe', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 11, 11, 'አንተም ሙሴ! የእስራኤልን ልጆች እዘዛቸው። ከልጆቻቸውም ለአሕዛብ እንዳያጋቡ፥ ከአሕዛብም ልጆች እንዳያገቡ በእነርሱ ላይ አዳኝባቸው፤ በእግዚአብሔር ፊት የተናቀ ነውና።'),
  ('8c49ecf6-16ef-5c2d-af61-a5da5cfd4416', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 12, 12, 'ስለዚህ ነገር የሕጉን ነገር፥ በዲና ላይ ያደረጉትን የሰቂማን ሰዎች ሥራ ሁሉ፥ የያዕቆብም ልጆች፥ “ለእኛ ስድባችን ነውና እኅታችንን ላልተገረዘ ሰው አንሰጥም” ብለው እንደ ተናገሩ ጻፍሁልህ።'),
  ('4382e5b1-a443-5aab-a149-7a424681259b', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 13, 13, 'ልጃቸውን ለአሕዛብ ልጆች ለሚሰጡ፥ ከአሕዛብም ልጆች ሚስትን ለሚያገቡ ለእስራኤል ስድብ ነውና፥ ርኩስም ነውና፥ ለእስራኤልም የተናቀ ነውና።'),
  ('0bdeacde-8b61-5f5f-af07-4ee53a87d4fa', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 14, 14, 'ከአሕዛብም ልጆች ሚስት ያለው፥ ከልጆቹም ከአሕዛብ ወገን ለተወለደ ሰው የሰጠ እስራኤል ከዚህ ኀጢአት አይነጻም። በመቅሠፍት ላይ መቅሠፍት፥ በመርገም ላይ መርገም፥ ቅጣትም፥ መቅሠፍትም፥ መርገምም ሁሉ ይመጣባታልና።'),
  ('c730ac6b-bf17-5806-af97-2cd1ee1a7aa6', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 15, 15, 'ይህንም ነገር ቢያደርግ ኀጢአት ከሚሠሩ ከእነዚህ ወገኖች በዐይኖቹ አይቶ ቸል ቢል፥ የእግዚአብሔርንም ማደሪያ ከሚያጐሳቍሉ፥ የከበረ ስሙንም ከሚያሳድፉ ወገን አይቶ ቸል ቢል፥ ስለዚች ኀጢአትና ስለዚች ሁሉ በደል ሕዝቡ ሁሉ በአንድነት ይጠፋሉ።'),
  ('4d10ddd0-9b0e-5659-a8b1-11e015620d25', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 16, 16, 'ፊት መመለስ የለም። ፊት አይቶ ማድላት የለም። በጎ መዓዛ አድርጎ ይቀበለው ዘንድ መሥዋዕቱንና ቀዳምያቱን፥ ስቡንና የሚጤሰውን ከእጁ መቀበል የለም።'),
  ('e85fa340-850f-5877-a4e7-18ac729e808d', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 17, 17, 'ወንድም ቢሆን፥ ሴትም ብትሆን፥ በእስራኤል ዘንድ ሰውነቱን በኀጢአት የሚያሳድፍ አይሁን። ስለዚህ ነገር ይህችን ምስክር በእስራኤል አሰማባቸው ብዬ አዘዝሁህ።'),
  ('3454767c-ddf0-594d-afcd-a00048f31ed7', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 18, 18, 'በሰቂማና በልጆችዋ የተደረገውን፥ በሁለቱ በያዕቆብ ልጆች ለጥፋት እንደ ተሰጠች፥ ታመው ሳሉ እንዳጠፉአቸው፥ ጽድቅ ሆኖ እንደ ተቈጠረላቸው እይ።'),
  ('52acebc0-0567-5e33-aca0-678e221ed53a', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 19, 19, 'እነርሱም ለጽድቅ እንደ ተቈጠሩ የሌዊም ልጅ ለክህነት እንደ ተመረጠ፥ እኛ በዘመኑ ሁሉ እንዳገለገልን፥ ሌዋውያንም በእግዚአብሔር ፊት ያገለግሉ ዘንድ እንደ ተመረጡ እይ። እውነት ነገርን ይሠራ ዘንድ፥ ፍርድንም ይፈርድ ዘንድ፥ በእስራኤል ላይ በጠላትነት ከሚነሡ ብድራትን ይመልስ ዘንድ ቀንቶአልና ሌዊ ይባረክ፤ ልጆቹ ለዘለዓለም ይባረኩ።'),
  ('de42b0eb-d57f-52d3-aaa8-e4f83c6a3c23', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 20, 20, 'በሰማይ ጽላት ምስክር ሊሆን ወደ ሁሉ አምላክ ጽድቅንና በረከትን እንዲህ ያቀርቡለታል። ሰው በሕይወት ሳለ የሠራውን ጽድቅ እናስባለን። በዓመት በዓመት በሚመላለሱ ጊዜያት ሁሉ እስከ ሺህ ትውልድ ድረስ ያቀርባሉ። በረከት ይመጣለታል፥ ከእርሱም በኋላ ለልጆቹ።'),
  ('09b92b26-6db8-546e-ae15-de9519879755', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 21, 21, 'በሰማይ ጽላት የእግዚአብሔር ወዳጅ ደግ ሰውም ተብሎ ተጻፈ። ይህን ሁሉ ነገር ጻፍሁልህ። ኀጢአት እንዳይሠሩ፥ ከሥርዐትም እንዳይተላለፉ፥ ይሠሩአት ዘንድ፥ ይጽፉአትም ዘንድ፥ የእግዚአብሔር ወዳጆችን ሁነው ይጽፉ ዘንድ፥ የተሠራላቸውን ቃል ኪዳን እንዳያፈርሱ ለእስራኤል ልጆች ትነግር ዘንድ አዘዝሁህ።'),
  ('2f0523db-a0b7-5062-abbf-d6a4fe13fc6f', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 22, 22, 'ቃል ኪዳኑንም ቢያፈርሱ፥ ከኀጢአት ሥራ ወገንም ሁሉ ቢሠሩ ግን ጠላቶች ሆነው በሰማይ ጽላት ይጻፋሉ፤ ከሕያዋንም መጽሐፍ ይደመሰሳሉ፤ የሚጠፉ ሰዎች በሚጻፉበትም መጽሐፍ ይጻፋሉ። ከምድር ላይ ከሚጠፉ ሰዎችም ጋር ይቈጠራሉ።'),
  ('f39f7a4f-9970-50b8-a069-07d13cfbe808', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 23, 23, 'የያዕቆብም ልጆች ሰቂማን ባጠፉበት ቀን ጽድቅንና የቀና ሥራን እንደ ሠሩ፥ በኀጢአተኞችም ብድርን እንደ መለሱ በሰማይ ጽላት ተጻፈላቸው። ለበረከትም ተጻፉ።'),
  ('d3c9e0ad-c5f7-5cad-a7dd-e8ce13f8999e', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 24, 24, 'እኅታቸውን ዲናንም ከሴኬም ቤት አወጡ። በሰቂማ ያለውንም ሁሉ፥ በጎቻቸውንም፥ ላሞቻቸውንም፥ አህዮቻቸውንም፥ ገንዘባቸውንም ሁሉ፥ መንጋቸውንም ሁሉ ማረኩ። ሁሉንም ወደ አባታቸው ወደ ያዕቆብ አመጡ።'),
  ('b0a45632-685a-5572-a477-3c2aca19d5c5', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 25, 25, 'በዚያ ከሚኖሩ ከከነዓናውያንና ከፍሪዛውያን የተነሣ ፈርቶአልና ሀገሩን ስላጠፉ ከእነርሱ ጋር ተነጋገረ።'),
  ('341f1db1-b288-5c8c-aa1a-be177aa3dc50', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 26, 26, 'በሰቂማ ዙሪያ ባሉ ሀገሮች ሁሉ የእግዚአብሔር መፈራት ሆነ። በእነርሱ ድንጋጤ ወድቆባቸዋልና የያዕቆብን ልጆች ለማሳደድ አልተነሡም።'),
  ('505c80fe-4901-5ad1-a4b9-0c1a4099f0d8', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 27, 27, 'በወሩ መባቻ ያዕቆብ ለቤተ ሰቡ ሁሉ፥ “ከኀጢአት ንጹሓን ሁኑ፤ ልብሳችሁንም ለውጡ” ብሎ ተናገረ።'),
  ('b06af994-6a82-5fd5-a804-fc771693c269', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 28, 28, '“ከወንድሜ ከዔሳው ፊት በሸሸሁ ጊዜ ከእኔ ጋር ላለ፥ ወደዚህችም ሀገር በሰላም ለመለሰኝ ለእግዚአብሔር ወደ ጸለይሁበት ወደ ቤቴል ተነሥተን እንውጣ።'),
  ('9ac4803a-8e48-503c-ad56-37786710815c', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 29, 29, 'በመካከላችሁም ያሉትን እንግዶች አማልክት አርቁ። ልዩ የሆኑ አማልክትንም አጥፉአቸው፤ በጆሮአችሁ ያለውንም፥ በአንገታችሁም ያለውን ጌጥ አስወግዱ።”'),
  ('745035b4-0caf-5648-a3ad-46d29b9abe0c', '54bb72d4-d103-5d1a-a655-19aa4212ce4e', 'b5d32c98-fab7-560d-a986-328a981b53c0', 30, 30, 'ራሔል ከአባቷ ከላባ የሰረቀችውን ጣዖት፥ ገንዘብዋንም ሁሉ ለያዕቆብ ሰጠች። እርሱም አቃጠለው፤ ሰበረውም፤ አጠፋውም፤ በሰቂሞን ሀገር ባለ በዮርዳኖስም በታች ቀበረው።'),
  ('96f87132-6fb0-5e97-a7d1-62570e2afaab', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 1, 1, 'በሰባተኛውም ወር መባቻ ወደ ቤቴል ወጣ። በዚያ በተኛበትም ቦታ መሠዊያ ሠራ። በዚያም ሐውልት አቆመ።'),
  ('cb199da0-37bf-5042-a7b4-17f1213d8f89', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 2, 2, 'ወደ እርሱ፥ ወደ መሥዋዕቱም ይመጣ ዘንድ ያዕቆብ ወደ አባቱ ወደ ይስሐቅ ላከ፤ ወደ እናቱ ወደ ርብቃም ላከ።'),
  ('9cafd876-8758-5800-a23e-a6adb7ba9d6a', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 3, 3, 'ይስሐቅም፥ “ልጄ ያዕቆብ ወደ እኔ ይምጣ፤ ሳልሞትም ልየው” አለ።'),
  ('72e81b28-f634-5706-ad06-c7de156ca2f3', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 4, 4, 'ያዕቆብም ወደ አባቱ ይስሐቅና ወደ እናቱ ወደ ርብቃ ወደ አባቱ ወደ አብርሃም ቤት ሄደ።'),
  ('c705d473-4de7-5aa2-a7b8-1a8b37b85c33', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 5, 5, 'ከልጆቹም ሁለቱን ልጆች ይሁዳንና ሌዊን ከእርሱ ጋር ይዞ ወደ አባቱ ወደ ይስሐቅና ወደ እናቱ ወደ ርብቃ መጣ።'),
  ('18c7c56e-4029-5244-ae95-f76efc940545', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 6, 6, 'ርብቃም፥ “እነሆ፥ ልጅሽ ያዕቆብ ደረሰ” እንደ አሉአት በሰማች ጊዜ ልቡናዋን ደስ ብሎአታልና ያዕቆብን አቅፋ ትስመው ዘንድ ከአንዱ ግንብ ወደ ሌላው ግንብ በር ወጣች።'),
  ('c693e43e-fe83-5eaf-a2e9-df2dc4508967', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 7, 7, 'ሳመችው፤ ሁለቱንም ልጆቹን ባየች ጊዜ ዐወቀቻቸው። “ልጄ ሆይ፥ እነዚህስ ልጆችህ ናቸውን?” አለችው፤ አቅፋም ሳመቻቸው። እንዲህም ብላ መረቀቻቸው፥ “የአብርሃም ዘር በእናንተ ይክበር፤ እናንተም በምድር ላይ ለበረከት ትሆናላችሁ።”'),
  ('1d71b864-1183-5e9c-ab85-de965f8099dc', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 8, 8, 'ያዕቆብም አባቱ ይስሐቅ ወደ ተኛበት እልፍኝ ገባ። ሁለቱም ልጆቹ ከእርሱ ጋር ገቡ።'),
  ('681cc7b9-d9ba-595a-ac2d-c69cc049dd4c', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 9, 9, 'የአባቱን እጅ ይዞ ዘንበል ብሎ ሳመው። ይስሐቅም በልጁ በያዕቆብ አንገት ላይ ተጠምጥሞ አንገቱን እቅፍ አድርጎ አለቀሰ። የይስሐቅንም ዐይኖች ሸፍኖአቸው የነበረው ተገፈፈ።'),
  ('e01b7179-bc1b-5f12-a0c9-f6eadc6e0848', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 10, 10, 'የያዕቆብን ሁለቱን ልጆቹን ይሁዳንና ሌዊን አይቶ፦ እንዲህ አለ፥ “ልጄ ሆይ፥ ይመስሉሃልና እነዚህ ልጆችህ ናቸውን?” እርሱም በእውነት ልጆቹ እንደ ሆኑ ነገረው፤ “በእውነት ልጆች እንደ ሆኑ በእውነት አየህ” አለው።'),
  ('b5568955-e343-5738-a83b-fcffde20f359', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 11, 11, 'ወደ እርሱም ቀረቡ፤ መለስ ብሎም ሁሉን በአንድነት አቅፎ ሳማቸው፤ ትንቢት የሚያናግር መንፈስ ቅዱስ በአፉ አናገረው። ሌዊንም በቀኝ እጁ ያዘው፤ ይሁዳንም በግራ እጁ ያዘ።'),
  ('e1afed7f-9574-5f92-a15b-b711b8dda35c', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 12, 12, 'በመጀመሪያ ወደ ሌዊ ተመልሶ አስቀድሞ ይመርቀው ጀመር። እንዲህም አለው፥ “እርሱ እግዚአብሔር ይባርክህ፥ የዓለማት ሁሉ ጌታ አንተንና ልጆችህን በዓለሙ ሁሉ ያክብር፤ ክብር ሊሆንህ እግዚአብሔር ለአንተ ገናናነትን ይስጥህ፤ ለልጆችህም ይስጣቸው።'),
  ('d8d9bc08-db65-5b90-a46d-f70fa0fb4851', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 13, 13, 'አንተን ወደ እርሱ ያቅርብህ፤ በቤተ መቅደስም ያገለግሉት ዘንድ ከሰው ሁሉ ለይቶ ልጆችህን ወደ እርሱ ያቅርባቸው፤ እንደ መላእክተ ገጽና እንደ ቅዱሳንም እንደ እነርሱ ልጆችህ ለክብር፥ ለጌትነትና ለምስጋና ይሁኑ፤ በዓለሙ ሁሉ ከፍ ከፍ ያድርጋቸው፤ ለያዕቆብም ልጆች ወገኖች ሁሉ መሳፍንትና መኳንንት፥ አለቆችም ይሆናሉ።'),
  ('8a4961e5-439a-50c2-ace7-f4c848d00504', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 14, 14, 'የእግዚአብሔርንም ቃል በእውነት ይናገራሉ፤ ፍርዱንም ሁሉ በእውነት ይፈርዳሉ፤ ለያዕቆብ መንገዶችን፥ ለእስራኤልም ፍለጋዬን ይናገራሉ፤ የተወዳጁን ዘር ሁሉ ይመርቁ ዘንድ የእግዚአብሔር በረከት በአፋቸው ይነገራል።'),
  ('4ff6957b-ae3d-51e3-ade6-285b62ebda7e', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 15, 15, '“አንተንም እናትህ ስምህን ሌዊ ብላ ጠራች። ስምህንም በእውነት ጠራች፤ ከእግዚአብሔር ጋር አንድ ትሆናለህ፤ ከያዕቆብ ልጆች ሁሉ ጋር አንድ ትሆናለህ፤ ማዕዱ ለአንተ ትሁን።'),
  ('27167cec-895d-5e3a-ab07-be7228cd7ae1', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 16, 16, 'አንተና ልጆችህ ብሉአት፤ ማዕድህም ለልጅ ልጅ ሁሉ የመላች ትሁን፤ በዓለሙ ሁሉ እህልህ አይጕደል፤ የሚጠሉህም ሰዎች ሁሉ በፊትህ ይውደቁ፤ ጠላቶችህ ሁሉ ፈጽመው ይጥፉ፤ የሚባርክህ የተባረከ ይሁን፤ የሚረግሙህም ሕዝብ ሁሉ የተረገሙ ይሁኑ።”'),
  ('5c489aef-65a9-5aeb-ad03-36a07d3613dc', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 17, 17, 'ይሁዳንም እንዲህ አለው፥ “የሚጠሉህን ሰዎች ሁሉ ታጠፋቸው ዘንድ እግዚአብሔር ኀይልንና ጽናትን ይስጥህ፤ አንተ ገዥ ሁን፤ ከልጆችህም አንዱ ለያዕቆብ ልጆች ገዥ ይሁን፤ ስምህና የልጆችህ ስም በሀገሩና በከተማው ሁሉ ሲጠራ የሚኖር ይሁን።'),
  ('364df04a-253c-5747-a335-f0faba5a7545', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 18, 18, 'ያንጊዜ አሕዛብ ከፊትህ የተነሣ ይፈራሉ፤ አሕዛብም ሁሉ ይታወካሉ፤ ሕዝቡም ሁሉ ይሸበራሉ፤ የያዕቆብ ረድኤት በአንተ ይደር፤ የእስራኤልም ድኅነት በአንተ ትገኛለች።'),
  ('3606d37a-3459-5d16-a624-339bbdd7644d', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 19, 19, 'እውነተኛ ክብር በአለው ዙፋንም በተቀመጥህ ጊዜ ለተወዳጁ ልጆች ዘር ታላቅ ሰላም ይሆናል፤ የሚመርቅህ ሰው የተመረቀ ነው፤ የሚጠሉህና መከራንም የሚያጸኑብህ፥ የሚረግሙህም ሁሉ ከምድር ፈጽመው ይጥፉ፤ የተረገሙም ይሁኑ።”'),
  ('064da46c-cdc1-5360-a3bd-e0508324e765', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 20, 20, 'ዳግመኛ ተመልሶ እቅፍ አድርጎ ሳመው፤ በእውነት የወለዳቸውን የልጁ የያዕቆብን ልጆች አይቶአልና ፈጽሞ ደስ አለው።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('466746f2-8ac9-5e0a-a228-4f026532e7ae', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 21, 21, 'ከእግሮቹ መካከል ወጥቶ በግንባሩ ወድቆ ሰገደለት፥ ባረካቸው፤ በአባቱ በይስሐቅም አጠገብ ተቀመጠ፤ በዚያችም ሌሊት ደስ ብሎአቸው በሉ፥ ጠጡም።'),
  ('37b09b39-e158-5337-aa44-43ebe6555feb', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 22, 22, 'ሁለቱንም የያዕቆብን ልጆች አንዱን በቀኙ፥ አንዱንም በግራው አቆመ፤ ይህም ጽድቅ ሆኖ ተቈጠረለት።'),
  ('157e4a6a-9fa1-57da-aca6-c13be4c3228c', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 23, 23, 'ያዕቆብም እግዚአብሔር ለእርሱ ብዙ ይቅርታ እንደ አደረገ፥ ጎዳናውን ሁሉ እንዳቀናለት፥ ከክፉም ነገር ሁሉ እንደ ጠበቀው ሌሊት ለአባቱ ሁሉን ነገረው።'),
  ('6aff3fb7-6d5e-56b0-a1a7-192de65af34d', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 24, 24, 'ይስሐቅም ከባሪያው ከይስሐቅ ልጅ ቸርነቱንና ይቅርታውን ያላራቀ የአባቱን የአብርሃምን አምላክ አመሰገነው።'),
  ('9f634443-4171-5bf4-a414-cef04fe9c564', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 25, 25, 'ያዕቆብም ሲነጋ ለአባቱ ለይስሐቅ ለእግዚአብሔር የተሳለውን ስእለት፥ ያየውንም ራእይ፥ መሠዊያውንም እንደ ሠራ፥ በእግዚአብሔርም ፊት እንደ ለመነው ለማድረግ፥ ለመሥዋዕት የሚሆነውም ሁሉ እንደ ተዘጋጀ፥ በበቅሎውም አስቀምጦ ይወስደው ዘንድ እንደ መጣ ነገረው።'),
  ('a4b67d89-040c-5507-a7e7-44cf5a6386ae', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 26, 26, 'ይስሐቅም ልጁን ያዕቆብን እንዲህ አለው፥ “አርጅቻለሁና ከአንተ ጋር መምጣት አልችልም፤ ጎዳናውንም መታገሥ አልችልም፤ ልጄ ሆይ፥ በሰላም ሂድ፥ እኔ አሁን የመቶ ስድሳ አምስት ዓመት ሰው ነኝና እንግዲህ ወዲህ መሄድ አልችልም።'),
  ('e3803906-cd4f-5814-a743-4f3707523d07', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 27, 27, 'እናትህን በበቅሎ አስቀምጠህ ከአንተ ጋር ይዘሃት ሂድ፤ ልጄ ሆይ፥ ስለ እኔ እንደ መጣህ አውቃለሁ፤ በሕይወትህ ሳለህ እኔን ያየህባት፥ እኔም በሕይወት ሳለሁ አንተን ያየሁባት ይህች ቀን የተባረከች ትሁን።'),
  ('d6f14257-ab36-508e-ae9d-8089802d1eaf', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 28, 28, 'ልጄ ሆይ፥ ተዘጋጅተህ የተሳልኸውን ስእለትህን ስጥ፤ ስእለት ቢያስቀሩት በፍዳ ይመረምራልና ስእለትህን አታዘግይ።'),
  ('07c445e4-3f50-5a10-adef-4c9456490c6b', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 29, 29, 'አሁንም ታደርጋት ዘንድ ቸኩል፤ ሁሉን የፈጠረ እግዚአብሔር የተሳልኸውን ስእለት ወድዶ ይቀበልህ።”'),
  ('581b69f2-5b50-527b-ad9d-efe171568bf1', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 30, 30, 'ርብቃንም፥ “ከልጅሽ ከያዕቆብ ጋር ሂጂ” አላት። ርብቃም ከልጅዋ ከያዕቆብ ጋር ሄደች፤ ዲቦራም ከእርስዋ ጋር ሄደች፤ ወደ ቤቴልም ደረሱ።'),
  ('e7d15202-a86d-53c5-a416-8f2381b49721', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 31, 31, 'ያዕቆብም ስእለቱን፥ አባቱ ይስሐቅም ከሁለቱ ልጆቹ ከይሁዳና ከሌዊ ጋር የመረቀውን ምርቃት አስቦ ደስ ብሎት የአባቶቹን የይስሐቅንና የአብርሃምን አምላክ አመሰገነው።'),
  ('0c700a72-c363-5ca9-abe6-b34e43f595da', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 32, 32, '“አሁንም በሁሉ አምላክ ፊት ለዘለዓለም ተስፋ እንዳለኝ፥ ለልጆችም ተስፋ እንዳላቸው ዐወቅሁ” አለ።'),
  ('635223a6-4f55-5f39-abc6-dce8a070c3a4', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 33, 33, 'ስለ ሁለቱ ሁሉ እንደዚህ ሠርቶአል። ይስሐቅ እንደ መረቃቸው ለዘለዓለም ምስክር ሊሆን በሰማይ ጽላት ይጽፉላቸዋል፤ በዚያችም ሌሊት በቤቴል አደረ።'),
  ('8902353c-05fc-554e-a134-b0d3cd47c90c', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 34, 34, 'ሌዊም እንደ ሾሙት፥ ለልዑል አምላክም እርሱን አገልጋይ እንደ አደረጉት፥ ልጆቹንም እስከ ዘለዓለም ድረስ አገልጋዮች እንደ አደረጉአቸው ሕልም አየ።'),
  ('4b340b93-ada7-579e-a6e1-494bb9238bcc', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 35, 35, 'ከእንቅልፉም ተነሥቶ እግዚአብሔርን አመሰገነ። ይህ ወር በባተ በዐሥራ አራተኛው ቀን ያዕቆብ በጥዋት ገሠገሠ።'),
  ('8d273f3a-c011-5162-a090-f29fa96cf4cb', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 36, 36, 'ከእርሱም ጋር ከመጣው ሁሉ ዐሥራት አወጣ፥ ከሰው ጀምሮ እስከ ከብት ድረስ፥ ከወርቅም ጀምሮ እስከ ሌላው ገንዘብ ሁሉ፥ እስከ ልብስም ድረስ፥ ከሁሉም ዐሥራት አወጣ።'),
  ('20057b5d-ce16-5f7e-a86a-6bc0bfb699a5', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 37, 37, 'በዚያም ወራት ራሔል ልጅዋን ብንያምን ፀነሰች፤ ያዕቆብም ከእርሱ ጀምሮ ልጆቹን ቈጠረ።'),
  ('cd588744-3d29-5b78-a6d3-9fbf875cff98', '49fed3c2-b331-5178-a875-20092da36178', 'c3f62abb-4aec-5363-a45f-d15b038eb3b7', 38, 38, 'ዕጣም ጣለ፤ የእግዚአብሔርም ዕጣ በሌዊ ወጣ፤ አባቱም የክህነት ልብስን አለበሰው፤ እጁንም ቀባው።'),
  ('0f53a548-0a78-5d86-a666-3a206edd7eb5', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 1, 1, 'ይህ ወር በባተ በዐሥራ አምስተኛው ቀን፥ ከላሞች ወገን ዐሥራ አራት ፍሪዳዎችን፥ ሃያ ስምንት የበግ ሙክቶችን፥ አርባ ዘጠኝ በጎችን፥ ዘጠና ስድስት የበግ ጠቦቶችን፥ ሃያ ዘጠኝ የፍየል ጠቦቶችን ለሚቃጠልመሥዋዕት አቀረበ፤ የተወደደ ቍርባንም አድርጎ በእግዚአብሔር ፊት ለበጎ መዓዛ ወደ መሠዊያው አገባ።'),
  ('f95b34ec-f571-5857-aa45-3844d9dc8709', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 2, 2, 'ዐሥራትም ያወጣ ዘንድ ከተሳለው ስእለት ከመሥዋዕታቸው ጋር ያቀረበው መባ ይህ ነው። የመጠጡም ቍርባን ከዚህ ጋር አንድ ነው።'),
  ('a61ddefa-383c-53d7-a2f3-17bc87d58e85', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 3, 3, 'እሳት በበላው ጊዜም በእሳቱ ላይ ነጭ ዕጣንን ያጥን ነበር። ስለ ድኅነት መሥዋዕትም አራት ፍሪዳዎችን፥ አራት የበግ ሙክትቶችን፥ አራት በጎችን፥ አራት የፍየል ሙክቶችን፥ ዓመት የሆናቸውን ሁለት የበግ ጠቦቶችን፥ ሁለት የፍየል ጠቦቶችንም ያቀርብ ነበር። በየዕለቱ ሰባት ቀን እንዲህ ያደርግ ነበር።'),
  ('3d299034-47d4-5849-a1cd-fbab120ddf6a', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 4, 4, 'እርሱም ከቤተ ሰቦቹና ከልጆቹ ሁሉ ጋር ደስ ብሎት ሰባት ቀን በዚያ ይበላ ነበር። ከክፉ ሁሉ ያዳነውን፥ የለመነውንም የሰጠውን እግዚአብሔርን ፈጽሞ ያመሰግነው ነበር። ንጹሕ ከሆነውም ከብት ሁሉ ዐሥራት አወጣ።'),
  ('0459accf-b121-5be0-a748-29575120ca11', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 5, 5, 'የሚቃጠል መሥዋዕትም አደረገ፤ ንጹሕ ያልሆነውን እንስሳም ለልጁ ለሌዊ ሰጠው። የሰውንም ወገን ሁሉ ሰጠው።'),
  ('e3ef2fcf-56b1-5b24-a54a-0490e922206e', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 6, 6, 'ሌዊም ከዐሥሩ ወንድሞቹ ተለይቶ በአባቱ በያዕቆብ ፊት በቤቴል አገለገለ።'),
  ('fbce9acf-b844-5267-a0ec-a2f76ca6513a', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 7, 7, 'በዚያም ካህን ሆኖ ኖረ፤ ያዕቆብም ስእለቱን ሰጠው፥ ዳግመኛም ለእግዚአብሔር እንደዚሁ ዐሥራትን ሰጠ። ይህንም ቀደሰው፤ ለእርሱም የተቀደሰ ሆነ።'),
  ('00f46b3b-dbb2-516c-a01a-a8cebf3c075d', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 8, 8, 'ስለዚህ ነገር ዐሥራትን ለማውጣት፤ ከዓመት እስከ ዓመት ስሙ ይጠራበት ዘንድ በተመረጠ በቅዱስ ቦታ ዳግመኛ በእግዚአብሔር ፊት ለመብላት ሥርዐት ሆኖ በሰማይ ጽላት ተወስኖአል።'),
  ('24144894-6c4f-56e3-ae26-36682c99cf5e', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 9, 9, 'ለዚህም ሕግ ለዘለዓለሙ የተወሰነ ዘመን የለውም፤ ይኸውም ሥርዐት ከዓመት እስከ ዓመት ሊያደርጉት፥ ዳግመኛ በእግዚአብሔር ፊት በተመረጠ ቦታ ሊበሉት በሰማይ ጽላት የተጻፈ ነው።'),
  ('cb77dcaf-f026-5e57-aaf8-f729f834413a', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 10, 10, 'የዓመቱ አዝመራ እስከሚደርስበት ወራት ድረስ ዘሩ እሰከ ዓመት ድረስ ይበላልና፤ ከዚህም ዓመት ለሚመጣው ዓመት ከእርሱ ማትረፍ የለም፤ ወይኑም ወይን እስከሚደርስበት ወራት፥ ዘይቱም ዘይት እስከሚደርስበት ወራት ይበላልና ማትረፍ የለም።'),
  ('74014da0-4b5b-55ee-a28c-d3795a669674', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 11, 11, 'ከእርሱም የሚተርፈውና የደለበው ሁሉ የረከሰ ይሁን፤ የረከሰም ሆኖአልና በእሳት ይቃጠል። እንደዚሁ በቤተ መቅደስ ሆነው በአንድነት ይብሉት፤ አያድልቡት።'),
  ('4f46d7c5-c59f-5bbd-a859-99f2182db446', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 12, 12, 'የበጉና የላሙ ዐሥራት ሁሉ ለእግዚአብሔር የተቀደሰ ነው። ስለ ዐሥራቱም የሚሆነው እንደዚሁ በሰማይ ጽላት ተወስኖአልና፥ ተጽፎአልምና ካህናቱ ከዓመት እስከ ዓመት በፊቱ የሚበሉት ይሁን።'),
  ('f155c28a-9d81-5355-abc8-0794bbea78b5', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 13, 13, 'በሁለተኛዪቱ ሌሊት፥ ይህም ወር በባተ በሃያ ሁለተኛው ቀን ያዕቆብ ያን ቦታ ይሠራ ዘንድ፥ ቅጥሩንም ሠርቶ ይቀድሰው ዘንድ፥ ለእርሱም እስከ ዘለዓለሙ ድረስ፥ ከእርሱም በኋላ ለልጆቹ እስከ ዘለዓለም ድረስ የተቀደሰ ያደርገው ዘንድ መከረ።'),
  ('da2c3207-e635-5eec-aa36-6a876e9e43b9', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 14, 14, 'እግዚአብሔርም በሌሊት ተገለጠለት ባረከውም፦ እንዲህም አለው፥ “ስምህ እስራኤል ይባል እንጂ ያዕቆብ አይባል።”'),
  ('5eb4e93d-52a3-59c8-a3be-bce735cd21be', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 15, 15, 'ዳግመኛም አለው፥ “ሰማይንና ምድርን የፈጠርሁ አምላክህ እግዚአብሔር እኔ ነኝ፤ አከብርሃለሁ፥ እጅግ በጣምም አበዛሃለሁ።'),
  ('50f0d123-bf5e-504f-a28d-99288e3691e1', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 16, 16, 'ነገሥታቱም ከአንተ ይወለዳሉ፤ በቦታውም ሁሉ ይገዛሉ፤ የሰው ልጅም የረገጠውን ቦታ ሁሉ ይገዛሉ፥ ከሰማይ በታች ያለ ሀገርን ሁሉ ለዘርህ እሰጣለሁ፤ እንደ ወደዱም አሕዛብን ሁሉ ይገዛሉ።'),
  ('dc43e58b-54ab-58b3-ab44-d5f13f221cbf', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 17, 17, 'ከዚህም በኋላ ሀገሪቱን ሁሉ እጅ ያደርጋሉ፤ ለዘለዓለምም ይወርሱአታል።” ከእርሱም ጋር ተነጋግሮ ከጨረሰ በኋላ ከእርሱ ዘንድ ወጣ። ወደ ሰማይም እስኪወጣ ድረስ ያዕቆብ ያይ ነበር።'),
  ('1a508486-d7ef-5641-ab2d-ce814b588549', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 18, 18, 'እርሱም በሌሊት ራእይ አየ፤ እነሆ፥ መልአክ ከሰማይ ሲወርድ አየ፤ እነሆ፥ ሰባት ሰሌዳዎች በእጁ ነበሩ።'),
  ('3744ff13-fb0e-55fa-a433-52bb1a70248b', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 19, 19, 'ለያዕቆብም ሰጠውና አነበባቸው፤ በዓለሙ ሁሉ ለልጆቹና ለእርሱ የሚሆን በውስጣቸው የተጻፈውን ሁሉ አነበበ። በሰሌዳዎቹም የተጻፈውን ሁሉ አሳየው።'),
  ('408b1fca-58af-5bf3-a192-24091393dca4', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 20, 20, 'እንዲህም አለው፥ “ይህን ቦታ አትሥራ፥ የዘለዓለም መቅደስንም አታድርገው፤ ይህ ቦታ አይደለምና በዚህ ቦታ አትደር። ወደ አባትህ ወደ አብርሃም ቤት ሂድ፤ አባትህ እስከሚሞትባት ቀን ድረስ በዚያ በአባትህ በይስሐቅ ቤት ኑር፤ በግብፅ ሳለህ በሰላም ትሞታለህና።'),
  ('0efa5247-d06f-54ea-aa38-82a1ce0db62c', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 21, 21, 'በዚህች ምድር ከአባቶችህ መቃብር ከአብርሃምና ከይስሐቅ ጋር በክብር ትቀበራለህና አትፍራ፤ ሁሉ እንዳየኸውና እንዳነበብኸው እንደዚሁ ይደረጋልና።'),
  ('05268733-3914-54cc-a21a-661e62abb50e', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 22, 22, 'አንተም ያየኸውንና ያነበብኸውን ሁሉ ጻፍ።” ያዕቆብም፥ “ያነበብሁትንና ያየሁትን ሁሉ እንዴት አስታውሳለሁ?” አለ። ጌታም፥ “እኔ ሁሉን አሳስብሃለሁ” አለው።'),
  ('9ac291aa-6448-5562-af29-6d28e1eab437', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 23, 23, 'ከእርሱም ወጣ፥ ያዕቆብም ከእንቅልፉ ነቃ፤ ያነበበውንና ያየውንም ሁሉ ዐሰበ። ያየውንና ያነበበውንም ነገር ሁሉ ጻፈ።'),
  ('e33d2ad8-ce1b-5750-ac96-6f5e5fc22553', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 24, 24, 'ዳግመኛም በዚያ አንድ ቀን በዓል አደረገ፥ በቀደሙት ዕለታት እንደሚሠዋው ሁሉ አድርጎ ሠዋባት። ያች ቀን ተጨምራለችና ስምዋን ተውሳክ አላት።'),
  ('5e2e3a35-2b7b-5bd8-adc5-e27b84793b82', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 25, 25, 'የቀደሙትንም ቀኖች በዓል ብሎ ጠራቸው። እንዲህም ትሆን ዘንድ እንዲህ ይታይ ነበር፥ ይህም በሰማይ ጽላት ተጽፎአል።'),
  ('f97214f4-bac8-530b-ac60-a8449fc17c15', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 26, 26, 'ስለዚህም ነገር በዓል ያደርጋት ዘንድ፥ በዓል በሚደረግባቸው በሰባቱ ቀኖች ላይ እርስዋን ይጨምር ዘንድ ተገለጠለት። በዓመት እንደሚመላለሱ ቀኖች ቍጥር በሰላም መሥዋዕት የሚሠዋባትና በዓል የሚደረግባት ቀን ናትና ስምዋ ተውሳክ ተባለ።'),
  ('df9ab75f-8a16-5d50-ad35-7294be40cd0a', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 27, 27, 'ይህ ወር በባተ በሃያ ሦስት ቀን በዚያ ሌሊት የርብቃ ሞግዚት ዲቦራ ሞተች። ከከተማውም በታች በወንዙ አጠገብ በግራር ሥር ቀበሩአት።'),
  ('79c66b11-6f61-532a-a175-a76f8f01baa1', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 28, 28, 'የዚያንም ወንዝ ስም “ፈለገ ዲቦራ” አለው። ግራሩንም “የዲቦራ ልቅሶ ግራር” አለው።'),
  ('28764d32-8c77-5c37-a870-72d672f97909', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 29, 29, 'ርብቃም ተመልሳ ወደ አባቱ ወደ ይስሐቅ ቤት ሄደች። ያዕቆብም አባቱ እንደሚወድደው አድርጋ ለአባቱ ምግብ ታዘጋጅ ዘንድ የፍየሎችን ሙክቶችና የበጎችንም ሙክቶች፥ በጎችንም በእጅዋ ላከ።'),
  ('a95aa168-93e3-5fe1-a9f8-3d70b6358dd4', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 30, 30, 'ክብራታን ወደምትባል ሀገር እስኪቀርብ ድረስ ከእናቱ ኋላ ሄደ። በዚያም አደረ።'),
  ('3b238fe3-a01f-5161-a400-20f9784bdb8b', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 31, 31, 'ራሔልም ሌሊት ወንድ ልጅ ወለደች። በወለደችውም ጊዜ ተጨንቃ ነበርና ስሙን የኀዘኔ ልጅ አለችው።'),
  ('b5667cd2-dcb5-5185-a0a6-cdcbb5099b28', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 32, 32, 'አባቱ ግን ስሙን ብንያም አለው። በዚህ ኢዮቤልዩ በስድስተኛው ሱባዔ በአንደኛው ዓመት ስምንተኛው ወር በባተ በዐሥረኛው ቀን ራሔል ሞተች። ኤፍራታ በምትባል ምድርም በዚያ ተቀበረች፤ ይህችውም ቤተ ልሔም ናት።'),
  ('99297345-fa2a-5ec4-ae02-b3446f298c3a', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 33, 33, 'ያዕቆብም በጎዳና ዳር ባለ በራሔል መቃብር ላይ ሐውልትን አቆመ።'),
  ('83a666be-e766-5817-ad8a-a44e63f6198f', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 34, 34, 'ያዕቆብም ሄዶ በመግደላ ድራኤፍ ደቡብ አደረ ከሚስቱ ከልያም ጋር ወደ አባቱ ወደ ይስሐቅ ሄዱ።'),
  ('8c7a656e-209d-53b8-abc5-2002dfd983f0', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 35, 35, 'በዐሥረኛው ወር መባቻ ሮቤል የአባቱ ዕቅብት የምትሆን የራሔልን አገልጋይ ባላንን ተሰውራ በውኃ ስትታጠብ አይቶ ወደዳት።'),
  ('f323f5ad-543f-56fe-a8c5-7ce8cae97c23', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 36, 36, 'በሌሊትም ተሰውሮ ወደ ባላን ቤት ገባ፤ እርስዋም በቤቷ ብቻዋን በአልጋዋ ላይ ተኝታ አገኛት። ከእርስዋም ጋር ተኛ፥ በነቃችም ጊዜ እነሆ፥ ሮቤል ከእርስዋ ጋር በመኝታዋ ተኝቶ አየች።'),
  ('d02608cd-a261-57ff-aa8f-f349d876c4fa', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 37, 37, 'እጅዋንም ዘርግታ ያዘችውና ጮኸች፤ ሮቤል እንደ ሆነም ዐወቀች። ከእርሱም የተነሣ አፈረች። ከእርሱም ላይ እጅዋን አነሣች። እርሱም ሸሸ። በዚህም ነገር ፈጽማ ታለቅስ ነበር፤ ለማንም ሰው አልተናገረችም።'),
  ('e08a0c68-fa4a-5031-a6fe-ebeffe346eac', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 38, 38, 'ያዕቆብም መጥቶ በፈለጋት ጊዜ፥ “ሮቤል ስላሳደፈኝ ሌሊትም ስለደረሰብኝ ከአንተ ተለይቻለሁና ለአንተ የምገባ አይደለሁም፤ እኔ ግን እንቅልፍ ይዞኝ ነበር፤ ልብሴን ገልጦ ከእኔ ጋር እስኪተኛ ድረስ አላወቅሁትም ነበር” አለችው።'),
  ('733aa6f3-da72-526d-abe2-a4aa2f738b82', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 39, 39, 'ከባላን ጋር ተኝቶአልና፥ የአባቱንም ኀፍረት ገልጦአልና ያዕቆብ በሮቤል ፈጽሞ ተቈጣ።'),
  ('f6134774-6c2b-50a3-afd9-b89a5cdb9574', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 40, 40, 'ሮቤል አሳድፎአታልና ከዚህ በኋላ ያዕቆብ ወደ እርስዋ አልቀረበም። የአባቱን ኀፍረት የገለጠ ሰው ሁሉ ርኩስ ነው፤ ነገሩ እጅግ ክፉ ነውና፥ በእግዚአብሔርም ፊት የተናቀ ነውና።'),
  ('c85fdf05-81bf-5050-a977-eae2b2ead7f1', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 41, 41, 'ስለዚህ ነገር ሰው ከአባቱ ሚስት ጋር እንዳይተኛ፥ የአባቱንም ኀፍረት እንዳይገልጥ በሰማይ ጽላት ተጽፎአል፤ ርኩስም ስለ ሆነ ሞትን ይሙት።'),
  ('485ed670-f1f0-52bd-a15c-1f8dd426cfc0', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 42, 42, 'ከአባቱ ሚስት ጋር የሚተኛ ሰው ጐስቋላ ነው። ሴትም ብትሆን ጐስቋላ ናት። በምድር ርኩስ ሥራን ሠርተዋልና። እርሱም እርስዋም ይሙቱ። በአምላካችን ፊት ለአገዛዝ በመረጠው ወገን መካከል ርኵሰት አይሁን።'),
  ('f0d1786c-431b-537d-a8b2-9a67a8cce186', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 43, 43, 'ከአባቱ ሚስት ጋር የሚተኛ ሰው የአባቱን ኀፍረት ገልጦአልና የተረገመ ይሆን ዘንድ ዳግመኛ ተጽፎአል።'),
  ('63715b1f-cd03-59f0-a823-38feb5b50fb3', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 44, 44, 'የእግዚአብሔር ወዳጆች ሁሉ፥ “ይሁን፥ ይሁን” አሉ።'),
  ('3b75b8f3-074a-5af1-af1e-5852fb48b859', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 45, 45, 'አንተም ሙሴ ይህን ነገር ይጠብቁ ዘንድ የእስራኤልን ልጆች እዘዛቸው፥ ለሞት የሚያበቃ ፍርድ ነውና፥ የረከሰም ነውና።'),
  ('58430bf0-3f58-50ef-af4b-79a3628062df', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 46, 46, 'ይህን ክፉ ሥራ ለሠራ ሰው ከመገደልና በድንጋይ ከመደብደብ፥ ከእግዚአብሔርም ሕዝብ መካከል ተለይቶ ከመጥፋት በቀር በኀጢአቱ ይቅርታና ስርየት የለውም፤ በእስራኤልም መካከል ይህን ሥራ የሚሠራ ማንኛውም ሰው የተናቀና የተጠላ ስለ ሆነ በምድር አንድ ቀን እንኳ መኖር አይገባውም።'),
  ('f7c216cc-456d-5569-a2e1-e1e971d88c65', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 47, 47, 'ለእርስዋ ባልዋ አባቱ ያዕቆብ በሕይወት ሳለ ከአባቱ ዕቅብት ጋር ከተኛ በኋላ ለሮቤል ሕይወትና ስርየት ነበረው አይበሉ።'),
  ('8fb5bfef-cc89-55a2-a119-7c621f57f77a', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 48, 48, 'በዚያን ጊዜ ለሁሉ ሥርዐትና ሕግ፥ ፍርድም አልተሠራምና፤ ነገር ግን በዘመናችሁ የዘመናትና የቀናት ሕግ እንደ ዘለዓለም ሆኖ ለዘለዓለም ትውልድ ተሠርቶአል።'),
  ('4784e394-1c24-56bc-a584-ba786588a08e', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 49, 49, 'ለዚህም ሕግ የዘመን ፍጻሜ የለውም። በሕዝቡ መካከል ሁለቱ ሁሉ በአንድነት ይጠፉ ዘንድ፥ ይህችን ኀጢአት በሠሩባት ቀን ይገድሉአቸው ዘንድ ነው እንጂ ለኀጢአታቸው ምንም ስርየት የለውም።'),
  ('7c7f4a71-665d-518e-afa4-211ee9c682a6', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 50, 50, 'አንተም ሙሴ ለእስራኤል ጻፍላቸው፤ ይጠብቁአት፤ እንደዚህ ያለ ሥራም አይሥሩ፤ ለሞት የሚያበቃ በደልንም አይበድሉ። ፊት አይቶ የማያዳላ፥ መማለጃን የማይቀበል እርሱ አምላካችን እግዚአብሔር እውነተኛ ፈራጅ ነውና።'),
  ('75438a3d-b70d-5160-a997-d64d3684851a', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 51, 51, 'ይሰሙ ዘንድ፥ ይጠብቁም ዘንድ፥ ከእነርሱም ይለዩ ዘንድ ከምድር ፈጽመው እንዳይጠፉ ይህን የሥርዐት ነገር ንገራቸው። ዓለም በፈጣሪያችን ፊት ይህችን ኀጢአት ለሚሠሩአት ሰዎች ሁሉ የተጠላ፥ የተናቀና የተነቀፈ ነውና፥ በምድር ላይ ከሚሠሩት ከዝሙት የበለጠ ታላቅ ኀጢአት የለምና።'),
  ('6941d8f1-8688-5ba6-a9bd-d2f396a44099', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 52, 52, 'እስራኤል ለእግዚአብሔር የተለየ ወገን ነውና፥ ለአምላኩም የተለየ ወገን ነውና፥ የክህነትና የመንግሥት ወገን ነውና፥ ገንዘብም ነውና። በቅዱስ ሕዝብ መካከል እንዲህ ያለ ኀጢአት ሊታይ አይገባም።'),
  ('ac864611-c10e-565d-a459-018f6250e893', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 53, 53, 'በዚህ በስድስተኛው ሱባዔ በሦስተኛው ዓመት ያዕቆብና ልጆቹ ሄደው በአባቱ በይስሐቅና በእናቱ በርብቃ አቅራቢያ በአብርሃም ቤት አደሩ።'),
  ('0d83778b-84a6-58f0-a8b3-48343318e35f', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 54, 54, 'የያዕቆብም ልጆች ስማቸው ይህ ነው፤ መጀመሪያው ሮቤል ይባላል፤ ሁለተኛው ስምዖን ይባላል፤ ሦስተኛው ሌዊ ይባላል፤ አራተኛው ይሁዳ ይባላል፤ አምስተኛው ይሳኮር ይባላል፤ ስድስተኛው ዛብሎን ይባላል፤ እነዚህ የልያ ልጆች ናቸው።'),
  ('80aac709-c8c3-54f9-a475-c4298feac1d8', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 55, 55, 'የራሔልም ልጆች ዮሴፍና ብንያም ናቸው።'),
  ('b089bc15-cb67-5f58-af5b-7a4ef4f42f74', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 56, 56, 'የባላንም ልጆች ዳንና ንፍታሌም ናቸው።'),
  ('99de02b1-6432-5541-a5fb-932b281a4e5c', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 57, 57, 'የዘለፋም ልጆች ጋድና አሴር ናቸው።'),
  ('b7bbc84c-e34e-53fc-ae8e-05a44dd73b04', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 58, 58, 'ልያ ለያዕቆብ የወለደቻት ሴት ልጅ ዲና ብቻ ናት። ሄደውም ለያዕቆብና ለርብቃ ሰገዱ።'),
  ('17cba981-7dad-5550-ae60-e24299a75ae9', '840a8ad4-860b-5f8c-a680-13d8cbb035b6', '89b1d7ba-c9f4-564e-abab-949b42e2b6d1', 59, 59, 'ባዩአቸውም ጊዜ ያዕቆብንና ልጆቹን ሁሉ መረቁአቸው። የትንሹን ልጁን የያዕቆብን ልጆች አይቶአልና ይስሐቅ ፈጽሞ ደስ ብሎት መረቃቸው።'),
  ('db525846-4ef4-566d-ae8f-0cc9ef708449', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 1, 1, 'ከዚህ ከአርባ አራተኛው ኢዮቤልዩ በዚህ ሱባዔ በስድስተኛው ዓመት በጎችን ይጠብቁ ዘንድ ያዕቆብ ልጆቹን ላካቸው። አገልጋዮቹንም ከእነርሱ ጋር ወደ ሰቂሞን መስክ ላካቸው።'),
  ('d903ab13-0fd6-5121-ac7a-af5a96b24716', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 2, 2, 'በዛፍ ሥር ተሰውረው ያጠፉአቸው ዘንድ፥ ሚስቶቻቸውንና ከብቶቻቸውንም ይማርኩ ዘንድ ሰባቱ የአሞሬዎን ነገሥታት በእነርሱ ላይ ተሰበሰቡ።'),
  ('b2997a8f-a7b2-5aae-a3f7-b96f21bf8933', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 3, 3, 'የያዕቆብም ልጆች፥ ሌዊ፥ ይሁዳና ዮሴፍ ከአባታቸው ከያዕቆብ ጋር በቤት ነበሩ። ልቡናው ያዝንበት ነበርና፥ እርሱንም መተው አልተቻላቸውምና፤ ስለዚህም ታናሹ ልጁ ብንያም በእርሱ ዘንድ ነበረ።'),
  ('91648f0d-0d5a-5e48-a274-c72196b335df', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 4, 4, 'የታፋ ነገሥታት፥ የአሬሳ ነገሥታት፥ የሳራጋን ነገሥታትና የሴሎን ነገሥታት፥ የጋዒዝ ንጉሥ፥ የቤቴሮን ንጉሥና የማአኒሲኪሮስ ንጉሥ በተራራ የሚኖሩ ሁሉ።'),
  ('a7054808-55b8-5206-aac3-6c798d8f39c7', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 5, 5, 'በከነዓን ባለ ዛፍ ሥር የሚኖሩ ሁሉ መጡ። ለያዕቆብም፥ “እነሆ፥ የአሞሬዎን ነገሥታት ልጆችህን ከበቡአቸው፤ መንጋቸውንም ተነጠቁ” ብለው ነገሩት።'),
  ('bf29bd41-b689-5f38-a740-f8c832149132', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 6, 6, 'እርሱም ከቤቱ ተነሣ፤ ሦስቱም ልጆቹ፥ የአባቱም ብላቴኖች ሁሉ፥ የእርሱም ብላቴኖች ተነሡ።'),
  ('d7883ac5-f6d3-536a-a608-6f80baf2a6a5', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 7, 7, 'መሣሪያ የያዙ ዘጠኝ ሺህ ሰዎች ይዞ ሄዶ በሰቂሞን መስክ ወጉአቸው።'),
  ('fe23f444-55ee-5b21-ab0f-42f16fd128b5', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 8, 8, 'የሸሹትንም ተከትለው በሰይፍ አጠፉአቸው፤ ታፋና አሬሳን፥ ሴሎንና ሰራጋን፥ ማአኒሲኪሮስን፥ ጋኤዝንም አጠፋቸው፤ መንጋውንም ሰበሰበ።'),
  ('8a9b96c8-7fce-50df-a804-0158bc867b65', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 9, 9, 'በእነርሱ ላይ ከፍ ከፍ አለ። እነዚህ አምስት እጅ የምድራቸውን ፍሬ ግብር ይሰጡት ዘንድ በእነርሱ ላይ ግብር ሠራ።'),
  ('cb18e791-b260-5f2b-a03f-c511017d2154', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 10, 10, 'ታምናን ታሬስንና ሮቤልን ቀጸረ፤ በሰላምም ተመለሰ።'),
  ('b5f36d8f-6a0e-569c-a09c-be44b513536a', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 11, 11, 'ከእነርሱ ጋር ሰላምን አደረገ። እርሱና ልጆቹ ወደ ግብፅ እስከወረዱበት ቀን ድረስ አገልጋዮች ሆኑት።'),
  ('8d6e092d-968b-526b-a08f-b600fdde464b', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 12, 12, 'በዚህ ሱባዔ በሰባተኛው ዓመት የወንድሞቹን ደኅንነት ያውቅ ዘንድ ዮሴፍን ከቤቱ ወደ ሰቂሞን ምድር ላከው።'),
  ('53f883c1-af85-57c1-a97c-45258d0bf8b2', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 13, 13, 'በዶታኤም ምድርም አገኛቸው፤ በዘበዙት፥ ይገድሉትም ዘንድ፦ መከሩበት።'),
  ('199a1382-9dbe-5332-a5d1-3322a66ad291', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 14, 14, 'ተመልሰውም ለእስማኤላውያን ነጋዴዎች ሸጡት። እነሱም ወደ ግብፅ አውርደው የኤሌው ሀገር ካህን ለሚሆን፥ ለእንጀራ አሳላፊዎች አለቃ፥ ለፈርዖን ባለምዋል ለፋጢፋራን ሸጡት።'),
  ('5bdbe1b6-cdb1-5147-a81c-a77d9ed50f77', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 15, 15, 'የያዕቆብም ልጆች አውራ ፍየል አርደው የዮሴፍን ልብስ በደም ነከሩ።'),
  ('1d5a8995-d4a2-5b48-a62c-6cff0a180882', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 16, 16, 'ሰባተኛው ወርም በባተ በዐሥረኛው ቀን ወደ አባታቸው ወደ ያዕቆብ ላኩ። በዚያች ቀን ከጥዋት እስከ ማታ ድረስ አለቀሰ።'),
  ('a9a546c6-9b5d-542b-ae00-1de47ad52e34', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 17, 17, 'ልብሱንም አመጡለት፤ በሞቱ ኀዘን ተንቀጠቀጠ። ዮሴፍን ክፉ አውሬ እንደ በላው ነገሩት፤ የቤቱም ሰዎች ሁሉ በዚያች ቀን አለቀሱ፤ ቀኑን ሁሉ ከእርሱ ጋር ያዝኑና ያለቅሱ ነበር።'),
  ('f006b3f5-ceb1-5a5c-aa42-fdf245964b65', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 18, 18, 'ወንዶቹ ልጆቹና ሴቲቱ ልጁ ያረጋጉት ዘንድ ተነሡ። ነገር ግን ስለ ልጁ ስለ ዮሴፍ አልተረጋጋም።'),
  ('4c5e70eb-baf8-5cc3-a14c-71dee6401e2a', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 19, 19, 'በዚያም ቀን ባላን ዮሴፍ እንደ ሞተ ሰማች። ለእርሱም ስታለቅስ ሞተች። እርስዋም በቅፍራቲፋ ትኖር ነበር።'),
  ('16f38596-fa78-57ad-aa08-7858bb0c4dee', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 20, 20, 'ልጁ ዲናም ዮሴፍ ከጠፋ በኋላ ሞተች። በያዕቆብ ላይ በአንድ ወር ይህ ሦስቱ ኀዘን ደረሰበት። ባላንም በራሔል መቃብር አንጻር ቀበሩአት፤ ልጁን ዲናንም በዚያ ቀበሩዋት።'),
  ('38ca3153-af6e-56b2-a79e-f944a0148121', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 21, 21, 'ከዮሴፍ መጥፋት በኋላ አንድ ዓመት ሲያለቅስ ኖረ። “ስለ ልጄ ስለ ዮሴፍ እያለቀስሁ ወደ መቃብር እወርዳለሁ” ብሎአልና ልቅሶውን አልተወም።'),
  ('efd4e6dd-636a-5eb6-a219-b4d252d170bd', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 22, 22, 'ስለዚህ ነገር የዮሴፍን መርዶ ወደ አባቱ ወደ ያዕቆብ ባደረሱበት ቀን በፍየል ጠቦት ለእርሱ ያስተሰርይለት ዘንድ፥ ሰባተኛው ወር በባተ በዐሥረኛው ቀን ያዝኑ ዘንድ፥ በእስራኤል ልጆች ላይ ሥርዐት ተሠራ።'),
  ('a2ec0cac-11d4-50d2-a8b8-e4134b7a842a', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 23, 23, 'ሰባተኛው ወር በባተ በዐሥረኛው ቀን ከዓመት አንድ ጊዜ ስለ ኀጢአታቸው ተሠራች፤ ስለ ልጁ ስለ ዮሴፍ የአባታቸውን ልቡና አሳዝነዋልና።'),
  ('a0674661-9d01-560e-a6fb-f933a1573692', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 24, 24, 'ይህቺም ቀን ስለ ኀጢአታቸውና ስለ በደላቸው ሁሉ፥ ስለ ስሕተታቸውም በዚህች ቀን በዓመት አንድ ጊዜ በዚያች ቀን ራሳቸውን ሊያነጹ ያዝኑባት ዘንድ ተሠራች።'),
  ('914c261e-3bfa-5a1b-ade9-edfc038a0c1f', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 25, 25, 'ዮሴፍም ከጠፋ በኋላ የያዕቆብ ልጆች ለራሳቸው ሚስት አገቡ፤ የአንደኛው የሮቤል ሚስት ስምዋ አዳ ይባላል።'),
  ('49038900-f4a9-5550-acfd-c49c4f16a49f', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 26, 26, 'የሁለተኛውም የስምዖን ሚስት ስምዋ አንዲባአ ትባላለች፤ ይህችውም የከነዓን ሴት ናት። የሦስተኛው የሌዊ ሚስት ስምዋ ሚልካ ይባላል፤ እርስዋም ከታራ ልጆች ወገን ከአራም ልጆች የተወለደች ናት።'),
  ('f68d1a0b-1d8e-53be-ada9-4a40a9ce4544', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 27, 27, 'የአራተኛው የይሁዳ ሚስት ስምዋ ቤተ ሱኤል ይባላል፤ እርስዋም የከነዓን ሴት ናት። የአምስተኛው የይሳኮር ሚስትም ስምዋ ሒዛቃ ይባላል።'),
  ('0c53db43-b54b-5844-ab2c-8103c96ccb91', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 28, 28, 'የስድስተኛው የዛብሎን ሚስትም ስምዋ ኒኤሚን ይባላል። የሰባተኛው የዳን ሚስትም ስምዋ ኤግላ ይባላል። የስምንተኛው የንፍታሌም ሚስት ስምዋ የመስጴጦምያ ሴት የምትሆን ራሱኡ ናት።'),
  ('66aeee5b-b6d6-5892-a1ae-f7298729c4ff', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 29, 29, 'የዘጠነኛው የጋድ ሚስትም ስምዋ ሚካ ይባላል። የዐሥረኛው የአሴር ሚስትም ስምዋ ኢዮና ይባላል። የዐሥራ አንደኛው የዮሴፍ ሚስትም ስምዋ አስኔት ይባላል። ይህችውም የግብፅ ሴት ናት።'),
  ('00077f5d-23eb-57c2-a867-6b17fa53c117', '0c0d9031-a088-5bb6-aa29-feb638cbeb3a', '82303966-6de1-5f25-a94e-9b85a576ad0a', 30, 30, 'የዐሥራ ሁለተኛው የብንያምም ሚስት ስምዋ ኢዮሳካ ይባላል። ስምዖንም ተመልሶ ከመስጴጦምያ እንደ ወንድሞቹ ሁለተኛ ሚስት አገባ።'),
  ('54019393-6b8f-50b5-a5e8-142d436dcf88', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 1, 1, 'በአርባ አምስተኛው ኢዮቤልዩ በመጀመሪያው ሱባዔ በመጀመሪያው ዓመት ርብቃ ልጅዋን ያዕቆብን ጠርታ በያዕቆብ በዘመኑ ሁሉ ያከብራቸው ዘንድ፥ ስለ ወንድሙና ስለ አባቱ አዘዘችው።'),
  ('78b070e8-19f4-516f-a8ef-f23851f485f7', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 2, 2, 'ያዕቆብም እንዲህ አለ፥ “ይህ ነገር ለእኔ ክብር፥ ጌትነትም ነውና፥ አከብራቸውም ዘንድ በእግዚአብሔር ፊት በጎ ነገር ነውና እኔ ያዘዝሽኝን ሁሉ አደርጋለሁ።'),
  ('643ccf7f-bdbd-5390-ad56-9fc0b35d6540', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 3, 3, 'እናቴ ሆይ፥ ከተወለድሁባት ቀን ጀምሮ እስከዚህች ቀን ድረስ በዘመኔ ሁሉ ለሁሉ በጎ ነገር እንደማስብ ሥራዬን ሁሉና በልቤ ያለውን ሁሉ ታውቂያለሽ።'),
  ('c0a7e05c-d44e-5717-ad9f-19118adcbcec', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 4, 4, 'ወንድሜንና አባቴን አከብር ዘንድ ያዘዝሽኝን ነገር እንዴት አላደርግም? በእኔ ምን ጥመት አየሽብኝ? እናቴ፥ እስኪ ንገሪኝ፤ እኔም ከእርሱ ፈጽሜ እርቃለሁ፤ ይቅርታም ይደረግልኛል” አላት።'),
  ('3dbde888-f14a-5a35-af4d-3e4268505906', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 5, 5, 'እርሱዋም አለችው፥ “ልጄ ባለ በዘመኔ ሁሉ የቀና ሥራን ነው እንጂ በአንተ ያየሁት ምንም ጠማማ ሥራ የለም።'),
  ('03fc956f-731d-5b13-a3c6-97857c8d2eef', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 6, 6, 'ነገር ግን ልጄ! እውነት ነገርን እነግርሃለሁ። እኔ በዚህች ዓመት እሞታለሁ። ከመቶ አምሳ አምስት ዓመት በላይ እንዳልኖር፥ የምሞትባትን ቀን በሕልሜ አይቻለሁና ይህችን ዓመት በሕይወት አላልፋትም።'),
  ('670c0011-44b6-5b19-a343-1806bb570ab6', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 7, 7, 'እኖርበት ዘንድ ያለኝን ዘመኔን ሁሉ እነሆ፥ እኔ ፈጽሜአለሁ።” ያዕቆብ እናቱ፥ “እሞታለሁ” ብላዋለችና ስለ እናቱ ነገር ሳቀ።'),
  ('14cb7db7-2451-540a-a63e-08df35820680', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 8, 8, 'እርስዋ ግን በአንጻሩ ተቀምጣ ነበር፤ ኀይልም ነበራት፤ ትወጣና ትገባ ነበርና፥ ታይም ነበርና። ጕልበቷም አልደከመም ነበር፤ ጥርስዋም ጽኑ ነበር፤ በሕይወት በኖረችበት ዘመን ሁሉ ምንም በሽታ አላገኛትም ነበር።'),
  ('f1db338f-94e5-5791-ada5-19f2a535b64f', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 9, 9, 'ያዕቆብም አላት፥ “እናቴ ሆይ! ዘመኔ በሕይወት ወደ ኖርሽበት ዘመን ከቀረበ እኔ እድለኛ ነኝ፤ ኀይሌም እንደ አንቺ ኀይል እንዲህ በእኔ ጸንቶ ይኖራል፤ ስለ ሞትሽም ከእኔ ጋር በዋዛ ከንቱ ነገርን ትናገሪያለሽና አትሞቺም።”'),
  ('57be5445-0316-5f3d-a5c4-2d26abfa7bd3', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 10, 10, 'ወደ ይስሐቅም ገብታ እንዲህ አለችው፥ “አንድ ልመናን እለምንሃለሁ፤ የዔሳው ልቡ ከሕፃንነቱ ጀምሮ ክፉ እንደ ሆነ ታውቃለህና፥ በእርሱም ቸርነት የለምና፤ ከሞትህ በኋላ እርሱ ይገድለው ዘንድ ይወድዳልና፥ በያዕቆብም ላይ ክፉ ነገርን እንዳያደርግ፥ በጠብም አስወጥቶ እንዳይሰድደው ዔሳውን አምለው።'),
  ('8cfb3d28-15ef-5c0f-a92d-0473ceb0a0d2', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 11, 11, 'ወንድሙ ያዕቆብ ወደ ካራን ከሄደ ጀምሮ እስከዚህች ቀን ድረስ በዘመኑ ሁሉ ያደረገውን አንተ ታውቃለህ፤ በፍጹም እንደ ተወን፥ በእኛም ክፉ ነገርን እንዳደረገ አንተ ታውቃለህ፤ መንጋህን ሰበሰበ፤ ገንዘብህንም ሁሉ ከፊትህ ቀማህ።'),
  ('4f6692c6-6d81-5b65-a301-3437fbc97624', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 12, 12, 'ገንዘባችንን ይሰጠን ዘንድ ስንለምነው እርሱ እንደሚመጸውተን ሰው ያደርገዋል፤ ፍጹምና ቅን የሚሆን ልጅህ ያዕቆብንም ስለ መረቅኸው አንተን ይጠላሃል።'),
  ('aedf8847-7fdf-5c12-a18e-9f83ae18db44', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 13, 13, 'ከደግነት በቀር ክፋት የለውምና ከካራን ከመጣ ጀምሮ እስከዚህ ቀን ድረስ ምንም ያጐደለብን የለም፤ ሁሉን በየጊዜው ዕለት ዕለት ያመጣልን ነበርና ያመጣልንንም ከእጁ በተቀበልን ጊዜ በፍጹም ልቡናው ደስ ይለው ነበር፤ ያከብረንም ነበር፤ ከካራንም ከመጣ ጀምሮ እስከዚህች ቀን ድረስ ከእኛ አልተለየም።'),
  ('e034bc41-6e70-5865-a1be-943becd67ce6', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 14, 14, 'እርሱም እያከበረን ከእኛ ጋር ሁልጊዜ በቤት ይኖራል።”'),
  ('a4f1353e-113c-5b95-a78d-b5c83bd8a6bf', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 15, 15, 'ይስሐቅም እንዲህ አላት፥ “እርሱ በፍጹም ልቡናው እንደሚያከብረን፥ ከእኛ ጋር ያለ የያዕቆብን ሥራ ዐውቃለሁ፤ አያለሁም። ቀድሞ ከተወለደበት ቀን ጀምሮ ከያዕቆብ ይልቅ ዔሳውን እወደው ነበር፤'),
  ('d877affe-ac76-5818-ad04-6e365c1ccffb', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 16, 16, 'ዛሬ ግን ከዔሳው ይልቅ ያዕቆብን እወድዳለሁ። ክፉ ሥራውን አብዝቶአልና፥ ለእርሱም በጎ ሥራ የለውምና፥ ሥራው ሁሉ ዐመፅና ግፍ ነውና፥ በዙሪያውም እውነት ነገር የለውምና።'),
  ('c435522f-2cda-5d68-a3df-727276be6d43', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 17, 17, 'አሁንም ስለ ክፉ ሥራው ሁሉ ልቡናዬ ይታወካል። የአብርሃምንም ፈጣሪ ትቶ ሚስቶቹን ስለ ተከተለ፥ ጣዖታቸውንም ስላመለከ፥ እርሱም ከልጆቹ ጋር ስሕተታቸውን ስለ ተከተለ ለእርሱና ለዘሩ ድኅነት የለውም። እነርሱ ከሰማይ በታች ካለ ከዚህ ዓለም የሚጠፉ ናቸውና።'),
  ('c074c4c2-d7ca-56d8-a71a-a7ed87cc100a', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 18, 18, 'አንቺ ግን ወንድሙን ያዕቆብን እንዳይገድል አምለው ዘንድ አምለው ትያለሽ፤ ቢምልም በመሐላው ጸንቶ አይኖርም፤ ከክፉ ነገርም በቀር በጎ ሥራን አይሠራም።'),
  ('aac99daa-0763-51df-ac18-2f9a32c15bc7', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 19, 19, 'ወንድሙን ያዕቆብንም ይገድል ዘንድ ቢወድ በያዕቆብ እጅ ይወድቃል። በእጁም ይወድቃልና ከእጁ አያመልጥም።'),
  ('08a92acf-f22e-5ead-ab23-84317bdc3535', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 20, 20, 'ዔሳውን ከሚጠብቀው ይልቅ ያዕቆብን የሚጠብቀው ገናናና ኀያል፥ የከበረና የተመሰገነም ነውና አንቺ ስለ ያዕቆብ አትፍሪ” አላት።'),
  ('5fb1cbcf-a27e-5f2f-a966-96b03d4cf73e', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 21, 21, 'ርብቃም ልካ ዔሳውን ጠራችው፤ ወደ እርስዋም መጣ፤ እርስዋም፥ “ልጄ ሆይ፥ ከአንተ የምለምነው ልመና አለኝ፤ ልጄ ሆይ፥ የምለምንህን ታደርግልኝ ዘንድ እሺ በለኝ” አለችው።'),
  ('e8e08809-2585-5830-a8ac-dc56319c4006', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 22, 22, 'እርሱም፥ “ያልሽኝን ሁሉ አደርጋለሁ፤ ልመናሽንም እንቢ አልልም” አላት። እርሱዋም እንዲህ አለችው፥ “በሞትሁ ጊዜ በአባትህ እናት በሳራ መቃብር አቅራቢያ ትቀብረኝ ዘንድ፥ ወንድምህ ያዕቆብና አንተም እርስ በርሳችሁ ትፋቀሩ ዘንድ፥'),
  ('0af42566-2765-54ea-ad85-e66270905d97', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 23, 23, 'ከፍቅርም በቀር አንዱም አንዱ በወንድሙ ላይ ክፉ ነገርን እንዳያደርግ፥ ልጆች በሥራችሁ ትከናወኑ ዘንድ፥ በዚህ ዓለምም ትከብሩ ዘንድ፥ ጠላትም በእናንተ ደስ እንዳይለው እኔ ከአንተ እለምናለሁ።'),
  ('79a4711b-f918-5db4-a8ea-2eae927657dd', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 24, 24, 'በሚወዱአችሁም ሰዎች ሁሉ ፊት ለይቅርታና ለበረከት ትሆናላችሁ።”'),
  ('777517c1-1b83-54c5-a399-744b1ac9981a', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 25, 25, 'እርሱም እንዲህ አለ፥ “እኔ ያልሽኝን ሁሉ አደርጋለሁ፤ በሞትሽም ጊዜ አጥንቶችሽ በአጥንቶችዋ አቅራቢያ ይኖሩ ዘንድ አጥንቶችዋን እንደ ወደድሽ በአባቴ እናት በሳራ አቅራቢያ እቀብርሻለሁ፤ ወንድሜ ያዕቆብንም ከሰው ሁሉ ይልቅ እኔ እወድደዋለሁ።'),
  ('5780a933-ab15-5c57-ac0d-b54333aded2b', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 26, 26, 'ከእርሱ ብቻ በቀር በምድር ሁሉ ለእኔ ሌላ ወንድም የለኝም፤ ወንድሜ ነውና እርሱን ብወድደው ይህ ለእኔ ታላቅ አይደለም፤ በማኅፀንሽም መካከል በአንድነት ተዘርተናል፤'),
  ('998dec32-aa24-5544-a333-e617d19cadd9', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 27, 27, 'ከማኅፀንሽም በአንድነት ወጥተናል፤ ወንድሜንስ ያልወደድሁ ማንን እወዳለሁ?'),
  ('287bfce9-4dba-52cb-a88e-d1de5943e9e1', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 28, 28, 'ስለ ልጆችና ስለ እኔ ያዕቆብን ትመክሪው ዘንድ እኔ እንዲህ እለምንሻለሁ፤ አባቴ ከመረቀው ቀን ጀምሮ እርሱን ታላቅ፥ እኔንም ታናሽ አድርጎአልና በልጆች ላይና በእኔ ላይ እንዲነግሥ አውቃለሁ።'),
  ('44bd09c0-25ef-5316-ae59-6775fe996d79', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 29, 29, 'እኔም በሕይወት በምኖርበት ዘመን ሁሉ እንደምወድደውና መቼም መች ከበጎ ነገር በቀር በእርሱ ላይ ክፉ ነገርን እንደማልፈልግ እምልልሻለሁ።”'),
  ('2b9de59e-7018-539d-a7cf-272fbda2dc40', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 30, 30, 'ስለዚህ ሁሉ ነገር ማለላት፤ ያዕቆብንም በዔሳው ፊት ጠርታ ከዔሳው ጋር እንደ ተነጋገረችው ነገር አዘዘችው።'),
  ('4ed24f8a-89e0-53ee-aef3-7d6070586a82', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 31, 31, 'እርሱም አላት፥ “እኔ ፈቃድሽን እፈጽማለሁ፤ በወንድሜም በዔሳው ላይ ከእኔና ከልጆች ክፉ ነገር እንደማይወጣ፥ ከፍቅርም በቀር መቼም መች አስቀድሜ እንደማልጣላ ተዋሽኝ።” እርስዋና ልጆችዋም በሉ፤ ጠጡም።'),
  ('94253812-737a-5b49-a4df-4011ed5a42e9', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 32, 32, 'በዚያችም ሌሊት የሦስት ኢዮቤልዩ፥ የአንድ ሱባዔና የአንድ ዓመት ሰው የነበረችው ርብቃ ሞተች። በዚያችም ሌሊት ሁለቱ ልጆችዋ ዔሳውና ያዕቆብ ደርብነት ባላት ዋሻ በአባታቸው እናት በሳራ መቃብር አጠገብ ቀበሩአት።'),
  ('53836377-c077-5950-a654-42665a26f320', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 33, 33, 'በዚህ ሱባዔ በስድስተኛው ዓመት ይስሐቅ ሁለቱን ልጆቹን ዔሳውንና ያዕቆብን ጠራቸው፤ ወደ እርሱም መጡ።'),
  ('f6b01e4b-6ecd-5dbb-a77c-1070fe4a3749', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 34, 34, 'እንዲህም አላቸው፥ “ልጆች ሆይ! እኔ አባቶች በሄዱበት ጎዳና አባቶች በዚያ ለዘለዓለም ወደሚኖሩበት ቤት እሄዳለሁ፤ አብርሃም ለመቃብር በገዛው፥ እኔ ለራሴ ባስቈፈርሁት፥ በኬጢ ሰው በኤፍሮን እርሻ ውስጥ ባለች ደርብነት ባላት ዋሻ በአባቴ በአብርሃም አጠገብ ቅበሩኝ።”'),
  ('0d6d1375-76ab-5541-a6f5-73f08a3fc382', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 35, 35, 'ልጆች ሆይ! እግዚአብሔር ለአብርሃምና ለዘሩ ያደርግ ዘንድ የነገረውን ሁሉ ለእናንተ እንዲያደርግላችሁ በዚህ ዓለም እውነትንና ቅንነትን ትሠሩ ዘንድ ይህን አዘዝኋችሁ።'),
  ('1a3094c4-b4fd-5619-a85d-4973d03f2f4f', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 36, 36, 'ልጆች ሆይ! ሰው ራሱን እንደሚወድድ እርስ በርሳችሁ ወንድሞቻችሁን እየወደዳችሁ ኑሩ።'),
  ('9fac95ae-9fca-5d97-ab87-76955a2cea58', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 37, 37, 'ሰው ለወንድሙ በጎ ነገርን ያደርግለት ዘንድ ፈልጎ፥ ይህንም በምድር ላይ በልቡናው በአንድነት አድርጎ፥ እርስ በርሳቸው እንደ ራሳቸው እንደሚፋቀሩ፥ እርስ በርሳችሁ የምትፋቀሩ ሁኑ።'),
  ('35899705-2b1e-507e-a282-1849d0190f7a', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 38, 38, 'ስለ ጣዖቱም ነገር ትንቁአቸውና ትጠሉአቸው ዘንድ፥ እንዳትወዱአቸውም እኔ አዝዛችኋለሁ። ለሚያመልኳቸውና ለሚሰግዱላቸው ሰዎች ስሕተትን የተመሉ ናቸውና፤'),
  ('49b4c4f8-9ebe-5a39-ac98-d09be4270dd1', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 39, 39, 'ልጆች ሆይ፥ የአባታችሁን የአብርሃምን አምላክ እግዚአብሔርን ዐስቡት።'),
  ('9524b02e-0ee3-5e7c-ac30-9b9fec817ed3', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 40, 40, 'ከዚህም በኋላ እኔ አመለክሁት። በእውነትና በሰፊ ልቡና ተገዛሁለት። በደስታ ያበዛችሁ ዘንድ፥ ልጆቻችሁንም እንደ ሰማይ ኮከብ ለማብዛት ያሳድግላችሁ ዘንድ፥ ለዘለዓለም ትውልድም ሁሉ የማይነቀል የእውነተኛ ተክል አድርጎ በምድር ይተክላችሁ ዘንድ ዐስቡት።'),
  ('1569150f-7331-50f7-aae4-7e8fc0a35d93', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 41, 41, '“አሁንም እኔ በታላቅ መሐላ አምላችኋለሁ። ከእርሱ የሚበልጥ በሌላ፥ በተመሰገነና፥ በከበረ፥ ገናናና ድንቅ በሆነ፥ ኀያል ጽኑ በሆነ፥ ሰማይንና ምድርን በፈጠረ፥ ሁሉንም አንድ አድርጎ በያዘ በእግዚአብሔር ስም ከመማል የሚበልጥ መሐላ የለምና፥ እያንዳንዱም በይቅርታና በቸርነት ወንድሙን እየወደደ የምትፈሩትና የምታመልኩት ትሆኑ ዘንድ አምላችኋለሁ።'),
  ('f85b80b3-17d8-5699-a9a1-102fd9cd0374', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 42, 42, 'ከዛሬ ጀምሮ እስከ ዘለዓለም ድረስ በሕይወት ዘመናችሁ ሁሉ፥ በሥራችሁ ሁሉ ትከናወኑ ዘንድ፥ እንዳትጠፉም ሰው በወንድሙ ክፉ ነገር ማድረግን አይውደድ።'),
  ('800ecb5d-67a7-5dfc-a29f-03d620ec9321', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 43, 43, 'ከእናንተ በወንድሙ ክፉ ነገርን ያደርግ ዘንድ የሚፈልግ ሰው ቢኖር በእጁ እንደሚወድቅ፥ ከሕያዋን ምድርም ከዛሬ ጀምሮ እንደሚጠፋ ዕወቁ።'),
  ('e413aa7c-46c2-594e-a7e5-84254f563dfd', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 44, 44, 'ዘርዑም ክርክር፥ መዓትና ቍጣ በሚደረግባት ቀን ከሰማይ በታች ካለ ከዚህ ዓለም ይጠፋል፤ እግዚአብሔርም በሚነድና በሚያቃጥል እሳት ሰዶምን እንዳቃጠለ እንደዚሁ ሀገሩንና ከተማውን ያቃጥላል። የእርሱ ገንዘብ የሆነውንም ሁሉ ያጠፋል፤ የሰው ልጅ ተግሣጽ ከተጻፈበትም መጽሐፍ ይጠፋል።'),
  ('aa71c77f-1e2e-589c-af5f-d78232d449cf', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 45, 45, 'እርሱ የሚጠፋ ነውና፥ ለዘለዓለም ርግማንም የሚያልፍ ነውና፥ በዘመኑ ሁሉ ቍርጥ ፍርዳቸው በመርገምና በስድብ፥ በጭንቅና በቍጣ፥ በዘለዓለም ደዌና መቅሠፍትም የታደሰ ይሆን ዘንድ በሕይወት መጽሐፍ አይጻፍም።'),
  ('56bb30ae-063a-5fe1-a223-6ad42f361804', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 46, 46, 'ልጆች ሆይ፥ በወንድሙ ክፉ ነገርን ያደርግ ዘንድ በሚወድ ሰው ላይ ቅጣት እንደሚመጣ፥ እንደሚጠፋም እነግራችኋለሁ፥ አዳኝባችኋለሁም።”'),
  ('7601ccd2-bbb3-5e86-a38c-4063a1dee783', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 47, 47, 'ያለውንም ገንዘብ ሁሉ በዚያች ቀን ለሁለቱ አደለ፤ ክብርንም አስቀድሞ ለተወለደው ልጁ ሰጠ። ግንቡንና በዙሪያው ያለውንም ሁሉ ሰጠ።'),
  ('2fd91cbd-986c-51d7-ac8d-903ff0c757c0', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 48, 48, 'አብርሃም በዐዘቅተ መሐላ ያጠራቀመውንገንዘብ ሁሉ ሰጠው። እንዲህም አለ፥ “ይህን ታላቅ ክብር አስቀድሞ ለተወለደው ልጅ ሰጠሁ።”'),
  ('0ed76ad4-8663-5554-a916-4191175974a6', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 49, 49, 'ዔሳውም አለ፥ “ለያዕቆብ ብኵርናዬን ሸጥሁለት፤ ክብርም ይሰጠው ዘንድ ብኵርናዬን ለያዕቆብ ሰጠሁ፤ በእርሱ ዘንድ አለችና ስለ እርስዋ ምንም የምናገረው ነገር የለኝም።”'),
  ('fa496202-052f-5aca-a69f-44b306748c33', '6e8d9c47-0585-5342-afc7-1444600fd010', 'c6aaac37-37d5-5a81-a3ce-ab7e16ad6ca6', 50, 50, 'ይስሐቅም እንዲህ አለ፥ “ልጆች ሆይ፥ አሳርፋችሁኛልና፥ በእርስዋም ምክንያት ክፉ ሥራን እንዳትሠሩ ስለ ብኵርና ልቡናዬ አላዘነችምና በዚህች ቀን በእናንተና በልጆቻችሁ ላይ በረከት ትደር፤ በጎ ሥራ የሚሠራ ሰውን ልዑል እግዚአብሔር ያክብረው፤ እርሱንና ዘሩንም ለዘለዓለም ይባርክ።”'),
  ('abe595bd-5862-5d78-a2c8-1f7ca10b033e', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 1, 1, 'ይህን አዝዞአቸውና መርቆአቸው ከጨረሰ በኋላ በፊቱ በአንድነት በሉ፤ ጠጡም።'),
  ('7d01993d-a693-512c-abf9-914caf228dee', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 2, 2, 'በመካከላቸውም መተካከል ሆኖአልና ደስ አላቸው። ከእርሱም ዘንድ ወጡ፤ በዚያችም ቀን ዐርፈው ተኙ።'),
  ('afde3da6-a137-5597-aa3a-6bdcc8df26ae', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 3, 3, 'ይስሐቅም ደስ ብሎት በዚያች ቀን በአልጋው ላይ ተኛ፤ የዘለዓለምንም እንቅልፍ አንቀላፋ።'),
  ('db36272f-e2f6-5dd4-ab55-599f4309aa46', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 4, 4, 'የመቶ ሰማንያ ዐመት ሰው ሆኖ ሞተ። ሃያ አምስት ሱባዔንና አምስት ዓመትን ጨረሰ። ሁለቱ ልጆቹ ዔሳውና ያዕቆብም ቀበሩት።'),
  ('fe8169a1-46b9-512c-a699-eab08fe396a9', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 5, 5, 'ዔሳውም በኤዶምያስ አውራጃ ወደ አለች ወደ ሴይር ተራራ ሄደ፤ በዚያም ኖረ።'),
  ('9f4d8a6c-53a2-50a5-aa46-2cf41c3dfd58', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 6, 6, 'ያዕቆብም አባቱ አብርሃም ተሰዶ ይኖርበት በነበረ በኬብሮን ምድር ባለ ግንብ ኖረ።'),
  ('d6dfc858-6099-5381-a624-eba7c75a5acd', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 7, 7, 'እንደ ተወለደበት ወራት እንደሚታየው ትእዛዝ አድርጎ በፍጹም ልቡናው እግዚአብሔርን አመለከው።'),
  ('dae7005c-116c-5ec6-a297-6c9d162145a2', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 8, 8, 'በአርባ አምስተኛው ኢዮቤልዩ በሁለተኛው ሱባዔ በአራተኛው ዓመት ሚስቱ ልያ ሞተች። በአባቱ እናት በሳራ መቃብር በስተግራ በእናቱ በርብቃ መቃብር አጠገብ ደርብነት በአላት ዋሻ ቀበራት።'),
  ('71e2624e-4129-58e5-a541-ebab17c1beba', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 9, 9, 'ልጆቹና ልጆችዋ ሁሉ ለሚስቱ ለልያ ከእርሱ ጋር ያለቅሱላት ዘንድ፥ ስለ እርስዋም ያረጋጉት ዘንድ መጡ፤ ያለቅስላት ነበርና። በሥራዋም ሁሉ ፈጽማ ቅን ስለሆነች እኅቷ ራሔል ከሞተች ጀምሮ ፈጽሞ ይወድዳት ነበርና።'),
  ('aed6f7a4-fe2d-517a-ab0f-606ba4c9ca22', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 10, 10, 'ያዕቆብንም ታከብረው ነበር፤ ከእርሱም ጋር በኖረችበት ዘመን ሁሉ ክፉ ነገር ከአፍዋ አልሰማም፤ የዋህና ሰላማዊት ነበረችና፥ ሰላም፥ ቅንነት፥ ክብርም ያላት ነበረችና።'),
  ('90075de1-7e56-535f-aac8-5eb6211a8940', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 11, 11, 'በሕይወት ሳለች የሠራችውን ሥራ ሁሉ ያስብ ነበር፤ ያለቅስላትም ነበር። በፍጹም ሰውነቱና በፍጹም ልቡናው ፈጽሞ ይወድዳት ነበርና።'),
  ('be3bb671-e1a4-5c3f-a00c-9eb68b1926de', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 12, 12, 'የዔሳውና የያዕቆብ አባት ይስሐቅ በሞተባት ቀን የዔሳው ልጆች ይስሐቅ ለታናሹ ልጁ ለያዕቆብ ብኵርናውን እንደ ሰጠው ሰሙ።'),
  ('b189bf7d-c68a-546d-a196-73f54f54f70b', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 13, 13, 'ፈጽመውም ተቈጡ፤ “አንተ ታላቅ ሳለህ፥ ያዕቆብ ያንተ ታናሽ ሲሆን፥ አባትህ አንተን ትቶ ለያዕቆብ ብኵርናን ለምን ሰጠው?” ብለው ከአባታቸው ጋር ተከራከሩ።'),
  ('aa22cef6-79e3-5abc-a91b-c8792ace4899', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 14, 14, 'እርሱም አላቸው፥ “እኔ ብኵርናዬን በትንሽ ምስር ንፍሮ ሸጫለሁና ስለዚህ ነው።'),
  ('186ce21e-a11f-5ea6-ac2c-4f39c4a8c125', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 15, 15, 'በልቶ ሊመርቀኝ አድኜ አመጣለት ዘንድ አባቴ በላከኝ ቀን በተንኰል መጥቶ የሚበላውንና የሚጠጣውን ለአባቴ አቀረበ። አባቴም መረቀው፤ እኔንም ከእርሱ በታች አደረገኝ።'),
  ('d90d3914-9029-59f2-a2a9-0862563fb202', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 16, 16, 'አሁንም ወንድም ከወንድሙ ጋር በክፉ ነገር እንዳንፈላለግ፤ ነገር ግን ወንድም ከወንድሙ ጋር በፍቅርና በሰላም ጸንተን እንድንኖር፥ መንገዳችንንም እንዳናጠፋ፥ አባታችን እኔንና እርሱን አማማለን።”'),
  ('6a48e53c-c99e-5730-af09-013121411a49', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 17, 17, 'እነርሱም አሉት፥ “ከእርሱ ጋር ፍቅር ለማድረግ አንሰማህም፤ ከእርሱ ኀይል የእኛ ኀይል ይጸናልና፥ እኛም ከእርሱ እንበረታለንና ወደ እርሱ ሄደን እንገድለዋለን፤ ልጆቹንም እንገድላለን፤ ከእኛ ጋር ካልሄድህም በአንተ ላይ ክፉ ነገር እናደርግብሃለን።'),
  ('ec7f25fc-82c7-5d82-a4e4-e5ee24e48785', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 18, 18, 'አሁንም ስማን፤ ወደ አራም፥ ወደ ፍልስጥኤም፥ ወደ አሞንና ወደ ሞዓብ ልከን በሰልፍ የሚመክቱ የተመረጡ ሰዎችን ለራሳችን እንምረጥ፤'),
  ('64a53a9a-4823-5c3a-a3c0-417400d43d8e', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 19, 19, 'ወደ እርሱም ሄደን ከእርሱ ጋር እንዋጋ፤ ኀይልም ሳይዝ ከምድር እናጥፋው።”'),
  ('03654b0e-fc95-594d-acc9-1d649dfdd20c', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 20, 20, 'አባታቸውም፥ “አትሂዱ፤ በፊቱም እንዳትጠፉ፥ ከእርሱ ጋር ጠብን አታድርጉ” አላቸው።'),
  ('4985cd1f-d798-5aef-aa2d-7f2492feccca', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 21, 21, 'እነርሱም አሉት፥ “ከልጅነትህ ጀምሮ እስከዚህች ቀን ድረስ ሥራህ ይህ ብቻ ነውን? አንተ አንገትህን ወደ ቀንበሩ ታገባለህ፤ እኛስ ይህን ነገር አንሰማም።”'),
  ('8a5c2085-dcbd-588d-a143-1d7e9bbcad38', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 22, 22, 'ወደ አራምና ወደ አባታቸው ወዳጅ ወደ አዱራም ልከው የተመረጡ አርበኞችና ጦረኞች የሚሆኑ ሺህ ሰዎችን ለመቅጠር ከእነርሱ ጋር ተስማሙ።'),
  ('d4575c5e-62b2-5cfa-ac8f-35050f96e163', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 23, 23, 'ከተወዳጁአቸው ከአሞንና ከሞዓብ ልጆች የተመረጡ ሺህ አርበኞች፥'),
  ('c28e2a47-63bb-5ec4-a4c1-5ce7163c034c', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 24, 24, 'ከፍልስጥኤም የተመረጡ ሺህ አርበኞች፥'),
  ('358c1d86-b287-576e-ae4a-8bc53c0d6b21', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 25, 25, 'ከኤዶምና ከኮራውስ የተመረጡ ሺህ አርበኞች፥'),
  ('edfe9795-a5de-567e-ae9b-83c21ee5c9b2', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 26, 26, 'ከኬጤዎንም ጽኑዓን የሆኑ አርበኞች ወደ እነርሱ መጡ።'),
  ('6e821965-7b63-547a-abd2-881bd9c43059', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 27, 27, 'አባታቸውንም፥ “ወጥተህ ምራቸው፤ ይህ ካልሆነ እንገድልሃለን” አሉት። እርሱም ወደ ወንድሙ ወደ ያዕቆብ ሊመራቸው ይሄድ ዘንድ ልጆቹ እንደ ተበራቱበት በአየ ጊዜ ፈጽሞ ቍጣን ተመላ።'),
  ('5cc26429-5161-5f5e-a5e0-d419a8c4388a', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 28, 28, 'ከዚህም በኋላ በልቡ የተሰወረ ክፋትን ሁሉ በወንድሙ በያዕቆብ ላይ አሰበ። ነገር ግን በዘመኑ ሁሉ በወንድሙ በያዕቆብ ላይ ክፉ ነገርን እንዳይፈልግ ለእናቱና ለአባቱ የማለውን መሐላ አላሰበም።'),
  ('0b8d13ea-a52b-5fe5-a714-b30f0149dd94', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 29, 29, 'ያዕቆብ ግን እነርሱ ለመዋጋት ወደ እርሱ እንደሚመጡ ይህን ሁሉ አላወቀም። እርሱም ከተመረጡ ከአራት ሺህ አርበኞችና ጦረኞች ጋር በግንቡ አጠገብ ወደ እርሱ እስኪቀርቡ ድረስ ለሚስቱ ለልያ ያለቅስ ነበር።'),
  ('99eae3c6-e04f-55c1-ad3b-8d40fbedb047', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 30, 30, 'የኬብሮን ሰዎችም፥ “እነሆ፥ ወንድምህ ይዋጋህ ዘንድ ሰይፍ ከታጠቁ፥ ጋሻቸውንና ጦራቸውንም ከያዙ ከአራት ሺህ ሰዎች ጋር መጣ” ብለው ወደ እርሱ ላኩ።'),
  ('97e82322-4bed-5f1f-a253-974acca01681', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 31, 31, 'ከዔሳው ይልቅ ያዕቆብን ይወዱት ነበርና ነገሩት፤ ያዕቆብ ለጋስ ሰው ነበረና፥ ከዔሳውም ይልቅ ቸር ነበረና። ያዕቆብም ወደ ግንቡ አጠገብ እስኪቀርቡ ድረስ የነገሩትን አላመነም። የግንቡንም በር ዘጋ።'),
  ('57717aae-bc7b-547d-a68a-226f18a3e8a2', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 32, 32, 'በግንቡም ላይ ቆሞ ከወንድሙ ከዔሳው ጋር ተነጋገረ፤ እንዲህም አለ፥ “ሚስቴ ስለ ሞተች በበጎ ማረጋጋት ታረጋጋኝ ዘንድ መጣህን?'),
  ('ee2bd0ae-40a7-52c0-a33c-6d4813a22526', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 33, 33, 'እናትህና አባትህ ሳይሞቱ ዳግመኛ ፈጥነህ የማልኸው መሐላ ይህ ነውን?'),
  ('95cd3322-491c-581e-acd2-a1f1779982be', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 34, 34, 'ከማልኸው መሐላ ወጥተህ በደልህ፤ ለአባትህም በማልህበት ጊዜ ተፈረደብህ።” ዔሳውም ያንጊዜ መለሰ።'),
  ('2cc2946d-95a8-53f4-a503-456fdf39d355', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 35, 35, 'እንዲህም አለው፥ “ለምድር አራዊትና ለሰው ልጆች በእውነት የተማማሉት መሐላ እስከ ዘለዓለም ድረስ የለም።'),
  ('bd5088a1-5ada-5496-aea8-e70c0741d2e1', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 36, 36, 'በየቀኑ ይህ ለዚህ ክፋትን ይፈልጋል። እያንዳንዱም ጠላት ጠላቱን ይገድለው ዘንድ ይፈልጋል።'),
  ('2b615e69-0624-553e-a65a-7db8492e8785', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 37, 37, 'አንተም እኔን ከልጆች ጋር እስከ ዘለዓለም ድረስ ትጠላኛለህ፤ ከአንተ ጋርም ወንድማማችነት ማድረግ የለም። እኔ የምነግርህን ይህን ነገሬን ስማ። እሪያ ጠጕሩንና ቁርበቱን እንደ ባዘቶ ቢለውጥ፥'),
  ('384fda5d-e952-57fb-a31f-e9db53a465f1', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 38, 38, 'እንደ በግና እንደ ዋልያም በራሱ ላይ ቀንድ ቢወጣ፥ ያንጊዜ ከአንተ ጋር ወንድማማችነትን አደርጋለሁ።'),
  ('942b7833-739c-5430-acbf-55c84b00b28f', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 39, 39, 'ጡቶች ከእናቶች ቢለዩ ወንድም በሆንኸኝ ነበር። ተኵላዎችም እንዳይበሉአቸውና እንዳይነጣጠቁአቸው ከበጎች ጋር ሰላምን ቢያደርጉ፥ ልቡናቸውም ለእነርሱ በጎ ነገርን ለማድረግ ቢያስብ፥'),
  ('2c312dc7-ceee-5aed-ab1b-cdef1673854a', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 40, 40, 'ያንጊዜ በልቡናዬ ለአንተ ሰላም ይሆናል። አንበሳ ለላም ወዳጁ ቢሆን፥ ከእርሱም ጋር በአንድ ቀንበር ቢጠመድ፥ ከእርሱም ጋር ቢያርስ፥ ከእርሱም ጋር ሰላምን ቢያደርግ፥ ያንጊዜ ከአንተ ጋር ሰላምን አደርጋለሁ።'),
  ('a60dcd82-dce0-59fc-a7d2-495f11d70526', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 41, 41, 'ቁራዎች እንደ ሳቢሳ ቢነጡ፥ ያንጊዜ እንደ ወደድሁህ፥ ከአንተም ጋር ሰላምን እንዳደረግሁ አውቃለሁ፤ አንተም ትጠፋለህ፥ ልጆችህም ይጠፋሉ። ለአንተም ሰላም አይደረግልህም።”'),
  ('4a3088df-0d33-5c17-ab25-7d8640c6699d', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 42, 42, 'ያንጊዜም ያዕቆብ በእርሱ ልቡናውን እንዳስጨከነ፥ ይገድለውም ዘንድ በፍጹም ልቡናው እንዳሰበ ዐወቀ።'),
  ('42b67eb1-62a8-56a1-a1f2-8a36fb89d8d1', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 43, 43, 'እርያ በጦር ወግቶ ወደሚገድለው ሰው ፈጥኖ እንደሚወጣ፥ ከእርሱም እንደማይሸሽ ዔሳው ፈጥኖ መጣ።'),
  ('95488058-6cd0-52f3-a367-f6a9589e6b9d', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 44, 44, 'ያንጊዜም ባሪያዎቹንና ወገኖቹን፥ ወዳጆቹንም ሁሉ ይከቡት ዘንድ አዘዘ።'),
  ('5e1c770f-30fc-5497-affd-5ff79065f5a2', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 45, 45, 'ከዚህም በኋላ ይሁዳ አባቱን ያዕቆብን ተናገረው፤ እንዲህም አለው፥ “አባቴ ሆይ፥ ቀስትህን ሳብ፥ ፍላጻህንም ወርውረህ ጠላትህን ውጋ፤ ጠላትህንም ግደል። ኀይልም ይሁንልህ።'),
  ('737ca42a-795b-51c5-a9c0-152052cb5be3', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 46, 46, 'እኛ ወንድምህን አንገድልምና፤ እርሱም በአንተ ዘንድ አለና፥ በእኛም ዘንድ ለመከበር እንደ አንተ ነውና።”'),
  ('cd448dae-e844-52dd-aaee-0eff7a111bdb', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 47, 47, 'ያንጊዜም ያዕቆብ ቀስቱን ስቦ ፍላጻውን ወርውሮ ወንድሙን ዔሳውን ወግቶ ገደለው።'),
  ('7ab84611-e4d2-5cea-a5f4-eb47882bfafd', '93fc2424-0d4f-5d90-aec0-bb680913cff6', '01ee4d80-cf6e-5b16-a481-30d55916a697', 48, 48, 'ዳግመኛም ፍላጻውን ወርውሮ የአሕዛብ ወገን የሚሆን አዱራንን የግራ ጡት ሥሩን ወጋው፤ አሳድዶም ገደለው።'),
  ('d9570c3c-e08d-5c19-a9d3-541e96174ff4', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 1, 1, 'ከዚህም በኋላ እነዚያ የያዕቆብ ልጆች፥ ባሪያዎቻቸውም ተከፍለው በግንቡ በአራቱ ማዕዘን ወጡ።'),
  ('81aad433-888a-50ce-ab16-76e19dfb49e7', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 2, 2, 'ይሁዳ በፊት ወጣ፤ ንፍታሌምና ጋድ፥ አምሳ ብላቴኖችም በግንቡ ደቡብ ከእርሱ ጋር ነበሩ። በፊታቸው ያገኙትን ሁሉ ገደሉ። ከእነርሱም አንድ ሰው ስንኳ ያመለጠ የለም።'),
  ('b13aa510-e15f-5072-a146-e572d89e85fa', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 3, 3, 'ሌዊ፥ ዳንና አሴር በግንቡ ምሥራቅ ወጡ፤ አምሳ ብላቴኖችም ከእነርሱ ጋር ነበሩ። የሞዓብንና የአሞንንም ተዋጊዎች ገደሉ።'),
  ('829f0a80-12bc-53f7-aafd-f2a5be97227d', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 4, 4, 'ሮቤል፥ ይሳኮርና ዛብሎንም በግንቡ ሰሜን ወጡ፥ አምሳ ብላቴኖችም ከእነርሱ ጋር ነበሩ፤ የፍልስጥኤምንም አርበኞች ገደሉ።'),
  ('2cd65c07-a363-5516-a863-015be7972992', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 5, 5, 'ስምዖን፥ ብንያምና የሮቤል ልጅ ኤናክ በግንቡ ምዕራብ ወጡ፥ አምሳ ብላቴኖችም ከእነርሱ ጋር ነበሩ። ከኤዶምና ከኮራውስ አራት መቶ ጠንካሮች ተዋጊዎች ሰዎችን ገደሉ። ስድስት መቶዎቹ ግን ሸሹ፤ አራቱ የዔሳው ልጆችም።'),
  ('6f159fe2-a84d-55cb-a8ab-cc0d997ec19c', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 6, 6, 'አባታቸው በኮረብታው ላይ ሞቶ እንደ ወደቀ ትተውት ከእነርሱ ጋር ሸሹ። ይህችውም በአዱራም ያለች ኮረብታ ናት፤ የያዕቆብም ልጆች በኋላቸው ተከትለው እስከ ሴይር ተራራ ድረስ አሳደዱአቸው።'),
  ('e144bdd6-e32f-51f8-aaa8-c72dab9648be', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 7, 7, 'ያዕቆብ ግን በአዱራም ኮረብታ ወንድሙን ቀብሮ ወደ ቤቱ ተመለሰ። የያዕቆብ ልጆች የዔሳውን ልጆች በሴይር ተራራ አስጨነቁአቸው። ለያዕቆብ ልጆችም ተገዢዎች ይሆኑ ዘንድ አንገታቸውን ዝቅ አደረጉ።'),
  ('e881a136-b7ec-56ac-ae07-999619a17a9c', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 8, 8, 'ከአነርሱም ጋር ሰላምን ያደርጉ እንደ ሆነ ይወጉአቸውም እንደ ሆነ፥ ወደ አባታቸው ላኩ።'),
  ('f1bfc085-33e2-5725-a375-d0adc9655b39', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 9, 9, 'ያዕቆብም ሰላምን ያደርጉ ዘንድ ወደ ልጆቹ ላከ፤ ከእነርሱም ጋር ሰላምን አደረጉ።'),
  ('fa11d347-035d-5ba7-ad66-8a5277ebf563', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 10, 10, 'በዘመኑ ሁሉ ለያዕቆብና ለልጆቹ ይገብሩ ዘንድ የመገዛት ቀንበርን በእነርሱ ላይ አኖሩ።'),
  ('fc11cc6c-8622-53b4-a19e-7257225279da', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 11, 11, 'ያዕቆብ ወደ ግብፅ እስከሚወርድበት ቀን ድረስ ለያዕቆብ ሲገብሩ ኖሩ፤ የኤዶም ልጆችም፥ ዐሥራ ሁለቱ የያዕቆብ ልጆች በእነርሱ ላይ ከሠሩት ከመገዛት ግብር እስከዚያች ቀን ድረስ አላጐደሉም።'),
  ('312af2f2-8c54-55e7-ab9a-60248f581622', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 12, 12, 'እስከዚያች ቀን ድረስ ለእስራኤል ልጆች ንጉሥ ሳይነግሥ በኤዶምያስ የነገሡ ነገሥታት እነዚህ ናቸው።'),
  ('f8602978-2b1d-5bce-a385-146b763ae19d', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 13, 13, 'በኤዶምያስ የቢዖር ልጅ ባላቅ ነገሠ፤ የከተማውም ስም ዲናባ ነበር፤ ባላቅም ሞተ።'),
  ('879c9ca1-eadc-537d-addd-075361e676cc', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 14, 14, 'በእርሱም ፋንታ ከቦሶር ወገን የዛራ ልጅ ዮባብ ነገሠ። የዛራ ልጅ ዮባብም ሞተ። በእርሱም ፋንታ ከቴማን ሀገር አሳም ነገሠ፤ አሳምም ሞተ።'),
  ('77231652-00d9-549b-a14d-043ca5116f85', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 15, 15, 'በእርሱም ፋንታ በሞዓብ ምድረ በዳ የምድያምን ሰዎች የገደለ የባሬድ ልጅ አዶታ ነገሠ፤ የከተማውም ስም አውት ነበር። አዶታም ሞተ።'),
  ('4cae1793-0277-585a-a330-4f729861b6e7', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 16, 16, 'በእርሱም ፋንታ ከአሜሴቅ ወገን ሰልማን ነገሠ። ሰልማንም ሞተ። በእርሱም ፋንታ ከሮባኦት ወንዝ የመጣ ሳኦል ነገሠ፤ ሳኦልም ሞተ። በእርሱም ፋንታ የአክቡር ልጅ ብዑሉናን ነገሠ፤ የአክቡር ልጅ ብዑሉናንም ሞተ።'),
  ('5975de72-47e8-5ca1-acf7-a888c75e75e4', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 17, 17, 'በእርሱም ፋንታ አዳት ነገሠ፤ የሚስቱ ስም ማየጦቢት ነበር፤ ይህችውም የሜትቤድዘብ ልጅ የመጥሪት ልጅ ናት። በኤዶምያስ ሀገር የነገሡ ነገሥታት እነዚህ ናቸው።'),
  ('6a4da67b-3cf3-510e-a822-94946a569835', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 18, 18, 'ያዕቆብም አባቱ ተሰዶ በኖረበት ያዕቆብ በተዛመዳቸው ሀገር በከነዓን ኖረ።'),
  ('56320973-0574-5922-a72e-49cf1aec5d43', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 19, 19, 'ዮሴፍም የዐሥራ ሰባት ዓመት ልጅ ሳለ ወንድሞቹ ከሸጡት በኋላ ወደ ግብፅ አወረዱት። የፈርዖን ባለሙዋል የአዛዦች አለቃ ፋጢፋራን ገዛው። ዮሴፍንም በቤቱ ሁሉ ላይ ሾመው።'),
  ('ba408db9-6194-566c-a54d-d9d64407f718', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 20, 20, 'በዮሴፍ ምክንያት የእግዚአብሔር በረከት በግብፃዊው ሰው ቤት ሆነ። እግዚአብሔርም የሚሠራውን ሁሉ ያቀናለት ነበር።'),
  ('9ebf1355-dedc-5f3b-a429-97d154e94e83', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 21, 21, 'ግብፃዊውም ሰው እግዚአብሔር ከዮሴፍ ጋር እንደ አለ፥ የሚሠራውንም ሥራ ሁሉ እግዚአብሔር እንዲያቀናለት አይቶአልና ሁሉን በዮሴፍ ፊት ተወ።'),
  ('82e16e3a-2dd7-5d31-a90c-ba4e7fd25654', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 22, 22, 'ዮሴፍም መልከ መልካም፥ እጅግም የተዋበ ነበረ።'),
  ('da6ba941-4292-5688-a060-dfd755b39c4a', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 23, 23, 'የጌታውም ሚስት ዐይኖችዋን አንሥታ ዮሴፍን አየችው። ወደደችውም፤ ከእርስዋም ጋር ይተኛ ዘንድ ለመነችው፤ እርሱ ግን ልቡን አልሰጣትም።'),
  ('a3a3a9b9-861b-58ab-ac2a-4cb59eeea456', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 24, 24, 'እግዚአብሔርንም አሰበው፤ ባል በአላት ሴት ማንም ሰው እንዳያመነዝር ከአብርሃም ቃላት አባቱ ያዕቆብ ያነበበላቸውን ነገሮች አሰበ። በሰማይ በልዑል እግዚአብሔር ፊት የተሠራለት የሞት ቅጣት እንደ አለ አሰበ። በዘመኑ ሁሉ ኀጢአት ስለ እርሱ በእግዚአብሔር ፊት በዘለዓለም መጽሐፍ እንደምትጻፍ አሰበ።'),
  ('f5dc661c-e469-5a66-a703-d6976c43d81a', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 25, 25, 'ዮሴፍም ይህን ነገር አሰበ፤ ከእርስዋም ጋር ይተኛ ዘንድ አልወደደም፤ አንድ ዓመት አባበለችው፤ ከለከላትም፤ መስማትንም እንቢ አላት።'),
  ('0cf8a22f-2c5d-5f90-a337-e8549372fca1', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 26, 26, 'እርስዋ ግን ከእርስዋ ጋር ይተኛ ዘንድ ልትጣላው በቤት አስጨንቃ ያዘችው፤ የቤቷንም ደጃፍ ዘጋች፤ በገሃድም ያዘችው፤ እርሱ ግን ከእጅዋ አመለጠ፤ ልብሱንም በእጅዋ ትቶ፥ ሳንቃውንም ሰብሮ ከፊቷ ወደ ውጭ ሸሸ።'),
  ('9a94067e-8176-5ca6-abf0-bd0bd9352d06', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 27, 27, 'ያቺም ሴት ከእርስዋ ጋር እንደማይተኛ በአየች ጊዜ እንዲህ ብላ በጌታው ፊት አጣላችው፥ “የምትወድደው ይህ ዕብራዊ ባሪያህ ይደፍረኝ ዘንድ ወደደ።'),
  ('214fffa4-f288-52fc-a305-2fa1a309bafc', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 28, 28, 'እንዲህም ሆነ፥ ቃሌን ከፍ አድርጌ በጮኽሁ ጊዜ ልብሱን በእጄ ትቶ፥ በያዝሁትም ጊዜ ሳንቃውን ሰብሮ ሸሸ።”'),
  ('02c11a48-1eef-523d-a31e-a2b8bf1298c5', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 29, 29, 'ግብፃዊውም የዮሴፍን ልብስና የተሰበረውን መዝጊያ አየ፤'),
  ('a799eff9-0c5e-532d-a625-83dff3fbbe79', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 30, 30, 'የሚስቱንም ነገር ሰምቶ ዮሴፍን ንጉሥ ያሰራቸው እስረኞች ወደ አሉበት እስር ቤት አገባው።'),
  ('271df9e7-71e4-57d8-aea3-108a08d9edc3', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 31, 31, 'በዚያም በእስር ቤት ኖረ። እግዚአብሔርም ለዮሴፍ በእስር ቤት ጠባቂዎች አለቃ ፊት ሞገስን፥ ምሕረትንም በፊቱ ሰጠው። እግዚአብሔር ከእርሱ ጋር እንደ አለ፥ የሚሠራውንም ሥራ ሁሉ እግዚአብሔር እንዲያቀናለት አይቶአልና ሁሉን በፊቱ ተወ።'),
  ('f6429afd-8f48-599d-a506-86c2867031d8', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 32, 32, 'ዮሴፍ ሁሉን ያደርግ ነበርና፥ እግዚአብሔርም ይፈጽምለት ነበርና የእስር ቤት ጠባቂዎች አለቃ ያለ እርሱ ምንም የሚያውቀው አልነበረም። በዚያም ሦስትዓመት'),
  ('23abc207-9496-5707-a7c3-5a0dcfd9b300', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 33, 33, 'በዚያም ወራት የግብፅ ንጉሥ ፈርዖን በሁለቱ ባለምዋሎቹ በጠጅ አሳላፊዎች አለቃና በእንጀራ አሳላፊዎች አለቃ ላይ ተቈጣ። ዮሴፍ ተይዞ በዚያ በታሠረበት በእሥር ቤቱ አለቃ ቤትም በእስራት አኖራቸው።'),
  ('0f7431e3-b6bf-5216-a415-aff55609e4b8', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 34, 34, 'የእስረኞች አለቃም በፊታቸው ይላላካቸው ዘንድ፥ በፊቱም ይላላከው ዘንድ ዮሴፍን ሾመው።'),
  ('743ded31-b11a-5deb-a88d-00aa1df2e4e3', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 35, 35, 'ሁለቱም የጠጅ አሳላፊዎች አለቃና የእንጀራ አሳላፊዎች አለቃ ሕልም አለሙ። ለዮሴፍም ነገሩት፤ ዮሴፍም እንደ ተረጐመላቸው እንዲሁ ሆነላቸው።'),
  ('44e16c59-790f-55d0-a902-ff1b33db270e', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 36, 36, 'ፈርዖንም ዮሴፍ እንደ ተረጐመላቸው የጠጅ አሳላፊዎችን አለቃ ወደ ሥራው መለሰው፤ የእንጀራ አሳላፊዎችን አለቃ ግን ገደለው፤'),
  ('0af06ae4-53f9-5fc4-a569-a988e25f3e33', '17526af0-3ca5-568e-a67a-0074cdc3e610', 'd11bd1f2-4895-56eb-ab63-3ec5441e01e5', 37, 37, 'የጠጅ አሳላፊዎች አለቃ ግን ዮሴፍን በእስር ቤት ረሳው። ዮሴፍ የሚሆንለትን ነግሮት ነበርና እንደ ነገረው ለፈርዖን ይነግረው ዘንድ አላሰበም። ረስቶታልና።'),
  ('509e72fb-702c-56b1-a6ae-4f961f25f4bf', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 1, 1, 'በዚያም ወራት ፈርዖን በምድር ሁሉ ስለሚሆነው ጥጋብና ራብ በአንዲት ሌሊት ሁለት ሕልሞችን አየ።'),
  ('873abc6d-fbeb-59e7-adb2-61216751fa82', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 2, 2, 'ከእንቅልፉም ነቃ፤ በግብፅ ያሉ ሕልም የሚተረጕሙትንና ጠንቋዮችን ሁሉ ጠርቶ ሁለቱን ሕልሞቹን ነገራቸው። ነገር ግን ሊተረጕሙ አልቻሉም።'),
  ('33519256-20ae-545e-a5c8-49cbff414142', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 3, 3, 'ከዚህም በኋላ የጠጅ አሳላፊዎች አለቃ ዮሴፍን አሰበው፤ የእርሱንም ነገር በንጉሡ ዘንድ ተናገረ።'),
  ('5ec11baf-8a25-5135-a768-e7fa41c197fe', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 4, 4, 'ከእስር ቤትም አወጡት። ሁለቱን ሕልምቹንም በፊቱ ተናገረ።'),
  ('d206e298-dfc3-504a-a955-f4c6535aefce', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 5, 5, 'እርሱም ሁለቱ ሕልሞቹ አንድ እንደ ሆኑ፥ በፈርዖን ፊት ተናገረ።'),
  ('3111cb00-d9d8-5e5a-ae00-13bb4ef45490', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 6, 6, 'እንዲህም አለው፥ “በግብፅ ሀገር ሁሉ ጥጋብ የሚሆንበት ሰባት ዓመት ይመጣል፤ ከዚህ በኋላ በሀገሩ ሁሉ ተመሳሳይ የሌለው ሰባት የራብ ዓመት ይመጣል፤'),
  ('022eb62c-29b5-5bf0-abaa-e97f026fa689', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 7, 7, 'አሁንም የግብፅ ሰዎች ሁሉ ለፈርዖን ጎተራ ይሥሩ፤ ጥጋብ በሆነበት ዘመንም በሀገር የተገኘውን እህል ለሀገር ምግብ ሊሆን ያኑሩት፤ ሰባት ዓመት ራብ ለሚሆንበትም ዘመን ምግብ ይሆናል፤ ራቡም እጅግ የጸና ይሆናልና ከራብ ጽናት የተነሣ ሀገር አትጠፋም።”'),
  ('96d98e38-617f-5149-a836-f92e6ad3fa31', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 8, 8, 'እግዚአብሔርም በፈርዖን ፊት ለዮሴፍ ባለምዋልነትንና ምሕረትን ሰጠው።')
